D.SharedStrings[9428]="对暗影飓风眼以外的敌人造成越来越强的暗影伤害。"
D.SharedStrings[9429]="对暗矛巨魔来说，现在真是困难的时期。赞达拉部族正在集结所有巨魔部落，想要收回所有他们失去的领土。$b$b我们想警告尽可能多的人，但恐怕已经太晚了。$b$b已经有另一个暗矛战士去荆棘谷警告他们了，但在荆棘谷单独出行并不安全。$b$b帮助我找到他，并警告荆棘谷的人们，巨魔部落即将重新崛起。$b$b我会让我的灵魂跟随你，如此一来，你赶到荆棘谷的时候，我将可以帮助你。"
D.SharedStrings[9430]="对最多3个目标造成{2}点自然伤害。除第一个目标外每个目标依次承受较少的伤害。"
