D.SharedStrings[9691]="寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。$B$B在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。$B$B将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。"
D.SharedStrings[9692]="寻找组队"
D.SharedStrings[9693]="寻找美猴王谜语里描述的物品。"
D.SharedStrings[9694]="寻物公司的委托"
D.SharedStrings[9695]="导管破坏者链甲护腿"
D.SharedStrings[9696]="导致憎恶爆炸，消灭周围所有的达卡莱裂颅者。"
