D.SharedStrings[9701]="射出{1}支邪能之箭，每支造成{2}点暗影伤害。"
D.SharedStrings[9702]="射出一把淬毒匕首，造成大量初始伤害，然后再造成持续伤害。中毒的生物移动速率在短时间内降低。"
D.SharedStrings[9703]="射出一支活血箭，对目标造成伤害并溅射至目标附近的盟友身上，恢复量等同于目标附近的盟友所受到的伤害量。"
D.SharedStrings[9704]="射出一支移动的火焰箭穿过目标位置，对其路径上触碰到的首个目标造成大量的火焰伤害。"
