D.SharedStrings[9732]="将10块烧烤秃鹰翅膀和5瓶密林葡萄酒带到斯莫特船长的救生艇上去。$B$B然后杀死奈古拉什，将斯莫特的弯刀交给荆棘谷的斯莫特船长。"
D.SharedStrings[9733]="将1份石中盐和5个金币交给冬青树储藏器，以换取5棵冬青树。"
D.SharedStrings[9734]="将20只粉碎的夜行蜘蛛腿和2份尖啸者的脑浆粘液做成一份魔能混合物。"
D.SharedStrings[9735]="将2份丝纹夹板和1个野外急救包带到地图上标记的地点。到达之后，治疗受伤的冒险者。"
D.SharedStrings[9736]="将2块冰冷的肉和采自达拉然下水道的4枚魔法蘑菇放在你的煎肉锅中，烹制成一份魔法蘑菇肉片，然后将其带到达拉然的鲁因广场，交给摩尔珍品店中的奥尔顿·本内特。"
D.SharedStrings[9737]="将3个畸变怪从他们的生长室中释放出来，让他们攻击此区域内所有敌人。"
D.SharedStrings[9738]="将3个野外急救包带到地图上标记的地点。到达之后，治疗发烧的探险者。"
D.SharedStrings[9739]="将3份丝纹绷带和1个野外急救包带到地图上标记的地点。到达之后，治疗重伤的士兵。"
D.SharedStrings[9740]="将3份银色药膏和1个野外急救包带到地图上标记的地点。到达之后，治疗邪灼斥候。"
D.SharedStrings[9741]="将3枚战歌峡谷荣誉奖章交给战场外的联盟准将。"
D.SharedStrings[9742]="将3枚战歌荣誉奖章交给战场外的部落战争使者。"
D.SharedStrings[9743]="将3枚阿拉希盆地荣誉奖章交给战场外的联盟准将。"
D.SharedStrings[9744]="将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。"
D.SharedStrings[9745]="将4份法力余烬的能量导入附近的水晶结界。"
D.SharedStrings[9746]="将4份诺森德炖肉和从一壶达拉然的奶酪店中取来的葡萄酒带到达拉然的鲁因广场，交给魔术旅馆中的埃里雷。"
D.SharedStrings[9747]="将4根采自晶歌森林的晶歌胡萝卜与4块冰冷的肉放在炖肉锅里进行烹饪。$B$B炖好之后，将萝卜炖肉交给达拉然下水道的旅店老板埃因·格林。"
D.SharedStrings[9748]="将{1}点神器能量注入到你当前装备的神器之中。"
D.SharedStrings[9749]="将{1}点神器能量注入到指定的神器之中。"
D.SharedStrings[9750]="将“本月美酒”俱乐部会员资料表交给奥格瑞玛的莱玛。"
D.SharedStrings[9751]="将“本月美酒”俱乐部会员资料表交给铁炉堡石火旅店的拉尔金·雷酒。"
D.SharedStrings[9752]="将一个宠物提升至3级。"
D.SharedStrings[9753]="将一个敌人禁锢在琥珀中，使其昏迷，直到被释放。"
D.SharedStrings[9754]="将一个敌人转化为石头。被石化的敌人将免疫所有伤害和效果，但无法移动或采取任何行动。"
