D.SharedStrings[9802]="将你射至高空中，并展开机械滑翔机。"
D.SharedStrings[9803]="将你找到的脏兮兮的东西和三枚银币放入超级清洁器5200型里面后，机器仿佛重获生命一般，疯狂地清理着那东西表面上的污垢，并发出响亮而剧烈的搅动声。它的金属外壳吱吱作响，发出吱吱呀呀的声音……"
