D.SharedStrings[9844]="将制作圣杖所需的元素徽记给我带回来！$B$B土灵徽记在屠龙者格鲁尔手中，他就躲在刀锋山的巢穴里。$B$B另一枚徽记是夜之魇的心脏，据说这只神秘的野兽居住在先知麦迪文的高塔内。$B$B迅速行动吧！"
