D.SharedStrings[9935]="将档案馆数据圆盘带到奥杜尔的档案馆控制台前。"
D.SharedStrings[9936]="将欧瑞克的水晶球放在遗忘海岸的废墟中心。"
D.SharedStrings[9937]="将武器投向敌人，造成{1}%的武器伤害。"
D.SharedStrings[9938]="将死亡的情景植入目标的脑海里，使其被恐惧所压迫。"
D.SharedStrings[9939]="将永恒沙漏放在青铜巨龙圣地的地面上。不能放置在另一只沙漏附近40码的范围内。"
D.SharedStrings[9940]="将沃格斯碎片和考扎克碎片组合成艾瑞达燃烧水晶。"
D.SharedStrings[9941]="将法庭传票送给影牙城堡的药剂师汉摩尔。"
D.SharedStrings[9942]="将法术反射给施法者。\r\n对近战攻击者造成{1}点暗影伤害。"
D.SharedStrings[9943]="将洛拉姆斯的躯体带到风暴祭坛去，然后在仪式进行期间保护它。"
D.SharedStrings[9944]="将浸水的书籍带给达拉然的罗伯特·纽哈斯。"
D.SharedStrings[9945]="将淬火的奎尔德拉带到映像大厅里面的剑冢去。"
D.SharedStrings[9946]="将淬火闪电长枪带回雾纱栈道的迷雾酒肆，交给拉希奥。"
D.SharedStrings[9947]="将激冻冰弹交给千针石林沉没的挖掘场的布里维普。"
D.SharedStrings[9948]="将灰烬使者的意志灌注到持有者体内。"
D.SharedStrings[9949]="将灵魂与目标融合，吸收{1}点生命值，并使造成的伤害提高{2}%。"
D.SharedStrings[9950]="将灵魂与目标融合，吸收目标的{1}点生命值，并让造成的伤害提高{2}%。"
D.SharedStrings[9951]="将灵魂囚禁在一个有限的时光之环内，任何会杀死目标的攻击反而会为其恢复{1}%的最大生命值。"
D.SharedStrings[9952]="将煞能注入你的体内，使你的攻击有一定几率造成额外的{1}点伤害，但同时对你自身造成{2}点伤害。"
D.SharedStrings[9953]="将熔火邪能抛向高空，最终坠向地面，对附近敌人造成火焰伤害。"
D.SharedStrings[9954]="将物品恢复到一个更稳定的状态。"
D.SharedStrings[9955]="将物品等级为{1}的工程学护目镜升至{2}。"
D.SharedStrings[9956]="将玩家传送到双子所在的大厅。"
D.SharedStrings[9957]="将玩家传送到埃兰之影的房间。"
D.SharedStrings[9958]="将玩家传送到岩石大厅。"
D.SharedStrings[9959]="将玩家传送到巅峰之台。"
D.SharedStrings[9960]="将玩家传送到斯坦索姆内。"
D.SharedStrings[9961]="将玩家传送到旋云之巅。"
D.SharedStrings[9962]="将玩家传送到紫罗兰监狱中。"
D.SharedStrings[9963]="将玩家传送至青龙寺。"
D.SharedStrings[9964]="将玩家传送至魔古山宫殿。"
D.SharedStrings[9965]="将玩家传送至黑石岩窟。"
D.SharedStrings[9966]="将玩家打上天空。"
D.SharedStrings[9967]="将瓦塔拉克饰品的左瓣、右瓣和上瓣组合起来。"
D.SharedStrings[9968]="将生命的能量转换为纯粹的魔法能量。"
D.SharedStrings[9969]="将生成的每个卑劣的灵魂在炸裂前杀死，然后击败巫妖王（10人）。"
D.SharedStrings[9970]="将生成的每个卑劣的灵魂在炸裂前杀死，然后击败巫妖王（25人）。"
D.SharedStrings[9971]="将盗贼之一到盗贼之三的所有卡片组合成为一副套牌。"
D.SharedStrings[9972]="将盗贼之一到盗贼之五的所有卡片组合成为一副套牌。"
D.SharedStrings[9973]="将目标与施法者绑定，并保护施法者不受任何伤害。杀死目标后，这个效果就会消失。"
D.SharedStrings[9974]="将目标从束缚中解放出来。"
D.SharedStrings[9975]="将目标困在寒冰障壁中。"
D.SharedStrings[9976]="将目标拉到施法者身边。"
D.SharedStrings[9977]="将目标的灵魂从其躯体中剥离，让灵魂暴露在灵魂世界中。"
D.SharedStrings[9978]="将目标的灵魂永久从身体中割裂出来。"
D.SharedStrings[9979]="将目标禁锢于冰霜之中，直到冰墓被摧毁，目标将一直处于昏迷状态。"
D.SharedStrings[9980]="将目标禁锢在坚冰之中，使其陷入昏迷并对目标及目标附近的敌人造成{1}点冰霜伤害。"
D.SharedStrings[9981]="将目标队友伪装成忍者。"
D.SharedStrings[9982]="将目标队友伪装成海盗。"
D.SharedStrings[9983]="将目标队友伪装成蝙蝠。"
D.SharedStrings[9984]="将目标队友伪装成骷髅。"
D.SharedStrings[9985]="将目标队友伪装成鬼魂。"
D.SharedStrings[9986]="将目标队友伪装成麻风侏儒。"
D.SharedStrings[9987]="将矮人精神的力量赐予其族人。"
D.SharedStrings[9988]="将破旧的战斧锻造成符文战斧。必须在符文熔炉旁进行。"
D.SharedStrings[9989]="将破旧的长剑锻造成符文之剑。必须在符文熔炉旁进行。"
D.SharedStrings[9990]="将神器进行展览。"
D.SharedStrings[9991]="将种子播在一片肥沃土壤中。可以在破碎群岛的河流和湖泊沿岸找到肥沃土壤。"
D.SharedStrings[9992]="将稀释药剂扔进痛苦之匣的天灾之锅里。"
D.SharedStrings[9993]="将符文嵌在巨人平原的石巨人身上以控制它。"
D.SharedStrings[9994]="将等级提升至3级，学习冰霜新星。然后对一个训练假人施放2次冰霜新星。"
D.SharedStrings[9995]="将等级提升至3级，学习冲锋。然后对一个训练假人进行冲锋。"
D.SharedStrings[9996]="将等级提升至3级，学习刺骨。然后对一个训练假人使用3次刺骨。"
D.SharedStrings[9997]="将等级提升至3级，学习暗言术：痛。然后对训练假人施放5次暗言术：痛。"
D.SharedStrings[9998]="将等级提升至3级，学习腐蚀术。然后对一个训练假人使用5次腐蚀术。"
D.SharedStrings[9999]="将翻修过的书籍和3根导能魔棒交给棘齿城的斯坦哈德·法尔杉。"
D.SharedStrings[10000]="将肯瑞托徽记之戒交给达拉然紫罗兰之门的大法师塞琳德拉。"
D.SharedStrings[10001]="将能量引导至某个位置，对附近的任意敌人造成奥术伤害。"
D.SharedStrings[10002]="将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。"
D.SharedStrings[10003]="将苏拉玛海陆大餐食谱的两半拼在一起。"
D.SharedStrings[10004]="将获救的雏龙交给燃烧平原滑石的阿克莱德。"
D.SharedStrings[10005]="将萨满变成一头幽魂之狼，移动速度提高{1}%，攻击速度提高{2}%。"
D.SharedStrings[10006]="将萨满祭司变成一头幽魂之狼，移动速度提高{1}%。只能在户外使用。"
D.SharedStrings[10007]="将藤蔓拉到至少离作物15码的地方将它除去。"
D.SharedStrings[10008]="将被污染的奎尔德拉放入太阳之井。准备好进入太阳之井高地后，就同太阳之井守卫交谈。"
D.SharedStrings[10009]="将被浸透的配方交给达拉然城中的克莉丝蒂·斯多克顿。"
D.SharedStrings[10010]="将被邪能毁坏的书籍带给达拉然的罗伯特·纽哈斯。"
D.SharedStrings[10011]="将装着半瓶水的瓶子交给多兰纳尔的科瑞萨斯·月怒。"
D.SharedStrings[10012]="将诱饵扔进深渊，好捉住一只深渊鳐鱼。"
D.SharedStrings[10013]="将货仓幸存者从束缚中解救出来。"
D.SharedStrings[10014]="将贵族之一到贵族之八的所有卡片组合成为一副套牌。"
D.SharedStrings[10015]="将足球炸弹踢过球场后的烟囱球门，赢得这场球的决胜一分！"
D.SharedStrings[10016]="将身边的物品向敌人抛掷，造成{1}点伤害。"
D.SharedStrings[10017]="将辛达苟萨的灵魂交给龙骨荒野中龙眠神殿的卡雷苟斯。"
D.SharedStrings[10018]="将达尔坎的徽记交给银月城的洛瑟玛·塞隆。"
D.SharedStrings[10019]="将这个面具戴在脸上或者头盔上。"
D.SharedStrings[10020]="将这本典籍交给它的主人。"
D.SharedStrings[10021]="将这面军旗插在双塔废墟的墓地中以占领它！"
D.SharedStrings[10022]="将远古魔力注入传送道标。"
D.SharedStrings[10023]="将迷你白金圆盘拿到塔纳利斯的奥丹姆大门去，找出两者之间的联系。"
D.SharedStrings[10024]="将遗失的邮件交给达拉然下水道的郭雅夫人。"
D.SharedStrings[10025]="将遗物进行展览。"
D.SharedStrings[10026]="将那盘“金子”送给千针石林裂蹄高地的阿布力可汗。"
D.SharedStrings[10027]="将邪能腐蚀散播到世界中，使附近生物的急速和移动速度提高。"
D.SharedStrings[10028]="将邪能腐蚀散播到世界中，使附近的恶魔急速和移动速度提高。"
D.SharedStrings[10029]="将重磅炸药包放在加姆深处的霜胆祭坛附近。"
D.SharedStrings[10030]="将铸币交给拉希奥，他就在翡翠林附近的永恒岛上。"
D.SharedStrings[10031]="将阵亡者的旗帜交给暗月岛上暗月马戏团的萨杜斯·帕雷教授。"
D.SharedStrings[10032]="将阿坎多尔的果实交给沙尔艾兰的一名苏拉玛难民。"
D.SharedStrings[10033]="将附近所有敌人抓到维克多·奈法里奥斯勋爵的位置。"
D.SharedStrings[10034]="将附近所有的敌人拉到恶魔所在的位置。"
D.SharedStrings[10035]="将附近所有的敌人拉到维克多·奈法里奥斯勋爵所在的位置。"
D.SharedStrings[10036]="将附近的所有敌人传送到施法者身前。"
D.SharedStrings[10037]="将雷神之核带回雾纱栈道的迷雾酒肆，交给拉希奥。"
D.SharedStrings[10038]="将面前的树木锯倒或者对面前5码范围内的所有敌人造成伤害。"
D.SharedStrings[10039]="将鞭尾幼龙带给反抗军营地的塞斯曼下士。"
D.SharedStrings[10040]="将飓风之一到飓风之八的所有卡片收集起来以完成这副套牌。"
D.SharedStrings[10041]="将饮用者变形，使其攻击和法术有一定几率对黑暗院长和其爪牙额外造成自然伤害。"
D.SharedStrings[10042]="将驾驶员从座舱里弹射出来，造成{1}点伤害。"
D.SharedStrings[10043]="将驾驶员发射到指定地点"
D.SharedStrings[10044]="将驾驶员发射到指定地点。"
D.SharedStrings[10045]="将魔古武器插在9个邪刃蜥蜴人的尸体附近。"
D.SharedStrings[10046]="将魔网振荡器的能量集中到一位达拉然居民身上，然后看看会发生什么。"
D.SharedStrings[10047]="將暗淡的亡域之石送給某人。"
D.SharedStrings[10048]="將演說稿交給鋼架補給站的特瑞德·炫鼻上尉。"
D.SharedStrings[10049]="對X、Y、Z地點發射遠程攻擊。每個地點均需要一個像此法術的獨立複製法術。"
D.SharedStrings[10050]="對一個悲慘的生命來說，是一個好的開始，也許是伊利丹的人生中屈指可數的幾個愉快記憶之一。雖然在那之後的數年，預言之子受到考驗，但依舊沒有使他挫敗。不論在往後在旅途中你會看到什麼，都不能忘記這點。$B$B還有許多的事情要玩成，不過時機還沒到。時機成熟時，我會呼喚你。"
D.SharedStrings[10051]="對話潛獵者"
D.SharedStrings[10052]="小型元素"
D.SharedStrings[10053]="小型克西斯号"
D.SharedStrings[10054]="小型煞魔开始锁定了工匠。任何攻击都会打断该效果。"
D.SharedStrings[10055]="小型虚空召唤者"
D.SharedStrings[10056]="小心地做下一个决定。我们尽最大的努力来配合我们的盟友，但就连达拉然的资源都有他们的底限。"
D.SharedStrings[10057]="小心地将修复的遗物放入箱子中。"
D.SharedStrings[10058]="小心地调整屏障控制器。"
D.SharedStrings[10059]="小心选择，这可是没办法退货的。"
D.SharedStrings[10060]="小心！“信条”的属下都提高了警觉。注意保持距离。"
D.SharedStrings[10061]="小心！纳莉丝爪牙们的视野经过魔法增幅，注意保持距离。"
D.SharedStrings[10062]="小心，那东西随时都可能爆炸！"
D.SharedStrings[10063]="小精灵"
D.SharedStrings[10064]="小虫图金斯"
D.SharedStrings[10065]="小蜜蜂软鞋"
D.SharedStrings[10066]="小风暴之翼幼龙"
D.SharedStrings[10067]="小鬼也是要喝水的，许多小鬼会随身携带自己的水杯。有些人认为，古代那些像小鬼一样的恶魔族群会将它们喝水用的容器当作圣物来崇拜，直到它们被燃烧军团收编之后，这些水杯仍然作为仪式的一部分被保留了下来。"
D.SharedStrings[10068]="小鬼存活的时间足以让阿加莎激怒它们，使其伤害提高{1}%。"
D.SharedStrings[10069]="小鳄鱼造成伤害，并降低目标的移动速度。"
D.SharedStrings[10070]="小鳄鱼造成持续型伤害，并降低目标的移动速度。"
D.SharedStrings[10071]="少女之爱"
D.SharedStrings[10072]="少年河鬃牛头人"
D.SharedStrings[10073]="尖刺刺穿地面升起，对施法者远方呈直线形排列的敌人造成{1}点物理伤害，并将其击飞。"
D.SharedStrings[10074]="尖刺陷阱爆炸，对10码内所有受害者造成{2}点伤害。"
D.SharedStrings[10075]="尖啸之虎，齐昂的不灭战矛"
D.SharedStrings[10076]="尖啸者卡兹"
D.SharedStrings[10077]="尖啸者卡兹嗜血残暴，且酷爱焚烧东西。尽管疯狂，她却是个不折不扣的强力萨满。"
D.SharedStrings[10078]="尘归尘，土归土"
D.SharedStrings[10079]="尘泥沼泽任务"
D.SharedStrings[10080]="尘泥沼泽有迪菲亚兄弟会？"
D.SharedStrings[10081]="尚喜师父"
D.SharedStrings[10082]="尝试从敌人面前逃脱，向后方跳跃。必须面对目标使用。"
D.SharedStrings[10083]="尝试以下颜色组合之后，击败不眠的约萨希（普通或英雄难度）。"
D.SharedStrings[10084]="尝试吊起附近的物体。"
D.SharedStrings[10085]="尝试在阴影中穿行，并出现在你的敌人身后。"
D.SharedStrings[10086]="尝试复生一个亡灵仆从，并令其为施法者作战。在12秒后，如果亡灵仆从仍然活着，它将牺牲自己以治疗施法者。"
D.SharedStrings[10087]="尝试将一名敌人焊接在地面上，使其移动时受到周期性自然伤害。"
D.SharedStrings[10088]="尝试脱离战斗，向后方跳跃。"
D.SharedStrings[10089]="尝试说服打击目标交待实情。非常有效。"
D.SharedStrings[10090]="尤亚姆巴电离胸甲"
D.SharedStrings[10091]="尤卡·斯库比格特"
D.SharedStrings[10092]="尤德利斯·岩怒"
D.SharedStrings[10093]="尤格-萨隆"
D.SharedStrings[10094]="尤格-萨隆的卫士"
D.SharedStrings[10095]="尤格-萨隆的大脑"
D.SharedStrings[10096]="尤格萨隆的谜之匣"
D.SharedStrings[10097]="就因为这个勋章，这个诅咒才会降临到我们身上。瓦萨拉克领主显然知道如何掌握仇恨。$B$B我们会尽力找到剩下的碎块 - 希望是在我面临最终的死期之前。不过在那之前，让我们先来看看你的奖励。"
D.SharedStrings[10098]="就在今天早上，我的斥候报告说，有一队诅咒教派的教徒带着一样东西离开冰冠堡垒，前往黑暗大教堂了。$B$B现在我明白了，那恐怕就是阿尔萨斯的心脏……里面残留着他的最后一点尚未泯灭的人性。$B$B这是圣光的启示。只要这颗心脏仍然存在，阿尔萨斯·米奈希尔就有可能变回人类！$B$B我们到大教堂的入口处汇合吧。记得带一件教徒的兜帽来，我们要乔装混进去。"
D.SharedStrings[10099]="就在荆棘谷藏宝海湾的西北边，有一处藏宝点位于加尼罗哨站的雕像附近。$b$b前往那个雕像领取你的奖赏，$c。"
D.SharedStrings[10100]="就在那裡。希望黎利斯給的是好消息…"
D.SharedStrings[10101]="就是你了，断钢者（25人）"
D.SharedStrings[10102]="就是你了，符文大师莫尔基姆（10人）"
D.SharedStrings[10103]="就是你了，符文大师莫尔基姆（25人）"
D.SharedStrings[10104]="就跟我所擔憂的一樣。希望他們現在不敢再派間諜出來了。"
D.SharedStrings[10105]="尼古拉斯·瑟伦霍夫公爵"
D.SharedStrings[10106]="尼姆·杰码"
D.SharedStrings[10107]="尼托格·雷塔"
D.SharedStrings[10108]="尼米·辉城的宠物"
D.SharedStrings[10109]="尼索格的子嗣"
D.SharedStrings[10110]="尼诺洛克奋力扇动翅膀，制造一股强风，快速扇开周围的敌人。"
D.SharedStrings[10111]="尽快猎杀足够的野生火鸡来获得对火鸡的全面胜利。"
D.SharedStrings[10112]="尽管不太中看，但这把利刃可是削铁如泥。"
D.SharedStrings[10113]="尽管你已经打遍外域无敌手，可还有诺森德在等着你呢！$B$B你现在必须击败四位驯宠师：嚎风峡湾的毕格·爆索、晶歌森林的差点没头的雅各布、龙骨荒野的奥克鲁特·荒龙和祖达克的格特瑞奇。$B$B要是你能将他们悉数打败，那么诺森德的驯宠宗师一定会对你发出挑战！"
D.SharedStrings[10114]="尽管击败地面上的天灾士兵至关重要，但我们也不能疏忽了死亡之门的威胁。$B$B城墙上的血肉巨人可以投掷巨大的石块和冰块，对下面的部队造成毁灭性的伤害。$B$B集合一支队伍去干掉那些巨人。我们必须要对敌人有足够的了解。$B$B啊，对了……把它们的脊骨给我带回来。如果我没记错的话，那东西有一些特别的用处。"
D.SharedStrings[10115]="尽管大部分食人魔生来就有两只眼睛，但每一代中总有一小撮食人魔会出现返祖现象，生来就只有一只眼睛。大部分氏族都认为这些食人魔拥有超凡的力量，注定会成为大人物。有一个倒霉的独眼食人魔法师在一次决斗中丢失了自己的眼睛，于是就将这块拳头大的石头代替它塞入眼眶，结果却发现它有着魔法属性。"
D.SharedStrings[10116]="尽管最佳的学习途径是借由了解简单金属的属性而逐步提升，但也可以通过掌握幽冥铁的各种应用方法，制作日常家用物品来成为一名优秀的铁匠。要是你希望以这种方式成为禅师级锻造大师，我可以教你如何开始。不论你选择哪种途径，如果你能制作出一把幽冥万能钥匙并拿给我看，你就会赢得我的尊重。"
D.SharedStrings[10117]="尽管有许多凹痕和擦痕，你还是可以分辨出这把曾经风光无限的锤子上蚀刻着黑石氏族的印记。黑石氏族是第一个掌握黑石熔炼技术的兽人氏族。这种矿石正是以他们的氏族名称命名的。因此，黑石兽人偏好在战斗中使用钝头武器，以纪念他们的祖先。"
D.SharedStrings[10118]="尽管阿古斯的核心散发着危险的能量，猎魂者却可以在燃烧王座随意走动。我们的斥候报告说他的舰船拥有恶魔符文的力量，可以抵达安全抵达邪能圣堂。\n\n如果我们能得到这些符文，维迪卡尔就可以使用这条航线。这可以为我们的部队节省宝贵的时间。"
D.SharedStrings[10119]="尾巴用力抽打，将尘土泥石甩向空中，造成越来越高的自然伤害，并降低{1}%的目标命中几率。"
D.SharedStrings[10120]="居然成功了，卡萊德斯不敢相信！儀式失敗，暗影議會全軍覆沒，而且我們沒死！\r\n\r\n喔，還有你拿到權杖！這是我們的大勝利！"
D.SharedStrings[10121]="展平的羊皮纸上写着一段文字，书写者似乎承受了某种极端的痛苦。"
D.SharedStrings[10122]="展现奔波尔霸的终极形态。"
D.SharedStrings[10123]="展览馆管理员"
D.SharedStrings[10124]="属性提高{1}%。"
D.SharedStrings[10125]="屠夫拉佐克劳"
D.SharedStrings[10126]="屠夫锁定近战范围内人群最多的地方并对其造成大量物理伤害。该伤害由人群中的所有目标分摊。\r\n被顺劈斩击中的受害者将受到龟裂创伤影响。"
D.SharedStrings[10127]="屠龙勇士霍鲁兹的破盾"
D.SharedStrings[10128]="屠龙者格鲁尔"
D.SharedStrings[10129]="山丘之王的遗产"
D.SharedStrings[10130]="山地徘徊者"
D.SharedStrings[10131]="山岭之王投下了最长的阴影。"
D.SharedStrings[10132]="山岭巨人灵魂精华"
D.SharedStrings[10133]="山岳贤者便鞋"
