D.SharedStrings[10137]="山岳贤者毁灭之石"
D.SharedStrings[10138]="山岳贤者毁灭戒指"
D.SharedStrings[10139]="山岳贤者毁灭指环"
D.SharedStrings[10140]="山岳贤者毁灭斗篷"
