D.SharedStrings[10145]="山岳贤者长袍"
D.SharedStrings[10146]="山泽正在岛中央将雕像集结成一支大军，日夜不休地滋扰我们的防线。将你看到的会走路的雕像全都消灭。我们的防御者会对你感激不尽的。"
D.SharedStrings[10147]="山泽灵爪刺客"
D.SharedStrings[10148]="山泽腾云翔龙"
D.SharedStrings[10149]="山脉之心"
D.SharedStrings[10150]="山谷德鲁伊"
D.SharedStrings[10151]="山谷行者法罗丁"
D.SharedStrings[10152]="山麓矿场步兵"
D.SharedStrings[10153]="岑塔布拉"
D.SharedStrings[10154]="岩浆喷射到空中并落到战场上，在指定区域内造成火焰伤害。"
D.SharedStrings[10155]="岩灰原始恐角龙"
D.SharedStrings[10156]="岩石看守者阿尔卡冯"
D.SharedStrings[10157]="峡湾座狼幼崽"
D.SharedStrings[10158]="峡谷中的战斗"
D.SharedStrings[10159]="峡谷深处的大门被关闭了。我们的侦查表明，他们的车队里载着一些箱子，里面的某种石头可以打开大门。$B$B去守卫的尸体上找一把箱子钥匙来。找到以后，就用它打开车队里的一个箱子，将门石给我带来。"
D.SharedStrings[10160]="崔丝提亚中尉"
D.SharedStrings[10161]="崔利艾克斯"
D.SharedStrings[10162]="崔利艾克斯被清洁者人格占据，想要将整个团队从这个世界上清除。"
D.SharedStrings[10163]="崔利艾克斯被看管者人格占据，不再抱有敌意。"
D.SharedStrings[10164]="崛起吧，勇士"
D.SharedStrings[10165]="巡视者加戈玛"
D.SharedStrings[10166]="巡逻队长加多"
D.SharedStrings[10167]="巢穴主母苏伯妮"
D.SharedStrings[10168]="巢穴捍卫者处于较低生命值，使所有附近的捍卫者的攻击速度提高{1}%。"
D.SharedStrings[10169]="工匠吉兹洛克"
D.SharedStrings[10170]="工匠大师欧沃斯巴克"
D.SharedStrings[10171]="工匠文书 - 侏儒作战小鸡"
D.SharedStrings[10172]="工匠文书 - 巨型瑟银战斧"
D.SharedStrings[10173]="工匠文书 - 瑟银手榴弹"
