D.SharedStrings[10176]="工匠文书 - 邪恶皮甲腰带"
D.SharedStrings[10177]="工匠莫法鲁斯要你杀死10个虚灵盗墓者、5个虚灵巫师、5个节点潜行者和5个虚灵缚法者。$B$B全部搞定之后，激活沙法尔房间的前一个房间中的虚灵传送器。"
