D.SharedStrings[10179]="工头拉泽克拉兹"
D.SharedStrings[10180]="工程学供应商"
D.SharedStrings[10181]="工程学和采矿供应商"
D.SharedStrings[10182]="工程学训练师"
D.SharedStrings[10183]="工程师“洗衣桶”"
D.SharedStrings[10184]="工程师加兹维茨"
D.SharedStrings[10185]="巧克力甜又甜，全都装进彩蛋篮"
D.SharedStrings[10186]="巨力粉碎猛击"
D.SharedStrings[10187]="巨型下水道老鼠"
D.SharedStrings[10188]="巨型元素"
D.SharedStrings[10189]="巨型北地大角鹿"
D.SharedStrings[10190]="巨型土元素"
D.SharedStrings[10191]="巨型地狱火"
