D.SharedStrings[10193]="巨型深渊大嘴鳗"
D.SharedStrings[10194]="巨型火元素"
D.SharedStrings[10195]="巨型烈日行者科多兽"
D.SharedStrings[10196]="巨型白骨蜘蛛"
D.SharedStrings[10197]="巨型盲眼湖鲟"
D.SharedStrings[10198]="巨型空气元素"
D.SharedStrings[10199]="巨型骑乘双头飞龙"
D.SharedStrings[10200]="巨型黑水鞭尾鱼"
D.SharedStrings[10201]="巨大的手臂横扫而过，由此产生的冲击波可以造成{1}点自然伤害。"
D.SharedStrings[10202]="巨大的爆炸，对周围的敌人和建筑物造成伤害。"
D.SharedStrings[10203]="巨大的独眼魔一直在冲击着我们的前线，而且不管我们干掉多少个，敌人似乎都会前仆后继地不断涌来。\n\n这些独眼魔大多数都是从纳格兰遥远西部的破碎悬崖来的。如果我们想在接下来的战斗中立于不败之地，就必须想办法把这些独眼魔从战场上赶走。"
D.SharedStrings[10204]="巨大的独眼魔一直在冲击着我们的前线，而且不管我们干掉多少个，敌人似乎都会前仆后继的不断涌来。\n\n这些独眼魔大多数都是从纳格兰遥远西部的破碎悬崖来的。如果我们想在接下来的战斗中立于不败之地，就必须想办法把这些独眼魔从战场上赶走。"
D.SharedStrings[10205]="巨大的玛戈隆、戈隆还有其它石头怪物一直威胁着我们的要塞。它们大多数都是从北边的玛戈纳洛克来的。\n\n如果我们突袭它们的老巢，应该就能迫使敌人撤退了。虽然这样做有风险，但却是眼下最好的对策。在那的时候顺便找回我们的补给品吧。"
D.SharedStrings[10206]="巨大的玛戈隆、戈隆还有其它石头怪物一直威胁着我们西边哨站的安全。它们大多数都是从霜火岭的玛戈纳洛克来的。\n\n如果我们突袭它们的老巢，应该就能迫使敌人撤退了。虽然这样做有风险，但却是眼下最好的对策。在那的时候顺便找回我们的补给品吧。"
D.SharedStrings[10207]="巨大的锣声会唤醒远古之神贝瑟克。"
D.SharedStrings[10208]="巨大的鳗鱼卵"
D.SharedStrings[10209]="巨石将目标击退并造成{1}点物理伤害。"
D.SharedStrings[10210]="巨钳鲁克玛尔"
D.SharedStrings[10211]="巨魔仆从伍迪"
D.SharedStrings[10212]="巨魔已将一个巨大的构造体部署在南边的路上，阻碍了我们岛屿四周的通行。去帮我们除掉障碍，$c。"
D.SharedStrings[10213]="巨魔炸药"
D.SharedStrings[10214]="巨龙之怒，泰蕾苟萨的寄魂杖"
D.SharedStrings[10215]="巨龙之怒，泰蕾苟萨的寄魂杖（公会版）"
D.SharedStrings[10216]="巨龙之魂"
D.SharedStrings[10217]="巨龙之魂的力量形成一道无法穿透的屏障。"
D.SharedStrings[10218]="巨龙找到他的目标，造成毁灭性的火焰伤害！"
D.SharedStrings[10219]="巨龙的女王"
D.SharedStrings[10220]="巫医祖穆拉恩"
D.SharedStrings[10221]="巫妖王 - 最常杀死的10人团队首领"
D.SharedStrings[10222]="巫妖王 - 最常杀死的25人团队首领"
D.SharedStrings[10223]="巫妖王 - 最常杀死的5人地下城首领"
D.SharedStrings[10224]="巫妖王 - 杀死10人团队首领的次数"
D.SharedStrings[10225]="巫妖王 - 杀死25人团队首领的次数"
D.SharedStrings[10226]="巫妖王 - 杀死5人地下城首领的次数"
D.SharedStrings[10227]="巫妖王 -10人团队副本完成次数（杀死最终首领）"
D.SharedStrings[10228]="巫妖王 -25人团队副本完成次数（杀死最终首领）"
D.SharedStrings[10229]="巫妖王 -5人副本完成次数（杀死最终首领）"
D.SharedStrings[10230]="巫妖王"
D.SharedStrings[10231]="巫妖王之怒城市攻擊寒冰屏障兔子，BUG測試"
D.SharedStrings[10232]="巫妖王之怒城市攻擊寒冰屏障兔子，小型"
D.SharedStrings[10233]="巫妖王凶残至极，他的亡灵大军总是倾巢而出，瞬间席卷他的敌人。为了挑选足以对抗他的后备勇士，大领主提里奥·弗丁发起了勇气、忍耐力和团队协作力的试炼。他麾下经验丰富的精兵强将会淘汰掉那些缺乏勇气，无法面对铺天盖地亡灵大军的弱者。"
D.SharedStrings[10234]="巫妖王的手下在科雷萨的墙头安装了三种水晶，分别是绝望碎片、恐惧碎片和苦难碎片。一旦我们的部队抵达科雷萨城下，他就会使用这三种水晶进行攻击。$B$B如果让这些水晶完全发动，士兵们的精神就会被痛苦和恐惧压垮。这样一来，天灾军团就可以轻易消灭他们。$B$B去找到那些碎片，摧毁它们，把水晶给我带回来。我们不能让这些武器留在巫妖王手里！"
D.SharedStrings[10235]="巫妖王臭名昭著的坐骑，在收藏家中间广受追捧。"
D.SharedStrings[10236]="巫婆长老"
D.SharedStrings[10237]="差点就正中靶心了！和弗兹尔巴布交谈可以使你快速传送回去。"
D.SharedStrings[10238]="差点没头的雅各布"
D.SharedStrings[10239]="已充能准备就绪。\r\n自动震击附近的无形寄生蟹。"
D.SharedStrings[10240]="已故术士沃加鲁斯·道尔的魔化手稿，记载了许多来自遥远的燃烧军团世界的古老而强大的武器。"
D.SharedStrings[10241]="已经很少有人能认出他是昔日那个金色眼睛的预言之子了，他在这个破碎世界的边缘过着流亡者的生活，但坚定的决心从不曾改变过。抗击燃烧军团，结束他们的远征，这是他心中唯一的念头。$B$B然而，命运奇特而扭曲，给他带来最后一击的却并不是燃烧军团。$B$B我们必须到外域去，重温伊利丹最后的记忆。"
D.SharedStrings[10242]="已经有两口天灾之锅被成功打开了，虽然并不确定你能否继续前进，但我们仍然想要打开剩下的两口天灾之锅。这可以让我们的解药发挥更大的效果！$B$B这次你的目标是嚎哭鬼屋的天灾之锅。那个地方在安多哈尔正东边，相对来说比较靠近被毁坏的城墙。和以前一样，消灭那里的护锅者，拿到它的钥匙。用这只瓶子从锅里取得样品。$B$B祝一切顺利，$n！"
D.SharedStrings[10243]="已被辛德拉古灵祝福"
D.SharedStrings[10244]="已解锁额外的技能。"
D.SharedStrings[10245]="巴图罗·吉塞提"
D.SharedStrings[10246]="巴塔里烈焰召唤者"
