D.SharedStrings[10249]="巴尔格·维普杉克"
D.SharedStrings[10250]="巴拉丁典狱官"
D.SharedStrings[10251]="巴拉丁典狱官战旗"
D.SharedStrings[10252]="巴珊娜·符文图腾"
D.SharedStrings[10253]="巴琳达·斯通赫尔斯"
D.SharedStrings[10254]="巴瑞克·疾风"
D.SharedStrings[10255]="巴瑞碑文!没错，这也许会提供我们非常有用的资料。"
