D.SharedStrings[10289]="布雷兹里克·巴克舒特"
D.SharedStrings[10290]="布雷特·休斯将军"
D.SharedStrings[10291]="布雷者的气垫鞋"
D.SharedStrings[10292]="布鲁塔卢斯"
D.SharedStrings[10293]="希亚玛特的仆从"
D.SharedStrings[10294]="希亚玛特的爪牙"
D.SharedStrings[10295]="希克提克士兵"
D.SharedStrings[10296]="希克提克毁灭者"
D.SharedStrings[10297]="希克提克琥珀飞翼"
D.SharedStrings[10298]="希克提克虫群"
D.SharedStrings[10299]="希兹·“千里眼”·密集轰炸"
D.SharedStrings[10300]="希奈丝特拉周期性地召唤一组五条暮光雏龙来攻击入侵者。"
D.SharedStrings[10301]="希姆埃巴的祝福"
D.SharedStrings[10302]="希姆托加的祝福"
D.SharedStrings[10303]="希姆鲁克的祝福"
D.SharedStrings[10304]="希尔加·奈辛瓦里"
D.SharedStrings[10305]="希尔斯布莱德丘陵"
D.SharedStrings[10306]="希尔斯布莱德丘陵任务"
D.SharedStrings[10307]="希尔斯布莱德之战"
D.SharedStrings[10308]="希尔斯布莱德平民"
D.SharedStrings[10309]="希尔斯布莱德狼人"
D.SharedStrings[10310]="希尔斯布莱德的胜利"
D.SharedStrings[10311]="希尔格林"
D.SharedStrings[10312]="希尔格林的伙伴"
D.SharedStrings[10313]="希尔瓦娜斯·风行者"
D.SharedStrings[10314]="希尔瓦娜斯·风行者要求你将她的密信交给杜隆塔尔首都奥格瑞玛的萨鲁法尔大王。"
D.SharedStrings[10315]="希尔瓦娜斯的歌声提高了你的战斗力。"
D.SharedStrings[10316]="希尔瓦娜斯的残影"
D.SharedStrings[10317]="希尔达·盘角"
D.SharedStrings[10318]="希拉柯丝女士"
D.SharedStrings[10319]="希拉柯丝海潮女祭司"
D.SharedStrings[10320]="希望之光护肩"
D.SharedStrings[10321]="希望你不是个怕弄脏自己的人。看你的风尘仆仆的样子，这应该不是问题。$b$b在北边的熔岩边上，有一堆堆的暗色泥土。我需要这东西。$b$b如果你不问问题，只管埋头执行命令就最好了，$n。"
D.SharedStrings[10322]="希望你是做好了準備才進入這座城市。時候到了。"
D.SharedStrings[10323]="希望寻找合适的能量源的事不会太麻烦。"
D.SharedStrings[10324]="希望會有更多人跟隨他們。\r\n\r\n感謝你讓他們知道，要為夜裔效力還有其他的選擇。"
D.SharedStrings[10325]="希望破坏者威利"
D.SharedStrings[10326]="希萨莉·黑鸦"
D.SharedStrings[10327]="希萨莉·黑鸦是一位执掌天空的猛禽德鲁依。"
D.SharedStrings[10328]="希萨莉·黑鸦有几率出现，对附近的所有敌人造成大量伤害。"
D.SharedStrings[10329]="希萨莉正在跟随你。"
D.SharedStrings[10330]="希赛克的备用长弓"
D.SharedStrings[10331]="帕奇维克陪你玩（25人）"
D.SharedStrings[10332]="帕拉克希斯号"
D.SharedStrings[10333]="帕拉克希斯号发出一股席卷上层船体的邪能脉冲。船上的所有玩家都将死亡。"
D.SharedStrings[10334]="帕拉克希斯号向位于安托兰废土的所有敌人发射致命的火炮轰击，对军团的敌人们造成火焰伤害。"
D.SharedStrings[10335]="帕拉克希斯审判官"
D.SharedStrings[10336]="帕瓦尔·雷瑟上尉"
D.SharedStrings[10337]="帕米拉·雷德帕斯"
D.SharedStrings[10338]="帕米拉的洋娃娃"
D.SharedStrings[10339]="带上生命之水，将它倒在淹死的矮人尸体上。$B$B生前他与金属为伍，如今湖水浸透他的肉身。你想知道的一切，生命之水都会让他告诉你。$B$B你知晓答案后，请立即离开我的领地。"
D.SharedStrings[10340]="带上精美的战斗号角前往龙眠神殿，看看那里有谁可以评估一下这潜在的威胁。"
D.SharedStrings[10341]="带上这个小发明就能解决你几乎所有的问题。它还能帮忙抗斧头、十字弩，而且样子拉风。"
D.SharedStrings[10342]="带上这颗生命水晶，也让你的同伴们都各拿上一颗。它蕴含着龙骨荒野巨龙圣地的力量。正是靠着这种力量，我才能抵抗黑暗魔法这么长的时间。$B$B当你与辛达苟萨作战的时候，要先尽量削弱他，然后让你们队伍中的四个人一同使用生命水晶，吸出被封锁在她躯体内的灵魂。然后当你击败辛达苟萨之后，就可以收取她的灵魂，并将这个灵魂送到龙骨荒野的龙眠神殿。"
D.SharedStrings[10343]="带电的巨石对目标造成{1}点自然伤害，并将其击倒在地。"
D.SharedStrings[10344]="带着一顶有趣的帽子。"
D.SharedStrings[10345]="带着你的钢铁保卫者的精华去找大主教玛拉达尔，从他那里选一件合用的装备吧。"
D.SharedStrings[10346]="带着你的钢铁保卫者的精华去找女伯爵莉亚德琳，从她那里选一件合用的装备吧。"
D.SharedStrings[10347]="带着你的钢铁征服者的精华去找大主教玛拉达尔，从他那里选一件合用的装备吧。"
D.SharedStrings[10348]="带着你的钢铁征服者的精华去找女伯爵莉亚德琳，从她那里选一件合用的装备吧。"
D.SharedStrings[10349]="带着你的钢铁胜利者的精华去找大主教玛拉达尔，从他那里选一件合用的装备吧。"
D.SharedStrings[10350]="带着你的钢铁胜利者的精华去找女伯爵莉亚德琳，从她那里选一件合用的胜利者装备吧。"
D.SharedStrings[10351]="带着酒桶的林精。只要他们不把酒桶和火混到一块儿去，就不会有事的……"
D.SharedStrings[10352]="带领圣光军团进入燃烧军团不可侵犯的首都与之战斗，并彻底消灭他们！"
D.SharedStrings[10353]="带领着一只冬日麋鹿。"
D.SharedStrings[10354]="席瓦拉·索格蕾"
D.SharedStrings[10355]="席瓦莱恩男爵"
D.SharedStrings[10356]="席瓦莱恩男爵召唤狼人灵魂来协助他！"
D.SharedStrings[10357]="帮助下列小动物对坏蛋火元素进行复仇。"
D.SharedStrings[10358]="帮助大法师卡德加击退钢铁部落并关闭塔纳安丛林里的黑暗之门！"
D.SharedStrings[10359]="帮助奔波尔霸。"
D.SharedStrings[10360]="帮助布莱恩找到他的泰坦遗物的所有碎片。"
D.SharedStrings[10361]="帮助迦罗娜清除暴风城里的隐蔽之手邪教徒。"
D.SharedStrings[10362]="帮避难谷地的斯奎尔图找到特雷莱恩的符咒魔杖，并把它带回来。"
D.SharedStrings[10363]="帶著元素裝置到奧格瑪的力量谷找血衛士托雷克。"
D.SharedStrings[10364]="帶著元素裝置到暴風要塞找安東上尉。"
D.SharedStrings[10365]="幕间：释放被奴役的灵魂"
D.SharedStrings[10366]="干得太出色了，医生。实在是太出色了。"
D.SharedStrings[10367]="干得好!喔，拜托…请保留篮子!$B$B记得，你总是可以带着更多的贵族花园巧克力回来交换额外的物品。"
D.SharedStrings[10368]="干得好!收集到越多水袋，我们就可以越早脱离这场灾难!继续干，你每给我带回五个水袋，我就会给你相应的奖励。"
D.SharedStrings[10369]="干得好!阴谋之书和三根完整的―呃，只有轻微损伤的导能魔棒。$B$B真有趣，我记得已经很久没有一个像你这样年轻的术士可以召唤恶魔猎犬了。"
D.SharedStrings[10370]="干得好。和其它骁士对战是准备联赛的最佳方法。我知道你一定会让我们引以为傲的，$N。"
D.SharedStrings[10371]="干得好，$C!在你的帮助下，部落取得了战歌峡谷的胜利!"
D.SharedStrings[10372]="干得好，$C。$B$B<博学者莱德罗斯从书中撕出一页。>$B$B我相信你会发现这个配方很有用的。"
D.SharedStrings[10373]="干得好，$C。如果你找到更多的书籍，请尽快把它交给我们。$B$B随着时间的推移，我们计画进行一些改变，并增加交还书籍后的奖励。"
D.SharedStrings[10374]="干得好，$N!炫彩黎明披肩是你的了!$B$B只要你能够一直在银色黎明中保持受人崇拜的声望，那么你就可以从银色黎明组织的任何一个军需官那里购买更多的炫彩黎明披肩。"
D.SharedStrings[10375]="干得好，$N―这种东西只要经过处理就可以帮助我们净化费伍德森林。拿着这些塞纳里奥植物药膏，然后回到森林中去吧。夺回费伍德森林的任务迫在眉睫，$N!"
D.SharedStrings[10376]="干得好，$N…你赢得了节庆酿酒师的信任，获得了借用啤酒节骑乘用山羊的资格。"
D.SharedStrings[10377]="干得好，$N。你在亚什虫巢攻击行动中的卓越表现已经引起了关注。"
D.SharedStrings[10378]="干得好，$N。你在佐拉虫巢攻击行动中的卓越表现已经引起了关注。"
D.SharedStrings[10379]="干得好，$N。你的行动，对我们在地狱火半岛上的战事，有相当的助益。"
D.SharedStrings[10380]="干得好，$N。对那些习惯于步兵战斗的人，骑乘战斗可是很难上手的。我相信你会继续精进你的技巧，应该不需要我多言。"
D.SharedStrings[10381]="干得好，$N。当大德鲁伊需要晨光麦时，我会把这些交给他的。同时，请收下这个作为塞纳里奥议会对你的酬谢。$B$B我们对晨光麦的需求量非常大，如果你想要继续帮助我们的话，那么当你种植出更多的晨光麦之后就把它们交给我。"
D.SharedStrings[10382]="干得好，$N。我几乎可以听见在那些堡垒中开展的战事。我真希望我在现场观看!"
D.SharedStrings[10383]="干得好，$n！后面已经安全。剩下的散兵就交给我们来对付吧。我要你返回南面的北郡修道院前，向治安官玛克布莱德复命，告诉他滋事的地精已经被清理了。$B$B再见，$c。"
D.SharedStrings[10384]="干得好，这是给你的塞纳里奥植物药膏，回到费伍德森林中去，拯救这片堕落的土地吧!"
D.SharedStrings[10385]="干得好，这里是一些塞纳里奥植物药膏。如果你能在费伍德森林采矿过程中找到更多的硝酸盐的话，记得一定要把它们交给我!这东西越多，我就能造成越多的药膏来。"
D.SharedStrings[10386]="干得漂亮!要学会怎么操控你的山羊得花上不少时间。当你一旦做到，你就会希望每只山羊都是竞速山羊。$B$B你说什么?“我的报酬在哪里?”哈哈哈…你得试试最快的山羊!你想要更多?那这样如何…$B$B你赢得了替啤酒节服务的权力，那边有许路复用作可做，有许多的报酬。尤其是对一个年轻急躁的山羊赛手。"
D.SharedStrings[10387]="干得漂亮，$N。我们不惜任何代价也要维持疆界的完整!"
D.SharedStrings[10388]="干得漂亮，$N。我们离拯救艾泽拉斯又更近了一步!"
D.SharedStrings[10389]="干得漂亮，$N。那些混帐东西罪有应得。既然我的船和我的水手们已经不在了，那么就让这些纳迦的死给我带来一些安慰吧。"
D.SharedStrings[10390]="干得漂亮，指挥官。然而，我们还需要更多的经验和资源才能升级这座船坞。等我们达到目标之后，我们就能提升船坞的容量，拥有更多舰船了！"
D.SharedStrings[10391]="干扰X个不稳定的传送门，击败1个世界首领。"
D.SharedStrings[10392]="干扰一颗腐化的龙蛋，使一只怨嗣雏龙破卵而出，并开始进食。"
D.SharedStrings[10393]="干的太好了，$N！人们将蜂拥而至抢购香水，他们也会对之前的试用样品感到惊喜的。$B$B这也是在帮我们摆脱困境。"
D.SharedStrings[10394]="平均每日完成的任务数量"
D.SharedStrings[10395]="平均每日完成的日常任务数量"
D.SharedStrings[10396]="平均每日获得的金币数量"
D.SharedStrings[10397]="平静并沉默。"
D.SharedStrings[10398]="年轻人$C，你进步神速。或许是该让你加入塞拉利卡―赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。"
D.SharedStrings[10399]="年轻的冒险者们，注意了！灰谷的野兽正在等着你们！$B$B部落在贫瘠之地以北的区域建立了强大的基地。我们的两个前哨站——碎木哨岗和佐拉姆海岸哨岗——正在努力地为部落的荣耀而战！想要证明自己能力的勇士就到那儿去吧。碎木岗哨位于贫瘠之地的正北方，塞娜尼·雷心正在那里招募愿意参与灰谷狩猎中的冒险者！"
D.SharedStrings[10400]="年轻的德鲁伊，很高兴今天可以在这里看到你。现在是你大步迈向一个更广阔世界的时候了。$B$B我们都向往着为自然效力。动物和植物是我们的朋友，也是我们力量的泉源。我们选择为它们，也是为守护自然的平衡而奉献自己的一生。作为进入这个世界的第一步，你首先要学习的是熊之道，以及肉体和心灵所蕴含的力量。$B$B做好准备吧!"
D.SharedStrings[10401]="年轻的德鲁伊，很高兴你在此踏入正途。现在是你大步迈向一个更广阔的世界的时候了。$B$B我们都向往着为自然效力。动物和植物是我们的朋友，也是我们力量的源泉。我们选择为它们，也是为守护自然的平衡而奉献自己的一生。作为进入这个世界的第一步，你首先要学习的是的熊之道，以及肉体和心灵所蕴含的力量。$B$B准备好了!"
D.SharedStrings[10402]="年轻的瓦里安·乌瑞恩"
D.SharedStrings[10403]="年轻的联盟战士"
D.SharedStrings[10404]="并非所有恶魔都能适应混乱，有些恶魔会反感燃烧军团的所作所为。这种恶魔往往会携带一颗魔法宝珠，用来激起一只优秀的恶魔所必不可少的怒火。没有人知道这些宝珠是怎样做成的，或是谁制作了它们。"
D.SharedStrings[10405]="并非所有灵魂都被磨魂者尽数消灭，有些灵魂像我一样或多或少地保持了完整。其它那些却被扭曲并发狂了。$B$B去结束它们的痛苦吧，拿上我的灵魂碎片去净化它们。愤怒遮蔽了它们的双眼，使它们对碎片能量的效力视若不见，所以你必须先将其击败才能使用碎片。"
D.SharedStrings[10406]="并非每一个至高岭牛头人都是猎人，但通常每位猎人都会用一面仪式战鼓来作为自己第一次杀死猎物的纪念，制作这面鼓用的皮子就是从那只猎物身上剥下来的。大多数启程之鼓是用兔皮或狐皮做成的。这面战鼓往往会伴随猎人度过他的一生。"
D.SharedStrings[10407]="幸好有你，我们才能安全地来到这里。"
D.SharedStrings[10408]="幸运卡片"
D.SharedStrings[10409]="幸运魁麟幼崽"
D.SharedStrings[10410]="幻化套装"
D.SharedStrings[10411]="幻影和虚空之门的链接使其在攻击时会造成额外的暗影伤害。"
D.SharedStrings[10412]="幻术师多米尼卡"
D.SharedStrings[10413]="幻灭猛击还会使目标对你的下一次自动攻击的伤害降低{1}%。"
D.SharedStrings[10414]="幼年其拉守护者"
D.SharedStrings[10415]="幼年原始魔暴龙"
D.SharedStrings[10416]="幼年双头飞龙"
D.SharedStrings[10417]="幼年变异战龟"
D.SharedStrings[10418]="幼年多头蛇"
D.SharedStrings[10419]="幼年大角鹿"
D.SharedStrings[10420]="幼年毒牙风蛇"
D.SharedStrings[10421]="幽暗城冠军"
D.SharedStrings[10422]="幽暗城守护者"
D.SharedStrings[10423]="幽灵虎幼崽"
D.SharedStrings[10424]="广泛记载了许多在艾泽拉斯历史上占有一席之地的伟大武器。"
D.SharedStrings[10425]="庆祝冬幕节的奇迹！"
D.SharedStrings[10426]="库卡隆刺客"
D.SharedStrings[10427]="库卡隆劫掠者"
D.SharedStrings[10428]="库卡隆忠诚护肩"
D.SharedStrings[10429]="库卡隆战争使者"
D.SharedStrings[10430]="库卡隆战争萨满"
D.SharedStrings[10431]="库卡隆战狼"
D.SharedStrings[10432]="库卡隆手持火炮"
D.SharedStrings[10433]="库卡隆投石车"
D.SharedStrings[10434]="库卡隆护卫"
D.SharedStrings[10435]="库卡隆指挥官"
D.SharedStrings[10436]="库卡隆狙击手"
D.SharedStrings[10437]="库卡隆监视者"
D.SharedStrings[10438]="库卡隆突击队"
D.SharedStrings[10439]="库卡隆精英"
D.SharedStrings[10440]="库卡隆精锐骷髅面具"
D.SharedStrings[10441]="库卡隆织魔者"
D.SharedStrings[10442]="库卡隆蛮兵"
D.SharedStrings[10443]="库卡隆钢铁之星"
D.SharedStrings[10444]="库卡隆铁刃战士"
D.SharedStrings[10445]="库卡隆铁甲哨兵"
D.SharedStrings[10446]="库卡隆防御者"
D.SharedStrings[10447]="库卡隆霸权之杖"
D.SharedStrings[10448]="库卡隆黑暗萨满"
D.SharedStrings[10449]="库古克的刚毅肩甲"
D.SharedStrings[10450]="库古克的强力践踏震碎地面，使附近玩家的移动速度降低。该效果可以叠加。"
D.SharedStrings[10451]="库塔洛斯·拉文凯斯"
D.SharedStrings[10452]="库尔克罗什将军"
D.SharedStrings[10453]="库尔塔兹领主"
D.SharedStrings[10454]="库尔提克掠夺者"
D.SharedStrings[10455]="库尔提克精英剑圣"
D.SharedStrings[10456]="库尔提拉斯水兵"
D.SharedStrings[10457]="库尔森特种部队"
D.SharedStrings[10458]="库尔迪拉·织亡者"
D.SharedStrings[10459]="库德兰·蛮锤"
D.SharedStrings[10460]="库拉·雷蹄"
D.SharedStrings[10461]="库拉伦双头怪"
D.SharedStrings[10462]="库斯卡侍从"
D.SharedStrings[10463]="库斯卡唤海者"
D.SharedStrings[10464]="库斯卡持戟者"
D.SharedStrings[10465]="库斯卡队长"
D.SharedStrings[10466]="库纳库纳，卡兹拉金的斩首斧"
D.SharedStrings[10467]="废墟行者的涌砂斗篷"
D.SharedStrings[10468]="废弃的实验品"
D.SharedStrings[10469]="废灵者达库尔"
D.SharedStrings[10470]="废灵者达库尔必须死！"
D.SharedStrings[10471]="废物贩卖机器人制造器"
D.SharedStrings[10472]="度假旅客"
D.SharedStrings[10473]="座狼训练：凶残的食人魔"
D.SharedStrings[10474]="座狼训练：铁颚狼"
D.SharedStrings[10475]="康·棘杖"
D.SharedStrings[10476]="康的骄傲常常会让他自信过头，这也导致他总是身涉险境。他现在的处境一点也不乐观——他正朝着卡桑琅丛林的深处走去。$b$b我一般不会请求陌生人的帮助，不过……你能去找找他，确保他安然无恙吗？这样我才会放心一点，因为我知道有一位勇敢的$r正照顾着他。"
D.SharedStrings[10477]="建筑师斯卡瓦尔德"
D.SharedStrings[10478]="建筑师的应急手段使你受到的元素伤害降低{1}%。\r\n\r\n只有当你处于黑石岩窟中的时候才会生效。"
D.SharedStrings[10479]="建筑设计桌"
D.SharedStrings[10480]="建造一艘可用于海军行动的新舰船。"
D.SharedStrings[10481]="建造专业技能建筑"
D.SharedStrings[10482]="建造任意的专业技能建筑。"
D.SharedStrings[10483]="建造暗夜要塞时，我的人民铸造了一块护符，用它就可以进入这些大厅。有了护符的力量，我们就可以畅通无阻地穿过王宫，直接面对大魔导师了。利用暗夜井碎片的力量，我们就可以找到护符，结束这场愚蠢的战争……"
D.SharedStrings[10484]="开启一个召唤指定队友的传送门。需要施法者和2名队友共同完成召唤仪式。所有参与召唤的队友都必须使用右键点击传送门，并且在召唤完成之前不得移动。"
D.SharedStrings[10485]="开启一场制造召唤传送门的仪式，需要施法者和一名盟友共同完成。该传送门可以用来召唤小队和团队成员。"
D.SharedStrings[10486]="开启一道传送门，你可以通过它返回黑锋要塞。\r\n\r\n在黑锋要塞内使用该法术可以将你送回原先离开的地方。"
D.SharedStrings[10487]="开启一道传送门，死亡骑士可以通过它返回黑锋要塞。\r\n\r\n在黑锋要塞内使用该法术可以将施法者送回原先离开的地方。"
D.SharedStrings[10488]="开启后将进入杂草清理者模式。把这些植物全都清理干净！再次使用将关闭杂草清理者模式。"
D.SharedStrings[10489]="开启黑暗之门"
D.SharedStrings[10490]="开始一项研究工作的订单。"
D.SharedStrings[10491]="开始任务"
D.SharedStrings[10492]="弄到一张发臭的卡片，并把它交给幽暗城的芬斯塔·艾吉勒。"
D.SharedStrings[10493]="弄清楚如何制作任务"
D.SharedStrings[10494]="弄潮女瑟瑞维丝"
D.SharedStrings[10495]="弑君者"
D.SharedStrings[10496]="弑君者奥尔库斯"
D.SharedStrings[10497]="弓箭和枪械"
D.SharedStrings[10498]="弓箭商"
D.SharedStrings[10499]="弓箭手小队"
D.SharedStrings[10500]="弓背是用一块岩石般坚硬的木材刻成的，几乎没法拉开。这把弓是从一开始就这么坚硬，还是因为随着时光的流逝石化了？考古学家们一直争论不休。无论如何，它的尺寸与重量都表明，只有最富有经验的牛头人猎人才能够使用它。"
D.SharedStrings[10501]="引发一次强烈地震将敌人击退，并造成{1}点自然伤害。"
D.SharedStrings[10502]="引导一个暮光裂隙，对其它领域的敌人造成伤害。"
D.SharedStrings[10503]="引导一场落石，对站在坠落碎片下的目标造成自然伤害。"
D.SharedStrings[10504]="引导一次地震，对邻近敌人造成自然伤害。"
D.SharedStrings[10505]="引导一股火焰风暴来攻击敌人。"
D.SharedStrings[10506]="引导一道死亡光束。引导的时间越长，打击的目标就越多，伤害也越高。"
D.SharedStrings[10507]="引导一阵猛烈的邪火风暴。"
D.SharedStrings[10508]="引导一阵猛烈的邪火风暴，对所有敌人造成火焰伤害。"
D.SharedStrings[10509]="引导强大的泰坦能量风暴，周期性地向敌方目标发射足以摧毁虚弱的不朽生物的闪电箭。"
D.SharedStrings[10510]="引导拉格纳罗斯真正的力量。使施法者受到的物理和魔法伤害降低{1}%。"
D.SharedStrings[10511]="引导湍流汹涌的流水，对附近的敌人造成冰霜伤害。"
D.SharedStrings[10512]="引导火蛇之灵对一名随机敌人造成{1}点火焰伤害。"
D.SharedStrings[10513]="引导灵魂之力，使附近的盟友免疫所有伤害和效果。不会影响施法者。"
D.SharedStrings[10514]="引导灼热的毁灭光柱。"
D.SharedStrings[10515]="引导烈焰灼烧敌人，对施法者前方锥形区域内的敌人周期性造成{1}点火焰伤害。"
D.SharedStrings[10516]="引导烈风，将敌人向后推去。"
D.SharedStrings[10517]="引导熔火之心的烈焰对所有邻近的敌人造成火焰伤害。伤害会随着地狱火的引导时间增加。"
D.SharedStrings[10518]="引导符文林地的力量，使一位弱化的无法安息的先祖重返大地。"
D.SharedStrings[10519]="引导自然的力量，召唤复仇的树苗攻击敌人。"
D.SharedStrings[10520]="引导蕴魔之血至目标体内，摧毁施法者并为目标恢复{1}点生命值。"
D.SharedStrings[10521]="引导邪能之槌号发射大片的弹幕，轰炸燃烧军团的部队。"
D.SharedStrings[10522]="引导邪能，对施法者前方的敌人造成火焰伤害。"
D.SharedStrings[10523]="引导闪电风暴。"
D.SharedStrings[10524]="引导黑暗之蚀，对所有玩家造成{1}点暗影伤害，并感染月之符文。"
D.SharedStrings[10525]="引导黑暗元素能量进入附近无法穿透的风所组成的盾墙。"
D.SharedStrings[10526]="引爆吉尔尼斯重磅炸药。在引爆前站远点！"
D.SharedStrings[10527]="引爆奥术能量，造成{1}点奥术伤害。"
D.SharedStrings[10528]="引爆烟花炸药桶，对附近的敌人造成{1}点火焰伤害。"
D.SharedStrings[10529]="引爆隐藏的炸药，将碎颅者魔山从暮光之门引开。"
D.SharedStrings[10530]="引领潮流：加尔鲁什·地狱咆哮（10人）"
D.SharedStrings[10531]="引领潮流：加尔鲁什·地狱咆哮（25人）"
D.SharedStrings[10532]="引领潮流：大女皇夏柯希尔"
D.SharedStrings[10533]="弗兰克罗恩·铸铁的烟斗"
D.SharedStrings[10534]="弗加拉什的船首像"
D.SharedStrings[10535]="弗喬里克為詹德維克而死，我們不會忘了他的英勇行為。"
D.SharedStrings[10536]="弗拉斯·希亚比"
D.SharedStrings[10537]="弗拉格尔"
D.SharedStrings[10538]="弗斯塔德·蛮锤"
D.SharedStrings[10539]="弗斯塔德归来号"
D.SharedStrings[10540]="弗林特·岩幔"
D.SharedStrings[10541]="弗林特·沙多摩尔"
D.SharedStrings[10542]="弗林特洛克的冲击枪"
D.SharedStrings[10543]="弗林特洛克的土拨鼠瞄准镜"
D.SharedStrings[10544]="弗林特洛克的海上飞机"
D.SharedStrings[10545]="弗洛克斯"
D.SharedStrings[10546]="弗洛尔的屠龙技术纲要"
D.SharedStrings[10547]="弗莱恩·顿沃德"
D.SharedStrings[10548]="弗莱拉斯总大使"
D.SharedStrings[10549]="弗诺斯·达克维尔"
D.SharedStrings[10550]="弗雷尔·“好帮手”·迅弹"
D.SharedStrings[10551]="张叶的辉煌精华"
D.SharedStrings[10552]="弥拉克兰，热情之弦"
D.SharedStrings[10553]="弧光邪能水晶"
D.SharedStrings[10554]="弹奏一把十二弦吉他。"
D.SharedStrings[10555]="弹射！弹射！"
D.SharedStrings[10556]="强制目标凝视着你。该效果结束后，他会攻击仇恨最高的敌人。"
D.SharedStrings[10557]="强制目标进入赎罪状态。如果他们在持续时间结束前进行移动，就会给周围的盟友造成神圣伤害。"
D.SharedStrings[10558]="强力的一击，让你飞上天空。"
D.SharedStrings[10559]="强力的巫毒法术！你的攻击更加强大，你感觉浑身充满了力量。为了暗矛部族！"
D.SharedStrings[10560]="强力的攻击，使近战攻击所造成的伤害提高{1}点。"
D.SharedStrings[10561]="强力的攻击，使近战攻击所造成的伤害提高{1}点，并造成大量的威胁。"
D.SharedStrings[10562]="强力的攻击，造成{1}点额外的物理伤害。"
D.SharedStrings[10563]="强化书籍来寻找失落的远古知识。"
D.SharedStrings[10564]="强化了的感知能够让深渊猎犬嗅探出隐藏的生物。别靠得太近！"
D.SharedStrings[10565]="强化亚煞极之触"
D.SharedStrings[10566]="强化传送门：纳斯雷萨"
D.SharedStrings[10567]="强化你的钝器，使其武器伤害提高{1}点，持续1小时。不能对物品等级高于200的物品使用。"
D.SharedStrings[10568]="强化护甲"
D.SharedStrings[10569]="强化施法者的武器，每次命中敌人都有一定几率造成{1}点额外火焰伤害。"
D.SharedStrings[10570]="强化潜行。"
D.SharedStrings[10571]="强化潜行侦测。"
D.SharedStrings[10572]="强化的奥术畸兽"
D.SharedStrings[10573]="强化腐蚀会为附近亚煞极的爪牙恢复满生命值，并提高其{1}%的最大生命值和{2}%的伤害。该效果可叠加。"
D.SharedStrings[10574]="强化腐蚀漩涡"
D.SharedStrings[10575]="强化邪能水晶"
D.SharedStrings[10576]="强化镜光斗篷"
D.SharedStrings[10577]="强化附近的盟友，提高其伤害和治疗效果。施法者生命值越低，则该效果加成越高。"
D.SharedStrings[10578]="强大动物：狮子"
D.SharedStrings[10579]="强大恶魔的眼睛，保存在风暴峡湾的冰冷石头地面中。根据上古之战时期的文献记载，邪能领主统帅乌达维斯的目标是消灭艾泽拉斯所有的生命。"
D.SharedStrings[10580]="强大的传送力量使你感到头晕目眩。"
D.SharedStrings[10581]="强大的信息素阻断了监护者之握。\r\n制造伤害的能力提高{1}%。"
D.SharedStrings[10582]="强大的护甲和武器"
D.SharedStrings[10583]="强大的收割系统对死神前进途中的所有东西都会造成物理伤害。"
D.SharedStrings[10584]="强大的敌人，可供你的神器吸取力量。"
D.SharedStrings[10585]="强大的旋风造成{1}点自然伤害，并将玩家击向空中，降低跌落速度。"
D.SharedStrings[10586]="强大的混沌能量组成的球体包裹着目标。它很快就会被毁灭！"
D.SharedStrings[10587]="强尼·傲森"
D.SharedStrings[10588]="强效塔拉迪特急速水晶"
D.SharedStrings[10589]="强烈的高热使目标失去武器，并让目标的攻击也具有同样热度，使近战攻击能够造成额外的火焰伤害。"
D.SharedStrings[10590]="强风击退了附近的目标。"
D.SharedStrings[10591]="强风吹着你后退。"
D.SharedStrings[10592]="强风对玩家造成{1}点火焰伤害，并将他们击退。"
D.SharedStrings[10593]="强风降低了跌落速度。"
D.SharedStrings[10594]="归属部落阵营。"
D.SharedStrings[10595]="归还战歌峡谷旗帜"
D.SharedStrings[10596]="当“怪医”在场时，你的生命值不会减少。"
D.SharedStrings[10597]="当一块装甲板被掀起时，装甲板连接束会快速地收拢装甲板，使连接束不再受到进一步的伤害，并防止装甲板飞落。"
D.SharedStrings[10598]="当不祥之物距离星术师过近时，星术师受到的伤害降低{1}%。"
D.SharedStrings[10599]="当任意泰坦之魂受到折磨时，造成越来越高的暗影伤害。"
D.SharedStrings[10600]="当你乘坐悬浮之碟时，亲手击杀一名永恒子嗣（10人）。"
D.SharedStrings[10601]="当你乘坐悬浮之碟时，亲手击杀一名永恒子嗣（25人）。"
D.SharedStrings[10602]="当你体验到雪怒之赐所赋予的敏捷时，你感觉整个世界都变慢了！"
D.SharedStrings[10603]="当你使用审判时，灰烬使者会使地面喷发出一道圣火之柱，并追逐你的目标，持续8秒，每1秒造成{2}点伤害。"
D.SharedStrings[10604]="当你使用近战武器造成伤害之后，你的下一个闪电箭、闪电链、次级治疗波、治疗链或治疗波有一定几率获得施法时间缩短{1}%的效果。可以叠加最多5次。"
D.SharedStrings[10605]="当你准备好动身前往索拉查盆地时，就与大法师伯塔鲁斯谈一谈。到达索拉查盆地之后，与蛮藤谷的蒙特谈一谈。"
D.SharedStrings[10606]="当你受到伤害时，丽丽有时会出现，并召唤一只云端翔龙来协助你。云端翔龙会治疗你，并攻击你周围的所有敌人。"
D.SharedStrings[10607]="当你只装备板甲时，你的力量提高{1}%。"
D.SharedStrings[10608]="当你只装备板甲时，你的耐力提高{1}%。"
D.SharedStrings[10609]="当你只装备皮甲时，你的敏捷提高{1}%。"
D.SharedStrings[10610]="当你只装备皮甲时，你的智力提高{1}%。"
D.SharedStrings[10611]="当你只装备锁甲时，你的敏捷提高{1}%。"
D.SharedStrings[10612]="当你只装备锁甲时，你的智力提高{1}%。"
D.SharedStrings[10613]="当你在塞纳留斯附近战斗时可获得他的治疗。"
D.SharedStrings[10614]="当你在巨石之核中的时候，受到的物理伤害降低{1}%。"
D.SharedStrings[10615]="当你在战斗外进入幽魂之狼形态时，雷加尔和你的移动速度都提高{1}%。"
D.SharedStrings[10616]="当你在流沙之鳞中的声望达到尊敬后，将永恒之戒交给时空之穴的索莉多米。"
D.SharedStrings[10617]="当你在流沙之鳞中的声望达到崇拜后，将永恒之戒交给时空之穴的索莉多米。"
D.SharedStrings[10618]="当你在流沙之鳞中的声望达到崇敬后，将永恒之戒交给时空之穴的索莉多米。"
D.SharedStrings[10619]="当你在猎豹形态下时，你会呈现出烈焰德鲁伊的形态。"
D.SharedStrings[10620]="当你在紫罗兰之眼的声望达到尊敬后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。"
D.SharedStrings[10621]="当你在紫罗兰之眼的声望达到崇拜后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。"
D.SharedStrings[10622]="当你在紫罗兰之眼的声望达到崇敬后，将紫罗兰徽记交给逆风小径的大法师蕾尔达。"
D.SharedStrings[10623]="当你带有侏儒美味营养糖效果时，获得10个荣誉击杀。对于敌人来说真是太耻辱了！"
D.SharedStrings[10624]="当你或你的宠物的最大生命值降至{1}%以下时，你获得{2}点全能。"
D.SharedStrings[10625]="当你或你的对手阵亡倒地时打斗就结束了。"
D.SharedStrings[10626]="当你所召唤的恶魔处于激活状态时，你和你所召唤的恶魔的移动速度提高{1}%。该效果不与其它提高移动速度的效果叠加。"
D.SharedStrings[10627]="当你把木桶放在木箱上之后，白蚁就开始不停地忙碌了。"
D.SharedStrings[10628]="当你把这尊雕像放回原位之后，屋里出现了一些新的石像。其中又有一座红宝石色的雕像，在屋中的一处遥远角落的围栏中。你听到了一个声音：$B$B  “哨兵在注视。$b  哨兵在保卫。$b   哨兵预见的，永不会落空。”$b$b屋中另一边的那座红色雕像看样子很重要。也许你应该把这两座红色雕像连起来试试看？"
D.SharedStrings[10629]="当你杀死一个可为你提供经验值或荣誉值的目标时，有一定几率掉落额外金币。"
D.SharedStrings[10630]="当你杀死一个可以为你提供经验值或荣誉值的目标之后，为你恢复相当于你的生命值上限{1}%的生命值。"
D.SharedStrings[10631]="当你死亡的时候，你的装备损失的耐久度减少{1}%。"
D.SharedStrings[10632]="当你潜入主城的废墟时，扎佐始终远远地注视着你。"
D.SharedStrings[10633]="当你潜入卡拉赞周围的废墟时，扎佐始终远远地注视着你。"
D.SharedStrings[10634]="当你潜入庄园时莫奥斯塔兹正在遥远地关注着你。"
D.SharedStrings[10635]="当你的孤儿在一旁观看时，吃掉下列糖果。"
D.SharedStrings[10636]="当你的宠物造成伤害时，你获得一层被窃取的能量。达到100层时，你的下一个暗影箭造成的伤害会显著提高。"
D.SharedStrings[10637]="当你的生命值降至{2}%以下时，你的护甲提高{1}%。"
D.SharedStrings[10638]="当你的队伍占领风暴之眼的4座基地时，夺取旗帜并将其运回基地。"
D.SharedStrings[10639]="当你的食尸鬼使用爪击时，会喷出气体云雾对附近敌人造成伤害，持续6秒。"
D.SharedStrings[10640]="当你获得奥术充能时，有几率触发一枚音波箭，造成{1}点伤害。越长时间不触发音波箭，此伤害就会越高。"
D.SharedStrings[10641]="当你被击中时，福枬会愤怒地舞动，攻击你的敌人。"
D.SharedStrings[10642]="当你触摸底座的时候，奥达曼的迷你白金圆盘在背包里嗡嗡作响，闪闪发光。一种熟悉的刺痛感涌过双手，另一个石之看守者的形像在奥丹姆大门前出现了。$B$B“您好，我是入口的护卫者。您的圆盘缺少了正确的登录圆盘，奥丹姆圆盘。请将所需的圆盘和你手中的圆盘合在一起，然后重新进入。谢谢。”$B$B"
D.SharedStrings[10643]="当你触碰到这块石头时，它就开始嗡嗡作响。"
D.SharedStrings[10644]="当你调查山谷的毁灭情况时，你注意到了一抹亮眼的青铜色。除非你是眼花了——有个身材矮小的侏儒正在魔古山宫殿上方的平台上试图吸引你的注意力，就在闻道之座外面。$b$b你应该去看看她意欲何为。"
D.SharedStrings[10645]="当前你的纠缠根须无法产生一次星涌术的使用机会。"
D.SharedStrings[10646]="当加速时间粒子到达时空畸体时，其能量将被转移到畸体中。"
D.SharedStrings[10647]="当受到伤害时，为目标恢复{1}%的最大生命值。"
D.SharedStrings[10648]="当奥妮克希亚升空后，在10秒内引出50只奥妮克希亚雏龙，随后击败奥妮克希亚（10人）。"
D.SharedStrings[10649]="当奥妮克希亚升空后，在10秒内引出50只奥妮克希亚雏龙，随后击败奥妮克希亚（25人）。"
D.SharedStrings[10650]="当奥杜尔（10人）中的萨拉对你发怒的时候，亲吻（/Kiss）她。"
D.SharedStrings[10651]="当奥杜尔（25人）中的萨拉对你发怒的时候，亲吻（/Kiss）她。"
D.SharedStrings[10652]="当导弹的燃料耗尽，或命中敌人时，会发生爆炸。"
D.SharedStrings[10653]="当巨型恐魔和基尔罗格·死眼互相靠近时，会使彼此造成的伤害提高{1}%，攻击速度提高{2}%。"
D.SharedStrings[10654]="当心！拉文霍德的守卫十分警惕。保持距离。"
D.SharedStrings[10655]="当我们的行动完成时，我将会迷失于黑暗虚空之中。"
D.SharedStrings[10656]="当所有勇士都在竞技中被击败后，玩家必须与其展开近身对决。"
D.SharedStrings[10657]="当控制台的圆形插座打开时，能量在控制台中呼啸流窜。"
D.SharedStrings[10658]="当敌方的旗帜仍在他们的基地中，且敌方成员已经将你方的旗帜运回他们的军旗室时，杀死携带旗帜的敌人。"
D.SharedStrings[10659]="当暗影克隆体消失或死亡时会爆炸，对其最后一个目标造成{1}点火焰伤害。"
D.SharedStrings[10660]="当治疗法术所产生的治疗量超过你最大生命值时，使你可以储存最多{1}点生命值。"
D.SharedStrings[10661]="当泰罗克结束流亡时，他已经遍体鳞伤，无法飞行。关于他被诅咒的流言像野火一样烧遍了整个鸦人族群，造成了迷信符咒和诅咒的盛行。捕梦网被认为是最保险的护符之一，因为鸦人相信诅咒会被捕梦网缠住，并在清晨的阳光照耀下消散。"
D.SharedStrings[10662]="当目标处于暮光领域中时，暮光烈焰对其造成{1}点暗影伤害！"
D.SharedStrings[10663]="当目标身上附有你的毒蛇钉刺时，使你对该目标造成的远程伤害提高{1}%。\r\n\r\n如果你的翼龙钉刺被驱散，则驱散者受到翼龙钉刺的影响，持续时间为被驱散钉刺剩余时间的{2}%。"
D.SharedStrings[10664]="当莫卓克引导大地黑血时，没有任意两名团队成员之间的距离小于5码（在25人模式中，没有任意三名团队成员之间的距离小于5码），并击败莫卓克（普通或英雄难度）。"
D.SharedStrings[10665]="当蝰蛇守护处于激活状态下时，你的远程攻击速度提高{1}%。"
D.SharedStrings[10666]="当被指定为战友时，可以作为保镖陪伴你游历破碎群岛。"
D.SharedStrings[10667]="当邪能小鬼的法力达到最大值时，它会将施法者传送到附近一个随机目的地。"
D.SharedStrings[10668]="当驾驶者离开区域时移除载具身上所有的附加效果。这应该移除控制权。"
D.SharedStrings[10669]="当高贾拉生命值过低时，她的毒液诅咒就会生效。她将变成一条毒蛇，在被击败之前持续施放毒箭弹幕。"
D.SharedStrings[10670]="当鲁克玛受到伤害后，血羽将掉落在地面上。掉落后，它将在荣耀烈焰中爆炸并生成精力充沛的凤凰。"
D.SharedStrings[10671]="形成一道空气漩涡，击退过于靠近的敌人。"
D.SharedStrings[10672]="影卫虚空法师"
D.SharedStrings[10673]="影月仪祭师"
D.SharedStrings[10674]="影月唤雷者"
D.SharedStrings[10675]="影月墓地"
D.SharedStrings[10676]="影月墓地（英雄难度）"
D.SharedStrings[10677]="影月岩浆术士"
D.SharedStrings[10678]="影月掠夺者"
D.SharedStrings[10679]="影月暗法师"
D.SharedStrings[10680]="影月氏族的残余力量继续在阿兰卡峰林东部边界的群山里蠢蠢欲动。\n\n伯德里克·格雷担心他们距离要塞过近，会是个隐患，要求我们尽快削减他们的兵力。"
D.SharedStrings[10681]="影月氏族的残余力量继续在阿兰卡峰林东部边界的群山里蠢蠢欲动。\n\n洛坎担心他们离通往影月谷的咽喉要道过近，会是个隐患，要求我们尽快削减他们的兵力。"
D.SharedStrings[10682]="影月氏族的萨满在做出重大决定时，一定会先向前代祖先的灵魂请教。先祖生前重要的护符和其他遗物可以让萨满与他们进行更清晰的精神沟通。"
D.SharedStrings[10683]="影月氏族督军"
D.SharedStrings[10684]="影月流亡者的鲁尔坎酋长是一位心狠手辣的首领。"
D.SharedStrings[10685]="影月灵斧战士"
D.SharedStrings[10686]="影月灵爪战士"
D.SharedStrings[10687]="影月虚空召唤者"
D.SharedStrings[10688]="影月虚空扭曲者"
D.SharedStrings[10689]="影月虚空萨满"
D.SharedStrings[10690]="影月迅爪战士"
D.SharedStrings[10691]="影踪派传承战裙"
D.SharedStrings[10692]="影踪派受训者"
D.SharedStrings[10693]="影踪派掌门"
D.SharedStrings[10694]="影踪派是潘达利亚最古老的守护者之一。$B$B我们年复一年地在位于昆莱之巅的那座白雪皑皑的禅院中训练，完善着我们祖先传下来的武术秘诀。$B$B我们的人数看来或许不多，但一名影踪派门人就能抵得上一百名训练有素的士兵。$B$B要想加入影踪派，就必须经历一段充满艰辛的旅程。如果你也想走上这条道路，那就必须先证明你的价值。$B$B眼下我们就有一个紧急任务。我要你去帮助金莲教守卫锦绣谷。"
D.SharedStrings[10695]="影踪派智遥大师"
D.SharedStrings[10696]="影踪派炸药"
D.SharedStrings[10697]="影踪禅院（英雄难度）"
D.SharedStrings[10698]="影锋对鲜血的嗜求已经满足，它要开始品尝鲜血女王兰娜瑟尔的灵魂了。"
D.SharedStrings[10699]="影锋闪耀着冰霜的光芒，准备赐辛达苟萨一死。"
D.SharedStrings[10700]="彼此靠近的心能魔像相互间产生了链接，使得每座魔像的攻击速度提高{1}%，伤害提高{2}%。此外，产生链接的魔像的移动速度也将提高{3}%，并免疫减速效果。"
D.SharedStrings[10701]="往休眠的构造体中注入强大的邪能能量。"
D.SharedStrings[10702]="往日的胜利：战歌峡谷"
D.SharedStrings[10703]="往日的胜利：阿拉希盆地"
D.SharedStrings[10704]="往日的贡献：战歌峡谷"
D.SharedStrings[10705]="征募官"
D.SharedStrings[10706]="征召冒险者：黑石深渊"
D.SharedStrings[10707]="征服之岛主宰"
D.SharedStrings[10708]="征服之岛大使"
D.SharedStrings[10709]="征服之岛战场军官"
D.SharedStrings[10710]="征服之岛的战斗"
D.SharedStrings[10711]="征服之岛胜利"
D.SharedStrings[10712]="征服之岛荣誉击杀"
D.SharedStrings[10713]="征服军需官"
D.SharedStrings[10714]="征服探索者末路，找到游学者周卓，并且在沿路的三个神龛稍停片刻，对自身进行一番反省。"
D.SharedStrings[10715]="征服者之路"
D.SharedStrings[10716]="征服者克鲁尔"
D.SharedStrings[10717]="征服者多斯拉泽"
D.SharedStrings[10718]="征服者泰克的残破石像"
D.SharedStrings[10719]="征服者瓦瑞克"
D.SharedStrings[10720]="征调一队[单位]为你执行任务。"
D.SharedStrings[10721]="征调一队元素生物为你执行任务。"
D.SharedStrings[10722]="征调结群小鬼为你执行任务。"
D.SharedStrings[10723]="征调结群小鬼，陪伴你的勇士执行任务。"
D.SharedStrings[10724]="很久以前，大魔导师艾利桑德曾经站出来对抗过燃烧军团，并公然表达了对艾萨拉女王的蔑视。但数千年的岁月改变了她的思想，并将她变成了恶魔的帮凶。是时候面对她了。"
D.SharedStrings[10725]="很多人都认为这位臭名昭著的迪菲亚兄弟会头目几年前已经在死亡矿井中丧生。然而，凭借一瓶能让人暂时装死的药剂和一套防火护甲，西部荒野的任性女儿得以逃出生天。此后她加入了一个名为“无冕者”的秘密组织，对政府的强烈叛逆让她在里面如鱼得水。她在组织中的地位迅速提升，成为了一名神秘的“影行者”，坚定地向着自己的复仇大业前进。"
D.SharedStrings[10726]="很好…这些东西有很大的帮助!这些材料在沙漠中很难取得，$N。谢谢你。"
D.SharedStrings[10727]="很好。我们正需要这些，$N。做的好。"
D.SharedStrings[10728]="很好。我們現在就前往戰爭前線，了解情況。"
D.SharedStrings[10729]="很好。拿上你的医疗器械，我们现在就开始!"
D.SharedStrings[10730]="很好。看来我得做一下自我介绍。我叫瑞维尔·考斯特，一名圣光牧师，我在寻找遗失的神器。我以前跟黑暗骑士打过交道，这次回来是为了彻底清理掉他们。\n\n黑暗骑士一向神出鬼没，但是我可能有关于他们行踪的线索。先前交战的时候，我瞥见了他们的过去。圣洁斗篷向我展示了一个场景，让我看到了黑暗骑士以前的身份。\n\n跟我一起到埃瑞丁营地去。我会在路上跟你解释。"
D.SharedStrings[10731]="很好。解決他之後，等我們部隊的主力抵達，就能建立更穩固的據點。"
D.SharedStrings[10732]="很好！我感觉到他们的法术正在消逝。我很快就能和拉图修斯会合！"
D.SharedStrings[10733]="很好，$N!现在轮到我了―我将对这些骸骨进行适当的回火，使它们不至于在锻造过程中断裂。$B$B下一步就是获得钥匙的模具了，在塔纳利斯有个哥布尔铁匠，他曾经制作过类似的模具。跟其它的哥布尔一样，他也会为那些出价最高的人效劳的。"
D.SharedStrings[10734]="很好，$N。如果你改变心意，我会在这里帮助你。"
D.SharedStrings[10735]="很好，$N，这些可以制成不少解药―至少可以让现在的局面有所改观。$B$B制作解药有时是很困难的，因为每种毒药都需要特定的解药。如果我们可以不考虑这种对应性，随意地制作解药，那就好了!$B$B现在，让我开始工作吧!"
D.SharedStrings[10736]="很好，你的贡献已经被记录在册，而你也得到了不错的评价。继续好好干，$C。$B$B如果你有更多徽章的话，我随时可以帮你进一步提高声望。"
D.SharedStrings[10737]="很好，很好。让宠物保持健康以随时应对战斗，这是非常重要的。$b$b我给你安排的下一个任务是，参加几场对决，将一只宠物升到3级。等你做到之后就回来见我，我会告诉你如何捕捉属于你自己的宠物！"
D.SharedStrings[10738]="很好，这解释了为什么玛乌提看起来那么小……格伦特·恐锤被真正的玛乌提抓走了，但作为一个聪明的猎手，他发射了信号弹以便我们可以追踪他的行迹。赶快去找恐锤吧，否则一切都晚了！"
D.SharedStrings[10739]="很好，非常好！我会把剩下的龙蛋完好无损地送回它们的巢穴去。$B$B同时，你也要把你的龙蛋带回百木园给天荆教头。"
D.SharedStrings[10740]="很庆幸这片大地的居民仍然会对古老的种族表达敬意。我祝你平安，$N，并且送你这个硬币……"
D.SharedStrings[10741]="很棒的样本，$N。$B$B我代表我的士兵感谢你今天的付出。$B$B鲁伯特上尉应该是你巡逻的下一站。他就驻守在东方的墙边。"
D.SharedStrings[10742]="很荣幸见到你，$N。我们一直在观察你的冒险，感激你为虚空之翼军团所做的一切。$B$B如果你选择我做为你的伙伴，我会载你来回世界的尽头。不论你要我做什么，我都会尽我所能去服从。$B$B请小心你只能选择我们其中一个来进行你在外域的旅程。一旦做下决定，就不能改变心意了。"
D.SharedStrings[10743]="很高兴你也能来。我们的旅程可不轻松。"
D.SharedStrings[10744]="很高兴你喜欢我的食物。你对这些食谱感兴趣吗？如果感兴趣，你可以向我的老师学习这些食谱。他们在半山市集。我所有的厨艺都是从他们那里学到的。$b$b如果你正好经过那里，可不可以帮我把这封信交给孙行·铁掌？她是我最喜欢的老师，我想让她知道我很想她。"
D.SharedStrings[10745]="很高兴你来了，$N。我们有很多要谈的，但是最重要的是你在圣光之道上的修行情况。$B$B有些课程是所有圣光的追随者都需要学习的，如果你准备好了，我们现在就来讨论一些相关的内容吧。"
D.SharedStrings[10746]="很高兴再次见到你，$N!是什么风把你吹回奥伯丁的?你来这里是不是有什么新的发现要报告给我们?"
D.SharedStrings[10747]="很高兴再见到你，$N。你有没有在儿童周中完成自己的义务?"
D.SharedStrings[10748]="很高兴再见到你，$N。我们正在努力找寻巨型海洋动物纷纷在黑海岸搁浅的原因，但是似乎只要我们有一点进展，就会陷入更大的谜团中。$B$B你有什么可以对我们的研究有所帮助的新消息吗?"
D.SharedStrings[10749]="很高兴和你做生意。$B$B另外，$N，你能不能不要把那讨厌的表情挂在脸上?"
D.SharedStrings[10750]="很高兴见到你，$N。我的职责是指引圣骑士们，让他们在致力于保卫艾泽拉斯、抵抗天灾军团和其它威胁的同时领悟更多的美德。是时候让你踏出走向真正美德的第一步了。如果你同意的话，我会给你一本圣洁之书。通过学习这本书可以让你了解圣光，以及圣光对你的期望。理解它，并证明你的能力，最终你会获得更强大的力量。"
D.SharedStrings[10751]="很高兴见到你，$N。我知道你急切地想要知道如何才能获得你的战骑，现在这个时刻终于来临了。$B$B你需要经过许多试炼，但是最重要的是，你的信念将通过克服这些困难得到最大程度的提升。这些并不是教课书式的试炼―你必须全身心地投入，才能克服即将到来的挑战。在拯救你未来的伙伴之前，你必须与无数邪恶的力量抗衡。$B$B现在，我们开始吧!"
D.SharedStrings[10752]="很高興你了解我所提供服務的價值，夥伴。"
D.SharedStrings[10753]="很高興你平安抵達了。這裡急需你的幫忙。"
D.SharedStrings[10754]="很高興看到你傷勢痊癒，$n。許多航向破碎海岸的精兵就沒這麼幸運了。"
D.SharedStrings[10755]="很高興看到友善的臉孔，我不知道靠自己一個人還能撐多久！"
D.SharedStrings[10756]="很高興知道他們還活著。他們的情報會在接下來的行動中派上很大的用場。"
D.SharedStrings[10757]="得到闪电充能，体型和伤害提高{1}%。"
D.SharedStrings[10758]="得到阿斯托的介绍信，并将其交给盗贼区的米奈特·卡加德。"
D.SharedStrings[10759]="從專業建築物展開你的第一個工作令，把材料交給助手。"
D.SharedStrings[10760]="微光之眼护肩"
D.SharedStrings[10761]="微光甲壳斗篷"
D.SharedStrings[10762]="微型炎刃防御者"
D.SharedStrings[10763]="微妙的气氛（肯定不是爱）"
D.SharedStrings[10764]="德丝缇拉克的熔融外壳迅速升温，使其移动速度持续提高。当德丝缇拉克受到伤害时，此效果重置。"
D.SharedStrings[10765]="德克加尔风裔骑士"
D.SharedStrings[10766]="德兰妮·语风"
D.SharedStrings[10767]="德夫伦·铁符"
D.SharedStrings[10768]="德尔瓦·铁拳"
D.SharedStrings[10769]="德尔瓦·铁拳在战斗中被击败了。你可以在他痊愈后在兵营里重新招募他。"
D.SharedStrings[10770]="德尔瓦·铁拳是个渴望战斗的矮人，就跟他渴望美酒一样。"
D.SharedStrings[10771]="德拉丝·月牙"
D.SharedStrings[10772]="德拉克瑞蝙蝠坐騎(德拉克瑞入侵者使用)"
D.SharedStrings[10773]="德拉卡"
D.SharedStrings[10774]="德拉卡正在跟随你。"
D.SharedStrings[10775]="德拉卡正在跟随你。她能强化你对匠灵的攻击。"
D.SharedStrings[10776]="德拉卡的伙伴"
D.SharedStrings[10777]="德拉诺 - 击败5人地下城首领的次数"
D.SharedStrings[10778]="德拉诺 - 击败团队首领的次数"
D.SharedStrings[10779]="德拉诺 - 最常击败的团队首领"
D.SharedStrings[10780]="德拉诺 - 最常击败的地下城首领"
D.SharedStrings[10781]="德拉诺之王"
D.SharedStrings[10782]="德拉诺公会地下城英雄"
D.SharedStrings[10783]="德拉诺制皮秘术"
D.SharedStrings[10784]="德拉诺大决战"
D.SharedStrings[10785]="德拉诺污血怪"
D.SharedStrings[10786]="德拉诺炼金秘术"
D.SharedStrings[10787]="德拉诺珠宝加工秘术"
D.SharedStrings[10788]="德拉诺的博学者"
D.SharedStrings[10789]="德拉诺的小动物们"
D.SharedStrings[10790]="德拉诺的许多生物都是在最为严酷的环境中成长起来的。在这当中，最狡猾的要数潜伏者。$B$B这种怪物可以潜伏在环境之中，潜行并偷取附近猎物的蛋。这次让我们瞧瞧你的坐骑能否识破这种天然的伪装。你可以在塔拉多找到合适的潜伏者。"
D.SharedStrings[10791]="德拉诺裁缝秘术"
D.SharedStrings[10792]="德拉诺锻造秘术"
D.SharedStrings[10793]="德斯克斯从附近的生命体体内吸取水分，使其脱水。"
D.SharedStrings[10794]="德罗娜·莱因哈特"
D.SharedStrings[10795]="德芙琳·斯蒂克斯面具"
D.SharedStrings[10796]="德莱尼/血精灵孤儿对其召唤者使用该法术以触发卫兵抵达。"
D.SharedStrings[10797]="德莱尼儿童"
D.SharedStrings[10798]="德莱尼囚犯"
D.SharedStrings[10799]="德莱尼奴隶"
D.SharedStrings[10800]="德莱尼学者"
D.SharedStrings[10801]="德莱尼微型防御者"
D.SharedStrings[10802]="德莱尼资深学者"
D.SharedStrings[10803]="德萊尼孤兒在艾克索達的水晶大廳，諾柏多的面前召喚各種元素，每種元素各召喚一隻。"
D.SharedStrings[10804]="德迪利特·星焰"
D.SharedStrings[10805]="德雷克塔尔的伙伴"
D.SharedStrings[10806]="德雷克塔尔的图腾"
D.SharedStrings[10807]="德雷克塔尔的图腾里包含有一个霜火之怒的子嗣。"
D.SharedStrings[10808]="德雷克塔尔赞美着你的伟业，卡利姆多到处都在传颂你的事迹。大酋长很高兴―你为我们部落做出的贡献让他感到非常高兴。$B$B你将统御我们的部队。$B$B这就是你的新徽记，指挥官$N。$B$B<拉格隆德向你致敬。>"
D.SharedStrings[10809]="德鲁伊的皮肤变得如树皮一样坚硬，受到的所有伤害降低{1}%，造成的所有伤害提高{2}%。"
D.SharedStrings[10810]="德鲁伊的睡眠"
D.SharedStrings[10811]="德鲁伊训练师"
D.SharedStrings[10812]="德鲁伊进入熊形态，近战攻击强度提高{1}点，由装备而获得的护甲值提高{2}%，耐力值提高{3}%。免疫变形魔法效果，并可使用多种熊形态下专有的技能。\r\n\r\n变身可以解除施法者身上的所有变形和移动限制效果。"
D.SharedStrings[10813]="心灵之眼的仪式匕首"
D.SharedStrings[10814]="心灵尖啸"
D.SharedStrings[10815]="心灵震爆"
D.SharedStrings[10816]="必须阻止暮光之锤使用界门。只有一个办法。$B$B输入错误的启动序列并摧毁它。$B$B嗯，让我看看。没错，这儿就有一个，能通往火元素位面火焰之地的爆破深度。应该可以成功。"
D.SharedStrings[10817]="忠实的小蛮兵"
D.SharedStrings[10818]="快捷的治疗能量涌动，为一名友方目标恢复{1}点生命。"
D.SharedStrings[10819]="快点!没有时间可以浪费了!"
D.SharedStrings[10820]="快点，$N，你的成功与否关系着不止一条人命。$B$B如果因为某些原因让你无法帮助杰生和亨兹，就赶快回来找我，我会再给你一个生命符记。$B$B别以为我的帮助仅仅是简单的恩惠，你必须证明自己具备和其它圣骑士一样的价值，在今后的日子里，你还会不断遇到挫折。"
D.SharedStrings[10821]="快过来，罗克！"
D.SharedStrings[10822]="快逃命吧！\r\n逃命时，移动速度提高{1}%。"
D.SharedStrings[10823]="快速向后跳跃。"
D.SharedStrings[10824]="快速地挥砍敌人，造成{1}%的武器伤害。"
D.SharedStrings[10825]="快速地连续攻击两次，对前方区域的敌人造成{1}点物理伤害。"
D.SharedStrings[10826]="快速抽击敌人，造成{1}%武器伤害。"
D.SharedStrings[10827]="快速挥砍施法者面前的所有目标，造成物理伤害。"
D.SharedStrings[10828]="快速攻击。"
D.SharedStrings[10829]="快速的铜质赛车"
D.SharedStrings[10830]="快速翻阅文件以选择你的下一项任务。"
D.SharedStrings[10831]="快速而有效的治疗，为目标恢复{1}点生命值。"
D.SharedStrings[10832]="怀特巴克的坠饰"
D.SharedStrings[10833]="怎么啦宝贝?有东西要给我?"
D.SharedStrings[10834]="怎么打开这玩意？"
D.SharedStrings[10835]="思维被黑暗法术所迷惑。"
D.SharedStrings[10836]="急救训练师"
D.SharedStrings[10837]="急速侵掠的利刃攻击目标。"
D.SharedStrings[10838]="急速射击"
D.SharedStrings[10839]="急速射击敌方目标。"
D.SharedStrings[10840]="急速挥舞利爪，对施法者前方的锥形区域造成物理伤害。"
D.SharedStrings[10841]="急速提高{1}%"
D.SharedStrings[10842]="急速提高{1}%。"
D.SharedStrings[10843]="急速提高{1}%。\r\n受到的伤害提高{2}%。\r\n免疫长时间的群体控制效果。"
D.SharedStrings[10844]="急速提高{1}%。\r\n回旋击会移除该效果。"
D.SharedStrings[10845]="急速提高{1}%。\r\n提高法力回复速度。"
D.SharedStrings[10846]="急速提高{1}%。\r\n移动速度提高{2}%。"
D.SharedStrings[10847]="急速提高{1}%。\r\n造成的伤害提高{2}%。"
D.SharedStrings[10848]="急速提高{1}%，所有法术的法力消耗降低{2}%。"
D.SharedStrings[10849]="急速提高{1}。"
D.SharedStrings[10850]="急速提高{1}点。"
D.SharedStrings[10851]="急速提高。"
D.SharedStrings[10852]="急速等级提高{1}。"
D.SharedStrings[10853]="急速降低{1}%。"
D.SharedStrings[10854]="急速降低{1}%。\r\n每秒受到自然伤害。"
D.SharedStrings[10855]="急速降低{1}%。\r\n移动速度降低{2}%。"
D.SharedStrings[10856]="怨恨的阿格希尔德"
D.SharedStrings[10857]="总指挥官艾里克苏斯"
D.SharedStrings[10858]="总督奈扎尔"
D.SharedStrings[10859]="恐怖之城，纳克萨玛斯"
D.SharedStrings[10860]="恐怖卫士"
D.SharedStrings[10861]="恐怖卫士莫利纳"
D.SharedStrings[10862]="恐怖图腾萨满祭司"
D.SharedStrings[10863]="恐怖图腾酋长：伊莎·暗斧"
D.SharedStrings[10864]="恐怖图腾酋长：格鲁迪格·黑云"
D.SharedStrings[10865]="恐怖图腾酋长：酋长之首"
D.SharedStrings[10866]="恐怖图腾酋长：雷蹄长老"
D.SharedStrings[10867]="恐怖指挥官伊索祖尔"
D.SharedStrings[10868]="恐怖指挥官萨拉诺尔"
D.SharedStrings[10869]="恐怖船长塔特赛尔"
D.SharedStrings[10870]="恐怖船长德梅萨手下的一名资深海盗。"
D.SharedStrings[10871]="恐怖黏液怪"
D.SharedStrings[10872]="恐惧。"
D.SharedStrings[10873]="恐惧之刃"
D.SharedStrings[10874]="恐惧之影"
D.SharedStrings[10875]="恐惧使者瓦鲁斯"
D.SharedStrings[10876]="恐惧召唤者瑞克佐拉"
D.SharedStrings[10877]="恐惧地狱火"
D.SharedStrings[10878]="恐惧护卫胸甲"
D.SharedStrings[10879]="恐惧渡鸦"
D.SharedStrings[10880]="恐惧渡鸦紧贴在受害者周围并专注攻击他们。\r\n\r\n在紧贴目标时，恐惧渡鸦受到的{1}%伤害会复制给目标。"
D.SharedStrings[10881]="恐惧渡鸦雏鸟"
D.SharedStrings[10882]="恐惧猎犬"
D.SharedStrings[10883]="恐惧附体的哨兵"
D.SharedStrings[10884]="恐惧骑士扎克加尔"
D.SharedStrings[10885]="恐惧魔王"
D.SharedStrings[10886]="恐惧魔王削弱者"
D.SharedStrings[10887]="恐惧魔王对前方的目标发动顺劈，造成{1}点暗影伤害，并吸收同等数量的生命。"
D.SharedStrings[10888]="恐惧魔王对前方的目标发动顺劈，造成暗影伤害，并吸收同等数量的生命。"
D.SharedStrings[10889]="恐惧魔蝠"
D.SharedStrings[10890]="恐翼是一隻非常可怕的惡魔…我不得不說，你的技術讓我印象深刻，$n。\r\n\r\n要殺的惡魔多到不行。很高興能夠再跟你並肩作戰。"
D.SharedStrings[10891]="恐轨车站"
D.SharedStrings[10892]="恐轨车站（英雄难度）"
D.SharedStrings[10893]="恐魔的近战攻击有一定几率令当前目标感染邪能血液，造成{1}点邪能腐蚀。"
D.SharedStrings[10894]="恐龙统领玺戒"
D.SharedStrings[10895]="恒定催化斗篷"
D.SharedStrings[10896]="恒定内爆护腕"
D.SharedStrings[10897]="恒燃召唤熔化的巨石，对敌人造成火焰伤害。"
D.SharedStrings[10898]="恢复{1}%的最大生命值。"
D.SharedStrings[10899]="恢复{1}点法力值。"
D.SharedStrings[10900]="恢复{1}点法力值。只能在PvP战场中使用。"
D.SharedStrings[10901]="恢复{1}点法力值。若掌握了工程学技能则效果提升。"
D.SharedStrings[10902]="恢复{1}点法力值和{2}点生命值。"
D.SharedStrings[10903]="恢复{1}点法力值和生命值。"
D.SharedStrings[10904]="恢复{1}点生命值。"
D.SharedStrings[10905]="恢复{1}点生命值。只能在PvP战场中使用。"
D.SharedStrings[10906]="恢复{1}点生命值。只能在搏击竞技场使用。"
D.SharedStrings[10907]="恢复{1}点生命值。若掌握了工程学技能则效果提升。"
D.SharedStrings[10908]="恢复{1}点生命值和{2}点法力值。"
D.SharedStrings[10909]="恢复全部生命值。"
D.SharedStrings[10910]="恢复施法者{1}%的最大生命值。"
D.SharedStrings[10911]="恢复法力值、能量值、集中值、怒气值或符文能量值。"
D.SharedStrings[10912]="恢复生命值。"
D.SharedStrings[10913]="恢复生命值和法力值。"
D.SharedStrings[10914]="恢复生命值，数值相当于圣光闪现或圣光术治疗量的{1}%。"
D.SharedStrings[10915]="恩多拉·莫尔海德"
D.SharedStrings[10916]="恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B勇气勋章有两个用途:它可以让你与银色黎明的关系更加亲密，这是对你奋力作战的表彰;你也可以凭这枚勋章再加上一点钱，到我们的军需官那里换取一些宝贵的物品。$B$B无论你决定怎样使用这枚勇气勋章，它都是你用血汗赢得的，干得不错!"
D.SharedStrings[10917]="恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B我们每向你这样的勇士颁发一枚勇气勋章，就说明我们在这场对抗天灾军团的战争中又取得了一点进展。只要有更多的英雄加入我们的行列，银色黎明终将剿灭这支无比邪恶的势力。我希望你在今天表现出来的过人勇气也能一直持续到胜利时刻的到来!"
D.SharedStrings[10918]="恭喜你，$N―我很高兴为你颁发这枚勇气勋章!$B$B这足以证明你是个甘愿为正义事业献身的英雄。我们会表彰一切与天灾军团抗争的勇士，但是击败他们的领袖才是真正给了他们一个迎头痛击!$B$B为了黎明而战，我的$g兄弟:姐妹;!"
D.SharedStrings[10919]="恭喜你，$n。你已经掌握了多种战斗技巧，完成了你遇到的所有挑战。毫无疑问，你已经做好了准备，可以迎战来自各个主城的冠军了。$B$B裁决者玛蕾尔·图哈特要与你谈谈，$n，她会正式批准你参加总冠军的角逐。"
D.SharedStrings[10920]="恳求的消耗提高{1}%。"
D.SharedStrings[10921]="恳求贝瑟克的祝福，使附近所有盟友造成的伤害提高{1}%。"
D.SharedStrings[10922]="恶孽角斗士云端翔龙"
