D.SharedStrings[11398]="恶魔训练师"
D.SharedStrings[11399]="悟道者潜行者"
D.SharedStrings[11400]="您一定会成为一个真正的英雄，$N。欢迎您来到艾泽拉斯世界，请从我们为您精心准备的特殊礼品中挑选一件吧!"
D.SharedStrings[11401]="您好!很高兴见到您!$B$B我看到您手里拿着一张特殊的礼品券，把它交给我，您就可以得到一件特殊的礼品!"
D.SharedStrings[11402]="悬槌特使护卫"
D.SharedStrings[11403]="悬槌附魔护腕"
D.SharedStrings[11404]="悲伤之路玺戒"
D.SharedStrings[11405]="情况看起来不妙，那猎豹拥有强大的魔法能力。我们最好快去看看那猎手现在怎么样了。"
D.SharedStrings[11406]="情报指出，三巨头的最后一名成员高阶术士克希鲁恩在巨槌石顶端的洞穴中秘密策划着他的伟大计划。$b$b他在等一件东西：统御宝珠，想利用它执行强大的仪式。我要你给他的是：$b$b<托德曼递给你一颗玻璃球。>$b$b这颗玻璃球是你从风暴祭坛取回的。它没有任何能量。把这玩意儿交给克希鲁恩，然后祈祷他不会识破吧。"
D.SharedStrings[11407]="惊天动地的爆炸，给大范围内的敌人造成{1}点火焰伤害。"
D.SharedStrings[11408]="惊恐的埃索达平民"
D.SharedStrings[11409]="惊恐的平民"
D.SharedStrings[11410]="惊骇。这个效果在被移除时会尝试转移到附近的盟友身上。"
D.SharedStrings[11411]="惊魂港亡灵卫兵"
D.SharedStrings[11412]="惨痛真相之冠"
D.SharedStrings[11413]="惩击一名敌人，对其造成神圣伤害。"
D.SharedStrings[11414]="惩击敌人，造成{1}点神圣伤害。"
D.SharedStrings[11415]="惩击敌人，造成{1}点神圣伤害，并为自己回复最大生命值的{2}%。"
D.SharedStrings[11416]="惩击敌方目标，造成神圣伤害。"
D.SharedStrings[11417]="想要守住阵线，我们就得重新激活所有结界。"
D.SharedStrings[11418]="想要证明你自己拥有获得风暴钥匙的资格，你必须首先完成四个试炼。$B$B现在，你只需要跨越最后一个障碍了，凡人。聚集一支军队，前往地狱火堡垒深处，在玛瑟里顿的巢穴中杀出一条血路，进入中央的密室，杀死那个邪恶的腐蚀者！"
D.SharedStrings[11419]="愈久愈香醇。"
D.SharedStrings[11420]="意外破绽"
D.SharedStrings[11421]="意志被削弱。\r\n叠加到3层后开始逃跑。"
D.SharedStrings[11422]="感到眩晕。"
D.SharedStrings[11423]="感受到矮人失去家园的怒火，你的爆击几率提高{1}%。\r\n\r\n只有当你处于格瑞姆巴托的时候才会生效。"
D.SharedStrings[11424]="感受酋长的力量吧！为了部落的荣耀而战！"
D.SharedStrings[11425]="感应报警机器人2000型"
D.SharedStrings[11426]="感恩者的好胃口"
D.SharedStrings[11427]="感恩节供应商"
D.SharedStrings[11428]="感恩节商人"
D.SharedStrings[11429]="感染撕咬"
D.SharedStrings[11430]="感染煞能的野牛人"
D.SharedStrings[11431]="感觉很棒，不是吗?你再也不是他们的一份子了，$N。你是天灾军。你是我们的一员。永远都是……"
D.SharedStrings[11432]="感謝你的勇氣，這些人的命都是你救的。他們不會忘記我們為此所冒的風險。"
D.SharedStrings[11433]="感謝你願意冒這個險。我們現在就來做個了結吧！"
D.SharedStrings[11434]="感谢你把这个拿回来交给我，$N。有了这些剩下的液体，我就可以继续进行研究了。$B$B虽然现在我们还有很多事情要做，但是你至少帮我阻止了维利塔恩的堕落力量继续在玛拉顿中蔓延。请接受这个作为我的感谢。"
D.SharedStrings[11435]="感谢你，这对治疗我们士兵的伤口有很大助益。"
D.SharedStrings[11436]="愤怒卫士"
D.SharedStrings[11437]="愤怒卫士入侵者"
D.SharedStrings[11438]="愤怒卫士夺灵者"
D.SharedStrings[11439]="愤怒卫士恐刃者"
D.SharedStrings[11440]="愤怒卫士斩杀者"
D.SharedStrings[11441]="愤怒卫士碎魂者"
D.SharedStrings[11442]="愤怒卫士织刃者"
D.SharedStrings[11443]="愤怒囚禁了我，$n，而你则把我救了出来。尽管我一直认为我所做的一切都是正确的，但我的灵魂却一直在为那些不幸因我而亡的艾泽拉斯人民哭泣着，为他们所经历的恐怖与死亡而哭泣。或许，我不会再次迷失方向了。$B$B把这本祷言书带给孤儿们吧，这样他们就会明白，我不会再纠缠他们了。"
D.SharedStrings[11444]="愤怒守卫毁灭者"
D.SharedStrings[11445]="愤怒的蜜蜂每秒造成{1}%的伤害。跳到附近的池子里摆脱蜜蜂！"
D.SharedStrings[11446]="愤怒领主亚雷兹"
D.SharedStrings[11447]="愿时光永远与你同在，$N。"
D.SharedStrings[11448]="憎恶……$b$b可怕的敌人。我不止一次目睹它们迅速地扭转了战局。事实上，它们也可以成为有用的伙伴，这一点倒是鲜为人知。$B$B憎恶并不聪明。只要你了解制造憎恶的秘密，就可以对它们发出简单的指令。相信我，它们会毫不犹豫地执行你的命令。$B$B你很幸运，我恰好知晓其中的奥秘。$B$B对憎恶的残骸使用这个工具包，将其复活。接下来你就可以利用它对付驻守在死亡之门的天灾军团了。"
D.SharedStrings[11449]="懂了吗?你的确杀了不少，但你每杀一个，另一个马上就从土中爬起来。$B$B你还不了解你正面对什么，$N。让我告诉你。"
D.SharedStrings[11450]="懒惰的苦工"
D.SharedStrings[11451]="戈多克食人魔装"
D.SharedStrings[11452]="戈尔隆德巨口蛙"
D.SharedStrings[11453]="戈尔隆德裂蹄牛"
D.SharedStrings[11454]="戈拉亚的凝视"
D.SharedStrings[11455]="戈杜尼投石车"
D.SharedStrings[11456]="戈莫克想要他的狗头人"
D.SharedStrings[11457]="戈隆灾星上涌动着烈火与冰霜之力。现在只需要获得兽之祝福，就能令这把武器恢复全盛时期的力量了。阿格拉姆相信，只要让它沾上石怒崖古老的黑色双头飞龙的鲜血，即可大功告成。他的日记原文如下：\n\n“在高耸的石怒崖上，我看见了一座食人魔祭拜这些古代野兽的祭坛。或许我能用它引一只下来。”"
D.SharedStrings[11458]="戈隆追猎者洛卡什"
D.SharedStrings[11459]="戈隆追猎者洛卡什是一名经验丰富的猎人，如今只为你这样的胜者而战。"
D.SharedStrings[11460]="戈隆追猎者洛卡什的投诚"
D.SharedStrings[11461]="成为本服务器首个公会等级达到25级的公会。"
D.SharedStrings[11462]="成为本服务器首个在所有专业与辅助专业中都获得525点技能点数的公会。"
D.SharedStrings[11463]="成为本服务器首个在所有专业与辅助专业中都获得600点技能点数的公会。"
D.SharedStrings[11464]="成为纳格兰鲜血竞技场的竞技场之王。"
D.SharedStrings[11465]="成为闪电囚笼的目标。"
D.SharedStrings[11466]="成功击中目标后有一定几率对施法者周围目标造成伤害。"
D.SharedStrings[11467]="成功地在火焰旁舞蹈。连续成功地这样做10次就能赢得挑战！"
D.SharedStrings[11468]="成功地引诱那些暗影灵魂。连续这样做20次而不被击中，就能赢得这次挑战！"
D.SharedStrings[11469]="成功施放伤害性法术或技能后将恢复最大生命值的1%。"
D.SharedStrings[11470]="成功施法之后有一定几率恢复{1}点法力值。只能在风暴峭壁生效。"
D.SharedStrings[11471]="成功的物理攻击造成{1}点额外的冰霜伤害。"
D.SharedStrings[11472]="成功的近战伤害将冻结敌人。"
D.SharedStrings[11473]="成功的近战攻击会为自己恢复{1}点生命值。"
D.SharedStrings[11474]="成功的近战攻击会为自己恢复生命值。"
D.SharedStrings[11475]="成功的近战攻击有一定几率造成自然伤害。\r\n攻击速度提高{1}%。"
D.SharedStrings[11476]="成功的近战攻击能够恢复{1}%的生命值。"
D.SharedStrings[11477]="成堆的石头"
D.SharedStrings[11478]="成果如何啊，$N?你看起来做得不错嘛。一个真正的杂耍大师!"
D.SharedStrings[11479]="成熟的季鹍凤凰蛋"
D.SharedStrings[11480]="成群的愤怒仆从"
D.SharedStrings[11481]="我…我的帽子!那么…那个人就是你。我就知道。你靠近我的时候，旧疤就隐隐作痛，但是…太年轻了!你一点都没变!$B$B好吧…所以现在你知道我的秘密了。我“曾经”被打败了…来吧:拿着这顶帽子，作为我的酬谢。它本来就是你的。"
D.SharedStrings[11482]="我一定會在你離開前為你準備一瓶秘能酒。"
D.SharedStrings[11483]="我一定要让这些纳迦为他们的暴行付出代价。\n\n他们和他们的海巨人走狗趁我们与燃烧军团作战的时候抓走了我们的战士。这群不知廉耻的家伙！\n\n我们必须救出那些士兵，不能让他们被当作奴隶卖掉，或者更惨……"
D.SharedStrings[11484]="我一直在努力为你的宠物们准备好这个地方，可我们在建造要塞时发现了一些恼人的祸害。我本想亲自动手解决的，但它们实在是太难对付了。$b$b在花园里有一根愤怒的胡萝卜，另外有只巨大的老鼠正在啃食我们的粮食，还有一个坏脾气的水怪在骚扰我们的渔夫。如果你能解决掉它们的话，我就能顺利无阻的完成我的工作了。"
D.SharedStrings[11485]="我一直在找像你这样优秀而强壮的士兵。我需要有人维持军队的秩序。$b$b兽人、食人魔和巨魔大军正在要塞外操练，准备进攻赤脊山。我的中士们负责监督他们，但是我希望你能参与协助。$b$b带上这根棍棒，用它教训那些不听话的士兵。我才不关心他们有没有犯错或是队伍没站整齐呢，我就是要让他们挨几下打。我要他们集中精神，训练有素并且绝对服从命令。$b$b去吧。"
D.SharedStrings[11486]="我一直在猎杀……那个猎杀我们的野兽。$b$b玛乌提，就是他的名字。他是个聪明的家伙，但他犯了个巨大的错误，就是杀死了我的兄弟。现在，这个错误将让他付出代价。恐锤已经找到了他的踪迹。$b$b我注意到他就在库尔森的营地上方游荡。如果我们赶快行动，我们可以消灭他。$b$b准备好了吗，$n？"
D.SharedStrings[11487]="我一直都接受水晶粉末的捐献，$N。你每捐献一组发现的样本都将会得到补偿的。"
D.SharedStrings[11488]="我不会空着手离开！你呢？$B$B我打赌你在纳闷这巨大的箱子里装的到底是啥。好吧，答案马上揭晓。我要你拿上钻机到油井那儿，抽点原油上来。$B$B当然，你会受到半人马的攻击，只要保护好钻机，让我们打上一两桶就好。"
D.SharedStrings[11489]="我不再覺得飢渴了。我能夠思考——我會活下去！喔，亞魯因…"
D.SharedStrings[11490]="我不知道他们究竟是谁，但我知道他们充满了敌意！$B$B据我观察，营地中有三个家伙总是喋喋不休的。穿上这件伪装服，潜入格兰戈瓦村，与阴暗新兵、阴暗劳工和阴暗顾问聊聊天。$B$B要小心，阴暗猎人可以识破你的伪装，这些猎人看上去就不好对付！维系伪装的魔法能量有些脆弱，因此打探敌情期间，你千万不能离开村子。如果你弄丢了这件伪装，就回来找我吧。我会为你另做一件的。"
D.SharedStrings[11491]="我不知道你怎麼拿到這東西，不過一定很不容易。我們面前困難重重，但你卻一一克服。來吧，讓我們復活奧肯多爾。"
D.SharedStrings[11492]="我不知道你是否还记得梅卡托克。内温跟我说，诺莫瑞根的幸存者普遍患有失忆症。$B$B梅卡托克，更正式地说，大工匠梅卡托克，是所有侏儒的领袖。他有个习惯，就是要亲自接见每一位幸存者。你应该去见见他。他就在镇中心的帐篷里，跟他的军事参谋们在一起。"
D.SharedStrings[11493]="我不确定自己是不是高兴听到这个!巫妖王放过依米伦只表示一件事:麻烦。可惜你没办法把他们夫妻一起杀死。$B$B但你终究为我们争取了宝贵的时间。$B$B谁知道呢，或许透过你的方法，你有机会再次遇见依米伦王。不过我相信下次他只会更难缠。"
D.SharedStrings[11494]="我不能再以你的老师自居了，$n。$B$B你已经证明了自己，你的确配得上你的云端翔龙。$B$B今天，你将加入到我们的行列。准备好了吗?"
D.SharedStrings[11495]="我不蠢！$B$B回到你的主子那儿告诉他，生意谈崩了！没错，要是你能活着回去的话。"
D.SharedStrings[11496]="我不認識你，但你不是海巨人，這樣就夠了。"
D.SharedStrings[11497]="我从梦里了解到，乌尔芬就在裂木森林西北边缘的某个洞穴里。$B$B他的处境非常危险！$B$B我会给你一件魔法斗篷，当你穿着它进入裂木森林后，就会变成座狼的样子。这件斗篷非常脆弱，完全依靠那片闹鬼的树林里的奇怪魔法能量才能生效。虽然它只对座狼有效，但它可以让你顺利找到乌尔芬。$B$B我请求你，$c，去帮帮他吧。"
D.SharedStrings[11498]="我从没看过这样不屈不挠的凡人!青铜龙军团将给你最后的附魔强化。这是永恒之王本人的希望!$B$B请将你的徽记之戒交给我，这样我才能开始施法。"
D.SharedStrings[11499]="我代表塞纳里奥议会欢迎你的到来，$C。你找我们有什么事吗?"
D.SharedStrings[11500]="我们一定要拿下石油。很不幸的是半人马正巧在海水淹来时撤到了这里。$B$B对他们来说，很不幸。$B$B他们给脸不要脸，$n。我们出的价那么慷慨，他们却敬酒不吃吃罚酒。现在我们……你要让他们看看自己犯下的什么错误。$B$B把裂蹄高地上的半人马清走。石油必定要为我们流淌！"
D.SharedStrings[11501]="我们不仅供应美酒，还独家出售啤酒杯呢！瞧这些漂亮的杯子，非常具有纪念意义哦！这是一张礼品券。$B$B与美酒节营地背后的布利克斯谈一谈。他是个古怪的家伙，总是带着一副护目镜。他负责兑换礼品券，以及出售各类美酒。"
D.SharedStrings[11502]="我们不断收到关于鸟人在南边伏击，以及焚烧途径主干道路车队的报告。\n\n哨站的卫兵们请求我们对阿兰卡峰林斯克提斯处的鲁克玛信徒们发起反击。"
D.SharedStrings[11503]="我们不能让奎尔德拉就这样只是一堆耻辱的碎片。带上这把剑的残片和你发现的剑柄，到冰冠堡垒的萨隆矿坑去。$B$B巫妖王强迫许多奴隶在那里采掘熔炼萨隆邪铁矿石。我们要用萨隆邪铁重铸奎尔德拉。$B$B你必须取得注能的萨隆邪铁锭和熔炉之主的大锤，然后用它们在熔炉之主的铁砧上重铸这把剑。"
D.SharedStrings[11504]="我们会再见面的，$C。"
D.SharedStrings[11505]="我们决战的障碍只剩下堕落的化身了。消灭他，了结此事。"
D.SharedStrings[11506]="我们到了吗?"
D.SharedStrings[11507]="我们又再次相见了。我一直从远处看着你的发展，萨满，我很高兴。$B$B你与水元素融为一体的时刻已经到了，学习它的秘密并把你自己交给水，如此你便能依次学习掌握它。"
D.SharedStrings[11508]="我们只差一步就可以完全战胜部落了。我们不能让敌人占领这个世界或其它地方的任何据点。"
D.SharedStrings[11509]="我们可以开始你的初级骑术训练了吗?"
D.SharedStrings[11510]="我们可以找到一件宝物，它可以帮助你对抗燃烧军团。这个封印能在最关键的时刻给你一次改变命运的机会。\n\n要我们帮你去找吗？"
D.SharedStrings[11511]="我们听到流言说，艾瑞达中的某位顶尖强者即将通过黑暗之门降临这个世界。\n\n假如这个传言是真的，那很有可能就是污染者阿克蒙德。要是让他毫无阻碍地进入这个世界，整个德拉诺恐怕都要完了。"
D.SharedStrings[11512]="我们和你一起渡过了一段最美好的时光$n。真希望你会是我们的$g爸爸:妈妈;。但你现在必须带我回达拉然的孤儿院里。$B$B也许你什么时候能再来看我们？我们喜欢去看冬鳞小鱼人和红龙女王。绝不会有人相信，我们竟然见到了造物主！$B$B我们会想念你的，$n。一定要给我们写信，我们也会给你写信的，好吗？"
D.SharedStrings[11513]="我们和联盟的冲突已经上升为一场真正的战争，不久之后战争就将全面打响。$B$B对于阿拉希盆地的争夺就是一个很好的开战理由。要么就是联盟占据它，并用其对付我们；或者就是我们占据它，然后用来对付联盟。帮助污染者保持这场资源竞赛上的优势吧，$n！"
D.SharedStrings[11514]="我们在中央阶梯上发现了一位赞达拉首领。必须赶在他返回营地前将他消灭。$B$B你愿意去执行这项任务吗？"
D.SharedStrings[11515]="我们在战歌峡谷对银翼哨兵展开攻势，这一战役至关重要。联盟以保护这片不属于他们的森林为由，妄图从部落手中夺取我们最大的伐木场。$B$B别让他们的妄想成为事实，$n！为了部落，证明你的价值！成功之后再回到我这儿来。"
D.SharedStrings[11516]="我们在模拟战中打闹的同时，不能忘了真正的敌人正环伺在我们周围。银色北伐军想通过比赛来选出最好的战士，但是真正的强者只能是那些从战场上生还的人。我们要让那帮圣骑士看看，在为锦标赛做准备的同时，我们也随时准备跟诅咒教派开战。$B$B到冰冠冰川去，杀死你遇到的所有异教徒。他们的力量在奥尔杜萨和亡语者岗哨周围尤其强大。"
D.SharedStrings[11517]="我们在海加尔的任务之中，最紧迫的任务很简单：消灭那些入侵者。火焰的本质就是吞噬一切。如果有片刻松懈，它就会将眼前的一切烧成灰烬。$b$b干掉任何你看见的烈焰入侵者。每一名敌人的倒下，都会为海加尔争取时间。"
D.SharedStrings[11518]="我们在海岸沿线部署的侦察力量为我们提供了关于这座岛屿的宝贵情报，$c。$B$B然而，如果我们不向本岛推进，就必将一事无成。$B$B我已经集结了一支由精英空军单位组成的战队，准备发起攻击。$B$B我想让你参与这次行动。像你这样的英雄一定能帮我们在紧要关头力挽狂澜。$B$B当你做好出击准备时，来与我谈谈。"
D.SharedStrings[11519]="我们在海滩上发现了一支赞达拉作战小队。必须赶在返回营地前将他们消灭。$B$B你愿意去执行这项任务吗？"
D.SharedStrings[11520]="我们在阿什兰的基地就快完成了，指挥官。$b$b要是你能到那去，对他们的集结区表示认可的话，兄弟们一定会士气大振。$b$b如果你愿意，我可以为你安排飞行。"
D.SharedStrings[11521]="我们塞纳里奥远征队的盟友需要你协助他们在赞加沼泽的行动。"
D.SharedStrings[11522]="我们失去了对岛屿上许多生物的控制，这真是太糟糕了。这里曾是一片无比宁静和谐的地方，最适合学习与研究了。可是现在，我们整天都把时间浪费在防备那些原本是被我们圈养的生物上！$B$B我现在将给你一个难得的机会，你只需要帮我做一些收集工作，我就可以帮你施展一个小魔法做为报酬。你可以在逐日岛上所有使用魔法的生物身上找到一种名叫奥术薄片的东西，给我带一打那玩意回来，完成之后，我会在你身上施放一个小法术，这样你就能更好地在岛上冒险了。"
D.SharedStrings[11523]="我们就快要把雷矛入侵者从奥特兰克山谷赶走了，因此我们必须调动一切可能的增援力量来帮助霜狼氏族。$B$B一场决定性的胜利可以让我们腾出足够的资源在其它战场上消灭联盟的那些混蛋。$B$B出发吧，$n。听从霜狼氏族的号令，去赢得无上的荣耀吧！"
D.SharedStrings[11524]="我们差不多已经清理了矿渣洞中的暴动囚犯，不过还有一个问题没有解决。典狱官。$b$b典狱官席尔瓦是他们的主人，那些囚犯唯他马首是瞻。如果我们除掉他，就可以把他们全都端掉。去把他解决了，然后把他的钥匙给我带回来。我们可以用那些钥匙进入牢房深处，没准还能找到岛上的水源。"
D.SharedStrings[11525]="我们已经一切就绪。$B$B假如你所言不虚，那么只要抓紧坐骑同我们一起进攻就会没事。谁都知道在开阔水域是别想游过纳迦的。$B$B一路杀出去，尽量多消灭一些。炸药用光后，我们就去上面平台的破损海崖汇合。但愿那时他们人数不多，我们可以用常规战消灭掉他们。"
D.SharedStrings[11526]="我们已经占领了岛屿，就该让这里的资源发挥作用了。我们在西南边找到了一座废弃的监狱，需要派你去侦察一下，$n。$B$B报告称，那里有许多被关押了多年的囚犯。尽你所能清理该地，解决之后回来向我报告。"
D.SharedStrings[11527]="我们已经抵御毒蛇的进攻好多天了，$n。但和丛林里的某样东西比起来，这些毒蛇根本就不算什么。$b$b我们是猎手，却被当成了猎物。$b$b一只名叫玛乌提的猎豹正不断猎杀我的手下，将他们拖入草丛的深处。$b$b我们派去了我们最好的猎手之一——格伦特·恐锤——去追踪这个野兽。$b$b恐锤去了东边，也许你可以在那里找到他们。"
D.SharedStrings[11528]="我们已经胜券在握，绝不能功亏一篑！"
D.SharedStrings[11529]="我们并不是在独自与部落交战，$g小伙子:小姑娘;。$B$B如果我们可以取得胜利，那么我们就可以使用部落的资源来在其它的战场上对抗他们。反之，如果我们输掉了这场战争，那么在其它的战场上，部落将会占有优势。$B$B联盟需要更多你这种身经百战、意志坚定的老兵！$n，当你在所有战场上都与部落交战之后再回到我这里。"
D.SharedStrings[11530]="我们应该首先追求哪一把武器?"
D.SharedStrings[11531]="我们影踪派于数个世代以来首次集结了麾下的部队。$B$B恨之煞已经逃出蟠龙脊，我们肩负着再次将它囚禁的神圣使命。$B$B我们的军中都是精兵强将，但人数太少了。我们不会拒绝来自一名强大$c的帮助。$B$B如果你希望加入这场进攻，去螳螂高原和祝踏岚谈一谈。"
D.SharedStrings[11532]="我们必须依靠我们的士兵进行战斗，所有的士兵都会这么告诉你的。他们还会告诉你，他们正在使用破烂不堪的装备，饥肠辘辘地开向战场！$B$B这就是阿拉希盆地显得非常重要的原因。金属，武器，食物，木材——所有我们所需要的东西都可以从那里获得。$B$B那就是我需要你发挥作用的地方，$n。进入阿拉希盆地，比敌人占据更多的基地，以此来获得战斗的胜利，然后给我带回一箱资源来。"
D.SharedStrings[11533]="我们必须增加要塞鱼塘中的本地鱼储备。我需要你去塔拉多的水域中寻找能够支持储备的鱼苗。一旦你把鱼给钓上来，就剖开他们的肚子寻找里面的鱼籽。"
D.SharedStrings[11534]="我们必须增加要塞鱼塘中的本地鱼储备。我需要你去影月谷的水域中寻找能够支持储备的鱼苗。一旦你把鱼给钓上来，就剖开他们的肚子寻找里面的鱼籽。"
D.SharedStrings[11535]="我们必须增加要塞鱼塘中的本地鱼储备。我需要你去戈尔隆德的水域中寻找能够支持储备的鱼苗。一旦你把鱼给钓上来，就剖开他们的肚子寻找里面的鱼籽。"
D.SharedStrings[11536]="我们必须增加要塞鱼塘中的本地鱼储备。我需要你去纳格兰的水域中寻找能够支持储备的鱼苗。一旦你把鱼给钓上来，就剖开他们的肚子寻找里面的鱼籽。"
D.SharedStrings[11537]="我们必须增加要塞鱼塘中的本地鱼储备。我需要你去阿兰卡峰林的水域中寻找能够支持储备的鱼苗。一旦你把鱼给钓上来，就剖开他们的肚子寻找里面的鱼籽。"
D.SharedStrings[11538]="我们必须增加要塞鱼塘中的本地鱼储备。我需要你去霜火岭的水域中寻找能够支持储备的鱼苗。一旦你把鱼给钓上来，就剖开他们的肚子寻找里面的鱼籽。"
D.SharedStrings[11539]="我们必须归还所有的神器，$N。等四样全部收集齐全，你就要把它们放回墓穴中。"
D.SharedStrings[11540]="我们必须抓紧时间，$n。必须回到达拉然，在那里把回复代码发射出去。$B$B带着它去找罗宁吧，我会在那里等你。"
D.SharedStrings[11541]="我们必须让那些该死的鸦人知道，任何攻击我们的人都要付出惨重的代价。否则，我们在泰罗卡森林内的所有商人、信使和士兵将会面临他们的威胁。$B$B我的斥候已经确认了鸦人在这个地区各个主要定居点的首领。去吧，找到里斯克鸦巢的阿什卡兹、西诺鸦巢的埃伊特和基斯鸦巢的乌达克，将他们全部定点清除。"
D.SharedStrings[11542]="我们必须赶快行动，指挥官。就在我们说话的当口，恐轨号正准备开离恐轨车站，用铺天盖地的大军席卷沙塔斯呢。有传闻说，他们给列车装备了足以粉碎内城护盾的强大武器。$B$B啸天者托瓦拉负责确保恐轨号安全抵达塔拉多。你必须阻止托瓦拉，决不能让列车抵达沙塔斯！"
D.SharedStrings[11543]="我们收到消息说影踪派已经开始对螳螂高原进行反击了，他们好像正沿着野牛人入侵的方向行进。$b$b熊猫人已经有数千年之久没踏足过螳螂高原了。影踪派的弟子虽然勇猛顽强，但同样也刚愎自用，他们需要像你这样的英雄帮助。你能前往西北方的冬花关吗？找到影踪派的首领并提供你的经验和帮助？"
D.SharedStrings[11544]="我们最近成功地从坠毁地区回收了一个已经损坏的全息图象发射器。如果我们能把它修好，就有机会找到其他在埃门谷之外的幸存者了。$B$B埃索达坠毁时，有些备用零件也散落出了船外。本来我们可以迅速回收的，可它们现在被这一地区的枭兽全部运走了。$B$B$n，你必须立刻到南方的木巢林地和木巢山去，回收那些备用零件。"
D.SharedStrings[11545]="我们有一些最出色的斥候，在失落的安苏鸦巢遗迹附近失踪了。\n\n伯德里克·格雷要求派遣任何可用的人手去查明威胁，并看看遗迹间还有没有我们的幸存者。"
D.SharedStrings[11546]="我们有一些最出色的斥候，在失落的安苏鸦巢遗迹附近失踪了。\n\n洛坎要求派遣任何可用的人手去查明威胁，并看看遗迹间还有没有我们的幸存者。"
D.SharedStrings[11547]="我们有了羽毛。$b$b我们有了$c。$b$b准备好了就跟女祭司谈一谈。"
D.SharedStrings[11548]="我们本打算在诅咒教派中安排一名线人，以刺探巫妖王的计划，但是，我们……低估了阿尔萨斯和他的黑暗部下，亡语者女士，的煽动能力。$B$B我们的线人，达尔纳文，现在已经投靠他们了。$B$B请务必留意达尔纳文的踪迹。如果你能将他活着带回来，我们可以尝试解除诅咒教派对他所做的洗脑工作。"
D.SharedStrings[11549]="我们来是做一件，也许是两件事的……"
D.SharedStrings[11550]="我们没有针对索基佐格或是黑石地面部队的战略措施了。我们必须继续执行计划的下一阶段。$b$b你处理完要塞的事务就返回凿握据点吧。"
D.SharedStrings[11551]="我们现在接受毛料的捐赠。只要捐赠60块毛料，暴风城就会对你的慷慨行为表示感谢。我们只需要你捐赠60块毛料就够了，更多的毛料可以从其它志愿者的捐赠获得。$B$B如果你有60块毛料并愿捐献的话，那现在就可以给我了。"
D.SharedStrings[11552]="我们的作战计划几乎无一能正常实行。我们被监视了。$B$B钢铁部落一定是在诅咒之地安插了斥候。胜利的机会正在从我们手中溜走。"
D.SharedStrings[11553]="我们的勇士在调查黑鸦堡垒废墟的时候遭到了伏击！黑鸦领主似乎已经和燃烧军团勾结到了一起。\n\n我们需要你协助我们击败他不断壮大的军队并将他消灭。"
D.SharedStrings[11554]="我们的勇士找到了腐化的源头。燃烧军团已经侵蚀了翡翠梦境，如果我们不加以阻止，腐化就会大肆扩散。我们必须把邪恶扼杀在摇篮里。"
D.SharedStrings[11555]="我们的协议仍在。记住，这还只是个前菜而已。帮我从受诅咒的命运解除开来，我会奖励你超强大的物品。"
D.SharedStrings[11556]="我们的天角盟友需要补给，帮助他们与鹰身人作战。"
D.SharedStrings[11557]="我们的斥候发现，卓格巴尔不仅得到了泰坦圣物，还集结了一支足以威胁整个世界的大军。\n\n在卓格巴尔军队大举入侵之前，深入地下，阻止地底之王。"
D.SharedStrings[11558]="我们的斥候回报这些刀塔食人魔已经在更接近山路的地方创建了一个营地，就是从他们的堡垒到我们这里的那条路。$B$B很不幸的我们无法苟同就这样屈服于这些巨魔垃圾底下，但如果他们想要开战，他们会发现部落不只适应力好而已。"
D.SharedStrings[11559]="我们的斥候在西北方的山泽岛发现一股强大的魔古势力。$B$B这个岛本应是荒无人烟的，所以他们的出现是个让人不安的消息。$B$B而更让我不安的是他们正在岛上进行邪恶的实验。$B$B我需要一名能力出众的$c去探查一下情况。$B$B山泽部落可能会给你带来麻烦，如果真是这样，就干掉他们。"
D.SharedStrings[11560]="我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。"
D.SharedStrings[11561]="我们的魔纹布储量很低，而你可以帮助我们补充库存!如果计算整个社区所能作出的贡献的话，我们只需要从你那里获得60块魔纹布就可以达到我们的目标了。你这样的慷慨贡献一定会被铁炉堡的矮人广为传颂，这一点我可以向你保证!$B$B如果你有60块魔纹布并且愿意捐赠的话，那现在就可以给我了。"
D.SharedStrings[11562]="我们知道每一口瘟疫之锅都使用不同的药剂来产生毒素，同样，我们也知道我们必须针对各个瘟疫之锅中的毒素研制出相应的解药。你从达尔松之泪取得的样品是我们解决那里的瘟疫之锅的关键。"
D.SharedStrings[11563]="我们终于占领了这块天杀的乱石堆，随即发现有一只巨大的双头魔在到处游荡，杀死我们的巡逻兵！$B$B$n，我要你带几个人去干掉那只双头魔。绝不能让那样的怪物随便乱跑，制造灾难。$B$B要提高警惕，前线报告称，他拿着一棵大树当武器，而且他真的会拿这玩意来砸你。"
D.SharedStrings[11564]="我们终于拿到这支花费巨大的骷髅钥匙啦，$N!但是它还差一点才能完成，我们还得继续努力。最终，你将要面对安多哈尔城中的强敌……那个在废弃的城墙中徘徊的邪恶生物。$B$B我说的是『召唤者』阿拉基，一个巫妖，天灾军团中最强大的爪牙之一。"
D.SharedStrings[11565]="我们终于来到这一步，四大元素中的最后一个:风。你认为你自己聪明得足以继续吗，$N?"
D.SharedStrings[11566]="我们经过调查发现，在艾萨拉女王的命令之下，纳迦正在准备召唤某种强大的存在，企图让艾萨拉的力量席卷整个破碎群岛。\n\n前往艾萨拉之眼，阻止这场仪式。"
D.SharedStrings[11567]="我们虽然没有完全脱困，但你的努力已经减缓了敌人的攻势。$B$B德拉克亚苟的格隆戴尔上尉应该也需要你的帮助。$B$B再会了，$N。"
D.SharedStrings[11568]="我们要想办法吸引虫棘的注意力，某种打断他的沉睡的办法，某种一定会奏效的办法。$b$b能在腐烂森林生存的少数几种野生动物无疑受到了这里能量的影响。你的任务就是收集它们的肢体，想办法把它们组合成一具容器。如果虫棘的沉睡是德鲁伊式的，甚至是恶魔式的，一个足够大的、由腐蚀的动物躯体组成的容器就足以打破它。"
D.SharedStrings[11569]="我们要找的神器已经在我们的控制之下了。$b$b准备迎接战斗吧。如果他们确实学会了如何控制戈隆的话，这也许会比我预想的还要困难。$b$b只要你一抵达，我就会加入战斗，与你并肩作战。"
D.SharedStrings[11570]="我们诚挚邀请您光临宝石庄园，与我们一起分享美味的点心和饮料，也许还有神秘嘉宾到场助兴哦……"
D.SharedStrings[11571]="我们这些烟林牧场的人感谢你找回了被偷窃的物品，$n。为此，我们要给你一件特殊的礼物……冬天爷爷将会亲自把它给你！$B$B请你去找冬天爷爷，他会给你冬幕节的礼物，来自于我们烟林牧场的礼物！我们这里应有尽有，烟林牧场能满足你一切需求……当然，我们还要谢谢你！"
D.SharedStrings[11572]="我们都吵着要冰激凌……然后就死了！"
D.SharedStrings[11573]="我们都知道，梦魇会扭曲现实和梦境之间的边界，毫无疑问，这会对我们造成威胁。我们的盟友已经堕入了黑暗。"
D.SharedStrings[11574]="我们需要更多的实验体才能继续凯尔丹纳斯的研究。"
D.SharedStrings[11575]="我们需要武器和装备来武装我们的勇士。"
D.SharedStrings[11576]="我会带领一支小队深入敌后。$b$b到巨槌要塞找我吧，$c。我们会在那里商定我们的下一步行动计划。"
D.SharedStrings[11577]="我会帮你把戒指上的宝石换下来。你会发现效果会变的比较……协调。"
D.SharedStrings[11578]="我会帮你造一座船坞。而且造出来的不会是像这边这样大肆浪费资源的垃圾疙瘩。$b$b不过我需要图纸。古尔丹把这座港口转交给海军上将纳尔后，我的作品就都被他没收了。$b$b<拉克吐了口唾沫。>$b$b他现在已经喝下了古尔丹的绿色毒汁，坐在高处发号施令。我们要爬上去干掉他。"
D.SharedStrings[11579]="我会想念你的，$N。我欠你很大一份人情;我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。"
D.SharedStrings[11580]="我会拿到那些你想要的已签字文件，$G小伙子:小姑娘;?"
D.SharedStrings[11581]="我会跟随你到艾泽拉斯的每一个角落。"
D.SharedStrings[11582]="我們多了一份力量，敵人少了一個助力。這場仗我們一定會贏，$n！"
D.SharedStrings[11583]="我們差點在入侵行動開始之前就失敗了。做得好。"
D.SharedStrings[11584]="我們已經驅除了腐化，新生的水元素現在可以蓬勃成長了。"
D.SharedStrings[11585]="我們必須找到解決方案，我們沒有多少時間了。"
D.SharedStrings[11586]="我們港灣裡的法力鱒魚都已經釣捕殆盡。自從護盾升起後，我們現在只能在回憶中品嘗這滋味了。"
D.SharedStrings[11587]="我們雖然找回馨菲了，但她的心智還掌握在俘虜她的惡魔手中。\r\n\r\n他們到底在她身上下了什麼古代魔咒？我從來沒看過這種事情。"
D.SharedStrings[11588]="我們非常幸運，居然可以取回它…謝謝你。"
D.SharedStrings[11589]="我像一位姐姐一樣關愛路納斯特女士，但我恐怕舉步維艱。"
D.SharedStrings[11590]="我其实不太喜欢让宠物去战斗，但我喜欢在它们战斗结束之后照顾它们。"
D.SharedStrings[11591]="我几乎准备好要出发了，只差我和我家人的午餐...呃...我的法师同事来了。"
D.SharedStrings[11592]="我刚刚收到报告，在阴惨泥沼里又发现了另一只飞翼幼龙。$B$B我们要把能找到的所有飞翼幼龙都找回来。它们也许是在这岛上飞行的关键所在。"
D.SharedStrings[11593]="我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！"
D.SharedStrings[11594]="我只希望我有機會早一步對付他。\r\n\r\n啊！他的屍體在這片水域裡腐爛了我也不在乎。"
D.SharedStrings[11595]="我可以在一里外闻到新技师的气味，就像我可以在一里外闻到炸药的气味一样。你是来揭开炸药的神秘面纱的吗?"
D.SharedStrings[11596]="我可以幫你，但你必須先幫我一點小忙。"
D.SharedStrings[11597]="我可以感受到你的变化。$B$B你准备好进行下一步了吗?"
D.SharedStrings[11598]="我向你致歉，$G小子:小女孩;!那时我全神贯注，完全忽略了你的存在。"
D.SharedStrings[11599]="我听到了尖叫，很高兴那是夜之子们发出的。做得好。"
D.SharedStrings[11600]="我听神官帕尔崔丝讲过了。我要告诉你，她的话让我深思良久。与十字军并肩战斗是不够的，我们必须担负起他们的任务。$B$B在北方海岸的洛斯加尔登陆点发生了一桩血案。克瓦迪尔海盗们攻入一处古老的海象人居民区，将那里的村民屠杀殆尽。带上这本书，在那些村民的尸体旁边诵读书中的悼文。这样能让他们的灵魂离开那座被迷雾环绕的岛屿，得到最后的安息。"
D.SharedStrings[11601]="我听说过在海龟背上有车架这种事情。我相信这些都是纳迦的车架，他们用它来为作战服务，以及向陆地上运送物品。你找到的箱子上的标志也是纳迦的，这也许可以解释为什么最近在黑海岸北边会出现大量的纳迦。$B$B我准备把这只箱子和你发现的其它东西都送到达纳苏斯去。这个是给你的―再次感谢你的帮助。"
D.SharedStrings[11602]="我听说，在燃烧前线上落败后，暗影议会眼下正在用附近逝网蜘蛛的毒液来扩散邪能的腐化并壮大他们的军队。$B$B我们有位缚魂者看见一个恐惧魔王带着沙塔尔闯进了东边的矿井，那是奥金顿之心其余碎片中的一块。$B$B我要你从那个恐惧魔王身上夺取沙塔尔，把它带给我，勇士。"
D.SharedStrings[11603]="我和你一样焦急地想要试一下我的便携式伐木机，$c，但是我必须要弄到一些材料——我是说很多材料——才能制作出配套的工具！$B$B实际上，我需要像山那么大的一堆瑟银、秘银和铁，另外每一台伐木机还需要有一个蒸汽锯才能完工，你最好到伐木场去找找看。$B$B我在这里游荡的时候（在我被抓住之前），曾在雷矛伐木场里看到很多的蒸汽锯。"
D.SharedStrings[11604]="我和苏利该出发了。我们会注意寻找白卒留下的一切痕迹并尽快回报。$B$B在海军上将泰勒康复期间，我恐怕只能让你留下来主持大局了。在我们离开的期间，你要尽可能多地多了解这些锦鱼人。我希望当我们回来的时候能得到一份详细的报告。"
D.SharedStrings[11605]="我喜欢收集宠物，而且已经在德拉诺发现了几个罕见的小家伙。你想跟我打一场吗？要是你能击败我这几员小将，我想我们都会从这场切磋中受益匪浅的。"
D.SharedStrings[11606]="我在寻找被称为部族硬币的权力珍宝。在过去，祖尔格拉布的居民们将它们作为流通货币使用，每一枚硬币都浸入了微量而强效的魔精。$B$B这些硬币分为9种。如果你有多馀的硬币，我可以按3枚硬币对应一枚荣誉勋章的价格跟你交换，然后你就可以用勋章去跟林沃斯换取某些特殊的物品了。"
D.SharedStrings[11607]="我在这块石板上刻了几行符文，你能感受到它们所散发的能量吗？和铁矮人使用的符文相比，这些符文较为低等。但是我们依然可以利用它们粉碎铁矮人的阴谋。$B$B带上符文前往巨人平原，对一个尚未被改造的石巨人使用符文。$B$B在符文的作用下，石巨人会听从你的指挥并逐渐恢复原有的力量。接下来，你要在他的帮助下击败缚石者穆迪斯，这家伙就是盘踞在巨人平原的铁矮人领袖。"
D.SharedStrings[11608]="我在這裡看得一清二楚。那真是…慘不忍睹。"
D.SharedStrings[11609]="我好高兴你能看到我，终于有人能跟我说说话!$B$B你能帮帮我们吗，$N?帮帮我们将以前所犯的错导入正轨?如果你真的有瓦萨拉克领主护符上半块，我就能指引你拿到另外那2块，然后拼凑好就行了。$B$B喔，对了，你好，我叫布德利。很高兴认识你!"
D.SharedStrings[11610]="我實在無法表達對你的感激。我們會再度重逢的，我會確保我們再也不分開。"
D.SharedStrings[11611]="我将向你传授龙鳞制皮技能，你做这样的决定一定是下了极大的勇气吧。我向你保证，掌握这种技能会给你带来丰厚的回报。$B$B要学会龙鳞制皮，你只要跟我交谈，我就会把我所掌握的知识都传授给你。"
D.SharedStrings[11612]="我就坦白说吧，这可不是什么好活儿。$b$b邪刃蜥蜴人将他们产生的污物都堆在村子中央的一个坑里。那里的污物太过集中，恶臭熏天，以至于都浓缩成了一种能够移动的活物。$b$b那些蜥蜴人可以留着他们的垃圾坑，可当它扩散到村子外面的时候，那我们就该干涉了。"
D.SharedStrings[11613]="我就是塔隆·血魔……"
D.SharedStrings[11614]="我就是法律，我就是鞭子"
D.SharedStrings[11615]="我就知道他们干不了什么好事！那里有一些能够影响神志的化学药剂，但现在我手中的样品太少，没办法对它进行分析。我需要更多这种药剂。\n\n不要去花钱买那种东西！我可不想给那些恶棍一个铜板。你要想其它办法把它弄过来。\n\n我会把你伪装成一个送包裹的。我看到那些恶棍正在城门外看守着一批那种货物。过去取包裹，千万不要逗留，否则他们就会认出你！他们会扔给你一只箱子。把箱子带到这里来。"
D.SharedStrings[11616]="我已着手展开初步的侦查。纳迦也许没有意识到我们的存在，但他们也不是对入侵者毫无防备。$B$B在巡逻线后面，他们设置了魔法警戒装置，一旦有不速之客随时报警。幸运的是，它们为数不多，因此绝对有隙可乘，可以在触发之前摧毁这些装置。$B$B我相信你可以在我们的士兵到来之前处理好这件事。"
D.SharedStrings[11617]="我已经修好戒指，不过宝石还没有处理。$b$b话说回来……你是珠宝匠，$n。工具已经有了，你来切割一下宝石吧！"
D.SharedStrings[11618]="我已经将所有实用的技能传授给你了。$B$B与其他幸存者汇合的时候到了。据说格雷迈恩国王和他的皇家卫队就在此地以南。$B$B我们应该赶往那里，寻求庇护。人多的话，也会安全一点。"
D.SharedStrings[11619]="我已经把你的名字排入名册了，$N。作为一个志士，你将会与其它想要在联赛中竞争的人练习，并磨练你的骑乘战斗技能。一旦你证明了自己的实力，你将可以代表你的主城，进入最层次的竞赛。"
D.SharedStrings[11620]="我已经没有激情了，铭文师。我再也无法进入角色的内心。$b$b那边桌上有本没写完的小说，你看看吧。我写不下去了。或许你可以接着发挥。"
D.SharedStrings[11621]="我希望他们除了草莓冰淇淋之外还能做出更多口味的冰淇淋，但是还好我最喜欢的就是草莓口味!"
D.SharedStrings[11622]="我希望你在寇普雷萨的战功是一个预兆。这下子我们进攻他的城堡时巫妖王恐怕不能再袖手旁观了。"
D.SharedStrings[11623]="我希望你没有不小心惹到任何鞭笞者!上星期他们请大兵铎安吃了好一顿鞭子。"
D.SharedStrings[11624]="我并不把刚刚发生的事视为一个错误，$N…恰恰相反地。$B$B藉由一窥这个“心脏”，你让我确信了一件事。阿尔萨斯.米奈希尔已经不复存在了－这里，只剩下巫妖王。"
D.SharedStrings[11625]="我幾乎不敢相信我看見的景象。以單一術士之力統領整支惡魔軍團，實在超乎我對議會能力的想像。\r\n\r\n我只希望這樣的力量足以逆轉戰局。"
D.SharedStrings[11626]="我应该早点告诉你的……$b$b该怎么说呢……$b$b摩根可能以为他的家人都死了，不过实际上他的女儿莎拉·拉迪莫尔还活着，她现在也是个守夜人。她一直在因为她父亲死了以后所发生的……那些事情而苦恼。我想，你可以把关于她父亲的最新消息带给她。"
D.SharedStrings[11627]="我很快就会去找你的族人缔结盟约。$B$B现在请你走开。让我安静会儿。"
D.SharedStrings[11628]="我很担心尼娅米。她太过专注于取回奥金顿之心，仿佛已经对其它一切全都视而不见了。$B$B抱歉，我并不是在小瞧她的智慧，可你看看四周！我们派进矿井里的所有士兵都被逝网蜘蛛给咬成了重伤。必须立即处理他们的伤口！$B$B拜托了，你能从那些蜘蛛身上取些毒牙来吗？我可以用它们来制作解毒药，可我得留在这里，确保伤员的病情稳定。"
D.SharedStrings[11629]="我很高兴你能来，$n。$b$b这个……大法师卡德加收到了我的消息，并提议会面。他想尽快在城门口跟我们见面。$b$b你能跟我一起去见他吗？我有种奇怪的预感，那里可能不只他一个人。"
D.SharedStrings[11630]="我很高兴听说你愿意帮助我们进攻安其拉，$n。我可以制作一件装备，让你在作战时获得一些保护，$c。$B$B我需要一件其拉斗篷，然后把它按照你的体型进行修改。我还需要其拉塑像和圣甲虫，这样我才能制作合适的扣子。$B$B我保证你一定不会失望的。"
D.SharedStrings[11631]="我很高兴有人找到你了，$N。我正在担心呢。我们为你付出了这么多时间，失去你会很可惜的。$B$B不过这些问题我们可以晚点再谈，现在继续对你进行训练才是最重要的事。"
D.SharedStrings[11632]="我很高兴碎石堡派你来。灌木林的德鲁伊都被杀死了!只有我和另一个人还活着，而他也疯了。$B$B我不知道发生了什么事，但我想追根究底。不管是什么原因，它来的很快且不合常理。$B$B你会帮我吗?"
D.SharedStrings[11633]="我得承認你蠻厲害的，或許你真的能幫上我們的忙。"
D.SharedStrings[11634]="我從沒想到，我居然會在被流放的時候，跑來研究凋萎者。透過他們，我又對我的族人有了更深刻的認識，也更加瞭解我們與夜井的關係。"
D.SharedStrings[11635]="我從這裡就能聽見他們的哭喊，看到屠殺的慘況！總算能教訓那些任意奴役生物的夜裔精靈。躲在護盾下這麼多年來，他們竟然墮落到這種地步！"
D.SharedStrings[11636]="我必須為你今天拯救的維酷人表達感激之情。"
D.SharedStrings[11637]="我忠诚的骑士们始终尽忠职守。看来他们网罗到了一位英雄!"
D.SharedStrings[11638]="我恐怕已经没什么可教你的了，$n。但是，你作为宠物训练师的道路还远未走完！$B$B去奥格瑞玛向瓦佐克报到吧。他跟艾泽拉斯的许多顶尖训练师都有联络，她会帮助你继续前行的。"
D.SharedStrings[11639]="我恐怕已经没什么可教你的了，$n。但是，你作为宠物训练师的道路还远未走完！$B$B去暴风城向奥黛丽·伯恩赫普报到吧。她跟艾泽拉斯的许多顶尖训练师都有联络，她会帮助你继续前行的。"
D.SharedStrings[11640]="我恨鲨鱼。我的人都恨鲨鱼。这就是我们要你做的事情，$n。$b$b我要你去失落希望海角，干掉一条名叫坦克的鲨鱼。坦克可不是好惹的，所以如果我是你的话，我会多带几个朋友一起去。"
D.SharedStrings[11641]="我想你一定很熟悉鸦人吧，指挥官？鸦人是会飞的鸟人，身形巨大。极具领地意识。\n\n然而，有些鸦人的翅膀萎缩了——或许是患上了某种疾病。他们似乎是被赶出了鸦人社会。你有时候会看见他们蹲在被遗忘的遗迹间，或是在路边叫卖饰品。\n\n看来钢铁部落进驻鸦人领地的举动刺激到了他们，那些被放逐者纷纷离开了。\n\n$B$B我们应该与这些被放逐者建立联系——他们手上可能会有宝贵的情报。"
D.SharedStrings[11642]="我想弗蕾亚的徽记可能是最难得到的一块。$B$B根据档案馆的数据，徽记与弗蕾亚身边的三位古树仆从密切关联，它们是明叶长老、铁枝长老和石树长老。一旦它们之中有任何一位受到伤害，徽记的完整性就无法保障了。$B$B然而，如果你们对这三位长老手下留情，弗蕾亚的力量就会变得更加强大。$B$B我又能说什么呢，$n，我们现在真是进退维谷。"
D.SharedStrings[11643]="我想我会最大限度地利用眼前的机会。这帮地精佣兵给我的要塞送来了这只巨大的火元素，以此“感谢”我雇佣他们。我在燃烧平原要这种东西做什么？还嫌这里的火不够多啊。$b$b如果你想找活干，就证明自己的实力吧。跟那个地精谈谈，向他的火元素发起挑战。如果你赢了，你就能赢得我的尊重和认可。"
D.SharedStrings[11644]="我想我可能把主动式负载平衡器给弄坏了——好像是把负载电容弄到了整流器的轮辐中。我们必须想办法修好它，很简单的。我认识一个三联活塞设备方面的专家，她肯定很乐意修理这个主动式负载平衡器。把坏掉的主动式负载平衡器交给维妮·布特巴克，她就在莫尔杉农场的南边。她会修好它的。$B$B嘿，你不用走路——这正是测试我的单人传送设备的好机会呀！"
D.SharedStrings[11645]="我想我和你之间的任务已经清了。等我胆量足够了，我会赶走剩余的术士的。$b$b给，别忘记带上这些物资。"
D.SharedStrings[11646]="我想，是时候报仇了。这可不能怨我，谁让他们把我锁在厕所里，还想把我淹死？！$B$B要是你前往东边悬崖的南海据点帮我报仇，我不会让你白干的。"
D.SharedStrings[11647]="我感到欣慰，但還有我們必須做的事。"
D.SharedStrings[11648]="我感应到废墟中有一股强大力量在召唤我。你能再帮我去查查南部战斗现场吗？我敢肯定那儿有东西。"
D.SharedStrings[11649]="我感觉那头猎豹不太对劲，$n。太不自然了。我需要在尸体上进行一些仪式。杀掉玛乌提，然后我们看看能有什么发现，$n。"
D.SharedStrings[11650]="我愿意收下你身上任何多的印记。别担心;你的行为将受到适当的表扬。"
D.SharedStrings[11651]="我所有後悔的念頭，都在那些人進入護罩底下的時候消失了。"
D.SharedStrings[11652]="我才在懷疑為何突然間沒了她的消息。這對我的心情或許只是小有撫慰，但對於夜裔的部隊來說卻是極大的打擊。做得很好，$n。"
D.SharedStrings[11653]="我找到了一个更好的雪人毛皮来源，这真令人难以置信！在菲拉斯北部的怒痕堡中有另外一批雪人，它们比你遇到过的雪人可要难对付多了，如果你想要尝试更大的挑战，就去那里吧！$B$B如果你可以给我弄来一些它们的毛皮，我会给你丰厚的奖励！"
D.SharedStrings[11654]="我把它交给你了，$N。我们的机会或许不大，但有你的帮助让我安心很多。"
D.SharedStrings[11655]="我抵达时，塔隆戈尔和古尔丹正要通过传送门离开……而我……我知道自己打不过他们。$B$B我会尽量保持传送门开启。只能靠你去给他们致命一击了。$B$B我们的命运都掌握在你手里，$n。"
D.SharedStrings[11656]="我接受的命令是护送你前往南方，穿过龙喉大门，来到格瑞姆巴托入口处。我们已经清出了一条道路，以便其他人能够跟着我们去占领入口。$B$B我简单翻译一下吧：把会动弹的统统杀掉，要是你觉得还挺过瘾，也没什么不好意思的。$B$B小伙子们都不耐烦了。咱们走吧。"
D.SharedStrings[11657]="我收到了你在阿拉希盆地大显神威的报告，$N。干得好!如果有越来越多的像你这样勇敢的$C加入我们，我相信我们终有一天能夺回我们的家园。"
D.SharedStrings[11658]="我收到了来自维里副队长的紧急消息。原来黑石兽人雇佣了地精刺客。他们在修道院后面偷袭我们了的军队。维里让我派一名英雄去帮他。就是你了，$n！$B$B到修道院北边的指挥营帐去找维里副队长。出发！"
D.SharedStrings[11659]="我敌人的敌人……还是我的敌人！"
D.SharedStrings[11660]="我明白了。你带来的消息很可怕，但我也不是完全没有考虑过这种可能性。我知道在没有侦查过纳迦数量的情况下，我们的计划很冒险，但这就是为什么我们在这里建立前哨站的原因。$B$B让我跟你直说吧，$c。要是我们不能让纳迦无暇他顾，他们就会主动找上来。我们既没有人手，也没有设备可以形成防御，所以这就不可取。$B$B我们需要更多的时间，你能去南边削弱一下他们的兵力吗？"
D.SharedStrings[11661]="我最好从头开始说。起初是爱情，$n。那是我一眼就看中的一个地精。$B$B我们共度了一个星期的美好时光，斯内维尔说他弄到了一大笔钱，打算和我一起去南海度个长假！你能相信吗？$B$B不管怎么说，他让我收拾好行李，自己去银行、拍卖行和理发店跑趟差，但他再没回来过！我开始意识到他就是个大骗子！"
D.SharedStrings[11662]="我最悔恨的事就是我们——不，是我——对待尼希昂卓拉的方式。我强迫她产卵，然后我用它们来做实验。一遍又一遍，一遍又一遍。$b$b虽然我自己也是母亲，但我仍然无法想象她要承受怎样的悲痛。$b$b不……我不能脆弱。毕竟，我们的工作是为了黑龙一族的未来。她的牺牲是必要的。$b$b她在新卡加斯西北边的卡加斯废墟盘旋，因愤怒而变得疯狂。求求你们，英雄们……让她摆脱痛苦吧。"
D.SharedStrings[11663]="我會一直配戴這條項鍊，紀念索隆迪爾！"
D.SharedStrings[11664]="我會仔細研究這些東西。要是我們夠幸運，說不定可以找到答案。"
D.SharedStrings[11665]="我會幫你把這些…呃…紀念品…裝好。"
D.SharedStrings[11666]="我會負責將這個安全送回朋友手中。做得很好。"
D.SharedStrings[11667]="我有无数问题，但白色原始迅猛龙不是问题"
D.SharedStrings[11668]="我有责任对你的发现进行调查，$r，这也就意味着我的任务现在只能交给你了。$b$b一股远非天然生成的强大魔力将我引来此地，我这才发现事态大为不妙。$b$b有人将诺达希尔的一根树枝折了下来，带到了火焰之地的深处。在那里，敌人正利用它进行邪恶的仪式，以腐蚀诺达希尔，试图用大火烧毁它。$b$b你必须想办法干扰仪式，将世界之树的树枝夺回来。"
D.SharedStrings[11669]="我有點嚇到。有時候我覺得歐庫雷斯也不知道自己在做什麼。"
D.SharedStrings[11670]="我来过，我砍过，我征服过"
D.SharedStrings[11671]="我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!"
D.SharedStrings[11672]="我注意到你今天的确有些长进，$C。某几个瞬间，你和龙彷佛合而为一了。$B$B我很欢迎你，在有空的时候，和我珍贵的宠物砥砺技术。"
D.SharedStrings[11673]="我熟知元素制皮的技艺，如果你愿意敞开心扉学习更多的知识，那么我愿意与你分享我所知的一切。$B$B你要明白，$c：一旦你选择了这条道路，就必须承诺永远不学习龙鳞制皮或是部落制皮；你只能学习这三种手艺中的一种。此外，我需要你证明自己与大自然的元素有着融洽的关系，所以，你要将火、水、土和风元素最纯净的精华交给我。"
D.SharedStrings[11674]="我爱萨隆邪铁的清香（25人）"
D.SharedStrings[11675]="我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，人类。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。"
D.SharedStrings[11676]="我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。"
D.SharedStrings[11677]="我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你需要的保护也能让我们的敌人尝到恐惧的滋味。"
D.SharedStrings[11678]="我的两名部下在抓捕猛犸人穿刺者戈莫克的行动中丧生了。而那头怪物还在四处横行。他连续几个小时高声嗥叫，只是因为它找不到他喜欢的那个狗头人。$B$B如果银色北伐军不想在演武场中使用这头怪物，我会亲手把它杀了。不过，现在我们也许应该先给它找些玩具。拿上这张网，到风暴峭壁东南方的加姆雷区去。那里就在K3的东北方。在那里抓住一些狗头人。圣光保佑，但愿你能找到那头怪物喜欢的狗头人。"
D.SharedStrings[11679]="我的兄弟贾纳尔在数小时前率领我最骁勇的副官对城堡发起了攻击。他们到现在还没回来。$B$B我需要你先行一步去找他们。要是我们想在明天到来之前站在刀塔领主食人魔国王的头骨上，就得集结所有的战士才行。"
D.SharedStrings[11680]="我的军队处境艰难。钢铁部落无止无休地冲击着我们的防御。$B$B如果你真想要帮忙的话，就去前线找我的指挥官，帮他们稳住阵线吧。"
D.SharedStrings[11681]="我的出现吓到你了吗?你知道我是谁吗?"
D.SharedStrings[11682]="我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。"
D.SharedStrings[11683]="我的地盘，我说了算"
D.SharedStrings[11684]="我的對手消失以後，我就可以不受阻攔的取得領導權。"
D.SharedStrings[11685]="我的小妹將宛若重生，不管她自己喜不喜歡。"
D.SharedStrings[11686]="我的帽子？是啊，那顶帽子的款式非同寻常，很早以前的事儿啦……如今可没几个裁缝知道怎么缝制。$B$B年少轻狂的时候，我将它当作身份的象征。很多人想要击败我，赢得那顶帽子……可惜没人成功。$B$B啊，这些都是陈芝麻烂谷子的事了。我已经老了，每天喝喝酒，钓钓鱼，早就不与人决斗啦。"
D.SharedStrings[11687]="我的弟兄们虽然坚韧勇猛，但他们毕竟是血肉之躯。$B$B受伤和疼痛削弱了他们完成任务的能力，没有什么训练或者诀窍可以改变这一点。$B$B值得欣慰的是，我们的炼金师发明了一种药膏，与我们的绷带一起使用的话，可以大大缓解士兵的疼痛。$B$B药膏需要用到一种特殊的罂粟，正好这里的巨魔在西边的达克索塔农田中种了不少。去采一些罂粟回来，以保证我们的库存充足。"
D.SharedStrings[11688]="我的探子说摩拉迪姆沿着一条穿过墓地的弯曲怪异的小路，在暮色森林中四处游荡。我们曾把他的尸体埋在山上那座小屋的后面，你知道在哪儿吧？$b$b除了祝你好运之外，我没什么能帮你的了。"
D.SharedStrings[11689]="我的整个身心都能感觉到奈瑟匹拉正在试图与我交流，但我就是听不到她的声音。也许纳迦对她的声音动了什么手脚。$b$b<达鲁思考了一会。>$b$b奈瑟匹拉的声音也许是被压制了……也就是说……我们要为她找到发声的办法！$b$b我知道了！埃卓凯丝纳迦经常训练深渊猎手蟹作为战斗宠物。用这张网去捉一只螃蟹，把它给我带来。你可以在这间腔室的外缘找到它们。"
D.SharedStrings[11690]="我的族人安然無恙。現在我們來解決這些毒蛇！"
D.SharedStrings[11691]="我的朋友，我能帮你什么忙吗?你有需要兑换的礼券吗?"
D.SharedStrings[11692]="我的爱就像火红的玫瑰"
D.SharedStrings[11693]="我的選擇不多。我無法獨自面對黑騎士的另一次埋伏，而你的力量顯然相當強大。\r\n\r\n我會幫忙找你要的那把武器，但前提是你必須協助我，把他們搶走的其他東西物歸原主。\r\n\r\n就這樣說定了吧，術士？"
D.SharedStrings[11694]="我相信你一定可以在东南面的因度雷村的某处找到下一个魔法焦点。但问题是，我们完全没有收到任何关于那里是否存在魔法焦点的报告。$B$B如果你愿意的话，请前往因度雷村调查魔法焦点的痕迹，或者调查那个区域中的法师猎手部队和他们的指挥官。$B$B对了，如果有必要的话，不要忘记搜查一下湖底。"
D.SharedStrings[11695]="我看到他丢掉了这个，你知道吗?他从上面一丢，直直地掉到这儿。$B$B他说他不再需要这玩意了。说这让他变的软弱。"
D.SharedStrings[11696]="我看到你帶了剛切下來的魔火石化蜥蜴肉塊回來。\r\n\r\n仔細聽好。我會解釋這些東西的用途…"
D.SharedStrings[11697]="我看到你帶著紋章回來。太棒了。\r\n\r\n讓我們看看這隻蟲舌魔看到自己同伴的下場，會有什麼反應。"
D.SharedStrings[11698]="我看见古树们举行过一种奇怪的仪式。它们走进火里，烧光它们枝干上的树叶，再烤焦它们的树皮。\n\n我给这起了个名字叫“焦木仪式”。如果我们想削弱那些古树的力量，就必须在它们变得更强之前除掉它们。\n\n- 弗兰娜"
D.SharedStrings[11699]="我真不敢相信我们的日子就因为这个愚蠢的勋章而绑死了!你确定安希恩有提到布德利吗?$B$B嗯，你完成了你的工作，让我们来看看你的奖励吧。"
D.SharedStrings[11700]="我真的会很想你，$N。我欠你一份人情，这是我永远也无法回报的。$B$B好好使用你的新头饰和胸甲。愿它能保护你很长一段时间，为你带来更多的荣耀!"
D.SharedStrings[11701]="我知道你会响应号召，加入战斗。很荣幸能和你一起战斗。"
D.SharedStrings[11702]="我知道你的朋友在担心魔古岬那边的活动雕像，但我要告诉你，你们真正应该担心的是什么。\n\n只要有这种活动雕像的地方，就有魔古族。我不知道你以前是否见过这个种族，但如果你没有……\n\n好吧，简单来说魔古族对我们而言是非常非常糟糕的消息。\n\n无论要做什么，都必须首先解决掉制造麻烦的魔古族！"
D.SharedStrings[11703]="我知道我们被遗忘者在你们眼中就像怪物，但我向你保证，我们对你们的人民绝无恶意。我们会来这里是因为与血精灵有共同的敌人;背叛者达克汗!他已重回世上并率领着天灾军团从死亡之域往南入侵这片土地。$B$B来自这片土地的希尔瓦娜斯.风行者，她曾是个精灵，现在是我们的领导者。她曾和达克汗交手过，所以也跟你们一样希望达克汗死!$B$B我们会一同击败他的，$C!"
D.SharedStrings[11704]="我知道柯林恩。我們不會低估他的狠毒，我保證。\r\n\r\n謝謝你幫助歐蘿蕾，她是我非常要好的朋友。"
D.SharedStrings[11705]="我知道费伍德森林正在被痛苦折磨，$N，因为我自己也在体尝这样的痛苦!但我必须保持自己坚定的意志……如果我所掌握的知识落入了错误的人的手里，那费伍德森林就将遭受一场空前的灾难。$B$B帮我从扭木元素身上抽取血琥珀，然后我就能相信你会帮助我和堕落进行斗争了。"
D.SharedStrings[11706]="我知道，我知道，这个要求很离谱，但我们需要一切可能的帮助，$G小伙子:丫头;！"
D.SharedStrings[11707]="我确实很熟悉这样的物品。$B$B<史戴芬望入你的眼中。>$B$B看起来，$N…你似乎被…选上了。"
D.SharedStrings[11708]="我简直要无聊到发疯了——我一步都没离开过这地方！$b$b你看起来像是个见过点世面的冒险者。要是你能给我带来一个真正的英雄故事，我这肯定有你感兴趣的好东西。"
D.SharedStrings[11709]="我聽說你打算離開這座城市…據說夜裔精靈還有其他地方可去，在那裡我們再也不用忍受艾莉珊德的瘋狂。\r\n\r\n我想跟你一起走。\r\n\r\n我可以為你彈豎琴，也可以當你的幫手，雖然這些在這裡都派不上用場。\r\n\r\n只要你開口，我就跟你一起透過傳送器離開，與另一端的知音分享我的音樂。"
D.SharedStrings[11710]="我肯定你的熊猫人朋友知道魔古族到底要找什么。$B$B他前几天独自上山去了，没有带向导，并且要求你自己去山上找他。他说得很详细：$B$B“$c必须独自完成这段艰难跋涉，让$g他:她;的思想指引前行之路。在山顶跟我碰面前，$g他:她;得拜祭每一个神龛。”$B$B上山的路径就在营地的西北边，已经用旗子标出来了。切记要小心！即使有老天保佑，探索者末路也是一段危险的路程。"
D.SharedStrings[11711]="我能够看出你操纵憎恶的技术有不错的成长。$B$B努力点，我的朋友，很快的死亡之门就会属于部落。"
D.SharedStrings[11712]="我要求你做的事几乎是不可能办到的，但我仍然希望你可以成功。全靠你了。"
D.SharedStrings[11713]="我要的原料在哪儿，$N?!"
D.SharedStrings[11714]="我要让你们的世界……彻底颠覆……"
D.SharedStrings[11715]="我要这里东边的亡灵卫兵驿站立刻给我提交一份最新的报告。$B$B我必须知道天灾军团是否已经迂回绕过了亡灵壁垒并进入了提瑞斯法林地。我们要时刻保持警惕，封锁住这里与瘟疫之地的边境，绝对不能让天灾军团占据这里的任何一寸土地！$B$B沿着路向南走，在第一个岔路口转向东，就可以到达驿站了。到那里去找亡灵卫兵林奈，她手里掌握着我最需要的情报。"
D.SharedStrings[11716]="我说的是戈多克镣铐钥匙―好吧，那些胖家伙是这么叫它的。任何巨魔都有可能拿着这把钥匙，不过我不清楚到底谁拿着它。没准那些卫兵是负责看管钥匙的……$B$B啊呀，我到底在想什么?你已经拿到钥匙了，对吧?"
D.SharedStrings[11717]="我跟你说，伙计，这地方离碧野千里的纳格兰的大草原和血腥残酷的祖达克很远，但是呢，哪里有金币，哪里就有我！那么，欢迎来到暮高，朋友。$B$B你是刚来这座竞技场的，我就跟你简单明了地说吧。我是这里的竞技场组织者，旁边这位活泼的巨魔是我的保镖伍迪。你是这里的主角，当你想要作战的时候，告诉我一声，我就给你安排比赛。$B$B如果你已经准备就绪，还带来了一组伙伴，我们就可以开始了！你觉得呢？"
D.SharedStrings[11718]="我过去在一条专跑从这里到卡利姆多的棘齿城的航线上干过。我是个很优秀也很有名望的船长。$B$B直到……$B$B那些该死的海巨人毁了我的生活！他们打沉了我的船，杀光了我的水手，把我丢在一条救生艇上，让我漂回了藏宝海湾。还有，其中一个名叫高拉什的巨人还把我的箱子给偷走了，他说要拿这东西当鼻烟盒，简直是神经病！$B$B我听说有人看见高拉什最近在东边的海岸一带闲逛。找到他，把我的箱子给抢回来！快去，你会得到一位船长的敬意的。"
D.SharedStrings[11719]="我还有好几百个任务要执行，$C。你取到书了吗?"
D.SharedStrings[11720]="我还有最后一个任务要给你，$r……一个足以扭转战局的任务。$B$B请你回到圣地，去杀死那些指挥战斗的通灵师。只要他们死了，我们就能击退天灾的军队，并慢慢夺回圣地。$B$B我还要你去找到圣地下面的堕落之源并摧毁它。$B$B我知道我要你做的事情太多了，但如果你能做到的话，我们就可以赢得这场战斗。"
D.SharedStrings[11721]="我需要你的帮助。艾斯卡不见了。有理由相信，他跟踪上了聚集在塔纳安的塞泰克余党。我一直在调查，而结果……那是什么？$b$b<瑞沙德的声音越来越低，像是在窃窃私语>$b$b阴影中有什么动静，有人在监视我们！$b$b拿上这些药剂，只要碰到空气，这些液体就会变成味道刺鼻的云雾。非常难闻，他们肯定受不了的。用它把那些监视我们的人从藏身之处赶出来。"
D.SharedStrings[11722]="我需要那些外套和头罩，另外还需要一株野葡萄，然后我就会把蛮皮盔帽的制作方法告诉你。$B$B防护头部的装备是冒险者们垂涎已久的，无论是简单的头带还是一顶密闭的盔帽，无论其外观如何，制造有价值的头部装备的道理是恒久不变的。"
D.SharedStrings[11723]="我预见你将跟随燃烧之星，走上它所揭示的道路。"
D.SharedStrings[11724]="戒指本身会缓慢烧灼佩戴者，但它的高温能被引导到目标身上。"
D.SharedStrings[11725]="战争之子巴尔萨鲁斯"
D.SharedStrings[11726]="战争之矛切割者"
D.SharedStrings[11727]="战争之矛步兵"
D.SharedStrings[11728]="战争使者施瑞瓦洛克斯"
D.SharedStrings[11729]="战争使者沃姆罗格"
D.SharedStrings[11730]="战争使者莫克纳"
D.SharedStrings[11731]="战争古树"
D.SharedStrings[11732]="战争坐骑军需官"
D.SharedStrings[11733]="战争大师布格索尔"
D.SharedStrings[11734]="战争大师黑角"
D.SharedStrings[11735]="战争机器免疫昏迷、移动限制效果和失去控制的效果。"
D.SharedStrings[11736]="战争来临了，$N，伴随着无法形容的恐惧。你已经做了你该做的事情，应该受到奖励。$B$B这……这预言会成真吗……$B$B<地质学家拉克斯班脸色变得苍白。>$B$B我们也许没有未来可言了。$B$B这些物资对你来说应该很有用。"
D.SharedStrings[11737]="战争法师法诺莱斯"
D.SharedStrings[11738]="战争践踏"
D.SharedStrings[11739]="战争领主加尔顿"
D.SharedStrings[11740]="战争领主加尔顿主动请缨，要为我们的事业招募更多的破碎者战士。首先，他需要一些东西。他提到要有合适的工具才能事半功倍之类的话。\n\n是时候派出你的新勇士接受考验了。我敢肯定，这次的任务会非常辛苦。"
D.SharedStrings[11741]="战刃会对其路径上的所有玩家造成{1}点物理伤害。"
D.SharedStrings[11742]="战地修理机器人110G"
D.SharedStrings[11743]="战地医者板带"
D.SharedStrings[11744]="战地治疗者披风"
D.SharedStrings[11745]="战场军官"
D.SharedStrings[11746]="战场：贫瘠之地"
D.SharedStrings[11747]="战士之殇长袍"
D.SharedStrings[11748]="战士训练师"
D.SharedStrings[11749]="战备招募员"
D.SharedStrings[11750]="战斗中，大魔导师会周期性地召唤时光元素。这些元素被击败后，会留下一道裂隙。该裂隙会一直存在，直到有人将其消耗为止。"
