D.SharedStrings[11758]="战斗宠物训练师：潘达利亚"
D.SharedStrings[11759]="战斗宠物训练师：诺森德"
D.SharedStrings[11760]="战斗开始时，瑟纳利昂立即飞上空中，瓦里昂娜在地面上迎战。这对双生龙共享生命值，并交替飞上空中和落地作战。"
D.SharedStrings[11761]="战斗次数最多的评级战场"
D.SharedStrings[11762]="战斗法师凯丝琳"
D.SharedStrings[11763]="战斗法师凯特琳的影像"
D.SharedStrings[11764]="战斗法师凯特琳的影像要你找回伯林纳德的研究笔记。"
D.SharedStrings[11765]="战斗法师艾尔娜希望你去和艾雷·碎云谈一谈，飞往死亡之痕。用奥术炸弹杀死2个深渊霸主、3个艾瑞达巫师和12个天怒执行者。"
D.SharedStrings[11766]="战斗的召唤"
D.SharedStrings[11767]="战斗的召唤！"
D.SharedStrings[11768]="战斗的召唤：奥特兰克山谷"
D.SharedStrings[11769]="战斗的召唤：征服之岛"
D.SharedStrings[11770]="战斗的召唤：战歌峡谷"
D.SharedStrings[11771]="战斗的召唤：远古海滩"
D.SharedStrings[11772]="战斗的召唤：阿拉希盆地"
