D.SharedStrings[11785]="战歌峡谷军官"
D.SharedStrings[11786]="战歌峡谷的战事趋于白热化，$N。尽你的努力将银翼哨兵驱逐出我们的土地!"
D.SharedStrings[11787]="战歌峡谷的战斗"
D.SharedStrings[11788]="战歌峡谷胜利"
D.SharedStrings[11789]="战歌恶狼"
D.SharedStrings[11790]="战歌掠夺者"
D.SharedStrings[11791]="战歌氏族"
D.SharedStrings[11792]="战歌氏族依靠震慑和威吓来战胜敌人，他们的氏族名就得名于他们可怕的战吼和行军过程中雷鸣般的战鼓声。这些骇人的战鼓由塔布羊皮蒙在疑似食人魔头骨的骨架上制成，以纪念氏族脱离食人魔帝国，获得自由的历史。"
D.SharedStrings[11793]="战歌氏族的骑手们总是在不停移动。在营地中，每个家庭的帐篷外都有一根插入地下的长矛作为标志——上面通常还会挂着主人所击败的敌人脑袋作为装饰。这个样品已经有超过一百年的历史，上面刻着好几场重大战役的名字。"
D.SharedStrings[11794]="战歌煽动者"
D.SharedStrings[11795]="战歌要塞的防御"
D.SharedStrings[11796]="战歌远征军统帅"
D.SharedStrings[11797]="战歌驯狼者"
D.SharedStrings[11798]="战火平原位于科雷萨的前方，铁墙堡垒的南方。巫妖王在这里布置了精锐部队以守卫冰冠堡垒。$B$B一队死亡骑士率领着大群的冰冠劫掠者守住了道路。我担心就算我们打倒了这些劫掠者，天灾军团也能复活它们，并把它们再次投入战场。$B$B我已经有了一个解决方案，不过尚不知道能否奏效。带着这瓶溶液，用它去溶解那些冰冠劫掠者的残骸。"
D.SharedStrings[11799]="战神阿尔图克拉"
