D.SharedStrings[11835]="戴拉·锐矛"
D.SharedStrings[11836]="戴着面具。"
D.SharedStrings[11837]="戴米多斯的仆从"
D.SharedStrings[11838]="所以传说是真的?有了这么一柄好剑，我一定能在联赛中好好发挥。非常感谢你，$N."
D.SharedStrings[11839]="所以传说是真的?有了这么一柄好剑，我一定能在联赛中好好发挥。非常感谢你，$N。"
D.SharedStrings[11840]="所以传说是真的?这柄剑足以胜过所有联盟参赛者的配剑。"
D.SharedStrings[11841]="所以你成功的阻止了黑铁矮人…还是在醉酒的时候?$C，这正是啤酒节的真正精神!我猜你这么具有啤酒节精神，也是想要一些奖品章。$B$B谢谢你的帮忙，$N。享受啤酒节吧。"
D.SharedStrings[11842]="所以你的决定是什么?是要战斗还是提供你的协助?"
D.SharedStrings[11843]="所以你说黑骑士的说词全是假的?太可疑了。轻则说谎，重则谋杀。但是我们不能揭穿他，除非我们能找到他涉入这些谋杀的证据。$B$B别引起他的怀疑，$N。谨慎行事有助于我们进一步的调查。"
D.SharedStrings[11844]="所以呢?你还喜欢你的天灾生活吗?$B$B相信我，并不像看起来的那么美好……"
D.SharedStrings[11845]="所以那个古老传说是真的?至少这把剑的质地是名不虚传。干得好，$N。能配上这把剑的勇士的确运气不错。"
D.SharedStrings[11846]="所受伤害的{1}%将转移到附近的一名德鲁伊身上。"
D.SharedStrings[11847]="所向披靡和上帝之手发出强烈的共鸣，急切地要刺入大检察官怀特迈恩的尸体。"
D.SharedStrings[11848]="所有人都让开，由你来表演精彩的独奏！"
D.SharedStrings[11849]="所有以银色黎明之名与邪恶战斗的勇士都必须佩戴我们的委任徽记，这样你们就可以向我们的军需官领取奖赏。$B$B在受到委任之后，你就可以从天灾军团士兵的尸体上收集天灾石，那是他们身份和职位的证明。将你收集到的天灾石交给我，每套天灾石都可用来换取一枚勇气和荣耀的象征―银色黎明勇气徽记。$B$B实现你的价值，$C，今天就加入与天灾军团作战的行列!"
D.SharedStrings[11850]="所有伤害性法术或技能命中目标时，都会为你恢复8%的最大生命值。"
D.SharedStrings[11851]="所有伤害提高{1}%。"
D.SharedStrings[11852]="所有伤害提高{1}%。\r\n攻击速度提高{2}%。"
D.SharedStrings[11853]="所有伤害提高{1}%。\r\n施法速度提高{2}%。"
D.SharedStrings[11854]="所有伤害提高{1}%。\r\n生命值恢复速度提高{2}%。\r\n急速提高{3}%。"
D.SharedStrings[11855]="所有伤害提高{1}%，移动速度提高{2}%。"
D.SharedStrings[11856]="所有属性提高{1}%。"
D.SharedStrings[11857]="所有属性提高{1}%。\r\n冰霜伤害提高{2}%。"
D.SharedStrings[11858]="所有属性提高{1}%。\r\n急速提高{2}%。"
D.SharedStrings[11859]="所有属性提高{1}%。\r\n最大生命值降低{2}%。"
D.SharedStrings[11860]="所有属性提高{1}%。这种效果在死亡后仍可继续存在。"
D.SharedStrings[11861]="所有属性提高{1}点。"
D.SharedStrings[11862]="所有属性降低{1}%。"
D.SharedStrings[11863]="所有属性降低{1}点。"
D.SharedStrings[11864]="所有攻击的爆击几率提高{1}%。"
D.SharedStrings[11865]="所有攻击者对该目标造成的远程伤害都提高{1}%。无论是潜行还是隐身，都无法摆脱猎人的追踪。"
D.SharedStrings[11866]="所有治疗效果提高{1}%。"
D.SharedStrings[11867]="所有治疗效果降低{1}%。"
D.SharedStrings[11868]="所有治疗法术消耗的法力值降低{1}%。"
D.SharedStrings[11869]="所有流血效果、重殴和撕碎造成{1}%的额外伤害。"
D.SharedStrings[11870]="所有玩家立即死亡。要不是泰坦的话，所有的希望都将消失……"
D.SharedStrings[11871]="所有的有害魔法效果对站在废灵壁垒之内的友方单位无效。"
D.SharedStrings[11872]="所有的鸦人在死后，都希望能升入德拉诺天空中的太阳神鲁克玛的神国。因此火葬就成为他们最偏好的葬礼形式。有些人会将他们的骨灰撒入高空，而其他人则选择用精美的骨灰坛将骨灰收集起来，放入墓穴。"
D.SharedStrings[11873]="所有神圣和自然系法术所消耗的法力值降低{1}点。"
D.SharedStrings[11874]="所有被暗影触摸过的东西都会在被击败后留下虚空的痕迹，如果你能在城市中收集到足够的虚空物质，就回来找我。我可以把它们提纯。 \n\n我们可以拯救更多族人。"
D.SharedStrings[11875]="所有身强力壮的部落成员，从此刻起都要向加林之陨的黑暗游侠阿莉娜报到。黑暗女王的部队需要你们的帮助，以拓展部落的势力范围，并击退联盟入侵者。$B$B要前往阿拉希高地，就向希尔斯布莱德丘陵东部进发，穿过索拉丁之墙后沿着路继续走。$B$B命运在召唤！"
D.SharedStrings[11876]="所有身强力壮的部落成员，从此刻起都要向希尔斯布莱德丘陵南点大门的高级执行官达萨利亚报到。被遗忘者的战争机器正在全力开动，为部落夺取洛丹伦！$B$B要前往南点大门，就沿着南边的路穿越银松森林，然后走东边的岔路进入希尔斯布莱德丘陵。$B$B前进吧，$g兄弟:姐妹;！命运在召唤！"
D.SharedStrings[11877]="所有近战攻击都会顺劈锥形范围内的目标。"
D.SharedStrings[11878]="所有造成的伤害提高{1}%。\r\n攻击速度提高{2}%。"
D.SharedStrings[11879]="所有链接的单位共享生命值。\r\n暗影镜像从所有来源受到的伤害提高{1}%。"
D.SharedStrings[11880]="所造成的一部分伤害反射给施法者。"
D.SharedStrings[11881]="所造成的伤害提高{1}%。"
D.SharedStrings[11882]="所造成的伤害提高{1}%。\r\n攻击和施法速度提高{2}%。"
D.SharedStrings[11883]="所造成的伤害提高{1}%。\r\n法术不消耗法力值且为瞬发。\r\n近战和远程攻击速度提高100%。"
D.SharedStrings[11884]="所造成的伤害提高{1}%。\r\n生命值提高{2}%。\r\n法术不消耗法力值且为瞬发。\r\n近战和远程攻击速度提高100%。"
D.SharedStrings[11885]="所造成的物理伤害提高{1}%。\r\n双持。"
D.SharedStrings[11886]="手中抓着舞棍。"
D.SharedStrings[11887]="扎尔提克助战者"
D.SharedStrings[11888]="扎尔提克琥珀祭司"
D.SharedStrings[11889]="扎尔提克祈愿者"
D.SharedStrings[11890]="扎尔杜姆，吞噬者的法杖"
D.SharedStrings[11891]="扎尼提克操纵者"
D.SharedStrings[11892]="扎尼提克穿刺者"
D.SharedStrings[11893]="扎布拉·海克斯"
D.SharedStrings[11894]="扎莉娅·影心"
D.SharedStrings[11895]="扑向目标。近战范围内的敌人被击倒，并遭受相当于{1}%武器伤害的物理伤害。"
D.SharedStrings[11896]="扑向目标并使其昏迷。"
D.SharedStrings[11897]="扑灭你的轰炸机上的火焰（如果轰炸机起火的话）。"
D.SharedStrings[11898]="扑灭北荆棘谷祖玛维的8个祖玛维火盆。"
D.SharedStrings[11899]="扑灭火焰然后在海盗上船之前使其沉没。"
D.SharedStrings[11900]="扒窃目标的口袋。如果目标身上携带有至少5个神器碎片，则会偷取碎片。"
D.SharedStrings[11901]="打击一名敌人，对其造成物理伤害。"
D.SharedStrings[11902]="打击一名敌人，对其造成物理伤害，并将其击退。"
D.SharedStrings[11903]="打击者科吉克"
D.SharedStrings[11904]="打孔的巫毒人偶"
D.SharedStrings[11905]="打开一个混乱裂隙后击败安托鲁斯，燃烧王座的传送门守护者哈萨贝尔（普通或更高难度）。"
D.SharedStrings[11906]="打开一件可爱的裙装盒，并获得一件可爱的黑裙子。"
D.SharedStrings[11907]="打开你的追随者页面并使用该物品，让一名勇士直接获得{1}点经验值。"
D.SharedStrings[11908]="打开木笼，帮助联盟斥候逃出银溪镇。抵达琥珀松木营地后向杜蒙特中尉汇报情况。"
D.SharedStrings[11909]="打开箱子。"
D.SharedStrings[11910]="打开蚌壳！"
D.SharedStrings[11911]="打开袋子。"
D.SharedStrings[11912]="打扮成赞达拉巫医！赞达拉巨魔认为你是友好的……"
D.SharedStrings[11913]="打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B达纳苏斯的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是伊范达尔·鹿盔亲自负责这项研究。$B$B要是你感兴趣的话，请直接去达纳苏斯的塞纳里奥区找他谈谈。"
D.SharedStrings[11914]="打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B雷霆崖的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是哈缪尔·符文图腾亲自负责这项研究。$B$B要是你感兴趣的话，请直接去雷霆崖的长者高地找他谈谈。"
D.SharedStrings[11915]="打洞者护腕"
D.SharedStrings[11916]="打破书上的封印，使你的治疗法术有一定几率为你召唤出一名幽灵盟友。"
D.SharedStrings[11917]="打破困住那头生物的冰块。"
D.SharedStrings[11918]="打碎补给箱，获得一个增益效果。"
D.SharedStrings[11919]="打磨你的锋利武器，使其武器伤害提高{1}点，持续1小时。不能对物品等级高于200的物品使用。"
D.SharedStrings[11920]="打翻你的对手（第1赛季）"
D.SharedStrings[11921]="打翻你的对手（第2赛季）"
D.SharedStrings[11922]="打遍天下无敌手（第1赛季）"
D.SharedStrings[11923]="扔出一个可攻击的桶在地上，它会周期性地召唤出愤怒的灵魂。"
D.SharedStrings[11924]="扔出一个阴燃的地狱火核心，对附近敌人造成伤害。"
D.SharedStrings[11925]="扔出一把沉重的武器，在冲击地点造成物理伤害。"
D.SharedStrings[11926]="扔出一把锤子，对一名敌人造成神圣伤害。"
D.SharedStrings[11927]="扔出一条鱼，干扰范围内的所有邪能鱼人，持续10秒。\r\n"
D.SharedStrings[11928]="扔出一颗火球，命中时会造成火焰伤害并将目标点燃，对目标区域中的敌人每秒造成额外的火焰伤害。"
D.SharedStrings[11929]="扔出你的武器，对目标造成{1}%的武器伤害。"
D.SharedStrings[11930]="扔出你的武器，对目标造成该武器伤害的{1}%的伤害。"
D.SharedStrings[11931]="扔出旋转的刀刃，对附近敌人造成物理伤害。"
D.SharedStrings[11932]="扔出这根钩线，让它绕过一个塞拉赞恩的仆从的腿，然后猛拉钩线，将他拖倒。"
D.SharedStrings[11933]="扔向一个朋友，或者扔向正在燃烧的建筑物。"
D.SharedStrings[11934]="扔掷易爆之球，对冲击点周围5码范围内的所有敌人造成{1}点火焰伤害，并将其击退。"
D.SharedStrings[11935]="扔火炬游戏对你来说已经易如反掌啦，那么试试接火炬吧！$B$B带上这捆未点燃的火炬，在篝火堆附近用力向上抛起一只，在火炬落地之前接住它……然后再往上抛！连续接住火炬4次，然后回来找我。可别接不住呀！如果你接不住的话，就得返回篝火堆那里从头再来咯。祝你好运！"
D.SharedStrings[11936]="扔进烟花发射器中！"
D.SharedStrings[11937]="扔进烟花束发射器中！"
D.SharedStrings[11938]="托什·混沌治愈者"
D.SharedStrings[11939]="托塞德林王子"
D.SharedStrings[11940]="托多斯的废弃甲壳"
D.SharedStrings[11941]="托多斯的攫甲者"
D.SharedStrings[11942]="托尔巴拉德主宰"
D.SharedStrings[11943]="托尔巴拉德战斗法师"
D.SharedStrings[11944]="托尔巴拉德的新一天"
D.SharedStrings[11945]="托尔巴拉德精英"
D.SharedStrings[11946]="托尔托拉之子"
D.SharedStrings[11947]="托尔托拉龟甲号"
D.SharedStrings[11948]="托德曼上校"
D.SharedStrings[11949]="托比亚斯·密斯特曼托"
D.SharedStrings[11950]="托米·乔·斯通菲尔德"
D.SharedStrings[11951]="托维尔圣甲虫"
D.SharedStrings[11952]="托维尔失落之城"
D.SharedStrings[11953]="托维尔失落之城奖励任务"
D.SharedStrings[11954]="托维尔的解剖学知识让你对尼斐塞特造成的伤害提高{1}%。\r\n\r\n只有当你处于托维尔失落之城的时候才会生效。"
D.SharedStrings[11955]="托维尔隆竞技场的比赛"
D.SharedStrings[11956]="托维尔隆竞技场的胜利"
D.SharedStrings[11957]="托莫克在战斗中被击败了。你可以在他痊愈后在兵营里重新招募他。"
D.SharedStrings[11958]="托莫克是高里亚帝国的百夫长。他是强大的士兵，且身经百战、所向披靡。"
D.SharedStrings[11959]="托里姆"
D.SharedStrings[11960]="托里姆已经失去了自我，$n。一股黑暗的力量正在影响着他。$B$B某个邪恶的家伙假扮成他死去的妻子西芙，蒙蔽了他的心智。$B$B你要阻止那个冒牌货控制托里姆。如果托里姆被这股力量征服，我们就永远都无法找到他的徽记了！$B$B你要让他清醒过来，越快越好！$B$B和以往一样，档案馆的控制台会给你提供所有必要的讯息……包括那些你不喜欢听到的讯息。"
D.SharedStrings[11961]="托里姆的影像"
D.SharedStrings[11962]="执政团之座"
D.SharedStrings[11963]="扬起一股沙尘，并使沙尘中的目标受到的伤害降低{1}%。"
D.SharedStrings[11964]="扭扭……是……我……最好的……朋友！"
D.SharedStrings[11965]="扭曲的符文腕轮"
D.SharedStrings[11966]="扭曲的虚空法师"
D.SharedStrings[11967]="扭曲观察者科里度斯"
D.SharedStrings[11968]="找出军团情报、星图，以及维伦的影像，然后消灭蛛后艾拉米丝。"
D.SharedStrings[11969]="找出玛乌提把格伦特·恐锤藏在了哪里。"
D.SharedStrings[11970]="找到BD-816战斗仪器、机械火焰、机械之冰和机械空气。"
D.SharedStrings[11971]="找到一位能够帮助我们的当地渔夫。"
D.SharedStrings[11972]="找到东部王国的糖罐。"
D.SharedStrings[11973]="找到他们，追猎他们，杀死他们。给我们的敌人上一堂永生难忘的课！"
D.SharedStrings[11974]="找到你的尸体或者与灵魂医者交谈以复活。"
D.SharedStrings[11975]="找到卡利姆多的糖罐。"
D.SharedStrings[11976]="找到并对兽栏中的5只迅猛龙、掠食龙、啸天龙或恐角龙使用恐龙神像。"
D.SharedStrings[11977]="找到并消灭维持苏伊什驯服状态的夜之子。"
D.SharedStrings[11978]="找到并碰触在黑石塔、厄运之槌、通灵学院和斯坦索姆内的火盆，并回到节日护火者处。"
D.SharedStrings[11979]="找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。$B$B根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。"
D.SharedStrings[11980]="找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。"
D.SharedStrings[11981]="找到水晶重塑装置并用它来复原阿古斯之梦。"
D.SharedStrings[11982]="找到洛拉姆斯的头颅、洛拉姆斯的躯干和洛拉姆斯的腿。"
D.SharedStrings[11983]="找到潘达利亚的糖罐。"
D.SharedStrings[11984]="找到灾变区域的糖罐。"
D.SharedStrings[11985]="找到破损的魔力圆盘并修复魔网能量。"
D.SharedStrings[11986]="找到臭名昭著的海盗巴隆·朗绍尔，跟他谈一谈。"
D.SharedStrings[11987]="找到贫瘠之地的水之先知伊斯伦。"
D.SharedStrings[11988]="找到霜火岭任务指令、影月谷任务指令和阿兰卡峰林任务指令。"
D.SharedStrings[11989]="找到高格里克的缩放模型、小型战争机器和塔纳安丛林地图。"
D.SharedStrings[11990]="找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。"
D.SharedStrings[11991]="找卡德加索要一个军团联络器的能量源。"
D.SharedStrings[11992]="找回下列讲述尼特加尔大帝盛衰历程的托维尔神器。"
D.SharedStrings[11993]="找回下列讲述派拉蒙德和瑟莱斯特命运的暗夜精灵神器。"
D.SharedStrings[11994]="找回遗失的奎尔德拉剑柄，从剑冢中拔出奎尔德拉，将其重铸，随后在太阳之井中进行净化，而它将成为你不辞辛苦的奖励。"
D.SharedStrings[11995]="找齐隐藏在风暴烈酒酿造厂内的30个金毛跳跳兔（任意难度）。"
D.SharedStrings[11996]="承受了橙色和绿色毒气之后，返回到采炼师阿德里安娜那里。"
D.SharedStrings[11997]="承受的伤害提高{1}%。"
D.SharedStrings[11998]="技师的膨化炸药"
D.SharedStrings[11999]="技师罗姆尔的使用战锤的本领就跟他的水晶制作技术一样神乎其神。"
D.SharedStrings[12000]="把10块致密砂轮、10块坚固的砂轮和10块重砂轮交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 III才能完成这个任务。"
D.SharedStrings[12001]="把1份大块魔光碎片、1份大块强光碎片和1块巨型绿宝石交给希利苏斯塞纳里奥要塞的地质学家拉克斯班。你还必须随身带着后勤任务简报 V才能完成这个任务。"
D.SharedStrings[12002]="把1块月布、2卷符文布卷和1份铁网蛛丝交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着后勤任务简报 VIII才能完成这个任务。"
D.SharedStrings[12003]="把2块魔化瑟银锭和2块魔化皮交给希利苏斯塞纳里奥要塞的瓦古斯。你还必须随身带着后勤任务简报 IX才能完成这个任务。"
D.SharedStrings[12004]="把3双精制秘银战靴交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。你还必须随身带着后勤任务简报 II才能完成这个任务。"
D.SharedStrings[12005]="把4份纯水之球、4份特效抗毒药剂和4份烤鲑鱼交给希利苏斯塞纳里奥要塞的卡兰德拉斯。你还必须随身带着后勤任务简报 I才能完成这个任务。"
D.SharedStrings[12006]="把《高效挖掘技巧》交给司克诺兹登陆点的贝洛克·辉刃。"
D.SharedStrings[12007]="把一个敌人从对面平台拉到施法者身边。"
D.SharedStrings[12008]="把不准的玛洛瑞滴定管交给技术高超的炼金师校准。"
D.SharedStrings[12009]="把主动式负载平衡器交给北贫瘠之地诺兹波特的哨站的斯布特瓦夫。"
D.SharedStrings[12010]="把他们熏出来！"
D.SharedStrings[12011]="把他们都干掉！"
D.SharedStrings[12012]="把你自己装进投石器的弹药篮中，可以被发射出去。"
D.SharedStrings[12013]="把信交给孙行·铁掌。她在半山市集教授厨艺。"
D.SharedStrings[12014]="把其拉统御腕轮、2个先知塑像、5个青铜甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。"
D.SharedStrings[12015]="把卡德加的信交给希利苏斯的麦格尼·铜须。"
D.SharedStrings[12016]="把可疑的徽章交给暴风城军情七处总部的马迪亚斯·肖尔。"
D.SharedStrings[12017]="把图纸交给你要塞船坞中的海军装备专家。"
D.SharedStrings[12018]="把图腾扔回去！"
D.SharedStrings[12019]="把埃瑞丁的罗盘放置在逆风小径灵魂出没的地方，调整罗盘找到乌萨勒斯的位置。"
D.SharedStrings[12020]="把它放在耳边，你就能听到来自远方的邪恶低语。"
D.SharedStrings[12021]="把守望者玺戒带给加洛德·影歌。"
D.SharedStrings[12022]="把巨型凯帕琥珀核心交给卡拉克西维斯的琥珀匠师齐克。"
D.SharedStrings[12023]="把巨型恐虫颚骨交给卡拉克西维斯的琥珀匠师齐克。"
D.SharedStrings[12024]="把巨型沙虫的皮、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。"
D.SharedStrings[12025]="把巨型沙虫的皮、2个重生塑像、5个黄金甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。"
D.SharedStrings[12026]="把德拉诺错币交给幽暗城的艾斯特蕾·根德瑞。你可以通过完成每天的第一个《德拉诺之王》随机英雄地下城来获取德拉诺错币。"
D.SharedStrings[12027]="把德拉诺错币交给铁炉堡的克罗姆·粗臂。你可以通过完成每天的第一个《德拉诺之王》随机英雄地下城来获取德拉诺错币。"
D.SharedStrings[12028]="把我们的威力联合起来"
D.SharedStrings[12029]="把战利品带到戈尔隆德的蛮兽岗哨，交给杜隆坦。"
D.SharedStrings[12030]="把战利品带到戈尔隆德的高山走廊，交给玛尔拉德。"
D.SharedStrings[12031]="把打开的莫什奥格的馈赠带给荆棘谷海角探险者协会挖掘场的达斯克·“空瓶”·哥布菲兹。"
D.SharedStrings[12032]="把救生火箭交给5名热砂港幸存者，用炸弹杀死40名南海封锁者。"
D.SharedStrings[12033]="把有奇怪标记的箱子交给奥伯丁的温尼斯·布莱葛。"
D.SharedStrings[12034]="把某人拉到你身边。"
D.SharedStrings[12035]="把某人拉到你身边。\r\n\r\n拟将该法术通用于怪物脚本。"
D.SharedStrings[12036]="把染煞水晶带给卡拉克西维斯的琥珀匠师齐克。"
D.SharedStrings[12037]="把橡子交给熔火前线的玛法里奥突破口的艾薇尔拉。"
D.SharedStrings[12038]="把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。"
D.SharedStrings[12039]="把海龟的残骸交给奥伯丁的温尼斯·布莱葛。"
D.SharedStrings[12040]="把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。"
D.SharedStrings[12041]="把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。"
D.SharedStrings[12042]="把烟熏过的坠饰带给熔火前线的玛法里奥。"
D.SharedStrings[12043]="把玛雷兹的徽记交给避难谷地的尼艾丝队长。"
D.SharedStrings[12044]="把球扔给友方玩家。如果他们的背包中有剩余的空间，就可以接住球！"
D.SharedStrings[12045]="把目标拉到施法者身边。"
D.SharedStrings[12046]="把空的奶酪盘、“再来一杯”奶酪店的陈年达拉然干酪、以及在达拉然的桌子上找到的6只半满的达拉然酒杯放在一起。$B$B将美酒和奶酪盘交给魔法商业区制皮店中的兰尼德·怒金。"
D.SharedStrings[12047]="把箭掷还给伊娜或她的伙伴。"
D.SharedStrings[12048]="把维克洛尔的王冠、2个重生塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。"
D.SharedStrings[12049]="把肥美的青蛙带给暗月马戏团的斯塔姆·雷角。"
D.SharedStrings[12050]="把自己炸成碎片，但是可以使周围的人受到感染。"
D.SharedStrings[12051]="把莎拉·拉迪莫尔的戒指拿到摩根·拉迪莫尔的坟墓上去。"
D.SharedStrings[12052]="把血蹄的印记带到奥格瑞玛，交给格罗玛什要塞里的萨鲁法尔大王。$B$B你可以跟双足飞龙管理员塔尔交谈飞到那里，也可以等飞艇。"
D.SharedStrings[12053]="把被诅咒的帕雷斯之眼交给湿地米奈希尔港的戈罗林·钢眉。"
D.SharedStrings[12054]="把证明带到戈尔隆德的蛮兽岗哨，交给断肢。"
D.SharedStrings[12055]="把证明带到戈尔隆德的高山走廊，交给游侠乔纳。"
D.SharedStrings[12056]="把这玩意儿戴在脖子上是安全的……吧？"
D.SharedStrings[12057]="把野兽的尸体剁成肉酱。"
D.SharedStrings[12058]="把间谍的报告交给蕨墙村的纳泽尔·血矛。"
D.SharedStrings[12059]="把飞行虎皮丝足鱼交给渔人码头的纳特·帕格。"
D.SharedStrings[12060]="把高压电和纯硝基的混合物注射到目标体内。能出什么差错呢？"
D.SharedStrings[12061]="把鱼饵绑到鱼竿上，吸引稀有鱼类。"
