D.SharedStrings[12068]="投出一块巨大的岩石，造成物理伤害，并将敌人击倒。"
D.SharedStrings[12069]="投出一块燃烧的巨石，对敌人造成火焰伤害。"
D.SharedStrings[12070]="投出一枚火球，造成{1}点火焰伤害。"
