D.SharedStrings[12075]="投掷一块巨石。"
D.SharedStrings[12076]="投掷一块燃烧的巨石。对敌人造成最多{1}点伤害，对附近的建筑造成最多{2}点攻城伤害。"
D.SharedStrings[12077]="投掷一支淬有特制猢狲毒药的琪麟飞镖。"
D.SharedStrings[12078]="投掷一枚可导致赞达拉岗哨图腾失效的烟雾弹，使你能够悄悄溜过去。"
