D.SharedStrings[12133]="护送卡玛洛斯神父逃离险境，然后向奥格瑞姆之锤的凯尔坦修士报告。"
D.SharedStrings[12134]="护送卡玛洛斯神父逃离险境，然后向破天号上的虔诚的阿布萨兰报告。"
D.SharedStrings[12135]="护送安古斯到邪魂堡垒中的邪喉洞穴。"
D.SharedStrings[12136]="护送瑞维尔·考斯特从暮色森林的密斯特曼托庄园前往逆风小径的埃瑞丁营地。"
D.SharedStrings[12137]="护送菲兹索普教授到洞穴里去并平安返回。"
D.SharedStrings[12138]="护锅领主的钥匙打开了这口锅的控制板，然后就消失了―与前两口瘟疫之锅的钥匙一样。一种带着腐烂气息的物质在锅里剧烈地翻滚着。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为亡灵壁垒的暗影牧师范蒂丝带回一份样品。"
D.SharedStrings[12139]="护锅领主索瓦斯的钥匙碰到瘟疫之锅平台底部控制板上的锁之后就消散了。一声轻轻的叮当声过后，控制板打开了，展现在你面前的是瘟疫之锅里沸腾着的毒素。$B$B锅的底部有一个小水龙头，可以让你用手中的瓶子为亡灵壁垒的暗影牧师范蒂丝带回一份样品。"
