D.SharedStrings[12146]="抵御2大波僵尸攻击。"
D.SharedStrings[12147]="抵抗军与你同在。"
D.SharedStrings[12148]="抵抗沉默和打断效果的几率提高{1}%。"
D.SharedStrings[12149]="抽取周围敌人的魔法，使你造成的伤害提高{1}%并使周围敌人的伤害和治疗效果降低{2}点。"
D.SharedStrings[12150]="抽取缚灵者受害对象的灵魂，完成后会将目标吞噬。"
