D.SharedStrings[12171]="拉格纳罗斯准备进行爆裂打击，用萨弗拉斯隔开人群。"
D.SharedStrings[12172]="拉格纳罗斯开始让他身边的平台区域陷入熊熊烈火！"
D.SharedStrings[12173]="拉格纳罗斯挥动萨弗拉斯，猛击地面，使猛烈的冲击力和熔岩波从目标地点向外迸发。"
D.SharedStrings[12174]="拉格纳罗斯注意到四个或更多敌人聚在一个地方，便趁机让那里形成一个熔岩喷泉！"
