D.SharedStrings[12183]="拓烙，碎裂王座之锤"
D.SharedStrings[12184]="拔出你的武器，$r。巡逻的时候到了！$b$b我们要拼死保住手中的四座岗哨，这对我们取得胜利有着关键性的意义。我要你去逐一巡查这几处岗哨，并向他们提供帮助。$b$b你可以从东南方的布兰顿上尉那里开始。等你完成他指派的任务后，他就会指引你去下一座岗哨。$b$b巡查完所有四座岗哨后再回来向我复命。记住——你回来得越快，报酬就越丰厚！所以给我动作麻利一点！$B$B解散！"
D.SharedStrings[12185]="拖曳30至50码范围内的所有敌人。"
D.SharedStrings[12186]="拖车管理员米格林"
D.SharedStrings[12187]="招架几率提高{1}%。"
D.SharedStrings[12188]="招架几率提高{1}%，敌方远程攻击对你的未命中几率提高{2}%，偏转法术的几率提高{2}%。"
D.SharedStrings[12189]="招架提高{1}点。"
D.SharedStrings[12190]="拜托，$N，告诉我你找到贝瑞那德的研究书了……"
