D.SharedStrings[12234]="拾取1000枚英雄纹章、勇气纹章、征服纹章、凯旋纹章或寒冰纹章。"
D.SharedStrings[12235]="拾取2500枚英雄纹章、勇气纹章、征服纹章、凯旋纹章或寒冰纹章。"
D.SharedStrings[12236]="拿到海盗的撬棍，用它撬开被淹没的厕所的门。"
D.SharedStrings[12237]="拿去吧，拿去吧!一个最适合$g国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。"
D.SharedStrings[12238]="拿着创世者的圆盘，前往创世者的图书馆内的控制台。"
D.SharedStrings[12239]="拿着这个，请把这个放到他的坟墓上。也许…也许这样他就可以知道我现在过得很好，而且我们也不会因为他所做的事责怪他。$b$b<她含着眼泪，把戴在右手上的一只戒指摘下放在你手里>$b$b还有……谢谢你，$n。"
D.SharedStrings[12240]="拿起旗帜并在75秒内交还。"
D.SharedStrings[12241]="持球击杀使胜利点数增加10点。"
D.SharedStrings[12242]="持盾方阵兵"
D.SharedStrings[12243]="持续向敌方位置射出火焰箭，对被击中的敌人造成{1}点火焰伤害。"
D.SharedStrings[12244]="持续掉落熔火之羽。"
D.SharedStrings[12245]="持续时间结束时受到{1}点暗影伤害，由附近所有玩家分摊。"
D.SharedStrings[12246]="持续时间结束时对附近盟友造成{1}点火焰伤害。"
D.SharedStrings[12247]="持续时间结束时轰炸该区域。"
D.SharedStrings[12248]="持续造成暗影伤害。\r\n提高你所造成的伤害。\r\n效果持续增强。"
D.SharedStrings[12249]="持续造成火焰伤害。"
D.SharedStrings[12250]="挂上一块巨大的宣传板，宣扬世界末日的到来。"
D.SharedStrings[12251]="指定一个提米苟斯做为我的提米苟斯。"
D.SharedStrings[12252]="指挥中心"
D.SharedStrings[12253]="指挥军团部队的精神压力让乘坐者无法进入军团座舱。"
D.SharedStrings[12254]="指挥官加洛德·影歌"
D.SharedStrings[12255]="指挥官卡泰克"
D.SharedStrings[12256]="指挥官埃里戈尔·黎明使者"
D.SharedStrings[12257]="指挥官安达西斯"
D.SharedStrings[12258]="指挥官库鲁尔格"
D.SharedStrings[12259]="指挥官扎萨克"
D.SharedStrings[12260]="指挥官拉康提亚"
D.SharedStrings[12261]="指挥官斯卡戈什"
D.SharedStrings[12262]="指挥官斯托比德"
D.SharedStrings[12263]="指挥官斯普林瓦尔"
D.SharedStrings[12264]="指挥官斯普林瓦尔出现时带着一个哀嚎的卫兵和一个痛苦的军官，每隔一段时间就会有两个新的帮手加入战斗。"
D.SharedStrings[12265]="指挥官杜兰德"
D.SharedStrings[12266]="指挥官沃加克"
D.SharedStrings[12267]="指挥官沃尔卡"
D.SharedStrings[12268]="指挥官沃拉克斯"
D.SharedStrings[12269]="指挥官法斯塔夫"
D.SharedStrings[12270]="指挥官泰克拉兹"
D.SharedStrings[12271]="指挥官泽斯加尔"
D.SharedStrings[12272]="指挥官玛洛尔"
D.SharedStrings[12273]="指挥官瑞魔克"
D.SharedStrings[12274]="指挥官索瓦克斯"
D.SharedStrings[12275]="指挥官维卡娅"
D.SharedStrings[12276]="指挥官罗娜·克罗雷"
D.SharedStrings[12277]="指挥官莫洛托夫"
D.SharedStrings[12278]="指挥官莱诺尔·风矛"
D.SharedStrings[12279]="指挥官萨拉妮丝"
D.SharedStrings[12280]="指挥官萨森纳尔"
D.SharedStrings[12281]="指挥官萨贝克"
D.SharedStrings[12282]="指挥官阿尔泰娅·埃伯洛克"
D.SharedStrings[12283]="指挥官阿米尔的影像"
D.SharedStrings[12284]="指挥官，你有一位客人。一个古尔丹手下的术士刚刚来到要塞向我们投降。他说他带来了关于即将发生的重大事件的情报。\n\n我建议你立刻去和他谈谈。"
D.SharedStrings[12285]="指挥官，古尔丹最得力的密探塔隆戈尔已经渗透进了位于塔拉多的奥金顿，并妄图吞噬在陵墓中安息的万千亡魂。我们决不能让这个邪恶的术士汲取更多力量了。$B$B快进入神圣的奥金顿陵墓，在塔隆戈尔和暗影议会造成更多伤害前将其击溃。"
D.SharedStrings[12286]="指挥官，我们最近派了斥候前往泽斯高附近的丛林侦察，并听说了一些新消息。\n\n似乎有其他人在报复血环氏族，到处……追杀……他们。他们的猎人正在密切追踪那个杀手。\n\n你一定听过那句话，“敌人的敌人……”什么的。所以我们最好找到他们的追踪地图，抢先一步找到那个杀手！"
D.SharedStrings[12287]="指挥官，据斥候回报，食人魔战队正在冒雪行进。要是那群家伙在上次挨打之后还没吃够苦头的话，我非常乐意去教训他们。"
D.SharedStrings[12288]="指挥舰的邪能光束锁定了你！"
D.SharedStrings[12289]="按照真正的维库传统，向身后丢一块啃过的骨头。"
D.SharedStrings[12290]="按生命值上限的比例为圣骑士恢复生命值。"
D.SharedStrings[12291]="挑战大师：围攻砮皂寺"
D.SharedStrings[12292]="挑战大师：血槌炉渣矿井"
D.SharedStrings[12293]="挑战大师：血色修道院"
D.SharedStrings[12294]="挑战大师：风暴烈酒酿造厂"
D.SharedStrings[12295]="挑战大师：魔古山宫殿"
D.SharedStrings[12296]="挑战大师：黑石塔上层"
D.SharedStrings[12297]="挑战木桩"
D.SharedStrings[12298]="挑衅骆驼驭手多尔穆斯。到时间限制后多尔穆斯会撤退。祝你好运！"
D.SharedStrings[12299]="挖矿的猴子"
D.SharedStrings[12300]="挥动一桶酒，对目标和附近敌人造成相当于武器伤害{1}%的物理伤害。"
D.SharedStrings[12301]="挥砍空气制造一股龙卷风，造成{1}点自然伤害，并且击退其周围的所有目标。"
D.SharedStrings[12302]="挥砍空气，制造一股龙卷风，造成自然伤害，并击退敌人。"
D.SharedStrings[12303]="挥舞灌注了虚空的武器，对施法者前方锥形范围内的敌人造成{1}点暗影伤害。"
D.SharedStrings[12304]="挥舞闪电之鞭，电流漫过地面。"
D.SharedStrings[12305]="捉住鬼祟的小鬼，找回魔典：奥术之道。"
D.SharedStrings[12306]="捉到一只！"
D.SharedStrings[12307]="捕获一只战斗宠物。"
D.SharedStrings[12308]="捕魂者麦芙拉"
D.SharedStrings[12309]="损坏的潜水头盔"
D.SharedStrings[12310]="损坏的灰槌保险箱"
D.SharedStrings[12311]="损坏的银色盟约构造体"
D.SharedStrings[12312]="损失法力值以吸收物理伤害。"
D.SharedStrings[12313]="捡起一只鸡。"
D.SharedStrings[12314]="换取你秘密的钱。"
D.SharedStrings[12315]="据斥候回报，一支由日怒血精灵新兵组成的大部队目前正朝卡拉波废墟前进。原本，如此大规模的军事行动势必会构成强烈的军事威胁，但是我们相信此事另有内情。$B$B他们的服饰和战斗风格很像伊利丹麾下的部队。我可不想自乱阵脚。前往卡拉波废墟取回他们的武器，这样我们就能搞清楚状况了。"
D.SharedStrings[12316]="据斥候回报，影月氏族已经近在咫尺，巫术也已准备就绪。要是我死了又爬起来的话，尽快把我解决掉，指挥官。我可不想变成个食尸鬼。"
D.SharedStrings[12317]="据说其拉虫人的军官所佩戴的戒指可以给他们带来无穷的能量。那些戒指上镶嵌着腐化的宝石，也许我们可以用纯净的材料替换它们，以此来制作净化版本的戒指。$B$B那些装饰在其拉雕像上的宝石就非常合适，它们的质量非常好。$B$B把戒指和雕像交给我，我会为你制作一枚强大的戒指，$c。"
D.SharedStrings[12318]="据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！"
D.SharedStrings[12319]="据说吞噬者之牙举世无双。如果这是真的，付出任何代价都值得。"
D.SharedStrings[12320]="据说在悼念日使用可以招来魂灵并与其交流。"
D.SharedStrings[12321]="据说，先知维伦利用这些简单的水晶向身处远方的同胞伸出了援手。"
D.SharedStrings[12322]="掀翻桌子以发泄你的怒火。"
D.SharedStrings[12323]="掉落：世界掉落\n地区：北荆棘谷、荆棘谷海角"
D.SharedStrings[12324]="掉落：受潮的宠物补给品\n"
D.SharedStrings[12325]="掉落：神秘的卵"
D.SharedStrings[12326]="掉落：赞达拉恐龙统领\n地区：巨兽岛"
D.SharedStrings[12327]="掉落：迷失者的圣骨匣\n地区：黑暗神殿"
D.SharedStrings[12328]="掉落：迷时钱包\n场景战役：克罗米之死"
D.SharedStrings[12329]="掉落：邪能宠物补给\n地区：塔纳安\n"
D.SharedStrings[12330]="掌握了身为一名候选者所必备的技术之后，你就可以参加候选者的挑战了。在这场挑战中，我们会测验你骑乘战斗的能力，以此来判断你是否已经做好了成为一名勇士的准备。通过这场挑战之后，你就可以晋升为勇士，加入你所归属的主城的代表团了。$B$B当你准备好了之后，就来找我。"
D.SharedStrings[12331]="掌炉者伊格尼斯"
D.SharedStrings[12332]="排出舰船中过多的进水，可以保证船只在风暴天气中的浮力。"
D.SharedStrings[12333]="掘地灾怨幼虫"
