D.SharedStrings[12532]="搜尋文獻之後，我們發現一部典籍，裡面詳細說明如何建立惡魔傳送門。只要我們知道位置，就能透過傳送門，出入任何惡魔世界。\r\n\r\n我們可以利用這種傳送門，找到並帶回剩下的議會成員。"
D.SharedStrings[12533]="搜查一名暴风城市民身上的异教物品。"
D.SharedStrings[12534]="搜查埃瑞丁营地，寻找关于黑暗骑士的线索。"
