D.SharedStrings[12536]="搜索警惕的流亡者的尸体，找到一处刺客的印记。"
D.SharedStrings[12537]="搜索贾德维克，寻找卷轴中提到的维库人。"
D.SharedStrings[12538]="搬运一块充能的水晶。水晶应送到附近其中一个能量塔，动作要快！"
D.SharedStrings[12539]="携带一小包瘫痪粉。"
D.SharedStrings[12540]="携带永恒灰烬。"
D.SharedStrings[12541]="携带着一枚炮弹。"
D.SharedStrings[12542]="携带着萨隆邪铁岩石。"
D.SharedStrings[12543]="携带至尊者柯尔凡的标记，获得起死回生技能。\r\n受到足以将你杀死的一击时，你被包裹在一块琥珀中，受到的伤害降低，并在该法术持续时间内恢复生命值和法力值。\r\n该效果每3分钟只能触发一次。\r\n\r\n只在凯帕圣树·扎尔有效。"
D.SharedStrings[12544]="携带谷物，可千万小心别弄掉了！"
D.SharedStrings[12545]="携带高爆火药桶。在遭受攻击和死亡时有一定几率发生爆炸。"
D.SharedStrings[12546]="摆出一个衣柜供你的团队或小队成员试衣。"
D.SharedStrings[12547]="摆放一个可爱的蛋糕，可供5位小队成员食用。"
D.SharedStrings[12548]="摆放炉石小站。\r\n冬幕节期间，冷却时间会缩短。"
