D.SharedStrings[12552]="摧枯拉朽的强风对敌人造成自然伤害，并将其击退。"
D.SharedStrings[12553]="摧毁6个蒂基面具假人。"
D.SharedStrings[12554]="摧毁XT-002拆解者的心脏，然后击败它（10人）。"
D.SharedStrings[12555]="摧毁XT-002拆解者的心脏，然后击败它（25人）。"
D.SharedStrings[12556]="摧毁一座烈焰巨兽防御炮台（10人）。"
D.SharedStrings[12557]="摧毁一座烈焰巨兽防御炮台（25人）。"
D.SharedStrings[12558]="摧毁一座腐化之墙，露出墙后面的东西。"
D.SharedStrings[12559]="摧毁为大门提供火力掩护的邪能防御火炮。"
D.SharedStrings[12560]="摧毁保护监督者费罗拉克斯的水晶，然后消灭他。"
D.SharedStrings[12561]="摧毁四部古籍——《光明下的阴影》、《克尔苏加德的深层知识》、《禁忌咒文及其他死灵仪式》和《黑暗法典》。"
D.SharedStrings[12562]="摧毁毒影的头颅将对其造成极大伤害！"
D.SharedStrings[12563]="摧毁目标一部分的法力值，并根据摧毁的法力值数值对目标周围的敌人造成伤害。"
D.SharedStrings[12564]="摧毁索克雷萨高地下方的上古屏障，并取得无名虚空魔典。"
D.SharedStrings[12565]="摧毁网茧将释放出被困的士兵！"
D.SharedStrings[12566]="摧毁该武器，将其相关技能从本场战斗中移除。"
D.SharedStrings[12567]="摧毁这件邪恶的魔古族圣物可以获得金莲教的青睐。"
D.SharedStrings[12568]="摧毁钢铁部落武器储备，尽可能地制造破坏。"
D.SharedStrings[12569]="摧毁魔眼，然后向暗影拱顶的斯利文男爵报告。"
D.SharedStrings[12570]="摧毁黑鸦堡垒。"
