D.SharedStrings[12584]="撕心狼将军每次命中目标的攻击都会令其变得更加嗜血。"
D.SharedStrings[12585]="撕裂性的音波冲击目标，在8秒后造成巨大的伤害。"
D.SharedStrings[12586]="撕裂施法者面前的地面，让大地之刺在2秒后从地下射出。"
D.SharedStrings[12587]="撕裂施法者面前的地面，让烈火在2秒后从地下喷出。"
D.SharedStrings[12588]="撕裂现实，吸引所有玩家，并对距离裂隙过近的玩家施放引力榨取。\r\n\r\n同时，如果玩家受到了引力榨取的影响，千魂之暗发射的飞弹将被吸引到裂隙之中，而不会击中玩家。\r\n\r\n最后，裂隙还会吸引烈焰宝珠所制造的火焰之池。如果火焰之池接触到接近裂隙的平台边缘，裂隙会吸收火焰，持续地使火焰之池的面积减小。"
D.SharedStrings[12589]="撞击攻城坦克前方的所有敌人，造成{1}点伤害，并将他们击退。对建筑物造成{2}点攻城伤害。"
