D.SharedStrings[12591]="撞击攻城车前方的所有敌人，造成{1}点伤害，并将他们击退。对建筑物造成{2}点攻城伤害。"
D.SharedStrings[12592]="撞落到敌方目标身上，造成伤害。"
D.SharedStrings[12593]="撤退到附近的地点，在末日指挥官身后制造暗影烈焰！"
D.SharedStrings[12594]="播放储存在灵魂石里的回忆。"
