D.SharedStrings[12703]="收集1000份要塞资源，1000金币，并完成15次海军行动。"
D.SharedStrings[12704]="收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。"
D.SharedStrings[12705]="收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。"
D.SharedStrings[12706]="收集2000份要塞资源，然后用绘图桌选择你的议政厅，并将要塞升至3级。"
D.SharedStrings[12707]="收集2500份要塞资源，2500金币，并完成25次海军寻宝行动。"
D.SharedStrings[12708]="收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。"
D.SharedStrings[12709]="收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。"
D.SharedStrings[12710]="收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。"
D.SharedStrings[12711]="收集4份发射器备用零件，然后向埃门谷坠毁点的技师沙娜安复命。"
D.SharedStrings[12712]="收集4只食腐狼的爪子和4只夜行蝙蝠翼。"
D.SharedStrings[12713]="收集5根完整的金色冠羽和1根完整的墨黑冠羽。"
D.SharedStrings[12714]="收集6块蛮鬃豹皮。"
D.SharedStrings[12715]="收集6块魔网能量碎片，并向魔网能量注入远古魔力。"
D.SharedStrings[12716]="收集9瓶弯牙土狼的血液和9瓶红石蜥蜴的血。"
