D.SharedStrings[12922]="放出一群小鬣蜥人去吞噬一台钢铁部落战争机器的主要部件。"
D.SharedStrings[12923]="放出一群幽灵，对幽灵接触到的敌人造成暗影伤害。"
D.SharedStrings[12924]="放出困在烬网虫茧中的海加尔德鲁伊。"
D.SharedStrings[12925]="放弃“迅如疾风”任务。放弃此任务会将你传送回任务起始地点。"
D.SharedStrings[12926]="放掉绑住的龙。"
D.SharedStrings[12927]="放火烧滨岸村。"
D.SharedStrings[12928]="放置100枚爆盐炸弹，并成功摧毁一段城墙。"
D.SharedStrings[12929]="放置一个坚不可摧的陷阱锁链，会捕获第一个靠近的烈焰德鲁伊。"
D.SharedStrings[12930]="放置一个彩蛋，可以售出换取大量金币。持续1小时。"
D.SharedStrings[12931]="放置一个梅特里古卷，安抚狂暴的奥术魔法并让奥术生物更加服从你的意志。"
D.SharedStrings[12932]="放置一个诱捕陷阱，当敌人靠近时陷阱会触发，纠缠附近的所有敌人。"
D.SharedStrings[12933]="放置一枚很快就会爆炸的尖刺炸弹，对附近的所有敌人造成巨大的伤害。"
D.SharedStrings[12934]="放置一枚鳗鱼卵炸药，吸引并炸死一条扭曲的巨海鳗。"
D.SharedStrings[12935]="放置一颗数秒后引爆的奥术炸弹。非常适合用来摧毁燃烧军团的建筑。"
D.SharedStrings[12936]="放置冰霜之握水晶，降低附近所有狼獾人的移动速度。"
D.SharedStrings[12937]="放置易变能量水晶，向附近的狼獾人频繁发射闪电。"
D.SharedStrings[12938]="放置波加尔的图腾，让奥兰娜开始仪式，然后消灭波加尔。"
D.SharedStrings[12939]="放置维伦之杖，吸收阿肯尼特水晶的能量。"
D.SharedStrings[12940]="放逐目标，阻止其进行任何动作，但也使其进入无敌状态。"
D.SharedStrings[12941]="故障检测晶塔"
D.SharedStrings[12942]="故障的银色盟约构造体"
D.SharedStrings[12943]="效果消失后对附近目标造成奥术伤害。"
D.SharedStrings[12944]="效果结束时会触发治疗，为目标恢复{1}%的最大生命值。"
D.SharedStrings[12945]="敌人包围着我们，而且他们的人数每一天都在增长。是时候向他们的大军发动决定性打击了，勇士。$B$B在我身边矗立着我们最憎恨的敌人的雕像。你将给他们带去毁灭，$n。你将成为他们的宿敌，令敌人一看见你就抱头鼠窜。$B$B现在选出你想要宣泄怒火的目标，并烧毁你要灭除的种族雕像吧。等你做好选择之后，就来跟我谈谈。"
D.SharedStrings[12946]="敌人的力量压迫着旗手，使其受到的伤害提高{1}%，并限制其移动速度。"
D.SharedStrings[12947]="敌人的鲜血就是我们的荣耀的象征，你做得很出色。"
D.SharedStrings[12948]="敌人被击退并受到伤害。"
D.SharedStrings[12949]="敌人被魔血覆盖，受到的火焰和暗影伤害提高，并能够听到萨格拉斯的耳语。"
