D.SharedStrings[13146]="教你学会永久性地为一件披风附魔，使其获得对怪物造成的威胁值降低2%的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13147]="教你学会永久性地为一件披风附魔，使其获得躲闪+12的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13148]="教你学会永久性地为一件胸甲附魔，使其获得所有属性+6的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13149]="教你学会永久性地为一件近战武器附魔，使其获得法术强度+40的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13150]="教你学会永久性地为一副护腕附魔，使其获得法术强度+15的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13151]="教你学会永久性地为一双手套附魔，使其获得对怪物造成的威胁值提高2%的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13152]="教你学会永久性地为一双靴子附魔，使其获得全能和耐力+10的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13153]="教你学会永久性地为一双靴子附魔，使其获得移动速度略微提升及敏捷+6的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13154]="教你学会永久性地为一双靴子附魔，使其获得移动速度略微提升及耐力+9的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[13155]="教官拉苏维奥斯"
D.SharedStrings[13156]="教徒?甲板下面?我真该把所有的船员都吊起来打!$B$B听着…为什么我们不让坎特伯理上将处理这个…情况?"
D.SharedStrings[13157]="教徒们已经发现了你上次召唤出来的信使，$r。$B$B虽然我们已经得到了大量的情报，但是能够监控诅咒教派的每一步行动对我们非常重要。$B$B前往奥尔杜萨，用这根魔棒从那些被奴役的爪牙的尸体上吸取一些黑暗物质，然后使用诅咒教派的召唤水晶，再帮我们召唤出一个黑暗信使。$B$B在黑暗信使被发现之前，它将一直作为我们的耳目，小心地观察敌人的行动。"
D.SharedStrings[13158]="教训一只不顺从的食尸鬼，使它驯服。"
D.SharedStrings[13159]="散发着低沉的嗡鸣声。"
D.SharedStrings[13160]="散发着荒野……以及麝香味。但主要是荒野的气味。"
D.SharedStrings[13161]="散发着邪能魔力和恶魔鲜血的恶臭。"
D.SharedStrings[13162]="数个世纪以来，金莲教一直守护着这片山谷，保护它免遭任何伤害。$B$B近来发生的事件使我们神圣的山谷被可怕的阴影笼罩，但金莲教的盟友们仍在顽强对抗，以期让和平重现。$B$B如果你想要帮忙，最好到残阳关卫戍营加入他们。"
D.SharedStrings[13163]="数字控制台"
D.SharedStrings[13164]="数百年来的不眠不休使得伊约库克对宇宙万物的内在机制了如指掌。世间万物都可以量化，包括你！"
D.SharedStrings[13165]="数秒后爆炸，造成{1}点火焰伤害。\r\n嘀嗒嘀嗒。"
D.SharedStrings[13166]="敲响沃金的战鼓来招募巨魔平民加入夺回回音群岛的行列中来。"
D.SharedStrings[13167]="敲破该物品可获得{1}到{2}份远古魔力。"
D.SharedStrings[13168]="整修过的攻城车"
D.SharedStrings[13169]="斡耳朵战争使者"
D.SharedStrings[13170]="斥候们回报说，影月氏族像被踢翻的马蜂窝一样躁动不安。又该大干一场了吧，指挥官？"
D.SharedStrings[13171]="斥候密报：玛戈纳洛克"
D.SharedStrings[13172]="斥候队长艾尔希娅"
D.SharedStrings[13173]="斩杀者诺萨米尔"
D.SharedStrings[13174]="断开与翔龙的灵魂链接，回到自己的身体里。"
D.SharedStrings[13175]="断掌大师"
D.SharedStrings[13176]="断气的科林·烈酒手中还紧紧抓着一只小酒桶。这大概就是他所酿造的臭名昭著的烈酒吧！"
D.SharedStrings[13177]="断裂因果护腕"
D.SharedStrings[13178]="斯克提斯卡利鸟"
D.SharedStrings[13179]="斯克提斯的利爪卫士都是训练有素的精英战士，这种训练方式如今在通天峰已经被禁止了。"
D.SharedStrings[13180]="斯内维尔·拉斯罗凯特"
D.SharedStrings[13181]="斯卡姆之子"
D.SharedStrings[13182]="斯卡德诺克斯的核铸印记"
D.SharedStrings[13183]="斯卡洛克上尉"
D.SharedStrings[13184]="斯卡迪乌斯男爵"
D.SharedStrings[13185]="斯古恩的潮汐印记"
D.SharedStrings[13186]="斯坦索姆（仆从入口奖励目标）奖励任务"
D.SharedStrings[13187]="斯基尔的巨型刀刃几乎将他的敌人劈成两半，将其脏器暴露在外，使其更容易成为里卡尔残暴实验的牺牲品。"
D.SharedStrings[13188]="斯基尔的沁血护符"
D.SharedStrings[13189]="斯塔文的传说"
D.SharedStrings[13190]="斯多姆卡意识到它的古老宿敌的存在，产生恐惧光环。"
D.SharedStrings[13191]="斯多姆卡，灭战者"
D.SharedStrings[13192]="斯拉德兰之握束缚敌人，当该效果叠加5次之后目标会被蛇群包裹。"
