D.SharedStrings[13208]="施展神迹，为一名盟友恢复{1}点生命值。"
D.SharedStrings[13209]="施放一连串灌魔攻击，对施法者正前方附近所有的敌人造成奥术伤害。"
D.SharedStrings[13210]="施放治疗法术时有几率使下一次激流的爆击几率提高{1}%。"
D.SharedStrings[13211]="施放火焰冲击敌人，对其造成{1}点火焰伤害。"
D.SharedStrings[13212]="施放炎爆术时改为施放凤凰烈焰。"
D.SharedStrings[13213]="施放的治疗总量"
D.SharedStrings[13214]="施放闪电箭时，同时也会释放当前的武器附魔，造成额外的伤害。"
D.SharedStrings[13215]="施放震耳咆哮，召唤附近的盟友加入战斗。"
D.SharedStrings[13216]="施放魔法冲击波，对附近的敌人造成奥术伤害。"
D.SharedStrings[13217]="施法和附魔材料商"
D.SharedStrings[13218]="施法快速但消耗很高的法术，为一个友方目标恢复大量生命。"
D.SharedStrings[13219]="施法时间延长{1}%。"
D.SharedStrings[13220]="施法的恶魔猎手对你造成伤害时为其自身恢复生命，相当于伤害的{1}%。"
D.SharedStrings[13221]="施法者一路拾取能捡到的东西，一路狂奔！"
D.SharedStrings[13222]="施法者不停旋转，缓慢移动至敌方目标。施法者路径上的敌人会受到等同于{1}%武器伤害的物理伤害。"
D.SharedStrings[13223]="施法者与目标的生命力链接在了一起，受到的所有伤害将由彼此平均承担。"
D.SharedStrings[13224]="施法者为附近的一个盟友恢复满生命值。该法术无法被打断。"
D.SharedStrings[13225]="施法者之死激怒了附近所有的其他邪能烧灼者，每层效果使灼烧和炼狱冲击的伤害提高{1}%。"
D.SharedStrings[13226]="施法者享用了刺鲑，使其造成的伤害提高{1}%。"
D.SharedStrings[13227]="施法者从地下召唤出怀疑的负面能量。进入该区域的敌人受到{1}点暗影伤害。"
D.SharedStrings[13228]="施法者从埃匹希斯能量塔上吸收存储的太阳能量。"
D.SharedStrings[13229]="施法者从眼中引导出刺眼强光。任何被光线所射到的敌人将遭受火焰伤害，且任何被光线所射到的苍白雾行兽将会显形。"
D.SharedStrings[13230]="施法者令大地分崩离析，造成周期性喷发，对敌人造成{1}点伤害，使其眩晕并将其击退。"
D.SharedStrings[13231]="施法者令大地自身分崩离析，造成周期性喷发，对敌人造成{1}点伤害，使其晕眩并将其击退。"
D.SharedStrings[13232]="施法者令生命值最低的邪能烧灼者复燃，令其损失的生命值恢复2/3，并使其灼烧敌人直至自身死亡。"
D.SharedStrings[13233]="施法者以容不迫的姿态渐渐地靠近想抓的目标。"
D.SharedStrings[13234]="施法者以挥舞的动作，用锁链向前扫击。被锁链击中的受害者会受到{1}点物理伤害，并被击退。"
D.SharedStrings[13235]="施法者会周期性向随机敌方目标喷射熔岩。"
D.SharedStrings[13236]="施法者传送到目标位置，爆发出奥术能量，对附近的敌人造成{1}点奥术伤害。"
D.SharedStrings[13237]="施法者体内爆发出暗影，对范围内的敌人造成少量暗影伤害。"
D.SharedStrings[13238]="施法者使所有敌方玩家身上减益效果的时间速率提高。受影响效果的生效周期和持续时间都会缩短。"
D.SharedStrings[13239]="施法者使用副手攻击前方锥形区域内的所有敌人。"
D.SharedStrings[13240]="施法者使用邪能护盾保护自己，在吸收所有伤害直至护盾能量耗尽。护盾存在期间，施法者每10秒获得一层力量效果。打破护盾将移除施法者身上的所有力量效果。"
D.SharedStrings[13241]="施法者使符文碎裂，向目标发射碎片，造成暗影伤害。"
D.SharedStrings[13242]="施法者做出潜行动作但不会隐身。"
D.SharedStrings[13243]="施法者免疫所有伤害。"
D.SharedStrings[13244]="施法者全力怒吼，对正前方所有敌人造成{1}点物理伤害。"
D.SharedStrings[13245]="施法者冲向目标位置，对其路径上的所有敌人造成物理伤害。"
D.SharedStrings[13246]="施法者冲向目标位置，对路径上的所有敌人造成物理伤害。"
D.SharedStrings[13247]="施法者准备召唤大量流星来攻击他的敌人。冲击区域内的目标受到{1}点暗影伤害。"
D.SharedStrings[13248]="施法者准备向周围的敌人进行几轮箭矢齐射。"
D.SharedStrings[13249]="施法者凝视的敌人受到{1}点火焰伤害，并被击退。"
D.SharedStrings[13250]="施法者分裂出灵魂幻像，旋风般地打击周围的敌人，造成物理伤害。"
D.SharedStrings[13251]="施法者分裂自身的一部分精华，制造出一个较弱的分身，在战斗中提供协助。"
D.SharedStrings[13252]="施法者创造一道火焰，灼烧在其路径上的所有敌人。"
D.SharedStrings[13253]="施法者利用火焰的力量，命令任何附近的火焰服从他的意志。"
D.SharedStrings[13254]="施法者制造一场奥术能量漩涡牵引附近的玩家。"
D.SharedStrings[13255]="施法者制造出一股强劲旋风向四个方向移动。旋风会对触碰到的敌人造成自然伤害。"
D.SharedStrings[13256]="施法者制造出一阵羽毛组成的猛烈旋风，对其路径上遇到的所有敌人造成自然伤害。"
D.SharedStrings[13257]="施法者剪除附近一个鸦人贱民的羽翼。受害者在持续时间内会受到伤害，但同时造成的伤害提高{1}%，急速提高{2}%。\r\n\r\n撕裂羽翼的受害者会移除任意群体控制效果，并在持续时间免疫此类效果。"
D.SharedStrings[13258]="施法者势大力沉，使得所有攻击会对最近的额外目标造成伤害。如果附近没有其他目标，则初始目标会遭到二次打击。"
D.SharedStrings[13259]="施法者卯足全力对当前目标发动攻击，对攻击路径上的所有目标造成大量的火焰伤害。"
D.SharedStrings[13260]="施法者卯足全力对当前目标发动攻击，对未能躲开的任意目标造成大量的物理伤害。"
D.SharedStrings[13261]="施法者卯足全力对当前目标发动攻击，对途中碰到的任意目标造成大量的物理伤害。"
D.SharedStrings[13262]="施法者压榨空气，缓慢窒息区域内的所有敌人。每秒对受害者造成暗影伤害。"
D.SharedStrings[13263]="施法者发出尖啸，产生的声波能量会对路径上的所有敌人造成物理伤害。"
D.SharedStrings[13264]="施法者发动一次强力近战攻击，造成物理伤害。"
D.SharedStrings[13265]="施法者发动一系列的攻击，每次攻击均会对受害者造成物理伤害。"
D.SharedStrings[13266]="施法者发起狂暴冲锋，对路径上的所有目标造成物理伤害。"
D.SharedStrings[13267]="施法者变形，释放自然的力量攻击所有邻近敌人，造成{1}点自然伤害。"
D.SharedStrings[13268]="施法者变成一个狼人。\r\n攻击命中时有一定几率造成{1}点暗影伤害。"
D.SharedStrings[13269]="施法者召唤3个暗影雕像包围目标并在施法者与雕像之间生成暗影能量锁链。触碰锁链的玩家将受到暗影伤害。"
D.SharedStrings[13270]="施法者召唤一排哀嚎的幽灵，在战场上冲锋。路径上经过的所有玩家都将受到暗影伤害。"
D.SharedStrings[13271]="施法者召唤出一团缓慢膨胀的业火。业火每秒会对受害者造成{1}点火焰伤害。当真空完全展开后，会对所有身陷其中的受害者造成{2}点火焰伤害。"
D.SharedStrings[13272]="施法者召唤出一股缓慢坍缩的真空。真空每秒会对受害者造成{1}点物理伤害。当真空完全坍缩后，会对所有身陷其中的受害者造成{2}点物理伤害，并将其击退。"
D.SharedStrings[13273]="施法者召唤出会缓慢收缩的巨型锁链。被锁链捆缚的受害者会随着锁链的收缩而受到更高伤害。"
D.SharedStrings[13274]="施法者召唤出回旋利刃，对其行进路线上的所有敌人造成物理伤害。"
D.SharedStrings[13275]="施法者召唤出滚滚的火焰落到战场上，对区域内的敌人造成火焰伤害。"
D.SharedStrings[13276]="施法者召唤出邪能之球，对触碰到的任何玩家造成火焰伤害。"
D.SharedStrings[13277]="施法者召唤纯粹暗影，造成暗影伤害，并降低移动速度。叠加5层后目标会昏迷。"
D.SharedStrings[13278]="施法者向一个目标冲锋，造成物理伤害并击退路径上的所有敌人。"
D.SharedStrings[13279]="施法者向一名随机敌人发射闪电箭，造成{1}点自然伤害。"
D.SharedStrings[13280]="施法者向前冲锋踩踏路径上的一切目标，对敌人造成{1}点物理伤害并将其击退。"
D.SharedStrings[13281]="施法者向前冲锋，对其路径上的所有敌人造成物理伤害。"
D.SharedStrings[13282]="施法者向前冲锋，对途中遇到的任何敌人造成大量物理伤害。"
D.SharedStrings[13283]="施法者向前冲锋，造成物理伤害并将敌人击倒，打断施法。"
D.SharedStrings[13284]="施法者向前方一条直线上射出一道太阳能量脉冲。被脉冲击中的敌人将受到火焰伤害。"
D.SharedStrings[13285]="施法者向前方直接引导一道高强度太阳能量光束。被光束击中的敌人每秒受到一次火焰伤害。"
D.SharedStrings[13286]="施法者向前方送出一道空气漩涡，在目标的当前位置旋转。被漩涡击中的玩家将受到自然伤害。"
D.SharedStrings[13287]="施法者向前猛冲，在身后留下一道燃烧的痕迹。"
D.SharedStrings[13288]="施法者向前猛冲，在身后留下一道闪电痕迹。"
D.SharedStrings[13289]="施法者向前猛冲，用头撞击目标并将其击退。"
D.SharedStrings[13290]="施法者向前猛冲，用头撞击目标，造成{1}%武器伤害。"
D.SharedStrings[13291]="施法者向四面八方释放出火花，每个火花造成{1}点自然伤害。"
D.SharedStrings[13292]="施法者向正前方发动猛攻，对范围内的所有敌人造成火焰伤害。"
D.SharedStrings[13293]="施法者向目标位置投掷一把战刃。"
D.SharedStrings[13294]="施法者向目标扔出大量蘑菇。靠近这些蘑菇会使其爆炸，造成自然伤害。"
D.SharedStrings[13295]="施法者向目标投掷一颗炸弹。如果目标手中已有炸弹，则将落在目标脚下，造成爆炸。\r\n受害者可以随时扔出炸弹，在落地点造成爆炸。"
D.SharedStrings[13296]="施法者向目标掷出飞轮。飞轮会对触碰到的任意目标造成物理伤害。"
D.SharedStrings[13297]="施法者向目标聚焦一道特殊的锥形彩光。"
D.SharedStrings[13298]="施法者向目标迸射气流，造成自然伤害。"
D.SharedStrings[13299]="施法者向锥形区域中喷发出永恒能量，对受到冲击的所有敌人造成{1}点奥术伤害。"
D.SharedStrings[13300]="施法者向锥形区域喷出火焰吐息。任何被火焰击中的敌人都会受到火焰伤害。"
D.SharedStrings[13301]="施法者向附近位置划了根火柴。在冲击半径内的敌人会受到少量的火焰伤害。"
D.SharedStrings[13302]="施法者向附近位置投掷一颗手雷。在冲击半径内的敌人会受到火焰伤害。"
D.SharedStrings[13303]="施法者向附近地点投掷战刃。"
D.SharedStrings[13304]="施法者向附近的所有目标投掷香料，触碰后引发猛烈爆炸。"
D.SharedStrings[13305]="施法者向附近的所有腐溃毒气投掷活性催化剂。催化剂会使毒气产生剧烈爆炸，对毒气中的所有玩家造成火焰伤害。"
D.SharedStrings[13306]="施法者向附近目标喷吐数团黏性胆汁。\r\n胆汁落地后会形成移动的邪水池，对站在上面的所有玩家造成自然伤害。"
D.SharedStrings[13307]="施法者向附近目标喷吐数团黏性胆汁。\r\n胆汁落地后会形成移动的邪水池，对站在上面的所有玩家造成自然伤害。\r\n每团胆汁都会额外弹跳两次。"
D.SharedStrings[13308]="施法者向随机目标投掷一团巨大的熔岩，造成{1}点火焰伤害。"
D.SharedStrings[13309]="施法者吞噬目标，无形寄生蟹将吸收目标所有的属性。"
D.SharedStrings[13310]="施法者吟唱邪焰冲击，对目标造成{1}点火焰伤害。"
D.SharedStrings[13311]="施法者吸取受害者{1}点生命值，造成暗影伤害。"
D.SharedStrings[13312]="施法者吸取受害者的生命力，使其原地陷入昏迷。"
D.SharedStrings[13313]="施法者吸引软泥怪。"
D.SharedStrings[13314]="施法者周围形成一道闪电风暴，对击中的所有玩家造成{1}点自然伤害。"
D.SharedStrings[13315]="施法者周期性地选取玩家作为目标，并向其爆发出奥术能量。这股奥术能量会对沿途接触到的所有玩家造成{1}点奥术伤害。"
D.SharedStrings[13316]="施法者周期性地随机对目标射出利剑，造成{1}点伤害。"
D.SharedStrings[13317]="施法者喷出会弹跳的腐烂胆汁球，造成自然伤害的同时生成一片残留胆汁，对范围内的任何人造成自然伤害。"
D.SharedStrings[13318]="施法者噬咬其当前目标，造成大量物理伤害，接着将其过肩摔下。"
D.SharedStrings[13319]="施法者在一个友方目标身上施放一个护盾，保护其免受伤害。"
D.SharedStrings[13320]="施法者在他们面前将灵魂能量转化为一股爆炸性力量。爆炸范围内的敌人受到{1}点火焰伤害。这股力量的爆炸威力如此大，以至于施法者瞬间被击倒。"
D.SharedStrings[13321]="施法者在前方施放护盾，在护盾吸收满{1}点伤害前，施法者将不会受到任何伤害。"
D.SharedStrings[13322]="施法者在多名玩家脚下召唤出数个水球，使他们浮上空中并逐渐窒息。此效果一直持续到受害者被盟友救出为止。"
D.SharedStrings[13323]="施法者在物质界和暮光领域之间进行相位变换，根据实体所在不同的位面改变其造成的伤害和受到的伤害。"
D.SharedStrings[13324]="施法者在目标位置制造一个邪能之种。当玩家踩在种子上或者持续时间结束，种子会爆炸。"
D.SharedStrings[13325]="施法者在目标位置召唤一个陷阱。任何受到陷阱影响的目标都会被束缚，必须停留在其范围内，否则每秒受到{1}点火焰伤害。"
D.SharedStrings[13326]="施法者在目标周围制造一个邪能力场，使他们对伤害免疫。"
D.SharedStrings[13327]="施法者在短时间内消耗能量过多，使造成的伤害降低。"
D.SharedStrings[13328]="施法者在短时间内连续攻击数次，每次都会造成物理伤害。"
D.SharedStrings[13329]="施法者在面前发射一张暗影蛛网纤维，对效果范围内的所有敌人造成{1}点暗影伤害。"
D.SharedStrings[13330]="施法者坐了下来，等待着即将端上来的美味汤面。"
D.SharedStrings[13331]="施法者奋力一击，对其目标造成大量的物理伤害。"
D.SharedStrings[13332]="施法者对前方一条直线上的所有敌人造成{1}点物理伤害。"
D.SharedStrings[13333]="施法者对所有敌人造成物理伤害。目标距离越远，受到的伤害越低。"
D.SharedStrings[13334]="施法者将一枚闪电箭矢引向目标，造成自然伤害。"
D.SharedStrings[13335]="施法者将其凝视能量浓缩成一颗虚空之眼，并投射向目标。当虚空之眼着地时，会制造出一片纠缠凝视区域。停留在区域内的玩家每秒会受到{1}点暗影伤害。"
D.SharedStrings[13336]="施法者将其战刃召回。"
D.SharedStrings[13337]="施法者将斧头抛出，对路径上的所有玩家造成物理伤害。"
D.SharedStrings[13338]="施法者将毒血箭射向目标，造成自然伤害。"
D.SharedStrings[13339]="施法者将注意力集中在一个目标身上。"
D.SharedStrings[13340]="施法者将自己的毒血以2枚飞弹形态射向远距离的目标。当飞弹击中后，将形成剧毒瓦斯。站在瓦斯内的玩家将受到自然伤害。"
D.SharedStrings[13341]="施法者开始在塔楼大门上安装炸药。该过程非常消耗时间，而且对精度的把握要求极高。一旦完成后，就可以开始突击塔楼了。"
D.SharedStrings[13342]="施法者开始审视自己的内心，直面潜藏的黑暗。"
D.SharedStrings[13343]="施法者开始破坏燃烧军团的屏障控制器。此过程需要消耗很长的时间，并且需要绝对精确的操作。"
D.SharedStrings[13344]="施法者引导一场强烈地震，越靠近震中造成的伤害越多。"
D.SharedStrings[13345]="施法者强化自己的武器，使其成功的近战攻击有一定几率造成自然伤害。"
D.SharedStrings[13346]="施法者强化自己的武器，使其成功的近战攻击有一定几率造成自然伤害。\r\n攻击速度提高{1}%。"
D.SharedStrings[13347]="施法者快速向前方劈砍三次，对击中的敌人造成物理伤害。"
D.SharedStrings[13348]="施法者快速飞掠当前目标，对其路径上的所有目标造成伤害。"
D.SharedStrings[13349]="施法者恸哭哀嚎，大声呼救。"
D.SharedStrings[13350]="施法者扭曲暗夜井，对所有玩家造成{1}点奥术伤害。\r\n\r\n每次施放此法术都会使施法者接下来施放的扭曲伤害提高{2}%。"
D.SharedStrings[13351]="施法者找了个位置排队，等待被安排就座。"
D.SharedStrings[13352]="施法者拥有极长的四肢。所有普通近战攻击都会击中施法者前方锥形范围内的所有敌人。"
D.SharedStrings[13353]="施法者挥动武器，发动毁灭性的圆弧斩，对武器路径上击中的所有敌人造成{1}点火焰伤害。"
D.SharedStrings[13354]="施法者挥舞巨斧，向随机敌人释放出毁灭之力。"
D.SharedStrings[13355]="施法者挥舞武器，对弧形区域发动毁灭性打击，对武器行进路线上的所有敌人造成{1}点奥术伤害。"
D.SharedStrings[13356]="施法者掷出一发暗影能量箭，并落在附近随机位置。被冲击的敌人受到暗影伤害。\r\n每次冲击形成一个暗影地带，对进入该地带的所有玩家造成暗影伤害。"
D.SharedStrings[13357]="施法者掷出三把呈圆弧状急速旋转的天剑，任何在其行进路线上的敌人遭受物理伤害。"
D.SharedStrings[13358]="施法者掷出他们的武器，将目标拖拽至身旁。"
D.SharedStrings[13359]="施法者攻击目标，造成大量物理伤害。"
D.SharedStrings[13360]="施法者旋转得太久了，现在感到天旋地转！"
D.SharedStrings[13361]="施法者显露出恶魔特质，造成的伤害提高{1}%。"
D.SharedStrings[13362]="施法者暗影庇体，将会一直保持隐身，直到被艾露恩之光或其他类似光源所发现。"
D.SharedStrings[13363]="施法者最近使用的法术使附着在其大脑的孢子充满了能量。当孢子抵达目标后，将变成前一任宿主的形态并使用被充能的法术。"
D.SharedStrings[13364]="施法者消失并在附近生成多个幻影。幻影会和施法者一起作战直到被杀死或消失。"
D.SharedStrings[13365]="施法者潜入梦魇之中，然后在目标身后再次出现。"
D.SharedStrings[13366]="施法者点燃附近所有的邪能烧灼者，令其损失的生命值恢复2/3，并使其灼烧敌人。"
D.SharedStrings[13367]="施法者烧灼附近所有的敌人，造成{1}点火焰伤害。"
D.SharedStrings[13368]="施法者燃烧起来，每秒对区域内的所有敌人造成{1}点火焰伤害，并回敬给所有攻击者同等的伤害。"
D.SharedStrings[13369]="施法者猛击地面，对冲击点的所有敌人造成大量物理伤害。"
D.SharedStrings[13370]="施法者猛击地面，对区域内的所有敌人造成大量物理伤害。"
D.SharedStrings[13371]="施法者猛击地面，对所有敌人造成{1}点物理伤害，并将其击退。"
D.SharedStrings[13372]="施法者生成一道强劲的热浪向外扩散，对区域内的所有目标造成{1}点火焰伤害。火山炸弹被冲击波击中后会遭到摧毁，但能提供免遭冲击的影响。"
D.SharedStrings[13373]="施法者用他们的利爪猛烈挥击，对前方所有的目标造成暗影伤害。"
D.SharedStrings[13374]="施法者用他们的弓对附近的敌人进行一阵乱射。"
D.SharedStrings[13375]="施法者用光束冲击敌人，造成{1}点神圣伤害。"
D.SharedStrings[13376]="施法者用奥术能量冲击目标，对目标造成奥术伤害。"
D.SharedStrings[13377]="施法者用尾巴发动猛击，对其身后的所有玩家造成{1}点物理伤害，并将其击退。"
D.SharedStrings[13378]="施法者用斧头猛击地面，力量之大导致所有敌人被乱扔到各个角落。"
D.SharedStrings[13379]="施法者用最近获得的埃匹希斯能量为这个构装体充能。"
D.SharedStrings[13380]="施法者用末日预言者的礼物诅咒一个附近的目标。目标受到的所有直接治疗，也会对施法者施加同样的治疗法术。"
D.SharedStrings[13381]="施法者用武器击打前方的地面，对区域内所有敌人造成物理伤害。"
D.SharedStrings[13382]="施法者的两个头分别吐出火焰和自然能量。被击中的玩家将受到火焰风暴伤害。"
D.SharedStrings[13383]="施法者的所有攻击会对最近的额外目标造成伤害。"
D.SharedStrings[13384]="施法者的治疗之潮对其造成的治疗量提高{1}%。"
D.SharedStrings[13385]="施法者的潜伏能量与周围的池子发生毁灭性的化学反应，从而消灭所有玩家。"
D.SharedStrings[13386]="施法者的火山岩护甲向外喷发，对所有玩家造成{1}点火焰伤害，并将所有其他熔岩巨人击退回放热的裂隙。"
D.SharedStrings[13387]="施法者的视野经过魔法增幅。别靠得太近！"
D.SharedStrings[13388]="施法者瞬间跨越时空，重新出现在敌人背后。"
D.SharedStrings[13389]="施法者离开暗夜井。"
D.SharedStrings[13390]="施法者继承了切割者的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13391]="施法者继承了掠风者的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13392]="施法者继承了操纵者的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13393]="施法者继承了明澈者的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13394]="施法者继承了暴食蝗的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13395]="施法者继承了毒心者的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13396]="施法者继承了至尊者的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13397]="施法者继承了虫群卫士的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13398]="施法者继承了觅血者的衣钵，并获得其与生俱来的所有力量。"
D.SharedStrings[13399]="施法者蛊惑附近的敌人走向他们。除非企图逃走的意愿压倒了走向施法者的意愿，否则敌人会被蛊惑。"
D.SharedStrings[13400]="施法者蜷缩在防护性琥珀之壳内进行恢复。当法术结束时，施法者会以生命值全满的姿态重新登场。"
D.SharedStrings[13401]="施法者被一层虚空外壳保护。所有来自外界的攻击都会被外壳吸收。"
D.SharedStrings[13402]="施法者被圣光笼罩，不会受到任何伤害。"
D.SharedStrings[13403]="施法者被阴影笼罩。对所有伤害和效果免疫。"
D.SharedStrings[13404]="施法者被阴影笼罩，受到的所有伤害降低100%。"
D.SharedStrings[13405]="施法者装备了一把致命的巨斧。"
D.SharedStrings[13406]="施法者试图修复附近的一个温度调节器，为其恢复{1}%的最大生命值。"
D.SharedStrings[13407]="施法者请求飞行盟友的协助，对她的敌人造成奥术伤害。"
D.SharedStrings[13408]="施法者跃向一个位置，巨大的力道使附近的敌人受到物理伤害并被击退。"
D.SharedStrings[13409]="施法者跃向目标，并使施法者的攻击速度提高{1}%。"
D.SharedStrings[13410]="施法者跳到目标地点。该区域中的所有敌人会受到相当于{1}%武器伤害的物理伤害。"
D.SharedStrings[13411]="施法者跳向远处的敌人，并猛击其脚下的地面。"
D.SharedStrings[13412]="施法者践踏地面，使平台中心到当前坦克目标之间出现一个直线裂隙。"
D.SharedStrings[13413]="施法者迅速冲向当前目标背后的位置。"
D.SharedStrings[13414]="施法者进入内省状态。在此期间击败腐化物将有助于净化你的部分灵魂。当所有的腐化物被清除完毕后，施法者将返回正常状态。"
D.SharedStrings[13415]="施法者进入狂暴状态，变得势不可挡。攻击速度提高{1}%。"
D.SharedStrings[13416]="施法者进入隐形状态，直到隐形效果被取消。"
D.SharedStrings[13417]="施法者进行自杀，立即杀死自己。"
D.SharedStrings[13418]="施法者连续猛击地面，对所有玩家造成物理伤害。"
D.SharedStrings[13419]="施法者逐渐变得强大，提高其造成的伤害和移动速度，可叠加。"
D.SharedStrings[13420]="施法者锁定了一个随机目标。"
D.SharedStrings[13421]="施法者震裂该处的土地，造成持续性的爆炸，对敌人造成{1}点伤害，并将其击退。"
D.SharedStrings[13422]="施法速度提高{1}%。"
D.SharedStrings[13423]="施法速度提高{1}%。\r\n法术伤害提高{2}点。"
D.SharedStrings[13424]="施法速度提高{1}%。\r\n移动速度提高{2}%。"
D.SharedStrings[13425]="施法速度提高{1}%。\r\n造成的所有伤害提高{2}%。"
D.SharedStrings[13426]="施法速度提高{1}%，所有法术的法力值消耗降低{2}%。"
D.SharedStrings[13427]="施法速度降低{1}%。"
D.SharedStrings[13428]="施法速度降低{1}%。\r\n攻击间隔延长{2}%。"
D.SharedStrings[13429]="旅店助理"
D.SharedStrings[13430]="旅店狂热者"
D.SharedStrings[13431]="旅店老板"
D.SharedStrings[13432]="旅店老板伯兰德·草风"
D.SharedStrings[13433]="旅店老板格雷什卡"
D.SharedStrings[13434]="旅店老板的女儿"
D.SharedStrings[13435]="旅行商人"
D.SharedStrings[13436]="旅行者的苔原猛犸象"
D.SharedStrings[13437]="旋转意识兜帽"
D.SharedStrings[13438]="旋转攻击，对所有邻近敌人造成伤害，并对一个随机目标造成{1}点奥术伤害。"
D.SharedStrings[13439]="旋转攻击，对所有邻近敌人造成伤害，并对一个随机目标造成自然伤害。"
D.SharedStrings[13440]="旋转攻击，对附近玩家造成{1}点物理伤害。"
D.SharedStrings[13441]="旋转着向随机目标发射闪电箭，每发闪电箭造成{1}点自然伤害。"
D.SharedStrings[13442]="旋风斩"
D.SharedStrings[13443]="旋风般挥舞利刃，往前倾泻一波火球。"
D.SharedStrings[13444]="无主的黑市宝箱"
D.SharedStrings[13445]="无人知晓的秘密"
D.SharedStrings[13446]="无伤者玛里克"
D.SharedStrings[13447]="无冕维和者"
D.SharedStrings[13448]="无冕者格斗家"
D.SharedStrings[13449]="无助的暮冬城平民"
D.SharedStrings[13450]="无可抗拒的腐蚀"
D.SharedStrings[13451]="无名踏风者之灵"
D.SharedStrings[13452]="无头骑士的坐骑"
D.SharedStrings[13453]="无家可归的暴风城平民"
D.SharedStrings[13454]="无尽守护者（英雄难度）"
D.SharedStrings[13455]="无尽的宝藏"
D.SharedStrings[13456]="无尽苦难护手"
D.SharedStrings[13457]="无形寄生蟹"
D.SharedStrings[13458]="无形寄生蟹会寄生在受害者头部。从现在起，它可以轻易窃取宿主的思维，利用其达成它们不可告人的目的。"
D.SharedStrings[13459]="无形寄生蟹会寄生在受害者头部。从现在起，它可以轻易窃取宿主的思维，利用思维达成它们不可告人的目的。"
D.SharedStrings[13460]="无形寄生蟹和它的宿主进化成了拥有极强力量的超级个体。"
D.SharedStrings[13461]="无形寄生蟹已储存了足够的思想来进行变异。这一阶段会杀死无形寄生蟹的宿主。"
D.SharedStrings[13462]="无情暴君护胸"
D.SharedStrings[13463]="无情角斗士的冰霜巨龙"
D.SharedStrings[13464]="无敌，但也无法行动。"
D.SharedStrings[13465]="无法从虚空之风或其他类似效果中获益。"
D.SharedStrings[13466]="无法安息的先祖"
D.SharedStrings[13467]="无法对这只宠物下达命令。"
D.SharedStrings[13468]="无法对这只宠物下达命令。\r\n伤害可中断此效果。"
D.SharedStrings[13469]="无法成为法术或技能的目标，但命中几率降低{1}%。"
D.SharedStrings[13470]="无法抗拒的池塘小马"
D.SharedStrings[13471]="无法拿起掉落的旗帜。"
D.SharedStrings[13472]="无法攻击或施法。"
D.SharedStrings[13473]="无法攻击或施法。\r\n免疫所有法术攻击。"
D.SharedStrings[13474]="无法攻击斡耳朵斯密使，也不会受其攻击。"
D.SharedStrings[13475]="无法瞄准或射击。"
D.SharedStrings[13476]="无法移动。"
D.SharedStrings[13477]="无法移动。\r\n受到的冰霜伤害提高{1}%。"
D.SharedStrings[13478]="无法移动或作出动作！"
D.SharedStrings[13479]="无法移动或采取任何行动。\r\n不过你还可以眨眼。"
D.SharedStrings[13480]="无法获得嗜血或其他类似效果的增益。"
D.SharedStrings[13481]="无法获得时间扭曲或其他类似效果的增益。"
D.SharedStrings[13482]="无法获得英勇或其他类似效果的增益。"
D.SharedStrings[13483]="无法获得远古狂乱或其他类似效果的增益。"
D.SharedStrings[13484]="无法被杀死。\r\n只有消灭先驱才能将其击败。"
D.SharedStrings[13485]="无法被选为目标。\r\n命中几率降低{1}%。"
D.SharedStrings[13486]="无法进行霰弹射击。\r\n需要重新装填。"
D.SharedStrings[13487]="无法通过大部分常规方式回复或获得法力值。\r\n近战攻击速度降低{1}%。"
