D.SharedStrings[13616]="无畏角斗士的龙皮软靴"
D.SharedStrings[13617]="无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉希盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！$B$B去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。$B$B出发吧，$n。当任务完成之后向我复命。"
D.SharedStrings[13618]="无疤者奥摩尔"
D.SharedStrings[13619]="无疤者奥斯里安"
D.SharedStrings[13620]="无礼的行为不会得到容忍！"
D.SharedStrings[13621]="无翼者伊基什"
D.SharedStrings[13622]="无脑的食尸鬼"
D.SharedStrings[13623]="无视其他人的存在，紧咬着目标不放。"
D.SharedStrings[13624]="无视该单位将导致其向附近的虚无逸散。\r\n造成的伤害减少{1}%。"
D.SharedStrings[13625]="无论在何处遇见天灾军，我们都使他们感到畏惧，此战也不例外。"
D.SharedStrings[13626]="无论是寻宝者还是偷猎者，任何试图支持奈辛瓦里并胆敢危害我们所珍爱的大自然的人，都是“仁慈对待野生动物德鲁伊协会”的敌人。$B$B如果你消灭了某个奈辛瓦里的同党，把他的死亡证据带回来，就可以赢得所有仁德会成员的奖励与祝福。"
D.SharedStrings[13627]="无间地狱兜帽"
D.SharedStrings[13628]="无间地狱手套"
D.SharedStrings[13629]="无间地狱护肩"
D.SharedStrings[13630]="无间地狱护腿"
D.SharedStrings[13631]="无间地狱长袍"
D.SharedStrings[13632]="无限传导护腕"
D.SharedStrings[13633]="无限管道护腕"
D.SharedStrings[13634]="无面织影者"
D.SharedStrings[13635]="无面腐蚀者"
D.SharedStrings[13636]="无面腐蚀者引导他的能量，腐蚀这颗蛋！"
D.SharedStrings[13637]="无面虐待者"
D.SharedStrings[13638]="无魂者目标造成的伤害降低{1}%，直到撕裂的灵魂被杀死为止。"
D.SharedStrings[13639]="既定之天命"
D.SharedStrings[13640]="既然你已经把碎颅者魔山从暮光之门引开了，现在就赶快发信号通知我们的部队发起进攻吧！"
D.SharedStrings[13641]="既然你已经有了制革厂，我们可以开始为你生产上蜡皮革了。等你找到材料就跟我的助手说一声，开始第一份产品订单吧。"
D.SharedStrings[13642]="既然你已经有了工坊，我们可以开始为你生产弹簧齿轮了。等你找到材料就跟我的助手说一声，开始第一份产品订单吧。"
D.SharedStrings[13643]="既然你已经有了炼金实验室，我们可以开始为你生产炼金催化剂了。等你找到材料就跟我的助手说一声，开始第一份产品订单吧。"
D.SharedStrings[13644]="既然你已经有了熔炉，我们可以开始为你生产真钢锭了。等你找到材料就跟我的助手说一声，开始第一份产品订单吧。"
D.SharedStrings[13645]="既然你已经有了珠宝店，我们可以开始为你生产塔拉迪特水晶了。等你找到材料就跟我的助手说一声，开始第一份产品订单吧。"
D.SharedStrings[13646]="既然你已经有了裁缝店，我们可以开始为你生产妖纹布了。等你找到材料就跟我的助手说一声，开始第一份产品订单吧。"
D.SharedStrings[13647]="既然你已经有了铭文师之家，我们可以开始为你生产战争颜料了。等你找到材料就跟我的助手说一声，开始第一份产品订单吧。"
D.SharedStrings[13648]="既然你已经有了附魔研究室，我们可以开始为你生产德拉诺之尘了。等你找到材料就跟我的助手说一声，开始第一份产品订单吧。"
D.SharedStrings[13649]="既然你是一名宠物训练师，那么是时候检验一下你的专业水准了！$b$b去野外找一只战斗宠物进行决斗。赢了之后回来找我，我会继续你的训练。祝你好运！"
D.SharedStrings[13650]="既然你是一名宠物训练师，那么考验你技术的时候到了！$b$b前往森林并挑选一只战斗宠物进行决斗。赢了之后回来找我，我会继续你的训练。祝你好运！"
D.SharedStrings[13651]="既然你是个从业的地精工程师，而且信誉纪录良好，那么我可以收取一定的费用帮你延长会员期。你付费之后就可以得到一张新的会员卡，你可以凭此卡到世界各地的地精工程学训练师那里学习新的结构图。$B$B这张卡的有效期是两周，过期后你必须再次续费才能享受它所带来的好处!"
D.SharedStrings[13652]="既然你的技巧已经得到了真正的磨练，那你就可以完全进入宠物对战的世界了。$B$B我希望你能击败东部王国的5名训练师：辛特兰的大卫·寇斯、东瘟疫之地的德扎·疫角、灼热峡谷的科塔兹·黑锤、悲伤沼泽的伊芙瑞莎和燃烧平原的杜林·黑锤——科塔兹的兄弟。$B$B如果你能打败他们，才能展开后续的冒险。"
D.SharedStrings[13653]="既然你的技巧已经得到了真正的磨练，那你就可以完全进入宠物对战的世界了。$B$B我希望你能击败卡利姆多的5名训练师：菲拉斯的叛徒格鲁克、尘泥沼泽的杰出的高雷兹勒、千针石林的科拉·恐怖图腾、费伍德森林的佐尔坦和月光林地的艾琳娜·振翼。$B$B如果你能打败他们，才能展开后续的冒险。"
D.SharedStrings[13654]="既然已经激活了所有钥匙，可以使用埃匹希斯装置找到护符了。\n\n鸦人的研究表明，它很可能在失落的安苏鸦巢——“乌鸦之神的祭坛内”。"
D.SharedStrings[13655]="日复一日，我矗立在这里，观察着，思索着，等待着。当我极目远眺着海平线时，有许多人指责我只会缅怀过去的日子，无法自拔。但我仍然坚定地认为，每一位来到这座岛屿的访客都应纪念那些曾为我们的生存而付出并牺牲一切的人。$B$B达斯雷玛·逐日者是我们的第一任国王。他领导着我们穿越了大漩涡，从卡利姆多来到这里。$B$B去西边寻找他的神龛吧，阅读了上面的纪念铭文之后再回来找我。"
D.SharedStrings[13656]="日夜轮替束带"
D.SharedStrings[13657]="日心学者特尔安"
D.SharedStrings[13658]="日志中记载了伊利丹军队近期的动向，还提到了瓦萨雷克率兵驻守征服之路的原因。原来这家伙亲手俘虏了一名沙塔尔高级将领。$B$B目前，这位将军被关押在位于征服之路南端的火红岗哨。一个名叫火色魔印的神秘组织负责看守囚犯。你若是想要调查此事，最好叫上你的朋友一同前往。"
D.SharedStrings[13659]="旧希尔斯布莱德丘陵奖励任务"
D.SharedStrings[13660]="时候到了，$n。你准备万全后就告诉我，我将召唤一团呼啸的气旋将你送上雷鸣峰。$B$B通过那元素来召唤大地之环的力量，在它的帮助下消灭元素勋爵玛格玛萨，让我们将他再一次带入平衡之中。"
D.SharedStrings[13661]="时光之末只在英雄难度下开放。"
D.SharedStrings[13662]="时光之穴的索莉多米要你从盘牙水库的瓦丝琪那里取回瓦丝琪的水瓶残余，并从风暴要塞的凯尔萨斯·逐日者那里取回凯尔萨斯的水瓶残余。"
D.SharedStrings[13663]="时光之穴黑色沼泽的萨艾特要求你保护麦迪文，直到他成功开启黑暗之门。$B$B任务完成后向萨艾特复命。"
D.SharedStrings[13664]="时光守护者"
D.SharedStrings[13665]="时光扭曲夜刃豹"
D.SharedStrings[13666]="时光旅行者"
D.SharedStrings[13667]="时光领主埃博克"
D.SharedStrings[13668]="时机终于到了。我们的大军已在这里稳住阵脚，现在可以冒险突进，前往雷电之王的老巢了。不幸的是，他好像一时半会还没有打开大门的意思。$b$b那我们就只好自己弄出一道门来了。等你做好准备就来找我，$n。"
D.SharedStrings[13669]="时空扭曲之镜可以找出新的重合节点。"
D.SharedStrings[13670]="时空漫游商人"
D.SharedStrings[13671]="时空畸体"
D.SharedStrings[13672]="时空领主德亚"
D.SharedStrings[13673]="时至今日人们仍然不明白，为什么有些生物，不管是恶魔还是艾泽拉斯的居民，会选择将玛诺洛斯的血放在罐子里来加入他的邪恶阵营。"
D.SharedStrings[13674]="时间之沙向前流逝很容易。它们可以倒着流，但困难度很高。"
D.SharedStrings[13675]="时间停止"
D.SharedStrings[13676]="昆莱难民"
D.SharedStrings[13677]="明叶长老的精华使弗蕾亚和她的自然盟友造成的魔法伤害提高{1}%。"
D.SharedStrings[13678]="明叶长老的精华使自然盟友造成的魔法伤害提高{1}%。"
D.SharedStrings[13679]="明澈者伊约库克"
D.SharedStrings[13680]="昏迷。"
D.SharedStrings[13681]="昏迷。\r\n免疫所有伤害。"
D.SharedStrings[13682]="昏迷。\r\n受到的伤害提高{1}%。"
D.SharedStrings[13683]="昏迷。\r\n护甲值提高{1}%。"
D.SharedStrings[13684]="昏迷。\r\n每秒造成{1}点自然伤害。"
D.SharedStrings[13685]="昏迷。免疫所有攻击和法术。无法攻击、移动和施法。"
D.SharedStrings[13686]="昏迷且被黑暗魔法包裹，以激活盔甲的防护效果。"
D.SharedStrings[13687]="昏迷并冻结。"
D.SharedStrings[13688]="易受邪能侵袭的枯法者"
D.SharedStrings[13689]="易爆的灭绝者炮弹"
D.SharedStrings[13690]="易默·长眉"
D.SharedStrings[13691]="映像大厅，终于到了。$B$B$C，等你准备完毕就告诉我。我可不会天真的想象阿尔萨斯会不拿他那宝剑毫无防备的坐着等死。"
D.SharedStrings[13692]="春节将至！"
D.SharedStrings[13693]="春节将至，$n！塞纳里奥议会邀请所有艾泽拉斯的居民参加我们的新年庆典活动。你可以在这座城市中寻找一个有神圣的月光之环标记的地方，我们的春节预告者就在那里！她可以告诉你更多关于这个节日的细节信息。"
D.SharedStrings[13694]="是什么让你觉得我会被你这样的$r所干扰，$C?好吧，让我停下每天都要处理的无数重要事情来帮你搞定你那点鸡毛蒜皮的小事情，我们相信达纳苏斯的利益-啊，不，整个泰达希尔的利益-与你手头上的事情相比都是不值一提的，对吗?$B$B月光林地的那群蠢货找了一堆人来为我提供帮助，这简直是在浪费我的时间，那么现在我是不是要继续忍受下去呢?"
D.SharedStrings[13695]="是個外地人…\r\n\r\n你收到了我的信息？"
D.SharedStrings[13696]="是奥鲁麦斯……他的力量又开始增强了，我能感觉到。现在他的手下正在把能量导入他的灵魂中。$B$B如果让他继续这样不受干扰地吸收能量，他很快就会变成一个强大的对手。$B$B回到奥尔杜萨的北部，在他的大厅中将他的精华、徽记、节杖和长袍组合起来，然后在那里的水晶上面使用他的残骸。$B$B快一点，$r！在他变得更加强大之前消灭他！"
D.SharedStrings[13697]="是德莉娜叫你来找我的?我会尽力帮你，但首先我必须请你帮我一个大忙。"
D.SharedStrings[13698]="是我叫他们来的。在我的人民为他们带来如此的灾难后，我希望他们能够获得帮助。"
D.SharedStrings[13699]="是时候使用聚焦之虹的钥匙了。$B$B虽然我很希望玛里苟斯能够悬崖勒马，但是目前看来这是不可能的事。局势相当严峻，其他守护巨龙一致认为应该击败织法者。$B$B<克拉苏斯的语调中带着一丝惊惶。>$B$B$n，请你进入永恒之眼，击败玛里苟斯，把魔法之心带回来。"
D.SharedStrings[13700]="是时候清除梦魇的根源并让翡翠梦境重归平衡了。深入梦魇之心，并战胜梦魇之王萨维斯。"
D.SharedStrings[13701]="是的，是我做了那些香水。很香啊，不是吗?另人无法抗拒。$B$B当联盟和部落的战士们都为这些爱的感觉所倾倒，他们就无法抵抗暗影议会的崛起了。$B$B他们会变的衰弱，手足无措。当他们担心着内心所挚爱的人，就会失去他们的优势。$B$B解决的方法很简单。为什么我要花那么久的时间去想呢?弱点就是心啊。会发生的事就是会发生，你无法避免的。"
D.SharedStrings[13702]="显示进攻行动的进度。"
D.SharedStrings[13703]="显示隐藏和隐形的敌人。"
D.SharedStrings[13704]="晋升者祖拉尔"
D.SharedStrings[13705]="晋见大工匠"
D.SharedStrings[13706]="普利莫修斯的狂怒护符"
D.SharedStrings[13707]="普利莫修斯（英雄难度）"
D.SharedStrings[13708]="普崔塞德教授"
D.SharedStrings[13709]="普崔塞德教授开始一瓶瓶地试喝桌上的所有药剂！"
D.SharedStrings[13710]="普崔塞德教授开始在你们所有人身上进行一项邪恶的实验！"
