D.SharedStrings[13764]="暗影箭雨"
D.SharedStrings[13765]="暗影耐格什是北面那群术士的头目。黑石兽人一露面，这个蠢货就将我赶出了家园。哼，他们都是坏蛋，但是耐格什尤其讨厌。$b$b我要想回到祭坛的话，他就必须死。"
D.SharedStrings[13766]="暗影能量将你的血肉从骨头上剥离。"
D.SharedStrings[13767]="暗影议会"
D.SharedStrings[13768]="暗影议会士兵"
D.SharedStrings[13769]="暗影议会最负盛名的传奇刺客，现在为你效命。"
D.SharedStrings[13770]="暗影议会术士"
D.SharedStrings[13771]="暗影议会正在被他们称为基尔加丹王座的高山顶上召唤他们的恶魔主子。别大意，那里可是整个塔纳安最危险的地方。\n\n快去召集一支战斗小队突袭基尔加丹王座吧，别让燃烧军团在这里站稳了脚跟！"
D.SharedStrings[13772]="暗影议会正在被他们称为基尔加丹王座的高山顶上召唤他们的恶魔主子。我们都知道燃烧军团有多么危险，不要忘记第一次大战的教训。\n\n前往基尔加丹王座，让我们阻止燃烧军团的入侵。"
D.SharedStrings[13773]="暗影议会首领"
D.SharedStrings[13774]="暗影贤者艾斯卡"
D.SharedStrings[13775]="暗影领主的力量随着其生命值的降低而变得虚弱。"
D.SharedStrings[13776]="暗影领主艾斯卡"
D.SharedStrings[13777]="暗影领主艾斯卡（史诗难度）"
D.SharedStrings[13778]="暗影魔的近战攻击吸取目标的能量，并将其转化为法力值转移给它的主人。"
D.SharedStrings[13779]="暗月卡片：伟大"
