D.SharedStrings[13781]="暗月马戏团"
D.SharedStrings[13782]="暗月马戏团对这些塔罗牌很有兴趣，如果你收集到更多的卡片，不要犹豫，立刻呼唤我们。我们也有自己的商人，所以请让我提供一些东西，来与你交换这些卡片。"
