D.SharedStrings[13802]="暫時性的標記。請別視為冬握PvP標記。"
D.SharedStrings[13803]="暮光之锤"
D.SharedStrings[13804]="暮光之锤俘虏并屠杀了很多红龙，但是尚有一只幸存。你还记得莉拉斯塔萨吗？她被囚禁在附近，我们要帮她重获自由。$B$B首先，我们需要一件锋利的器物砍断她的镣铐。$B$B双头怪守护者盲眼负责看守南面的升腾祭坛。$B$B他有一柄精心打造的源质之斧。说不定这就是古加尔的“终极”武器？"
D.SharedStrings[13805]="暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作灰烬公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。"
D.SharedStrings[13806]="暮光之锤已经进入了黑暗深渊中的月光神殿废墟里去了，他们的目标肯定是要强迫元素生物来对付我们。如果我们不及早采取对策的话，这个地区就将永远被他们控制。$B$B到黑暗深渊去找到废墟中的深渊之石，它应该在靠近水边的地方。深渊之石里面是深渊之核——那里面记载了所有元素生物的历史。如果我拥有了它，我和大地之环就能阻止他们了！"
D.SharedStrings[13807]="暮光之锤邪教和黑铁矮人正在黑石深渊里集结兵力。被炎魔之王拉格纳罗斯所束缚的，为其效命的大量火元素在他们后面压阵。$B$B如果我们能把这些元素从束缚中解放出来，就不但能削弱敌人，还能尽我们的本职。带上这根图腾，对那些被制约住的元素使用。它将把它们的灵魂从约束中解放出来，恢复其自然的天性。"
D.SharedStrings[13808]="暮光仇恨召唤者"
D.SharedStrings[13809]="暮光传送门"
D.SharedStrings[13810]="暮光信徒"
D.SharedStrings[13811]="暮光冲击波"
D.SharedStrings[13812]="暮光切割射线"
D.SharedStrings[13813]="暮光审判"
D.SharedStrings[13814]="暮光审判只在英雄难度下开放。"
D.SharedStrings[13815]="暮光审判降临到所有奥卓克希昂的敌人身上。在暮光领域内的敌人受到{1}点不可抵抗的暗影伤害。正常领域内的敌人立即被抓入暮光领域。如果没有敌人被暮光审判击中，守护巨龙们会承受所有伤害，打破巨龙之魂的护盾，艾泽拉斯的所有生命将遭到毁灭。"
D.SharedStrings[13816]="暮光巢穴姐妹"
D.SharedStrings[13817]="暮光巨龙之火在暮光领域将达到它的最大力量！"
