D.SharedStrings[14180]="暴虐角斗士的龙皮长袍"
D.SharedStrings[14181]="暴躁的巴巴加尔诺"
D.SharedStrings[14182]="暴躁的火焰之魂"
D.SharedStrings[14183]="暴躁的火焰守护者"
D.SharedStrings[14184]="暴露在强烈的辐射下，小心变成麻疯侏儒。"
D.SharedStrings[14185]="暴露在这种魔法烟雾中，治疗你的伤口，并缓慢回复你的法力值。\r\n\r\n只有当你处于旋云之巅的时候才会生效。"
D.SharedStrings[14186]="暴露在高强度的辐射下，有退化成一个麻疯侏儒的危险。"
D.SharedStrings[14187]="暴风之盾卫士"
D.SharedStrings[14188]="暴风之盾哨兵"
D.SharedStrings[14189]="暴风之盾的克里斯·克拉奇要你在荣耀之路消灭5名部落成员。"
D.SharedStrings[14190]="暴风城冠军"
D.SharedStrings[14191]="暴风城卫兵"
D.SharedStrings[14192]="暴风城国王"
D.SharedStrings[14193]="暴风城士兵"
D.SharedStrings[14194]="暴风城巡逻兵"
D.SharedStrings[14195]="暴风城战马"
D.SharedStrings[14196]="暴风城步兵"
D.SharedStrings[14197]="暴风城法师"
D.SharedStrings[14198]="暴风城海豹突击队员"
D.SharedStrings[14199]="暴风城狮鹫骑士"
D.SharedStrings[14200]="暴风城的国王将他的力量赐予你，你的生命总值、治疗效果、伤害吸收和伤害效果提高{1}%。"
D.SharedStrings[14201]="暴风城的王子"
D.SharedStrings[14202]="暴风城皇家卫兵"
D.SharedStrings[14203]="暴风城老鼠"
D.SharedStrings[14204]="暴风城调查员"
D.SharedStrings[14205]="暴风城防御部队最高指挥官"
D.SharedStrings[14206]="暴风城骑士"
D.SharedStrings[14207]="暴风领主纳拉克"
D.SharedStrings[14208]="暴食蝗卡诺兹"
D.SharedStrings[14209]="暴龙之王爵德"
D.SharedStrings[14210]="更上一层楼"
D.SharedStrings[14211]="更大的陷阱，更好的奖励"
D.SharedStrings[14212]="更快，更好，更强。"
D.SharedStrings[14213]="更易受到冰霜效果的伤害。\r\n体内注入了红龙军团的精华。"
D.SharedStrings[14214]="更易受到奥术效果的伤害。\r\n体内注入了绿龙军团的精华。"
D.SharedStrings[14215]="更易受到火焰效果的伤害。\r\n体内注入了蓝龙军团的精华。"
D.SharedStrings[14216]="更易受到神圣效果的伤害。\r\n体内注入了黑龙军团的精华。"
D.SharedStrings[14217]="更易受到自然效果的伤害。\r\n体内注入了青铜龙军团的精华。"
D.SharedStrings[14218]="曼杜尔·唤天者"
D.SharedStrings[14219]="曼瑟瑞尔·暗星"
D.SharedStrings[14220]="曾有一个聪明的食人魔发现骑乘双头飞龙旅行会比使用驮兽或走路快得多。这个用厚皮和大量绳结草草制成的鞍座可以舒适地承载一个食人魔。但是，它只能装在小山那么大的双头飞龙身上，这或许也解释了为什么人们从没见过飞翔的食人魔。"
D.SharedStrings[14221]="曾经有一群蓝色的巨龙死在这里。现在，他的仆从正在逐个复活它们。$B$B他亲自复活了其中最大的一条龙。给我从雏龙身上弄一些骨灰下来，我会向你展示他是如何复活那条龙的。"
D.SharedStrings[14222]="最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！"
D.SharedStrings[14223]="最后的一口天灾之锅在一个被称作盖罗恩农场的地方，由亡灵天灾中较为强大的爪牙守卫着——那里的鬼魂和幽灵尤其危险。你可不能掉以轻心，$n。$B$B盖罗恩农场在这里的东北方向，靠近东瘟疫之地的边界。和以前一样，消灭那里的护锅者以获取他的钥匙。拿着这个空样品瓶，把它装满给我拿回来。愿圣光护佑你平安完成这次危险的任务，$c。"
D.SharedStrings[14224]="最后的希里索恩"
D.SharedStrings[14225]="最多吸收{1}点魔法伤害。\r\n受到的物理伤害降低{2}%。"
D.SharedStrings[14226]="最大生命值提高{1}%。"
D.SharedStrings[14227]="最大生命值提高{1}%。\r\n伤害提高{2}%。"
D.SharedStrings[14228]="最大生命值提高{1}%。\r\n造成的伤害提高{2}%。"
D.SharedStrings[14229]="最大生命值降低{1}%。"
D.SharedStrings[14230]="最常使用的法力药水"
D.SharedStrings[14231]="最常使用的法师传送门"
D.SharedStrings[14232]="最常击杀敌人的大陆"
D.SharedStrings[14233]="最常参与的战场"
D.SharedStrings[14234]="最常杀死的怪物类型"
D.SharedStrings[14235]="最常获得荣誉杀敌的大陆"
D.SharedStrings[14236]="最常获胜的战场"
D.SharedStrings[14237]="最後，牠們都會蓬勃生長，而有了更多的闇角以後，狼群也能在之後幾年吃得更好。"
D.SharedStrings[14238]="最近使用过眼罩桶，无法再次使用了。"
D.SharedStrings[14239]="最近刚刚被传送。"
D.SharedStrings[14240]="最近刚刚被传送。\r\n短时间内无法再次传送。\r\n你感觉变轻了。"
D.SharedStrings[14241]="最近刚在荣耀之环中阵亡。一段时间里无法再次进入。"
D.SharedStrings[14242]="最近北边的反抗军营地那里有些动静。我刚听一个叫做尼麦兹的士兵说，那里有一名$r$c，找到了令他们如此疯狂的关键所在。那人不会是你吧，啊？$b$b不管怎么说，他给我送来一份样本，看上去和我在东北边莫什奥格食人魔山那儿看到过的石头差不多。$b$b听说食人魔们守着山后面废墟里的一口箱子。说不定这里面有什么联系呢。想不想去帮我拿过来啊？"
D.SharedStrings[14243]="最近发生了一系列令人不安的变动，关系到我们最珍贵的资源，魔力酒。\n\n我猜塔莉萨已经详细向你说明，夜之子没有魔力酒之类的能量供给后会发生什么。\n\n随着恶魔的不断涌入，缺乏的补给让许多人都难以支撑。\n\n给我带来尽可能多的魔力酒。我会把它们交给合适的人。"
D.SharedStrings[14244]="最近我方的士气十分低迷，$n。我们想尽了办法来振奋大家的精神，但是鼓舞士气的重要供给……朗姆酒就快喝光了。$b$b我接到了来自前线的步兵的报告，据说失落希望海角的船只残骸中储有大量的南海朗姆酒。你能去那里调查一下吗？$b$b如果找到朗姆酒，就带回来吧。"
D.SharedStrings[14245]="最高的2人战队个人等级"
D.SharedStrings[14246]="最高的2人战队等级"
D.SharedStrings[14247]="最高的3人战队个人等级"
D.SharedStrings[14248]="最高的3人战队等级"
D.SharedStrings[14249]="最高的5人战队个人等级"
D.SharedStrings[14250]="最高的5人战队等级"
D.SharedStrings[14251]="最高的制皮技能"
D.SharedStrings[14252]="最高的剥皮技能"
D.SharedStrings[14253]="最高的工程学技能"
D.SharedStrings[14254]="最高的炼金术技能"
D.SharedStrings[14255]="最高的珠宝加工技能"
D.SharedStrings[14256]="最高的裁缝技能"
D.SharedStrings[14257]="最高的采矿技能"
D.SharedStrings[14258]="最高的采药技能"
D.SharedStrings[14259]="最高的铭文技能"
D.SharedStrings[14260]="最高的锻造技能"
D.SharedStrings[14261]="最高的附魔技能"
D.SharedStrings[14262]="月之女祭司"
D.SharedStrings[14263]="月之女祭司妮希"
D.SharedStrings[14264]="月之守卫"
D.SharedStrings[14265]="月之守卫助祭"
D.SharedStrings[14266]="月光和日光增效的伤害加成提高{1}%。"
D.SharedStrings[14267]="月光林地守望者"
D.SharedStrings[14268]="月火术和阳炎术的伤害提高{1}%。"
D.SharedStrings[14269]="月神镰刀"
D.SharedStrings[14270]="月翼精灵龙"
D.SharedStrings[14271]="月落骑乘角鹰兽"
D.SharedStrings[14272]="有5%的几率对敌人造成{2}点火焰伤害。"
D.SharedStrings[14273]="有{1}%的几率偏转来自正面的攻击和法术。"
D.SharedStrings[14274]="有{1}%的几率反射法术。"
D.SharedStrings[14275]="有一件事情是可以肯定的。我们现在拿到了一样对钢铁部落至关重要的东西。$B$B我们最好立即把这个……“高格里克之心”送往安全的地方。"
D.SharedStrings[14276]="有一口天灾之锅被放置在一座早已废弃的农场上，现在这里被称为达尔松之泪。不过现在我们没时间掉眼泪，$c。我们必须打开这口天灾之锅！$B$B到安多哈尔正北方的达尔松之泪去，消灭那里的护锅者。像上次一样，护锅者身上应该有一把可以打开天灾之锅的钥匙。用这个瓶子从锅里装一份样品拿回来，每口锅所使用的毒素配方都是截然不同的。"
D.SharedStrings[14277]="有一定几率使目标中毒，你的移动速度提高{1}%，持续30分钟。只能在索拉查盆地使用。"
D.SharedStrings[14278]="有一定几率在成功击中敌人之后暂时提高自己的护甲值。"
D.SharedStrings[14279]="有一定几率在成功击中目标后使其中毒。"
D.SharedStrings[14280]="有一定几率在攻击时施放邪能箭雨。"
D.SharedStrings[14281]="有一定几率在被命中时对攻击者施加剧毒效果。"
D.SharedStrings[14282]="有一定几率在被近战武器击中时对攻击者施放腐烂气息。"
D.SharedStrings[14283]="有一定几率在被近战武器击中时对攻击者施放腐烂胆汁。"
D.SharedStrings[14284]="有一定几率在近战攻击对目标造成伤害时为你恢复{1}点生命值。"
D.SharedStrings[14285]="有一定几率对你的远程攻击目标造成{1}点暗影伤害。"
D.SharedStrings[14286]="有一定几率对你的远程攻击目标造成{1}点火焰伤害。"
D.SharedStrings[14287]="有一定几率对你的远程攻击目标造成{1}点自然伤害。"
D.SharedStrings[14288]="有一定几率对目标造成瘀伤，降低其护甲值。"
D.SharedStrings[14289]="有一定几率招架敌人的近战攻击。"
D.SharedStrings[14290]="有一定几率格挡敌人的近战攻击。"
D.SharedStrings[14291]="有一定几率立即对目标造成自然伤害。"
D.SharedStrings[14292]="有一定几率进行两次额外攻击"
D.SharedStrings[14293]="有一定几率进行两次额外攻击。"
D.SharedStrings[14294]="有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。$b$b这面铁盾牌可以从烟囱的砖上拿下来。"
D.SharedStrings[14295]="有东西在追你。"
D.SharedStrings[14296]="有东西爬到了你的腿上。"
D.SharedStrings[14297]="有了足夠的靈魂裂片，我們就應該有能力建立定位器了。"
D.SharedStrings[14298]="有了这些碎片，现在可以复原阿古斯之梦了。你必须找到马顿在他日记中提过的那个装置。据说它就在俯瞰痛楚堡垒的洞穴中。"
D.SharedStrings[14299]="有了这些部件，现在只要重铸古特里克的杀生刀就行了。金铲在日记里暗示说，只有在它当时被拆解的地方才能将它重铸。\n\n日记提到了一个用来拆解这把利刃的“灵魂熔炉”，可能就在附近峡谷里的某个地方。找到熔炉，用它将你收集到的所有部件拼合起来。"
D.SharedStrings[14300]="有了适宜的材料和试剂，我就能制作神话般的霜火护甲了。"
D.SharedStrings[14301]="有些冠军认为，诺森德出产的古代武器可以在比赛中给他们带来好运。我答应帮他们去寻找这些武器。$B$B一个流传于灰熊丘陵的古老传说中提到，那里有位女士为了守护一把剑受到诅咒，变成了一只青蛙。现在她就住在灰木哨站东边的灰木湖岸上，和其它的湖蛙生活在一起。根据传说，唯一能够解除这道诅咒的方法，是有人自愿去亲吻她。不过呢，你要记得先在嘴唇上涂抹这种药膏，然后再去亲吻湖蛙，不然你的嘴上会长疣的。"
D.SharedStrings[14302]="有些幸存者提到了食物，$n。我们最好赶快检查下食物补给，我有种不祥的预感。"
D.SharedStrings[14303]="有人反弹你的投掷物并打中了你的脸，好尴尬！"
D.SharedStrings[14304]="有人能看到你有什么。"
D.SharedStrings[14305]="有什么坏事马上就要发生了……你必须离开。"
D.SharedStrings[14306]="有什么来自岗哨的消息吗，$r?"
D.SharedStrings[14307]="有你做伴，哪怕只有很短的几天，我们的这位小姑娘也一定会非常开心。$B$B收下这只孤儿哨吧。只要吹响它，就可以召唤出你要照看的小孩子。你只需要负责照顾她一段时间就可以了——实际上就是儿童周期间。$B$B$n，召唤出这个孩子吧。她肯定迫不及待地想要跟你见面，随你探索城外的美丽世界！"
D.SharedStrings[14308]="有关上古之战时期隐秘事件的深度研究，以及它们对艾泽拉斯未来走向的影响。"
D.SharedStrings[14309]="有关初代巨龙、奥杜尔的守护者以及五大守护巨龙是如何获得力量的迷人传说，由历史学家伊夫琳娜撰写。"
D.SharedStrings[14310]="有关燃烧军团入侵计划的情报。"
D.SharedStrings[14311]="有关空气元素的统治，放逐，以及元素领主间无休止的纷争史。"
D.SharedStrings[14312]="有几排蹄印从树荫旅店那仍然冒着烟的废墟中延伸出来。大部分蹄印都埋在沼泽地的松软泥土里没法辨认，不过至少还有一些是可以看清的。"
D.SharedStrings[14313]="有几率一次钓起整个渔点的符鳞锦鲤。"
D.SharedStrings[14314]="有几率一次钓起整个渔点的至高岭鲑鱼。"
D.SharedStrings[14315]="有几率一次钓起整个渔点的藓鳃鲈鱼。"
D.SharedStrings[14316]="有几率一次钓起整个渔点的诅咒女王鱼。"
D.SharedStrings[14317]="有几率一次钓起整个渔点的风暴鳐鱼。"
D.SharedStrings[14318]="有几率一次钓起整个渔点的黑梭鱼。"
D.SharedStrings[14319]="有几率制造出多个炼金石。"
D.SharedStrings[14320]="有几率制造出多份合剂。"
D.SharedStrings[14321]="有几率制造出多份药水。"
D.SharedStrings[14322]="有几率在攻击时施放一连串胡椒吐息火球，每个造成{1}点火焰伤害。"
D.SharedStrings[14323]="有几率在苏拉玛的生物身上获得额外的远古魔力。"
D.SharedStrings[14324]="有几率造成奥术伤害并使移动速度提高{1}%。持续30分钟。只能在戈尔隆德使用。"
D.SharedStrings[14325]="有几率造成暗影伤害并使移动速度提高{1}%。持续30分钟。只能在戈尔隆德使用。"
D.SharedStrings[14326]="有几率造成火焰伤害并使移动速度提高{1}%。持续30分钟。只能在阿兰卡峰林使用。"
D.SharedStrings[14327]="有害法术和攻击造成额外的神圣伤害。"
D.SharedStrings[14328]="有很大的几率通过研磨破碎群岛的草药获得。"
D.SharedStrings[14329]="有志气的徒弟"
D.SharedStrings[14330]="有意思，他们想要和复仇军合作。以太族确实对于玛里苟斯和他的疯狂而言是个强力的盟友。$B$B这样可不行!"
D.SharedStrings[14331]="有报告指出死亡之门有一只非常强大的僵尸，$c。$B$B我们必须设法解除它带来的潜在威胁。如果你能亲自与它交手，应该可以了解到更多的有价值的情报。$B$B前往死亡之门西面的大厅，向这只怪物发起挑战，找出它的弱点。"
D.SharedStrings[14332]="有时可以在对敌人造成伤害时为达伊克恢复法力值。"
D.SharedStrings[14333]="有未修正的严重错误。"
D.SharedStrings[14334]="有腐蚀从中渗出。"
D.SharedStrings[14335]="有长着很多腿的东西爬到了你的身上。"
D.SharedStrings[14336]="朋友拿到顱骨了嗎？\r\n\r\n啊，卡萊德斯感受到了！別讓它盯著卡萊德斯，朋友。我很樂意協助你，完全沒有不甘願。"
D.SharedStrings[14337]="朋友，你好。你想要用银色黎明徽记或十字军徽记换取这些物品吗？$B$B如果你在银色黎明的声望达到崇拜的话，我们会给你最低的折扣！我建议你现在就购买吧！"
D.SharedStrings[14338]="朋友，你好。你想要用银色黎明徽记或十字军徽记换取这些物品吗？$B$B我得提醒你，如果你在银色黎明的声望只达到友好的话，这笔交易可是要收取很高的附加费的。我建议你跟银色黎明建立更高的声望之后再实施你的计划。"
D.SharedStrings[14339]="朋友，你好。你想要用银色黎明徽记或十字军徽记换取这些物品吗？$B$B我得提醒你，如果你在银色黎明的声望只达到尊敬的话，这笔交易可是要收取很高的附加费用的。我建议你跟银色黎明建立更高的声望之后再实施你的计划。"
D.SharedStrings[14340]="朋友，和平与宁静与你同在。是大德鲁伊派你来的，对吗?"
D.SharedStrings[14341]="朋友，打扰一下……$B$B我注意到玛斯雷·驭熊者已经放出话来，说想要和你谈谈。看样子你即将开始崭新的生活——去接受德鲁伊的训练，他将亲自训练你。玛斯雷是大德鲁伊的助手，也是泰达希尔中最为睿智、最为威严的德鲁伊之一。$B$B他居住在达纳苏斯的塞纳里奥区，就在范达尔·鹿盔所在的那棵树的第二层。"
D.SharedStrings[14342]="朋友，打扰一下……$B$B我的同伴想与你谈谈有关你同塞纳里奥议会联合进行的研究。他是一名德鲁伊，名叫奎恩提斯，居住在菲拉斯的羽月要塞。他想就晨光麦与你交换一些意见……而且他希望我们的谈话不为大德鲁伊所知。$B$B如果你感兴趣的话，就去跟他谈谈，当然，一旦你这么做了，所有的一切便不是秘密了。"
D.SharedStrings[14343]="朋友，祝你在冬幕节玩得开心！记得跟奥格瑞玛的冬天爷爷问好！如果你今年表现得好的话，就能在冬幕节那天收到很多礼物。记得告诉他你希望收到礼物！$B$B另外，别忘了准备一些礼品，送给那些今年表现良好的朋友！我们有很多东西可供选择，都是从农场精心挑选的新鲜食物——来自烟林牧场的馈赠！"
