D.SharedStrings[14366]="木桩击中地面后对附近的敌人造成物理伤害。"
D.SharedStrings[14367]="木精和它们召唤出的植物畸兽一直在渐渐蚕食着我们北边的哨站。我们每杀死一个植物怪，似乎都会生出新的来顶替它的位置。\n\n伯德里克·格雷想出了一个直捣敌人腹地——永茂丛林的计划。他认为这样一来就能把敌人引回戈尔隆德的荒野，给我们争取到更多与之周旋的余地。"
D.SharedStrings[14368]="木精和它们召唤出的植物畸兽一直在渐渐蚕食着我们北边的哨站。我们每杀死一个植物怪，似乎都会生出新的来顶替它的位置。\n\n洛坎想出了一个直捣敌人腹地——永茂丛林的计划。他认为这样一来就能把敌人引回戈尔隆德的丛林里，给我们争取到更多与之周旋的余地。"
