D.SharedStrings[14417]="朱鹤寺坐落在丛林深处，那里是伟大的赤精和他最虔诚的信徒们的家园。我认为他们应该对这儿发生的事情有所了解。$B$B寺庙就坐落在丛林南部海岸上，卡桑琅河的入海口处。"
D.SharedStrings[14418]="朱鹤寺目前尚未完全从煞魔的侵袭中恢复过来，祭祀们最近才重新聚集起来开始重建和训练战士。$B$B如果你想帮助那座寺庙，去和赤精栖木的塞隆尼斯谈一谈。"
