D.SharedStrings[14709]="材料供应商"
D.SharedStrings[14710]="材料全都凑齐了，现在你该去附近的洞穴寻找狞笑的托戈的营地来炼制药剂了。\n\n一旦喝下药剂，你应该就能和那里的掠食者交流了。运气好的话，它们会带你去找割颅者。\n\n他的面具能够换取不菲的奖励。"
D.SharedStrings[14711]="材料和毒药商"
D.SharedStrings[14712]="材料商"
D.SharedStrings[14713]="材料虽然昂贵，但你很快就不会放在心上了。"
D.SharedStrings[14714]="材料都已经备齐了，“魔法堡垒克星”也已装配完成。但愿这炸药的威力能粉碎那道屏障。\n\n成败在此一举……"
D.SharedStrings[14715]="村子中央放置着一盏巨大的南瓜灯。它闪烁着诡异的光芒，透露出难以捉摸的诡异气息。$B$B砸碎南瓜灯后，你发现了一枚烧焦的神圣符记。"
D.SharedStrings[14716]="杜加尔·朗德瑞克"
D.SharedStrings[14717]="杜萝希·米尔斯迪普女伯爵"
D.SharedStrings[14718]="杜隆坦"
D.SharedStrings[14719]="杜隆坦的伙伴"
D.SharedStrings[14720]="杜隆塔尔蝎子"
D.SharedStrings[14721]="杜鲁姆平台周围的水流会立即杀死任何跌进水中的目标。"
D.SharedStrings[14722]="杜鲁姆的怨毒凝视"
D.SharedStrings[14723]="杜鲁姆的断裂触须"
D.SharedStrings[14724]="杜鲁姆的被俘眼球"
D.SharedStrings[14725]="束缚一个元素，用邪能魔法将其扭曲。"
D.SharedStrings[14726]="束缚元素仆从。"
D.SharedStrings[14727]="束缚元素奴仆。"
D.SharedStrings[14728]="束缚艾瑞达的颅骨，使其昏迷并压制它的力量。"
D.SharedStrings[14729]="来往地狱火半岛"
D.SharedStrings[14730]="来的正好。这些补给能救回性命，$N。我们感谢你的努力。这是你的下一个任务。"
D.SharedStrings[14731]="来自于雷霆熔炉的能量使得环绕在其周围的池水充满了电能。"
D.SharedStrings[14732]="来自你的套牌。"
D.SharedStrings[14733]="来自古拉巴什帝国的贵重的权力珍宝。"
D.SharedStrings[14734]="来自古拉巴什帝国的较为普通的权力珍宝。"
D.SharedStrings[14735]="来自古拉巴什帝国的非常贵重的权力珍宝。"
D.SharedStrings[14736]="来自另一个世界的神秘陌生人摧枯拉朽般的胜利宣言，严重动摇了钢铁部落及其盟友的军心。\r\n降低造成的伤害。\r\n降低最大生命值。"
D.SharedStrings[14737]="来自戈尔隆德黑石矿坑中的黑石大军是钢铁部落军队的中坚力量。如果我们能在他们自己的土地上粉碎他们的话，钢铁部落的其余成员就几乎没有跟我们抗衡的希望了。\n\n要是你决意战斗，记得带上朋友一同前往。黑石氏族可没那么容易对付。"
D.SharedStrings[14738]="来自护盾正前方的所有攻击都将被偏转。"
D.SharedStrings[14739]="来自纳格兰的消息"
D.SharedStrings[14740]="来自莫高尔岗哨的战歌掠夺者对高墙之外的一切都不放过。我们已经告诫旅行者不要在外单独行动，可很多人还是置若罔闻。\n\n要是我们突袭莫高尔岗哨的话，几乎肯定能让战歌士兵们忙于撤退防守，从而牵制他们在纳格兰大部分的骑兵力量。"
D.SharedStrings[14741]="来自阿兰卡峰林的消息"
D.SharedStrings[14742]="来自霜火岭的血槌食人魔一直在整个大陆的各条贸易路线上伏击往来商人，还强迫被俘的士兵在他们的炉渣矿井里工作。\n\n伯德里克·格雷下令救出那些被囚禁在石怒崖血槌大本营里的友方军队士兵。"
D.SharedStrings[14743]="来自霜火岭的血槌食人魔一直在整个大陆的各条贸易路线上伏击往来商人，还强迫被俘的士兵在他们的炉渣矿井里工作。\n\n暗影猎手洛坎下令救出那些被囚禁在石怒崖血槌大本营里的友方军队士兵。"
D.SharedStrings[14744]="杰出的高雷兹勒"
D.SharedStrings[14745]="杰德尼勇士沃鲁斯克"
D.SharedStrings[14746]="杰斯·织暗"
D.SharedStrings[14747]="松岩盆地猎人"
D.SharedStrings[14748]="松软的绿色沙发垫"
D.SharedStrings[14749]="板甲商人"
D.SharedStrings[14750]="极大地提升了伤害输出，降低了所受伤害，并能侦测到潜行单位"
D.SharedStrings[14751]="极大地提高格挡来自正面的攻击和偏转来自正面的法术的几率。"
D.SharedStrings[14752]="极大地提高格挡正面攻击和偏转正面法术的几率。使施法者无法移动、转动或被击退。"
D.SharedStrings[14753]="极度脆弱和古老，这块石板上刻着的文字模糊地描述了一个拥有惊人力量的引擎，并宣称它能驾驭太阳的力量。"
D.SharedStrings[14754]="构造体启动了自毁程序，爆炸会造成火焰伤害。"
D.SharedStrings[14755]="林·柔掌"
D.SharedStrings[14756]="林地守护者"
D.SharedStrings[14757]="林地小蜘蛛"
D.SharedStrings[14758]="林庭的草药之旅"
D.SharedStrings[14759]="林精跟你开了个玩笑……"
D.SharedStrings[14760]="果敢的伊戈利玛"
D.SharedStrings[14761]="果然是真的。真是不可思议。怎么会发生这种事?让我想想。这后面一定有什么原因。"
D.SharedStrings[14762]="枪兵的铿锵护腿"
D.SharedStrings[14763]="枪械商"
D.SharedStrings[14764]="枭兽宝宝"
D.SharedStrings[14765]="枭兽形态（暗夜精灵德鲁伊，化身）"
D.SharedStrings[14766]="枯瘦的莫戈多格"
D.SharedStrings[14767]="枯萎的树人"
D.SharedStrings[14768]="某些情况下，应该很好用，你说是吗?$B$B譬如让人看起来永远不会老…"
D.SharedStrings[14769]="染煞武器"
D.SharedStrings[14770]="查尔·恐翼引导一股野蛮的地狱烈焰！对所有敌人造成火焰伤害并使献祭余烬在高温下不断强化。"
D.SharedStrings[14771]="查尼·马尔夫莱姆"
D.SharedStrings[14772]="柯尔凡的猩红月牙斧"
D.SharedStrings[14773]="柯尔拉，暮光之兆"
D.SharedStrings[14774]="柱子之间结合的力量使你的近战攻击和技能可以对敌人造成自然伤害。"
D.SharedStrings[14775]="标准超注射邪能物质反物质设备，可强化燃烧军团的战舰。"
D.SharedStrings[14776]="标记一个军团弹药库的位置，以便维迪卡尔发动攻击。"
D.SharedStrings[14777]="标记一个玩家，对其发动守护虫群攻击。"
D.SharedStrings[14778]="标记目标，使其在短时间内被你攻击时受到更高的伤害。"
D.SharedStrings[14779]="样式古朴，最近才从晨芳园深处被发掘出来。"
D.SharedStrings[14780]="根据不同的职业和作战职责，获得一项德鲁伊的技能。"
D.SharedStrings[14781]="根据伊约库克的计算，你是一个……你不会想知道的。"
D.SharedStrings[14782]="根据你从箱子里拿来的文件可以看出，风险投资公司已经制定了很多把我们从这儿赶走的计划，然后他们就能随心所欲地掠夺我们的土地了。$b$b他们为了利润居然可以堕落到这种程度，这简直让我感到厌恶和惊骇。我们要除掉这个阴谋的策划者，他就是菲兹普罗克主管。你可以在被破坏的货车以东的风险投资公司矿洞里找到他，把他的笔记板带给我，让我们看看有没有什么有价值的东西。"
D.SharedStrings[14783]="根据你的体重、体格和体型，我们要把你假扮成一个兽人。他们的军队里大部分都是兽人，所以你很容易混进去。$b$b你对裁缝有了解吗？如果没有的话，就把这个当成你的第一课吧。我的工作台就在那边，上面有所有必要的材料。$b$b去拿一些你觉得有用的东西，把它们拿来交给我。萨拉隆会帮你料理一切。"
D.SharedStrings[14784]="根据你的体重、体格和体型，我们要把你假扮成一个地精。黑石兽人一直拿地精雇佣兵来填补兵力空缺，所以你很容易混进去。$b$b你对裁缝有了解吗？如果没有的话，就把这个当成你的第一课吧。我的工作台就在那边，上面有所有必要的材料。$b$b去拿一些你觉得有用的东西，把它们拿来交给我。萨拉隆会帮你料理一切。"
D.SharedStrings[14785]="根据你的体重、体格和体型，我们要把你假扮成一个巨魔。燃棘巨魔一直跟黑石兽人共事，所以你很容易混进去。$b$b你对裁缝有了解吗？如果没有的话，就把这个当成你的第一课吧。我的工作台就在那边，上面有所有必要的材料。$b$b去拿一些你觉得有用的东西，把它们拿来交给我。萨拉隆会帮你料理一切。"
D.SharedStrings[14786]="根据你的体重、体格和体型，我们要把你假扮成一个食人魔。火腹食人魔一直在为黑石兽人卖力，所以你很容易混进去。$b$b你对裁缝有了解吗？如果没有的话，就把这个当成你的第一课吧。我的工作台就在那边，上面有所有必要的材料。$b$b去拿一些你觉得有用的东西，把它们拿来交给我。萨拉隆会帮你料理一切。"
D.SharedStrings[14787]="根据你的报告以及我对诅咒教派的认识，他们在荒凉之门一带的每座营地中都会有一个工头负责管理各项事务。$B$B虽然干掉他们的首领只会让他们暂时受挫，但至少这样可以拖延他们的工作进度，并让他们应接不暇。而且就目前来说，这也是一个足够有价值的成果了。$B$B去找到那些工头，消灭他们之后回来向我报告。"
D.SharedStrings[14788]="根据巴尔里石板的记载，巴尔里废墟中埋藏着一件名为卡拉波勋章的神器。在过去，德莱尼人当中只有最高阶的祭司团成员才有资格得到这件神器，从而也获得了自由进出卡拉波神殿的权利。$B$B我们现在必须查明灰舌破碎者们是否已从废墟中挖掘出了这枚勋章。这件神器一定可以对我们抵抗伊利丹有所帮助。$B$B现在，驻守在巴尔里废墟的灰舌军官——长者奥洛努每天都会接到他的上司阿卡玛的书面指令。去把阿卡玛的命令带来给我。"
D.SharedStrings[14789]="根据当地人的习俗，在心爱的人死去后，伴侣或子孙会保留一块火葬堆中烧过的石头。他们会把石头装在袋子里随身带着，时时拿出来擦拭，以获取勇气、寻求安慰、或是表达对逝者的思念。"
D.SharedStrings[14790]="根据我们的斥候报告，被诅咒的维库人被迫登上了纳格法尔号幽灵船。\n\n前往噬魂之喉并击败海拉，阻止她吸收更多的不幸灵魂。"
D.SharedStrings[14791]="根据我对我丈夫的了解，他此刻很可能正在冬眠。你能检查下沼泽里的松软泥土，找找他吗？"
D.SharedStrings[14792]="根据所造成伤害恢复生命值。"
D.SharedStrings[14793]="根据驾驶员的能力，使作战车辆的生命值和伤害获得提升。"
D.SharedStrings[14794]="格利克斯·格林德罗克"
D.SharedStrings[14795]="格尔宾·梅卡托克"
D.SharedStrings[14796]="格拉布托克"
D.SharedStrings[14797]="格拉布托克的拳头包裹了一层寒冰，使近战攻击可以造成额外的冰霜伤害，并有一定几率使附近的敌人减速。"
D.SharedStrings[14798]="格拉布托克的拳头燃起了烈焰，使近战攻击可以造成额外的火焰伤害，并有一定几率使附近的敌人被击飞。"
D.SharedStrings[14799]="格拉布托克的火墙模板"
D.SharedStrings[14800]="格挡2次攻击。"
D.SharedStrings[14801]="格挡几率提高{1}%。"
D.SharedStrings[14802]="格挡所有受到的伤害，并且每秒产生5点能量。引导完毕。"
