D.SharedStrings[14843]="格里斯沃德·汉尼登"
D.SharedStrings[14844]="格里米·油指"
D.SharedStrings[14845]="格雷克斯·布莱伯勒"
D.SharedStrings[14846]="格雷兹克斯·斯宾德斯纳普"
D.SharedStrings[14847]="格雷姆罗克·匹斯诺尔"
D.SharedStrings[14848]="格雷森·沙东布瑞克公爵"
D.SharedStrings[14849]="格雷泽的光束射线对其路径上的所有敌人造成{1}点火焰伤害。"
D.SharedStrings[14850]="格雷迈恩之傲号"
D.SharedStrings[14851]="格鲁尔之子"
D.SharedStrings[14852]="格鲁尔发出骇人的咆哮，使顶层的岩石不断落到玩家头上。该效果会造成{1}点自然伤害并将玩家击倒。"
D.SharedStrings[14853]="格鲁尔的巢穴"
D.SharedStrings[14854]="格鲁洛克的巨龙颅骨"
D.SharedStrings[14855]="桃丽丝·奇尔顿妮斯"
D.SharedStrings[14856]="桃丽丝·沃兰休斯"
D.SharedStrings[14857]="桑利亚斯·静刃"
D.SharedStrings[14858]="桑德拉·埃姆雷拉"
D.SharedStrings[14859]="桑德玛尔防御者"
D.SharedStrings[14860]="桑德玛尔麦酒让你进入一种醉醺醺的狂暴状态。伤害输出提高{1}%。"
D.SharedStrings[14861]="档案管理员加尔福特"
D.SharedStrings[14862]="档案馆数据圆盘"
D.SharedStrings[14863]="梅卡托克之谜号"
D.SharedStrings[14864]="梅卡托克的机械陆行鸟"
D.SharedStrings[14865]="梅拉·高岭"
D.SharedStrings[14866]="梅拉·高岭和灵魂行者黑角就在附近。"
D.SharedStrings[14867]="梅格斯·碎纸机"
D.SharedStrings[14868]="梅瑞尔·邪风"
D.SharedStrings[14869]="梅里斯·玛拉甘"
D.SharedStrings[14870]="梅露娜派來的協助真是及時。我幾乎要放棄希望了。"
D.SharedStrings[14871]="梦境守护者"
D.SharedStrings[14872]="梦境林地保卫者"
D.SharedStrings[14873]="梦境林地大德鲁伊"
D.SharedStrings[14874]="梦境林地角鹰兽"
D.SharedStrings[14875]="梦境林地防御者"
D.SharedStrings[14876]="梦魇之王"
D.SharedStrings[14877]="梦魇恐魔"
D.SharedStrings[14878]="梦魇恐魔存活时，每隔一段时间会在脚下制造梦魇腐蚀之池。"
D.SharedStrings[14879]="梦魇折磨着你的思维。"
D.SharedStrings[14880]="梦魇树人共享同一个根系，在施法结束后，如果盟友仍然存活，则它们能够复活。"
D.SharedStrings[14881]="梦魇注视着你，让你看到最恐怖的噩梦。你死了。"
D.SharedStrings[14882]="梦魇的黑暗力量层层笼罩，扭曲了现实，并且使所有生命的感知都发生了变化。梦境中的空间都已经逐渐得到净化，萨维斯的掌控遭到了削弱。很快，通往梦魇中心的道路就会显露出来。但也许还有一种更直接的方法……我的老师曾经提到过，有一种纯净的力量能够穿透梦魇的黑暗，并让所有通路都变得明晰。但是可惜的是，塞纳留斯迷失了……"
D.SharedStrings[14883]="梦魇触须"
D.SharedStrings[14884]="梦魇鞭笞者"
D.SharedStrings[14885]="梵妮莎·范克里夫"
D.SharedStrings[14886]="梵妮莎·范克里夫与你并肩作战。"
D.SharedStrings[14887]="检定你与目标之间的单位，锁定最近的家伙并赋予其特殊效果。"
D.SharedStrings[14888]="检查绘图桌并选择采用哪种岗哨建筑。"
D.SharedStrings[14889]="检测该样本的质量，需要野外实验工具包。"
D.SharedStrings[14890]="棍子上的胡萝卜"
D.SharedStrings[14891]="棒极了!我立刻就派信差把它们送到幽暗城去!$B$B这是我承诺会给你的报酬。拿着吧!"
D.SharedStrings[14892]="棒极了―这套硬币将进一步扩充我们的宝库……并用于抵抗血神哈卡崛起的邪恶势力。$N，你已经获得了荣誉勋章以及整个部族的感谢!"
D.SharedStrings[14893]="棕色土拨鼠"
D.SharedStrings[14894]="棕色骸骨军马"
D.SharedStrings[14895]="棘齿城的又一个忙碌的一天，不是吗?我多么喜欢看见港口城市的喧嚣啊，充满神秘，充满冒险……也充满着无知。$B$B我在你眼里看见的是仇恨吗，$N?很好，我们会好好利用这种仇恨的。"
D.SharedStrings[14896]="森提纳克斯号印记"
D.SharedStrings[14897]="森提纳克斯激光"
D.SharedStrings[14898]="森林守护者，塞纳留斯"
D.SharedStrings[14899]="森林里的狼人"
D.SharedStrings[14900]="森金村卫兵"
D.SharedStrings[14901]="森金村守护者"
D.SharedStrings[14902]="植物今天看起来很不一样。草叶都被风吹弯了，掠扫着我的靴子。早上还有两根树枝掉到了我的头盔上。"
D.SharedStrings[14903]="楚伦娜丰富的经验和智慧在应对未来的挑战时会显得无往不利。"
D.SharedStrings[14904]="横扫打击，攻击施法者前方的所有敌人。对目标造成{1}点火焰伤害。"
D.SharedStrings[14905]="横扫施法者前方锥形区域，造成两次火焰伤害。"
D.SharedStrings[14906]="横扫附近的敌人，造成物理伤害。"
D.SharedStrings[14907]="横行无忌（第1赛季）"
D.SharedStrings[14908]="横行无忌（第2赛季）"
D.SharedStrings[14909]="次级贪婪秘药"
D.SharedStrings[14910]="欢乐机器人8000"
D.SharedStrings[14911]="欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天灾军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。"
D.SharedStrings[14912]="欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边的广袤土地上，到处都潜伏着天灾军团的势力。面对部落的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。"
D.SharedStrings[14913]="欢迎你，$n。我有幸为你送上一个难得的好机会。经过几个世纪，我们找到了一种可以改变运势的方法。只要拥有长者的好运护符，就能让更多的珍贵神器落入你的手中。"
D.SharedStrings[14914]="欢迎你，$n。我有幸为你送上一个难得的好机会。经过几个世纪，我们找到了一种可以改变运势的方法。只要拥有魔古命运符石，雷电之王宫殿中的珍贵神器就会更加频繁地自动落入你的手中。"
D.SharedStrings[14915]="欢迎参加勇者比武大会，挑战者！今天我们要看看潘达利亚的英雄们到底有多厉害。$b$b你的第一个对手正在东边的凉亭下等着你呢。打败她，你就能晋级下一轮。$b$b为了力量而战！为了荣誉而战！"
D.SharedStrings[14916]="欢迎回来，$N。那张圆盘对你有用吗?或者它根本就是个没用的东西?"
D.SharedStrings[14917]="欢迎回来，$n。我知道你是回来打磨自己的技巧的。去我们下方的习武场找程大师过过招吧。"
D.SharedStrings[14918]="欢迎来到德拉诺"
D.SharedStrings[14919]="欢迎来到暗月马戏团!这张礼券可以兑换5张奖品券呢!$B$B你可以用奖品券兑换一些价值不菲的奖品券越多，能换取的奖品也就越多。哈哈!"
D.SharedStrings[14920]="欢迎来到灰熊丘陵"
D.SharedStrings[14921]="欢迎来到达拉然。$B$B我会确认戒指已经归还。"
D.SharedStrings[14922]="欢迎来到这块新的疆土，$N。灰谷是一片充满机遇的土地，像你这样年轻的$C肯定可以在这里找到无数证明自己实力的机会。在这里的前哨站到处转转，然后到佐拉姆海岸去，部落在那儿设有另一个岗哨。$B$B我看得出你是到这儿来学习狩猎的。用心学习吧，我将很乐意与你分享我所掌握的知识。"
D.SharedStrings[14923]="欢迎来到阿什兰"
D.SharedStrings[14924]="欢迎，$N。你是来这儿参加我们的节庆吗?"
D.SharedStrings[14925]="欢迎，$n。我很高兴你安然无恙。你有东西要给我吗？"
D.SharedStrings[14926]="欢迎，联赛勇士，$N。身为一位勇士，你将可以参加联赛来争取大勇士的资格。你也能选择成为其它联盟城市代表队的骁士，甚至是一名勇士。$B$B每一位勇士将会配有一名侍从，$N，你也不例外。请让我替你指派一位侍从，来协助你战斗。你将可以骄傲地带着你所代表城市的旌旗。"
D.SharedStrings[14927]="欧尔汀派你带着这些东西来找我?$B$B<这个铁匠检视了这些金属块。>$B$B他是对的。大部份内含的魔力已经完成，但是我仍然可以感觉到它未完成的部份。给我一些“奇特”的材料还有一些加工的时间，我可以用这个金属锭帮你打造出一把强而有力的抗恶魔剑。"
D.SharedStrings[14928]="欧库塔尔之眼"
D.SharedStrings[14929]="欧库塔尔用所有眼睛盯住目标，造成集火！"
D.SharedStrings[14930]="欧库纳·长牙"
D.SharedStrings[14931]="欧文·加多克"
D.SharedStrings[14932]="欧林·棕皮"
D.SharedStrings[14933]="欧林·棕皮挥舞着一根硕大的木头。别看他平时温文尔雅，一旦发起脾气来也很不好惹。"
D.SharedStrings[14934]="欧瑞克·图哈特"
D.SharedStrings[14935]="欧瑞克的角鹰兽"
D.SharedStrings[14936]="欧鲁诺克·裂心"
D.SharedStrings[14937]="欺诈者的双刃"
D.SharedStrings[14938]="歌者吟唱的甜美旋律使你很快进入梦乡……"
D.SharedStrings[14939]="歐庫雷斯已經準備好了。很好，少一件要擔心的事。"
D.SharedStrings[14940]="歡迎回來。很好，我們隨時可以開始。"
D.SharedStrings[14941]="正义的十字军"
D.SharedStrings[14942]="正义盾击的伤害提高{1}%，正义盾击使你受到的伤害额外减少{2}%。"
D.SharedStrings[14943]="正像我们担心的一样，部落打算通过在这座岛上烧杀抢掠巩固他们的位置，和我们担心的一样。去给他们点颜色看看，让他们知道联盟绝不会姑息他们的侵略！"
D.SharedStrings[14944]="正在为创世者的圆盘充能。$B$B已完成充能。$B$B准备启动紧急协议：伽玛。$B$B紧急协议已加载。请使用已充能的圆盘激活诺甘农之壳的守护者，档案员麦卡顿。在确认了你的身份之后，档案员会交出诺甘农之壳。$B$B祝你愉快一千年。"
D.SharedStrings[14945]="正在从濒死状态恢复过来……"
D.SharedStrings[14946]="正在使用战歌氏族武器。挥舞武器时，武器上的小洞会发出可怕的声音。"
D.SharedStrings[14947]="正在击碎大地……"
D.SharedStrings[14948]="正在切割宝石。"
D.SharedStrings[14949]="正在召唤幻象。"
D.SharedStrings[14950]="正在召唤恶魔。"
D.SharedStrings[14951]="正在召唤次级恶魔。"
D.SharedStrings[14952]="正在吸取能量。"
D.SharedStrings[14953]="正在吸收古老的知识。"
D.SharedStrings[14954]="正在坠落……"
D.SharedStrings[14955]="正在引导大量熔岩火球。"
D.SharedStrings[14956]="正在引导大量虚空能量。"
D.SharedStrings[14957]="正在引导暗影之雨"
D.SharedStrings[14958]="正在引导死亡光束。"
D.SharedStrings[14959]="正在引导虚空能量。"
D.SharedStrings[14960]="正在恢复法力值。\r\n受到的所有伤害提高{1}%。"
D.SharedStrings[14961]="正在拆除陷阱……"
D.SharedStrings[14962]="正在控制一台铁符文构造体。"
D.SharedStrings[14963]="正在控制一头暮冬要塞狮鹫！你只能在暮冬要塞、暮冬矿洞和腐臭平原飞行。"
D.SharedStrings[14964]="正在控制基尔罗格之眼。\r\n正在检测隐形目标。"
D.SharedStrings[14965]="正在控制枯法者。"
D.SharedStrings[14966]="正在控制枯法者。\r\n正在进行试验。"
D.SharedStrings[14967]="正在控制沃尔特的“特殊”铁符文构造体。"
D.SharedStrings[14968]="正在控制维库鱼叉炮。"
D.SharedStrings[14969]="正在控制魔能机甲斥候。"
D.SharedStrings[14970]="正在携带强化矿石，将矿石带回队伍的矿车可以获得分数。你的速度受到限制。"
D.SharedStrings[14971]="正在操作"
D.SharedStrings[14972]="正在汲取虚空能量。每隔一段时间，虚空施法者的攻击会得到强化。"
D.SharedStrings[14973]="正在治疗。"
D.SharedStrings[14974]="正在熟睡。周围18码范围内的战斗噪音会将其吵醒。"
D.SharedStrings[14975]="正在燃烧。"
D.SharedStrings[14976]="正在粉粹成沙土。"
D.SharedStrings[14977]="正在缓慢地死于邪能腐蚀……"
D.SharedStrings[14978]="正在聚集能量。在能量达到100时，施放不羁怒火。"
D.SharedStrings[14979]="正在聚集虚空能量。每隔一段时间，虚空施法者的攻击会得到强化。"
D.SharedStrings[14980]="正在虚空中游走。难以被虚灵和他们的爪牙发现。\r\n\r\n解散所有召唤物。无法使用坐骑。"
D.SharedStrings[14981]="正在计算击杀数。"
D.SharedStrings[14982]="正在试穿一套新的服装。"
D.SharedStrings[14983]="正在迁跃……"
D.SharedStrings[14984]="正在飞行。"
D.SharedStrings[14985]="正在驯服。"
D.SharedStrings[14986]="正带着一只丛林陆行鸟雏鸟返回巢穴。"
D.SharedStrings[14987]="正常体型的老鼠"
D.SharedStrings[14988]="正是我想听到的!在奥特兰克山谷的胜利 - 既使只是暂时的 - 也对我们对抗部落的战略非常重要。"
D.SharedStrings[14989]="正是时候…奈幽虫族光是这个礼拜的数量就增加了一倍。我们在这里用得上所有的帮助。"
D.SharedStrings[14990]="正邪之间的界限并不是那么清晰，而在正邪交界的地方，人的本意并不那么重要。$B$B伊利丹不知道他周围的人为什么对燃烧军团带来的威胁视而不见，就像瞎了一样。命运之中不乏讽刺。"
D.SharedStrings[14991]="此单位正专注于一个目标。免疫嘲讽。"
D.SharedStrings[14992]="此地的时间流逝速度加快了，急速和移动速度提高{1}%。"
D.SharedStrings[14993]="此天赋已被守望者封禁，敬请期待！"
D.SharedStrings[14994]="此时敌人杀死你将不会获得任何荣誉点数。"
D.SharedStrings[14995]="此时此刻，我们要回顾至今走过的路，庆祝我们伟大的历史，和塑造历史的重大事件。"
D.SharedStrings[14996]="此法術是由閒聊中的侍從所施放，目的在於使他的主人能對其施放錦旗法術。"
D.SharedStrings[14997]="此物品与维迪卡尔矩阵核心直接相连，能够让携带者在阿古斯使用维迪卡尔上安装的任意能力。"
D.SharedStrings[14998]="此生物会极度专注于仪式行为。嘲讽这个生物或其生命值低于90%时，它会开始攻击所有敌人。"
D.SharedStrings[14999]="此生物将遵守最初的指令，直到受到伤害、挑衅或嘲讽。"
D.SharedStrings[15000]="步入我右方的裂隙，你就将进入熔火之心。"
D.SharedStrings[15001]="武僧弟子"
D.SharedStrings[15002]="武僧训练师"
D.SharedStrings[15003]="武器军需官"
D.SharedStrings[15004]="武器商"
D.SharedStrings[15005]="武器大师哈兰"
D.SharedStrings[15006]="武器大师席恩"
D.SharedStrings[15007]="武器大师霍林卡"
D.SharedStrings[15008]="武器被灌注邪焰。\r\n近战攻击会造成额外的火焰伤害。"
D.SharedStrings[15009]="武器锻造师"
D.SharedStrings[15010]="武器锻造师纳什拉"
D.SharedStrings[15011]="歧途之力斗篷"
D.SharedStrings[15012]="死了？泰坦們死了？$B$B<卡德加沉思了一會。>$B$B這的確能解釋非常多事情，但我還是忍不住感到無比的哀傷。一直以來都只有我們獨自奮鬥，眾神在我們還沒出生之前就死了。$B$B至於聖光軍團和伊利丹，我感到不知所措，我從來沒感到如此無助過。$B$B伊利丹死了，而聖光軍團為了我們在群星間進行永無止盡的戰爭。$B$B我需要休息一會，$n。這消息對一個老人來說太難承受了。"
D.SharedStrings[15013]="死于杀人电梯（黑翼血环）。小心脚下。"
D.SharedStrings[15014]="死于火焰和熔岩"
D.SharedStrings[15015]="死亡之翼"
D.SharedStrings[15016]="死亡之翼开始寻找他的下一个攻击目标。在其肢体触须仍然抓住的平台中，死亡之翼会攻击玩家最多的那个平台。"
D.SharedStrings[15017]="死亡之翼开始流血，使得凝固之血在附近出现。"
D.SharedStrings[15018]="死亡之翼正在汲取圆环的邪恶能量，他能造成更高的伤害。杀死暮光腐蚀者来反逆效果！"
D.SharedStrings[15019]="死亡之翼灼热的血液包裹目标，浓厚的血液吸收对此目标造成的最多{1}点治疗效果，并使目标咳血，周期性地造成{2}点物理伤害。"
D.SharedStrings[15020]="死亡之翼的仆从"
D.SharedStrings[15021]="死亡之翼的体内正涌出堕落熔岩，造成火焰伤害。死亡之翼受伤越重，造成的伤害越高。"
D.SharedStrings[15022]="死亡之翼的幻影"
D.SharedStrings[15023]="死亡之翼的幻影对拉希奥造成{1}%的额外伤害。"
D.SharedStrings[15024]="死亡之翼的触手开始流血，在附近位置生成再生之血。"
D.SharedStrings[15025]="死亡之翼试图通过引发第二次大灾变来完成他一手策划的阴谋，对他的所有敌人造成{1}点火焰伤害。"
D.SharedStrings[15026]="死亡之莲十字弩"
D.SharedStrings[15027]="死亡之门邪能火炮"
D.SharedStrings[15028]="死亡使者萨鲁法尔"
D.SharedStrings[15029]="死亡后爆炸，变成活体黑曜石碎片。"
D.SharedStrings[15030]="死亡执行者的拥抱"
D.SharedStrings[15031]="死亡执行者的胸甲"
D.SharedStrings[15032]="死亡时爆炸，对附近的敌人造成奥术伤害。"
D.SharedStrings[15033]="死亡标记"
D.SharedStrings[15034]="死亡猎手兰尼·尤瑞克"
D.SharedStrings[15035]="死亡猎手指挥官贝尔蒙特"
D.SharedStrings[15036]="死亡猎手维赛里"
D.SharedStrings[15037]="死亡猎手莫戈斯"
D.SharedStrings[15038]="死亡的化身"
D.SharedStrings[15039]="死亡的金加塔尔袭击者"
D.SharedStrings[15040]="死亡观察者希尔拉克"
D.SharedStrings[15041]="死亡证明：伊米隆国王"
D.SharedStrings[15042]="死亡证明：传令官沃拉兹"
D.SharedStrings[15043]="死亡证明：先知萨隆亚"
D.SharedStrings[15044]="死亡证明：克莉斯塔萨"
D.SharedStrings[15045]="死亡证明：塑铁者斯约尼尔"
D.SharedStrings[15046]="死亡证明：塞安妮苟萨"
D.SharedStrings[15047]="死亡证明：玛尔加尼斯"
D.SharedStrings[15048]="死亡证明：阿努巴拉克"
D.SharedStrings[15049]="死亡证明：魔网守护者埃雷苟斯"
D.SharedStrings[15050]="死亡领主，我找到了那位特殊的骑士。他希望能够重回黑锋骑士团，而且他希望能和你谈谈。$b$b<莫格莱尼转身对旁边的一个守卫点了点头。>$b$b他一会儿就到。"
D.SharedStrings[15051]="死亡骑士"
D.SharedStrings[15052]="死亡骑士新兵"
D.SharedStrings[15053]="死亡骑士获得{1}点符文能量。"
D.SharedStrings[15054]="死从天降"
D.SharedStrings[15055]="死去的步兵"
D.SharedStrings[15056]="死去的运货人"
D.SharedStrings[15057]="死去的首领手中握着一卷羊皮纸，你从中辨认出了下面墓穴里正在举行的仪式场景。$B$B但维库人的王后安格博达女王似乎在唤醒伊米隆国王时遇到了困难。仪式就在亚勒伯龙最北端的寒冬大厅中举行。$B$B如果你动作够快，或许还来得及阻止她。"
D.SharedStrings[15058]="死寂降临到你头上，可以听到附近敌人跳动的心脏。"
D.SharedStrings[15059]="死忠的谄媚者"
D.SharedStrings[15060]="死爪龙人护卫"
D.SharedStrings[15061]="死神之锤正在寻找收割的目标。快跑！"
D.SharedStrings[15062]="死神开启引擎超速模式。对附近的所有敌人造成物理伤害。"
D.SharedStrings[15063]="死者代言人"
