D.SharedStrings[15310]="殘忍的賈岡諾斯被擊倒了！\r\n\r\n朋友，你就是懼痕裂隙的新主宰！\r\n\r\n這裡就是朋友的新家。你控制了懼痕裂隙，你想來就來想走就走！"
D.SharedStrings[15311]="殺死怪物與完成任務所獲得的經驗值提高{1}%。"
D.SharedStrings[15312]="毁天灭地会对所有敌人造成{1}点物理伤害，并在落点位置形成残骸堆。敌人距离冲击点位置越远，受到的伤害就越低。"
