D.SharedStrings[15315]="毁灭憎恶，杀死附近的所有达卡莱裂颅者。"
D.SharedStrings[15316]="毁灭法杖"
D.SharedStrings[15317]="毁灭程式被激活，摧毁附近的全部生命形式。"
D.SharedStrings[15318]="毁灭者塔尔达斯"
D.SharedStrings[15319]="毁灭者多弗"
D.SharedStrings[15320]="毁灭者的行路靴"
D.SharedStrings[15321]="毁灭风暴"
D.SharedStrings[15322]="毋洛，恐惧先驱"
D.SharedStrings[15323]="每0.25秒对施法者前方的敌人造成{1}点物理伤害。"
D.SharedStrings[15324]="每0.5秒对7码范围内的所有敌人造成一次火焰伤害。"
D.SharedStrings[15325]="每0.5秒对7码范围内的所有敌人造成一次火焰伤害，持续6秒。"
D.SharedStrings[15326]="每0.5秒造成{1}点冰霜伤害。\r\n移动速度减慢{3}%。"
D.SharedStrings[15327]="每0.5秒造成一次物理伤害。\r\n昏迷。"
D.SharedStrings[15328]="每1秒对8码范围内的所有敌人造成{1}%的武器伤害。"
D.SharedStrings[15329]="每1秒对8码范围内的所有敌人造成{1}%的武器伤害，持续4秒。"
D.SharedStrings[15330]="每1秒造成一次火焰伤害。"
D.SharedStrings[15331]="每2秒恢复10%的生命值和100点能量值。"
D.SharedStrings[15332]="每2秒钟让全部敌人受到震击一次，根据他们和洛肯的距离不同对他们造成强弱不等的伤害。距离洛肯越远，受到伤害越大。此效果一直持续到脉冲震荡功能关闭。"
D.SharedStrings[15333]="每3秒对附近的敌人造成一次暗影伤害。"
D.SharedStrings[15334]="每5秒回复{1}点生命值。"
D.SharedStrings[15335]="每5秒恢复{1}点法力值。"
D.SharedStrings[15336]="每5秒恢复{1}点生命值。"
D.SharedStrings[15337]="每60秒只能施放一个治疗或驱散不良效果的法术。"
D.SharedStrings[15338]="每个冒险家在疲惫的时候都需要休息——而休息和放松的最佳去处就是狮王之傲旅店！$B$B我的好朋友法雷是那里的旅店老板。告诉他是我介绍你去的，也许他还会给你些特别优惠呢。$B$B如果你要去狮王之傲旅店的，沿着大路往南走就没错了！"
D.SharedStrings[15339]="每个恶魔使徒都会从附近的盟友身上获得力量。每个盟友可使造成的伤害提高{1}%，生命值提高{2}%。"
D.SharedStrings[15340]="每个追随者都应该具备灵动的舞步——约翰尼·卡索"
D.SharedStrings[15341]="每位食人魔酋长都用铁拳统治着少量食人魔，而他们也从不缺乏挑战者。石槌氏族的首领是出了名的更迭频繁；从这块石头上层层叠叠的血迹来看，它上面应该躺过不少石槌酋长了。"
D.SharedStrings[15342]="每吸取一次灵魂，一个瞬间就永远消逝了"
D.SharedStrings[15343]="每天重置冷却时间。"
D.SharedStrings[15344]="每当一只剧毒小蜘蛛被杀死时就会留下一团毒气。进入毒气的玩家会受到自然伤害。中毒发疯的白鬼会冲向毒气并将其吸入体内。"
D.SharedStrings[15345]="每当你受到直接伤害时，即可造成[FormatDamage(SimpleDamage(1,1),nil,AURAENEMY)]点[School()]伤害。"
D.SharedStrings[15346]="每当你在朱鹤寺里杀死一个煞魔，安度因就为你恢复一部分的生命值和法力值，并鼓舞附近绝望的赤翼守护者。"
D.SharedStrings[15347]="每当你的法术治疗了一个目标，你都有一定几率使附近的另一个友方目标立即恢复{1}点生命值。"
D.SharedStrings[15348]="每当白骨之盾抵挡伤害时，有几率额外吸收{1}%的伤害，此几率等同于你的爆击几率。"
D.SharedStrings[15349]="每数秒使施法者周围一大片区域内所有敌人的生命值上限降低{1}%，该效果可以叠加。"
D.SharedStrings[15350]="每有一个受到你的救赎影响的目标，恳求的法力消耗就会提高{1}%。"
D.SharedStrings[15351]="每次击中目标都有一定几率造成{1}点额外火焰伤害。"
D.SharedStrings[15352]="每次成功的近战攻击将附带亡者的寒意，额外造成{1}点冰霜伤害。"
D.SharedStrings[15353]="每次攻击命中哈维奇船长都会使其更加嗜血。"
D.SharedStrings[15354]="每次攻击命中巨怪都会令其更加愤怒。"
D.SharedStrings[15355]="每次攻击都造成{1}%武器伤害，并视作火焰伤害。"
D.SharedStrings[15356]="每次施放都使攻击速度提高{1}%，体型增大{2}%。效果最多叠加50次。"
