D.SharedStrings[15461]="每轮对一名敌人造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[15462]="每轮对当前宠物造成[StandardDamage(1,1)]点[School()]伤害。"
D.SharedStrings[15463]="每轮对当前宠物造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n 燃烧。"
D.SharedStrings[15464]="每轮对敌人的宠物造成[StandardDamage(1,1)]点[School()]伤害，可造成2次。\r\n\r\n[StandardAccuracy(1,1)] 命中几率"
