D.SharedStrings[15466]="每轮造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n中毒。"
D.SharedStrings[15467]="每轮造成[StandardDamage(1,1)]点[School()]伤害。\r\n\r\n流血"
D.SharedStrings[15468]="每轮造成[StandardDamage(1,1)]点[School()]伤害。\r\n当你攻击时，有[accuracy(getProcIndex(PROC_ON_DAMAGE_DEALT),1)]%的几率受到[StandardDamage(getProcIndex(PROC_ON_DAMAGE_DEALT), 1)]点[School()]伤害。\r\n\r\n中毒。"
D.SharedStrings[15469]="每轮造成[StandardDamage(1,1)]点伤害。\r\n\r\n当效果结束时，会跳跃到同伴身上。"
D.SharedStrings[15470]="每轮造成[StandardDamage(1,1)]点元素伤害。\r\n\r\n燃烧"
D.SharedStrings[15471]="每隔一段时间从虚空中吸引碎石。"
D.SharedStrings[15472]="每隔一段时间吐出泡泡，为你和附近队友吸收{1}点伤害。"
D.SharedStrings[15473]="毒心者夏克里尔"
D.SharedStrings[15474]="毒性云雾"
D.SharedStrings[15475]="毒气之云的攻击释放了该目标身上的所有气体！毁灭毒气对所有敌人造成伤害，伤害数值依该目标受到攻击时身上堆叠的凋零毒气层数而定。"
D.SharedStrings[15476]="毒牙穿刺目标的身体，造成{1}点自然伤害。"
D.SharedStrings[15477]="毒瘴颅骨腰带"
D.SharedStrings[15478]="毒皮小暴掠龙似乎很满足你提供的大餐，但不知道何时它又会饿。"
D.SharedStrings[15479]="毒皮小暴掠龙对着你露齿微笑并开始休憩打盹。"
D.SharedStrings[15480]="毒皮小暴掠龙收下这些羽毛，开始打量着它们，并且把羽毛装饰在它的臂环上。"
D.SharedStrings[15481]="毒皮小暴掠龙舔了舔嘴唇并将头偏向一边。"
D.SharedStrings[15482]="毒皮暴掠龙"
D.SharedStrings[15483]="毒素注射护胸"
D.SharedStrings[15484]="毒药与材料"
D.SharedStrings[15485]="毒药和材料"
D.SharedStrings[15486]="毒药商"
D.SharedStrings[15487]="毒蛇茎总是向地下深处生长，盘踞在矿脉周围。"
D.SharedStrings[15488]="毒蛇钉刺和黑箭的持续性伤害的爆击伤害提高{1}%。"
D.SharedStrings[15489]="毒血利刃护肩"
D.SharedStrings[15490]="毒雾夜行斗篷"
D.SharedStrings[15491]="比亚格里将军"
D.SharedStrings[15492]="比尔·巴克勒"
D.SharedStrings[15493]="毫无刮痕的角鹰兽鳞片"
D.SharedStrings[15494]="水下呼吸。"
D.SharedStrings[15495]="水之召唤"
D.SharedStrings[15496]="水元素"
D.SharedStrings[15497]="水塘惩罚者之靴"
D.SharedStrings[15498]="水晶之脊"
D.SharedStrings[15499]="水晶牢笼"
D.SharedStrings[15500]="水晶碎片"
D.SharedStrings[15501]="水晶粉碎者妮卡"
D.SharedStrings[15502]="水晶被攻击时作出反应，将攻击者包裹在晶化甲壳中，吸收对目标造成的伤害和获得的治疗。甲壳本身可吸收相当于最大生命值{1}%的伤害，其吸收的治疗量可提高这个总值，但最多不超过最大生命值的{2}%。当无法吸收更多伤害时，甲壳将会破碎。"
D.SharedStrings[15503]="水术师瑟丝比娅"
D.SharedStrings[15504]="水栖宠物身上的浮空魔法水泡。"
