D.SharedStrings[15619]="永久性地为一条项链附魔，使其能周期性地召唤箭雨攻击你的目标。"
D.SharedStrings[15620]="永久性地为一条项链附魔，使其获得全能+{1}的效果。"
D.SharedStrings[15621]="永久性地为一条项链附魔，使其获得急速+{1}的效果。"
D.SharedStrings[15622]="永久性地为一条项链附魔，使其获得爆击+{1}的效果。"
D.SharedStrings[15623]="永久性地为一条项链附魔，使其获得精通+{1}的效果。"
D.SharedStrings[15624]="永久性地为一面盾牌或一件副手装备附魔，使其获得智力+17的效果。该装备等级不得低于372级。"
D.SharedStrings[15625]="永久性地为一面盾牌附魔，使其获得全能+{1}的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[15626]="永久性地为一面盾牌附魔，使其获得招架+{1}的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[15627]="永久性地为一面盾牌附魔，使其获得智力+{1}的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[15628]="永久性地为一面盾牌附魔，使其获得耐力+{1}的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[15629]="永久性地为一面盾牌附魔，使其获得躲闪+{1}的效果。不能对物品等级高于600的物品使用。"
D.SharedStrings[15630]="永久性地为坐骑附魔，使其移动速度提高{1}%。你只能对自己物品栏中的坐骑附魔，附魔之后该坐骑会变成灵魂绑定物品。只能使用一次。"
D.SharedStrings[15631]="永久性地使你的炼金技能提高{1}，上限为{2}点。"
D.SharedStrings[15632]="永久性地在一件腿部装备上附加一条魔法丝线，使其获得法术强度+{1}、全能+{2}的效果。\r\n\r\n附魔之后，该装备会与你绑定。不能对物品等级高于600的物品使用。"
D.SharedStrings[15633]="永久性地在一件腿部装备上附加一条魔法丝线，使其获得法术强度+{1}、耐力+{2}的效果。\r\n\r\n附魔之后，该装备会与你绑定。不能对物品等级高于600的物品使用。"
D.SharedStrings[15634]="永久性地在一件腿部装备上附加一条魔法丝线，使智力提高{1}点，全能提高{2}。\r\n\r\n附魔之后，该装备会成为灵魂绑定物品。不能对物品等级高于600的物品使用。"
D.SharedStrings[15635]="永久性地在一件腿部装备上附加一条魔法丝线，使智力提高{1}点，爆击提高{2}。\r\n\r\n附魔之后，该装备会成为灵魂绑定物品。不能对物品等级高于600的物品使用。"
D.SharedStrings[15636]="永久性地在一件腿部装备上附加一条魔法丝线，使智力提高{1}点，爆击提高{2}点。\r\n\r\n附魔之后，该装备会成为灵魂绑定物品。"
D.SharedStrings[15637]="永久性地在腿部装备上附加护甲片，使其获得力量提高{1}点，爆击提高{2}的效果。\r\n\r\n只能对你自己持有的护腿使用。不能对物品等级高于600的物品使用。"
D.SharedStrings[15638]="永久性地在腿部装备上附加护甲片，使其获得敏捷提高{1}点，爆击提高{2}的效果。\r\n\r\n只能对你自己持有的护腿使用。不能对物品等级高于600的物品使用。"
D.SharedStrings[15639]="永久性地在腿部装备上附加护甲片，使其获得耐力提高{1}点，躲闪提高{2}点的效果。\r\n\r\n只能对你自己持有的护腿使用。不能对物品等级高于600的物品使用。"
D.SharedStrings[15640]="永久性地对一件肩部护甲施放工匠的恩赐附魔。此附魔可以让穿着者从敌人的尸体上获取链齿容器。"
