D.SharedStrings[15659]="汉斯加尔与弗兰佐克"
D.SharedStrings[15660]="汉斯加尔与弗兰佐克（史诗难度）"
D.SharedStrings[15661]="汉瑟尔·重拳"
D.SharedStrings[15662]="污染一个玩家脚下的土地，每秒造成{1}点暗影伤害，并使其受到大地污染的伤害提高{2}%。"
D.SharedStrings[15663]="污染者卡迪洛斯"
D.SharedStrings[15664]="污染者扎克法兰"
D.SharedStrings[15665]="污染者拉瑟莱克之魂"
D.SharedStrings[15666]="污染者斥候已向我回报你成功了，$N。做得好。$B$B你慢慢就会知道，想要赢得阿拉希盆地的胜利，我们必须保持警惕，并击败联盟任何想扩张的企图。唯有这样，我们才能确保赢得最后的胜利。"
D.SharedStrings[15667]="污染者沃戈瑞萨"
D.SharedStrings[15668]="污染者的布质束带"
D.SharedStrings[15669]="污染者的布质长靴"
D.SharedStrings[15670]="污染者的板层甲护胫"
D.SharedStrings[15671]="污染者的板层甲束带"
D.SharedStrings[15672]="污染者的板甲护胫"
D.SharedStrings[15673]="污染者的板甲束带"
D.SharedStrings[15674]="污染者的皮甲束带"
