D.SharedStrings[15680]="污染者的锁甲护胫"
D.SharedStrings[15681]="污染者科普洛斯"
D.SharedStrings[15682]="污秽的费里克斯"
D.SharedStrings[15683]="汲取一具尸体的最后生命气息。"
D.SharedStrings[15684]="汲取魔法的双眼会使其免疫魔法效果。"
D.SharedStrings[15685]="汲命者的卑劣之握"
D.SharedStrings[15686]="沃加鲁斯·道尔的邪能魔典"
D.SharedStrings[15687]="沃卡纳斯极度憎恨任何形式的生命力量。"
D.SharedStrings[15688]="沃夫格里姆·布莱曼特"
D.SharedStrings[15689]="沃尔塔鲁斯的达库鲁要求你与高尔巴格交谈，并游览祖达克。"
D.SharedStrings[15690]="沃尔瓦攻城车"
D.SharedStrings[15691]="沃登勋爵"
D.SharedStrings[15692]="沃舒古的黑暗之心"
D.SharedStrings[15693]="沃达希尔的种子"
D.SharedStrings[15694]="沃金之傲步兵"
D.SharedStrings[15695]="沃金之傲猎头者"
D.SharedStrings[15696]="沃金之傲魔导师"
D.SharedStrings[15697]="沃金创建了一片区域，使站在其中的玩家免疫任何来自敌方的伤害。"
D.SharedStrings[15698]="沃金召唤出一个治疗结界，治疗周围的友方玩家。"
D.SharedStrings[15699]="沉入瓦丝琪尔"
D.SharedStrings[15700]="沉没的神庙"
D.SharedStrings[15701]="沉睡。"
D.SharedStrings[15702]="沉重的铜质赛车"
D.SharedStrings[15703]="沉默。"
D.SharedStrings[15704]="沉默。\r\n平静。"
D.SharedStrings[15705]="沉默与打断效果的持续时间缩短{1}%。"
D.SharedStrings[15706]="沉默寡言、一丝不苟，炼金师安戈卡用自己的药水支援她的盟友。"
D.SharedStrings[15707]="沐浴在赫希斯的剧毒中，召唤出剧毒的触须，对附近的敌人造成自然伤害。"
D.SharedStrings[15708]="沐浴在酋长的力量中！为部落的荣耀而战！"
D.SharedStrings[15709]="沒有裝甲的保護，電磁脈衝將在數秒內破壞自己。"
D.SharedStrings[15710]="沒錯，沒錯！找到眼睛！幫暗影議會！現在可以參加儀式了。權杖就在那裡。\r\n\r\n這件事有點麻煩，朋友，不過卡萊德斯對你很有信心！"
D.SharedStrings[15711]="沒錯，魔魂堡！卡萊德斯知道在哪裡！\r\n\r\n卡萊德斯可以建立一條路徑，連到那裡的傳送門！"
D.SharedStrings[15712]="沙塔尔护卫"
D.SharedStrings[15713]="沙塔尔防御者"
D.SharedStrings[15714]="沙塔斯城中的萨格雷军力每天都在增强，而且变得越来越大胆。我们决不能再对他们的威胁置之不理了。\n\n如果你想到城市深处去对抗萨格雷的话，记得叫上几个同伴。"
D.SharedStrings[15715]="沙塔斯城现在处于萨格雷军队的控制下，他们的首领是大主教索克雷萨那个叛徒。\n\n沙塔尔防御者的成员们请求援助，对抗沙塔斯城东部区域内的暗影议会军队。"
D.SharedStrings[15716]="沙塔斯城现在处于萨格雷军队的控制下，他们的首领是索克雷萨，曾经的大主教。\n\n沙塔斯城东部区域的暗影议会军队正在虚空恶魔的帮助下壮大自己的力量，必须要在他们对我们的行动构成威胁前斩草除根。"
D.SharedStrings[15717]="沙塔斯城的阿达尔要求你杀死玛瑟里顿。"
D.SharedStrings[15718]="沙娜安需要我们帮她回收一些埃索达的零件。塔蕾克丝准备了一个接种装置，它可以让生活在附近这片地区的木巢枭兽得到拯救。$B$B你只需靠近那些尚未被辐射影响到的枭兽，然后对它们使用这枚水晶就可以了。而那些已经被辐射影响的枭兽……很遗憾，你只能杀死它们。到东南方的木巢山去，枭兽们就居住在那里的木巢林地中。"
D.SharedStrings[15719]="沙尘风暴围绕着你！"
D.SharedStrings[15720]="沙拉斯鸦巢图腾"
D.SharedStrings[15721]="沙許塔爾的部隊比我預料的還難對付。"
D.SharedStrings[15722]="没什么是几颗瓜解决不了的"
D.SharedStrings[15723]="没有佩剑的食人魔……"
D.SharedStrings[15724]="没有及时摄入血蓟，使你的智力下降了{1}点。"
D.SharedStrings[15725]="没有我的帮助，你也可以中和敌人的天灾之锅了，$r。$B$B去消灭死亡之门一带的血肉巨人，用它们脊骨中的脓液中和瘟疫。$B$B你所打击的是敌军最重要的核心部分。这是一个重要的任务——对我们的事业而言生死攸关的任务。只要时间允许，就应该尽力去完成。$B$B记住，你可以在莫德雷萨找到血肉巨人和天灾之锅。"
D.SharedStrings[15726]="没有我需要的物品，你要我怎么做出什么东西来?"
D.SharedStrings[15727]="没有标记的苏拉玛宝箱"
D.SharedStrings[15728]="没有装备武器。"
D.SharedStrings[15729]="没材料怎么做煎蛋卷……"
D.SharedStrings[15730]="没错!这就是四个勋章碎片。现在，来将它们结合在一起……"
D.SharedStrings[15731]="没错，我相信你已经准备好了……"
D.SharedStrings[15732]="没错，我相信你已经准备好要接受训练了……$B"
D.SharedStrings[15733]="沮丧的朱家戒卫"
D.SharedStrings[15734]="河刃密径猎手"
D.SharedStrings[15735]="河流边上有一扇下水道格栅，它可以通向卡拉赞的地下墓穴。我以前从没留意过它，不过那里可能就是幽灵指出来的地方。\n\n想一想，黑暗骑士可能一直都在我们眼皮子底下！走吧，我们去看看里面会有什么。"
D.SharedStrings[15736]="河鬃牛头人"
D.SharedStrings[15737]="河鬃萨满"
D.SharedStrings[15738]="河鬃部族"
D.SharedStrings[15739]="河鬃酋长"
D.SharedStrings[15740]="沸腾地狱火护肩"
D.SharedStrings[15741]="治安官雷德帕斯"
D.SharedStrings[15742]="治疗一个友方目标，为其恢复{1}%的最大生命值，并弹射到附近的盟友身上。"
D.SharedStrings[15743]="治疗一个友方目标，回复{1}点伤害。"
D.SharedStrings[15744]="治疗一个盟友，施放的治疗量相当于施法者生命值上限。"
D.SharedStrings[15745]="治疗一个目标，回复其{1}%的生命值。"
D.SharedStrings[15746]="治疗一位盟友。"
D.SharedStrings[15747]="治疗一名受伤的战斗法师。"
D.SharedStrings[15748]="治疗之泉图腾"
D.SharedStrings[15749]="治疗之潮图腾"
D.SharedStrings[15750]="治疗之触"
D.SharedStrings[15751]="治疗之触使你的下一个单体法术的伤害和治疗效果提高{1}%。"
D.SharedStrings[15752]="治疗之触和愈合的施法时间缩短{1}%。"
D.SharedStrings[15753]="治疗之雨覆盖这一地区，回复生命值。"
D.SharedStrings[15754]="治疗你的坐骑。只能在非战斗状态下使用。"
D.SharedStrings[15755]="治疗你的所有宠物，使其达到100%的生命值。"
D.SharedStrings[15756]="治疗其他友方宠物，为每个宠物恢复[StandardHealing(1,2)]点生命值。"
D.SharedStrings[15757]="治疗友方目标，为其恢复{1}点生命值。"
