D.SharedStrings[15760]="治疗并复活你的所有战斗宠物，使其达到100%的生命值。"
D.SharedStrings[15761]="治疗效果提高{1}%。"
D.SharedStrings[15762]="治疗效果提高{1}%。\r\n受到的伤害提高{2}%。"
D.SharedStrings[15763]="治疗效果降低{1}%。"
D.SharedStrings[15764]="治疗效果降低{1}%。\r\n受到的火焰伤害会吞噬这个效果。"
D.SharedStrings[15765]="治疗施法者。"
D.SharedStrings[15766]="治疗目标。"
D.SharedStrings[15767]="治疗目标，恢复{1}点生命值。"
D.SharedStrings[15768]="治疗者"
D.SharedStrings[15769]="治疗能量从施法者涌向其目标。"
D.SharedStrings[15770]="治疗自己，恢复{1}点生命值。"
D.SharedStrings[15771]="治疗药水注射器"
D.SharedStrings[15772]="治疗该目标，使其重新加入战斗！"
D.SharedStrings[15773]="治疗附近的一个友方目标。"
D.SharedStrings[15774]="治疗附近的盟友。"
D.SharedStrings[15775]="治疗附近的盟友，数值相当于暮光暗影治疗者所造成伤害的一定百分比！"
D.SharedStrings[15776]="治疗附近盟友，数值相当于100%所造成的暗影伤害。"
D.SharedStrings[15777]="沼地领主穆塞雷克"
