D.SharedStrings[15822]="波加尔·毁灭之拳窃取了你的一部分灵魂！\r\n他获得了你所属职业的一项技能。"
D.SharedStrings[15823]="波加尔的死期到了。$b$b我们必须找一个能量充沛的地方，那样我才有举行仪式的空间。西北边那个废弃的塔楼再合适不过了。到那找我们，把图腾放到那里的能量区域内。等放好以后，我会举行召唤波加尔的仪式。$b$b而你的任务会比较困难——那就是消灭波加尔！"
D.SharedStrings[15824]="波塔努斯派你来的?很好，我们没多少时间可以浪费了!"
D.SharedStrings[15825]="波涛语者图尔拉"
D.SharedStrings[15826]="波涛语者瓦罗伦"
D.SharedStrings[15827]="波里斯，暗夜恐魔"
D.SharedStrings[15828]="注入古神的微光血。\r\n技能的冷却时间缩短为标准时间的一半。\r\n攻击速度提高{1}%。"
D.SharedStrings[15829]="注入古神的微光血。\r\n虚空箭现在具有范围效果。\r\n技能的冷却时间缩短为标准时间的一半。\r\n攻击速度提高{1}%。"
D.SharedStrings[15830]="注入风暴的能量。\r\n效果结束后，将不稳定的生命传输给距离最远的盟友。"
D.SharedStrings[15831]="注射蜘蛛卵，短时间内孵化出小蜘蛛。"
D.SharedStrings[15832]="注意了，英雄们！$B$B塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想象的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。$B$B所有对此感兴趣的联盟成员都应该去向塞纳里奥议会报到。去和达纳苏斯的大德鲁伊范达尔·鹿盔谈谈吧！"
D.SharedStrings[15833]="注意了，英雄们！$B$B塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想象的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。$B$B所有对此感兴趣的部落成员都应该去向塞纳里奥议会报到。去和雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈谈吧！"
