D.SharedStrings[15868]="洛斯贝格村。那座村落被诅咒了，这对我们来说也算是件好事，$n。我都不知道这帮强盗是如何学会钓鱼的，不过我也没时间刨根问底了。$B$B我要你去那里弄点鱼来，能弄多少是多少啦。自从我们夺回岛屿后，吃得简直跟狗屎一样，这次行动简直是储备军粮的绝佳机会。$B$B当心潜伏者，据说村落中到处都是他们的身影。"
