D.SharedStrings[15884]="活着的时候，没有任何生物之间的羁绊比霜狼兽人和他或她的霜狼伙伴更紧密。霜狼与兽人一起进食、睡觉和战斗，直到其中一方或双方都战死沙场。即使如此，有时候死亡也无法阻止霜狼协助它亲爱的兽人。"
