D.SharedStrings[15910]="海军上将泰勒已经查出了是谁在幕后搞鬼。他让我们想尽一切办法拯救幸存者……他想要自己一个人去处理这件事。$B$B之后我们就再也没有听到他的消息，但我们必须执行命令。$B$B我们请求你……找到他。他往农场那边去了。"
