D.SharedStrings[16101]="潜入地下，向目标敌人发起攻击，对5码范围内的所有敌人造成物理伤害，并将其击飞。"
D.SharedStrings[16102]="潜藏者的武器上涂着致命药膏，持续对其攻击目标造成自然伤害。"
D.SharedStrings[16103]="潜行。"
D.SharedStrings[16104]="潜行。\r\n潜行状态下发动的第一次攻击造成300%额外伤害。"
