D.SharedStrings[16115]="激光轰击附近的区域，造成火焰伤害。"
D.SharedStrings[16116]="激励一名侏儒平民参军。"
D.SharedStrings[16117]="激怒施法者及其附近的盟友，使他们造成的物理伤害提高{1}%。"
D.SharedStrings[16118]="激情豆咔啡公司"
D.SharedStrings[16119]="激活之后遁入阴影，降低敌人侦测到你的几率。持续直到取消或进行移动。取消这个效果之后，你对任何仍在战斗中的敌人造成的威胁值将恢复。"
D.SharedStrings[16120]="激活之后，施法者所承受的全部伤害有{1}%被你的小鬼、虚空行者、魅魔、地狱猎犬、恶魔卫士或奴役的恶魔分担。该伤害无法避免。只要恶魔保持激活和受控状态，该效果就一直持续。"
D.SharedStrings[16121]="激活之后，目标无法使用潜行或隐形术。"
D.SharedStrings[16122]="激活之后，目标的体积变大，所能造成的伤害提高10%。"
D.SharedStrings[16123]="激活之后，目标的体积变大，所能造成的伤害提高20%。"
D.SharedStrings[16124]="激活之后，目标的体积变大，所能造成的伤害提高30%。"
D.SharedStrings[16125]="激活之后，目标的法术和攻击的爆击几率提高10%。"
D.SharedStrings[16126]="激活之后，目标的生命值提高20%。"
D.SharedStrings[16127]="激活埃匹希斯装置并取得鲁克玛护符。"
D.SharedStrings[16128]="激活时将提高你所产生的威胁值，使你成为一个更有效的坦克。"
D.SharedStrings[16129]="激活时提高你所产生的威胁值。"
D.SharedStrings[16130]="激活的疾病效果有几率触发符文强化。"
D.SharedStrings[16131]="激活的防火结界"
D.SharedStrings[16132]="激活米米尔隆的自毁程序，然后击败他（10人）。"
D.SharedStrings[16133]="激活米米尔隆的自毁程序，然后击败他（25人）。"
D.SharedStrings[16134]="激活附近的钢铁爆弹。"
D.SharedStrings[16135]="激流的治疗量提高{1}%。"
D.SharedStrings[16136]="濒死时分解，产生的能量波会击退所有玩家。"
D.SharedStrings[16137]="灌注了恶魔精华。"
D.SharedStrings[16138]="灌注了邪能魔法。"
D.SharedStrings[16139]="灌注从扭曲虚空泄露出的虚空能量，使造成的伤害提高{1}%。"
D.SharedStrings[16140]="灌注来自附近虚空之池的虚空能量。造成的伤害提高10%。"
D.SharedStrings[16141]="灌注着邪能的一拳，造成火焰伤害。"
D.SharedStrings[16142]="灌注龙血的警卫能够嗅到潜行者的气味。别靠太近了！"
D.SharedStrings[16143]="灌魔幽灵进入了堕落十字军的尸体，将它复活为灌魔僵尸。"
D.SharedStrings[16144]="火元素向前猛冲，在身后留下一道火焰。"
D.SharedStrings[16145]="火元素的力量随着其生命值的降低而变得虚弱。"
D.SharedStrings[16146]="火刃剑圣"
D.SharedStrings[16147]="火刃氏族"
D.SharedStrings[16148]="火刃氏族督军"
D.SharedStrings[16149]="火刃烈焰先知"
D.SharedStrings[16150]="火刃祈求者"
D.SharedStrings[16151]="火力全开！"
D.SharedStrings[16152]="火势被扑灭了!你和你的救火队胜利了!呀哈!$B$B无头骑士的攻击失败了，但除非他和他的头一起被消灭，他还会再回来的。$B$B在此之前，让我们好好享受你为这些孩子们带来的安全吧。我很荣幸能目睹你今天勇敢的行为。"
D.SharedStrings[16153]="火山领主伊格尼斯向前方野蛮冲锋，使大地开始碎裂颤抖，对被击中的敌人造成火焰伤害。"
D.SharedStrings[16154]="火山领主伊格尼斯重击地面，使敌人衰弱崩溃，造成物理伤害并降低其最大生命值。"
D.SharedStrings[16155]="火把已经准备好了。把它插在码头的尽头，对可能出现的一切情况做好准备吧。$B$B我不知道火把的浓烟会带来什么……如果真的有东西出现的话。我必须说，我对这种民间魔法是有所怀疑的，但现在我们也没有时间来想其它办法了。看在你和加尔的份上，祝你好运。"
D.SharedStrings[16156]="火炬杂耍者"
D.SharedStrings[16157]="火炮准备开火。"
D.SharedStrings[16158]="火炮炮台使高格鲁克可以使用急速射击技能。"
D.SharedStrings[16159]="火炮炮台使高格鲁克可以使用火炮弹幕技能。"
D.SharedStrings[16160]="火焰中冒出的裝飾用煙霧"
