D.SharedStrings[16207]="灰葬男爵"
D.SharedStrings[16208]="灰葬男爵对你产生了怜悯，不过只有这样他才能继续施加痛苦！为附近的敌人恢复{1}%的生命值。"
D.SharedStrings[16209]="灰葬男爵治疗他的腐蚀躯体，为自己恢复{1}%的总生命值。"
D.SharedStrings[16210]="灰葬男爵释放出全部的力量，进入黑暗天使长的形态。"
D.SharedStrings[16211]="灵敏的嗅觉能发现任何间谍。别靠得太近！"
