D.SharedStrings[16215]="灵魂净化者玛瑞亚"
D.SharedStrings[16216]="灵魂医者"
D.SharedStrings[16217]="灵魂回归使玩家的灵魂回到在真实世界中的躯体中。"
D.SharedStrings[16218]="灵魂图腾"
D.SharedStrings[16219]="灵魂女王德雅娜"
