D.SharedStrings[16226]="灵魂行者黑角"
D.SharedStrings[16227]="灵魂链接图腾"
D.SharedStrings[16228]="灵魔，灵魔之子"
D.SharedStrings[16229]="灼烧敌人脚下的土地，每秒造成火焰伤害。"
D.SharedStrings[16230]="灼烧敌人，对其造成火焰伤害。"
D.SharedStrings[16231]="灼烧目标区域内的单位，造成火焰伤害。"
D.SharedStrings[16232]="灼热的流星撞击地面后爆炸，成为碎片。"
D.SharedStrings[16233]="灼热的流星撞击地面，爆炸后对周围玩家造成{1}点伤害并将其击退。"
D.SharedStrings[16234]="灼热的漩涡对附近的单位造成大量火焰伤害，并持续制造火焰飓风。"
D.SharedStrings[16235]="灾变角斗士暮光幼龙"
D.SharedStrings[16236]="灾变角斗士的活跃马靴"
D.SharedStrings[16237]="炎狱地狱火"
D.SharedStrings[16238]="炎魔领主斯莫德隆"
D.SharedStrings[16239]="炎鳞使附近的水升温，灼伤附近的敌人。"
D.SharedStrings[16240]="炫光毁灭对暮光领域的目标造成{1}点暗影伤害！"
D.SharedStrings[16241]="炮手的多孔武装带"
D.SharedStrings[16242]="炸弹机器人"
D.SharedStrings[16243]="炸弹爆炸后对周围的所有人造成{1}点火焰伤害。"
D.SharedStrings[16244]="炸弹的冲击波将对其所触及的所有敌人造成{1}点火焰伤害。"
D.SharedStrings[16245]="炸弹零件。所以我的怀疑是正确的。那不是我希望的事。$B$B好吧，接着你跟我还有一些讨厌的事情要处理。"
D.SharedStrings[16246]="炸药桶爆炸对附近的敌人造成{1}点火焰伤害。"
D.SharedStrings[16247]="点击右键来召唤或解散泡泡。"
D.SharedStrings[16248]="点击开始宠物对战。"
D.SharedStrings[16249]="点燃一名敌人附近的空气，造成大量火焰伤害。"
D.SharedStrings[16250]="点燃它，然后扔出去，尽情观赏魅力的焰火吧！"
D.SharedStrings[16251]="点燃海滩上部落登陆点的烽火，给部落舰队发信号。"
D.SharedStrings[16252]="点燃目标造成{1}点神圣伤害。"
D.SharedStrings[16253]="点燃附近的敌人，造成{1}点火焰伤害。"
D.SharedStrings[16254]="点起一堆营火，使附近的冒险者们的精神提高4点，并可以在营火旁烹饪。"
D.SharedStrings[16255]="為了你我著想，我希望你沒被跟蹤。我們動作要快，我就快要成功了。"
