D.SharedStrings[16339]="焚化前方锥形范围内的目标，造成火焰伤害。"
D.SharedStrings[16340]="焚化恶魔目标，立刻将其击杀，并将其尸体化为灰烬。"
D.SharedStrings[16341]="焚化恶魔，立即杀死目标。"
D.SharedStrings[16342]="焚化者古雷曼格"
D.SharedStrings[16343]="焚木村议会"
D.SharedStrings[16344]="焦躁的土元素"
D.SharedStrings[16345]="焰须狮鹫骑手"
D.SharedStrings[16346]="煞魔邪恶地尖笑，将一队玩家传送至附近的一个神龛，使其与平台上堕落的守护者战斗。"
D.SharedStrings[16347]="照你的描述…那是奥舆全览图投影!$B$B<大法师焦虑的神情马上就被他冷酷的外表给掩饰住了。>$B$B奥舆全览图是世界上所有魔力地脉交会点的地图。蓝龙军团利用它寻找并摧毁地脉“锚点”，以便把魔力能量送回魔枢。$B$B问题是，破坏的路径应该是通往西方，但是为何是往东方呢?"
D.SharedStrings[16348]="煽动者布莱卡特"
D.SharedStrings[16349]="熊形态和猎豹形态下的移动速度提高了。"
D.SharedStrings[16350]="熊猫人八宝汤面"
D.SharedStrings[16351]="熊猫人八宝汤面餐车"
D.SharedStrings[16352]="熊猫人古灵以藏匿这种神圣宝物袋而闻名。"
D.SharedStrings[16353]="熊猫人古灵宠物补给"
D.SharedStrings[16354]="熊猫人地灵"
D.SharedStrings[16355]="熊猫人建筑营地"
D.SharedStrings[16356]="熊猫人微风之灵"
D.SharedStrings[16357]="熊猫人找不到他的盾牌。如果你找到盾牌，他将会为你抗击野牛人！"
D.SharedStrings[16358]="熊猫人水灵"
D.SharedStrings[16359]="熊猫人流水之灵"
D.SharedStrings[16360]="熊猫人火灵"
