D.SharedStrings[16367]="熊猫人驭灵师"
D.SharedStrings[16368]="熔喉软弱的后脑暴露出来了！\r\n对这个部位造成的伤害提高{1}%。\r\n生命值为头部和躯体部分共有。"
D.SharedStrings[16369]="熔岩元素"
D.SharedStrings[16370]="熔岩喷注而出，造成{1}点伤害并将敌人击退。"
