D.SharedStrings[16377]="熔岩爆裂"
D.SharedStrings[16378]="熔岩穿刺者變形視覺效果"
D.SharedStrings[16379]="熔火切割者胸甲"
D.SharedStrings[16380]="熔火恶犬宝宝"
D.SharedStrings[16381]="熔火迸发者朝目标位置喷出一团熔岩火球，造成熔岩迸涌。"
D.SharedStrings[16382]="熔炉之主加弗斯特"
D.SharedStrings[16383]="熔炉就在你面前了，还有魔古族锻造武器的核心机密。\n\n在它的后面，就是魔古族的守门者，他掌握着开启下一个城区的钥匙。\n\n该我们行动了！"
D.SharedStrings[16384]="熱能噴發口兔子"
D.SharedStrings[16385]="燃放几组烟火，试图吸引大家对汤面餐车的注意。"
D.SharedStrings[16386]="燃灰幼蛛"
D.SharedStrings[16387]="燃灰熊猫人凤凰"
D.SharedStrings[16388]="燃烧6秒，造成相当于最大生命值3%的伤害。"
D.SharedStrings[16389]="燃烧之怒摧毁对盲眼巨龙造成眩晕的矮人护盾！"
D.SharedStrings[16390]="燃烧之拳有一定几率在攻击时造成灼烧之伤效果。"
D.SharedStrings[16391]="燃烧军团传送门的碎片。"
D.SharedStrings[16392]="燃烧军团信件"
D.SharedStrings[16393]="燃烧军团先锋"
D.SharedStrings[16394]="燃烧军团的进攻"
D.SharedStrings[16395]="燃烧军团花费了一万多年的时间策划对艾泽拉斯的入侵。击败他们的首领，让他们再也无法威胁到我们的世界。"
D.SharedStrings[16396]="燃烧吧，斯克恩，燃烧吧！"
D.SharedStrings[16397]="燃烧周围的敌人，对其造成周期性的{1}点火焰伤害。"
D.SharedStrings[16398]="燃烧周围的敌人，对其造成周期性的火焰伤害。"
D.SharedStrings[16399]="燃烧平原上的黑石兽人在为一个黑暗的主人卖命——他用活物来进行扭曲的实验，以创造属于自己的怪兽军队。他的实验品中，有许多像他本人一样堕落的家伙，但其他人则是完全无辜的。$b$b在南边的雏龙丘陵，他们将雏龙捆在地上，准备拿它们进行这种邪恶的实验。我不能容忍这种事。破坏它们的锁链，把雏龙带回来给我……让它们获得安全。"
D.SharedStrings[16400]="燃烧的女巫会"
D.SharedStrings[16401]="燃烧的锁链将附近20码范围内的所有敌人拖拽至施法者身边，并使其昏迷。4秒后施法者开始燃烧，对附近敌人造成火焰伤害。"
D.SharedStrings[16402]="燃烧的镜像围绕在施法者周围，对触碰到的敌人造成火焰伤害。"
D.SharedStrings[16403]="燃烧着的焦油可以将附近的所有东西都引燃。"
D.SharedStrings[16404]="燃烧，每2秒造成{1}点火焰伤害。"
D.SharedStrings[16405]="燃烬血肉之握"
D.SharedStrings[16406]="燃燒軍團的靈魂收割者每1秒對15碼範圍內的敵人造成{1}點火焰傷害。"
D.SharedStrings[16407]="爆击伤害提高{1}%。"
D.SharedStrings[16408]="爆击几率提高{1}%。"
D.SharedStrings[16409]="爆击几率的百分比数值提高{1}，对攻击者造成火焰伤害。"
D.SharedStrings[16410]="爆击奖励"
D.SharedStrings[16411]="爆击提高{1}-{2}。提高的数值取决于牌组中最上面一张牌。"
D.SharedStrings[16412]="爆击提高{1}。"
D.SharedStrings[16413]="爆击提高{1}点。"
D.SharedStrings[16414]="爆击等级和法术爆击等级提高{1}。"
D.SharedStrings[16415]="爆击等级提高{1}。"
D.SharedStrings[16416]="爆发能量，击退附近所有敌人，对其造成{1}点暗影伤害。"
D.SharedStrings[16417]="爆炸产生软泥云雾，对附近敌人造成自然伤害。"
D.SharedStrings[16418]="爆炸使你的船体周围的水面剧烈振颤。"
D.SharedStrings[16419]="爆炸使你船体周围的水面剧烈振颤。"
D.SharedStrings[16420]="爆炸在时空中撕扯出一道空洞，留下一道涡流。\r\n站在漩涡中的玩家移动速度降低{1}%，且每秒受到{2}点奥术伤害。"
D.SharedStrings[16421]="爆炸对敌人造成伤害。"
D.SharedStrings[16422]="爆炸接合混合物"
D.SharedStrings[16423]="爆炸桶会对恶魔目标造成{1}点自然伤害。"
D.SharedStrings[16424]="爆炸范围内的敌人被吸取{1}点法力值并且对目标造成伤害，数值等量于吸取的法力值。"
D.SharedStrings[16425]="爆炸陷阱"
D.SharedStrings[16426]="爆炸，对附近的敌人造成大量奥术伤害。"
D.SharedStrings[16427]="爆炸，造成{1}点火焰伤害，并使其受到的所有伤害提高{2}%。"
D.SharedStrings[16428]="爆破专家"
D.SharedStrings[16429]="爆破专家麦加奇"
D.SharedStrings[16430]="爆破小组是一支效率极高的团队。一旦有人阵亡，其他人也不会幸免。"
D.SharedStrings[16431]="爆裂成数个较小的炸弹。"
D.SharedStrings[16432]="爆裂熔炉会周期性释放出冲击热能至整个房间，对所有玩家造成{1}点火焰伤害。"
D.SharedStrings[16433]="爆裂熔炉（史诗难度）"
D.SharedStrings[16434]="爆裂领主的毁灭瞄准镜"
D.SharedStrings[16435]="爪击敌人，对其造成{1}%的普通近战伤害。"
D.SharedStrings[16436]="爪牙的天灾石是天灾军团的身份象征，通常是由那些部署在瘟疫之地的、较为弱小的士兵所携带的。我所说的“较为弱小”是个相对的概念，无论天灾军团出现在哪里，他们都是一个不可轻视的威胁。$B$B如果你能拿来二十个这样的天灾石，银色黎明将会给你颁发一枚勇气徽记，以此表彰你在于天灾军团的战争中做出的贡献!"
D.SharedStrings[16437]="爬上奥达希尔西边的坡道去见特纳隆·雷拳。"
D.SharedStrings[16438]="爱丽丝·普里洛斯"
D.SharedStrings[16439]="爸爸让我给你这把钥匙，他说你可以用它打开房子后面的一只箱子。$B$B他还要让我谢谢你。你是不是帮过他？你有没有告诉他你帮我找到了我的洋娃娃？$B$B好吧，这里是钥匙。谢谢你，$n。谢谢你！你是个好心的$g先生:小姐;！"
D.SharedStrings[16440]="片刻不得安宁"
D.SharedStrings[16441]="牛头人酋长乐队"
D.SharedStrings[16442]="牠們看起來很開心能回到家裡。做得非常好。"
D.SharedStrings[16443]="牢牢记住瓦利斯的课程，$N。这决定了你会赢得比赛还是在战斗中摔下坐骑。"
D.SharedStrings[16444]="牢狱在吸引着你，这可不是好兆头。"
D.SharedStrings[16445]="牧师训练师"
D.SharedStrings[16446]="牧师马鲁夫"
D.SharedStrings[16447]="牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。"
D.SharedStrings[16448]="牧羊人卡沃斯"
