D.SharedStrings[16602]="狼人的攻击一波接着一波，我能教你的也就这么些了。$B$B我们应该考虑一下要不要跟其他的幸存者一同前往南边。据说格雷迈恩国王就在此地。$B$B大家聚集起来的话，生存的机会也会大一点……如果你身旁的人会治疗法术，那就更好了。"
