D.SharedStrings[16694]="玛维·影歌"
D.SharedStrings[16695]="玛艾里可以把魂能提取出来，转移给$N……利用玛艾里的容器就可以把这中能量赋予你自己，或者你的盟友。"
D.SharedStrings[16696]="玛莱恩姑妈让我留在家里，因为我的爸爸出去作战了。爸爸是世界上最勇敢的人！$B$B但是我在这里等了很长时间，他一直都没有回来。有时候会有坏人来和我说话，我想让爸爸把他们赶走，但是他不在这里！$B$B有时候，天黑了以后，我会和我的洋娃娃玩，但是我把它丢在镇子里了。$B$B你能不能去帮我找到洋娃娃呢？"
D.SharedStrings[16697]="玛蒂尔达·斯克提多迪尔"
D.SharedStrings[16698]="玛诺洛斯"
D.SharedStrings[16699]="玛诺洛斯会持续不断地进行轰击。起初对较小半径范围内造成{1}点火焰伤害，之后对中等半径范围内造成{2}点火焰伤害，最后对较大半径范围内造成{3}点火焰伤害。强化邪能引导会对所有敌人造成额外的伤害，距离冲击点越远，受到的伤害越低。"
D.SharedStrings[16700]="玛诺洛斯在召唤强化邪焰风暴！风暴威力会随着时间持续增强。"
D.SharedStrings[16701]="玛诺洛斯的獠牙肩甲"
D.SharedStrings[16702]="玛诺洛斯释放一阵野蛮的强化长刀猛刺，以及强化巨力冲击。"
D.SharedStrings[16703]="玛诺洛斯释放一阵野蛮的长刀猛刺及巨力冲击。"
D.SharedStrings[16704]="玛诺洛斯（史诗难度）"
D.SharedStrings[16705]="玛霍拉姆·硬蹄"
D.SharedStrings[16706]="玩家保护自己，受到的伤害降低30%。敌人的碎盾或冲锋攻击将移除一层防御效果。该效果最多可叠加3次。"
D.SharedStrings[16707]="玩家可以骑着坐骑，践踏从坐骑上被击落的勇士。被践踏的敌人会昏迷15秒，并无法获得新的坐骑。"
D.SharedStrings[16708]="玩家向前冲锋，造成物理伤害，并从目标身上移除一层防御效果。"
D.SharedStrings[16709]="玩家向前刺出长枪，对目标造成物理伤害。"
D.SharedStrings[16710]="玩家在控制构造体时由于同步率较低，导致造成的伤害降低{1}%。"
D.SharedStrings[16711]="玩家将他们的长枪投过战场，对目标造成物理伤害并移除其身上一层防御。"
D.SharedStrings[16712]="玩家将突袭库卡隆重兵防守的塔楼，督军扎伊拉骑着她的始祖幼龙迦拉卡斯盘旋在空中。与此同时，联军的爆破师会炸开附近塔楼的大门，允许一支突击小队进入塔楼并且占领它。当两座塔楼都被占领之后，可以使用每座塔楼顶上的对空火炮来击落迦拉卡斯并开始最后的战斗。"
D.SharedStrings[16713]="玩家特技双倍"
D.SharedStrings[16714]="玩家的镜像"
D.SharedStrings[16715]="现在“金子”准备好了，我要你把它带给阿布力可汗。他肯定会喜出望外，然后帮咱们安设钻机。我们用的着他们的马力。$B$B哈哈，听明白了吗？马力？"
D.SharedStrings[16716]="现在你可以体验到另一边的人们的生活了。"
D.SharedStrings[16717]="现在你可以在水域里自由行动，也不用担心被淹死了。$b$b那么开始做正事吧。$b$b首先，很多士兵都面临溺亡的危险。我救了你，你也应该向他们伸出援手。$b$b我在这个海螺壳上施加了法术。用它来搭救你的朋友吧。$b$b快点！"
D.SharedStrings[16718]="现在你必须决定，是否要和我们同生共死。"
D.SharedStrings[16719]="现在你明白了吗？派你们的人去对付王子的部队，只会让他们获得更多的士兵。$B$B我也不指望你能明白……你的下场或许会和其他人一样。你还是回到派你来的人身边去吧，他们可能在担心你了。"
D.SharedStrings[16720]="现在你是大王，你可以从那个精灵王子手里拿回令戈多克骄傲的神器！你前一任的大王失败了，自从托塞德林那个可恶的精灵从我们古代戈多克大王手中偷走它之后，没有一个大王能想办法把它夺回来！$B$B这个神器叫做戈多克力量护手。传说说只有真正的戈多克大王才能把它拿回来。这个可恶的精灵还在附近——如果你找到它的话，那你就可以使用它！真的！"
D.SharedStrings[16721]="现在你是戈多克食人魔的国王啦！当国王的感觉真好……"
D.SharedStrings[16722]="现在你该明白自己面对的是怎样的敌人了，$n。他不会感到痛苦……悔恨……他完全没有人性。他为达目的，不择手段。$B$B这颗心就是他的弱点，现在他已经知道你发现了它。$B$B如果你要回去找那颗心，最好带一些帮手去。他不会再任由它全不设防地躺在那里了。"
D.SharedStrings[16723]="现在你该走了。我身后有一道传送门，它可以把你送到地面上去。$B$B我们还会见面的。他会来找你。$B$B他迟早会找到你。"
D.SharedStrings[16724]="现在可在猎豹形态下施放月火术，产生1个连击点数，造成的伤害取决于攻击强度，并消耗30点能量。"
D.SharedStrings[16725]="现在我们应该反过来了解敌人的更多情报。$B$B我们的斥候识别出了钢铁部落的几位中级军官。他们的攻击方式非常有组织性和纪律性，这样的战术是不可能从单纯的游牧文化中自然领悟出来的。肯定是有人给这些军官提供了什么锦囊妙计。$B$B你是我执行这项任务的唯一一个人选，$n。"
D.SharedStrings[16726]="现在我们终于在这座该死的岛上有了立足之地，可以开始调查它是如何变成现在这番模样的了。我们的士兵在东边的咒怨地牢入口一带发现了一些日记。$B$B基地里的那些老学究对这些日记颇感兴趣。我要你去尽快给我找四本日记回来。$B$B$n，多加小心，那地方到处都是亡灵。"
D.SharedStrings[16727]="现在我们需要做的就是一箭双雕，$c。$B$B你就是那支箭，而商人穆法赫和古拉莫什就是那两只雕。他们应该就在眠月花园的西半边，去那座两层楼的大房子里找找看。$B$B如果可以的话，我希望看到他们死亡的凭证。"
D.SharedStrings[16728]="现在所有人都可以看到你有多么强壮了！"
D.SharedStrings[16729]="现在有了这座船坞，就该忙着造船了！索洛格已经去了干船坞，你要不要去那里见见他？他说他已经有主意了。"
D.SharedStrings[16730]="现在该对付东边悬崖上该死的大炮了！$B$B要是你能的话，跳上你的赛艇，驶往南海据点。抬头你就能看到一排大炮在朝下对我们轰。$B$B那些海盗对工程一窍不通。让大炮炸膛对你来说应该不难。"
D.SharedStrings[16731]="现在跳入裂缝之中将会给你带来无穷的灾难……"
D.SharedStrings[16732]="现在，$n，你将参加达隆郡的战斗，并且拯救约瑟夫·雷德帕斯。$B$B把这个遗物包裹放到达隆郡的广场中，达隆郡居民的灵魂将因此而被唤醒。参加他们的战斗，并确保你完成两件事：在霍古斯死后，达维必须存活；雷德帕斯必须存活，直到他被腐化而堕落，此时再将其击败。$B$B在打败了堕落的雷德帕斯之后，他的灵魂就将得到救赎。同他交谈，然后再去找他的女儿帕米拉。"
D.SharedStrings[16733]="现在，你该回晴日峰继续武僧之道的训练了。你可以使用禅宗朝圣前往那里。抵达后，请去和海特大师谈一谈。"
D.SharedStrings[16734]="现在，翡翠林中的所有猢狲一见到你就颤栗不已。"
D.SharedStrings[16735]="现实撕裂者指环"
D.SharedStrings[16736]="玳刃正在引导一块攻击盲区。"
D.SharedStrings[16737]="玳刃的冰冻护足"
D.SharedStrings[16738]="珀光原始恐角龙"
D.SharedStrings[16739]="珀酒仙将酒保存在适当的温度中，并调配出合适的浓稠度。酿酒时在他的大锅中添加更多的酒！"
D.SharedStrings[16740]="珀酒仙的盎迦丛林酒的浓香可使跑速提高{1}%，急速提高{2}%。"
D.SharedStrings[16741]="珊德拉·巴尔坦"
D.SharedStrings[16742]="珊蒂斯·羽月"
D.SharedStrings[16743]="珍稀宠物与杂货"
D.SharedStrings[16744]="珍贵的强化物质"
D.SharedStrings[16745]="珍贵的武器"
D.SharedStrings[16746]="珠光宝气的哈莉娅"
D.SharedStrings[16747]="珠宝加工供应商"
D.SharedStrings[16748]="珠宝加工军需官"
D.SharedStrings[16749]="珠宝加工大师"
D.SharedStrings[16750]="珠宝加工报酬"
D.SharedStrings[16751]="珠宝加工的特别订单：比黄金还要耀眼的明黄色"
D.SharedStrings[16752]="珠宝加工的特别订单：蓝天碧海般的湛蓝色"
D.SharedStrings[16753]="珠宝加工训练师"
D.SharedStrings[16754]="珠鳍守池者"
D.SharedStrings[16755]="珠鳍波涛卫士"
D.SharedStrings[16756]="班·熊心"
D.SharedStrings[16757]="班福，班禄的幼崽"
D.SharedStrings[16758]="現在只需要全神貫注在他的精華上，然後分析出他的所在位置。你做得很好。"
D.SharedStrings[16759]="球状闪电"
D.SharedStrings[16760]="球状闪电会冲向一个敌人，根据其与目标的距离造成越来越高的自然伤害。"
D.SharedStrings[16761]="琥珀包裹的恐虫"
D.SharedStrings[16762]="琥珀塑形者昂舒克"
D.SharedStrings[16763]="琥珀塑形者昂舒克（英雄难度）"
D.SharedStrings[16764]="琥珀寄生虫"
D.SharedStrings[16765]="琥珀寄生长袍"
D.SharedStrings[16766]="琥珀岩臺的被囚禁的碧晶巫士的任務隱形功能"
D.SharedStrings[16767]="琥珀已经变成了胶状陷阱！"
D.SharedStrings[16768]="琳达·安·卡斯汀"
D.SharedStrings[16769]="琼娜·布鲁哈特"
D.SharedStrings[16770]="瑞文戴尔男爵"
D.SharedStrings[16771]="瑞文戴尔的死亡战马"
D.SharedStrings[16772]="瑞沙德"
D.SharedStrings[16773]="瑞沙德的伙伴"
D.SharedStrings[16774]="瑞特辛派你來的，是吧？看來我昔日的導師還是不肯親自動手做骯髒事。\r\n\r\n但當然，像他這樣地位的人，怎麼能讓人看到與疑似阿古斯覺醒者的成員在一起呢！其他人會怎麼想？\r\n\r\n雖然我很高興瑞特辛需要我的協助，但我不是在做慈善事業，$n。\r\n\r\n想要我幫忙，就要用力量與知識來交換。如果你有其中之一，那麼我們或許就能好好安排。"
D.SharedStrings[16775]="瑞维尔·考斯特"
D.SharedStrings[16776]="瑞苏的不竭勇气使你的移动速度提高{1}%。"
D.SharedStrings[16777]="瑟尔林·卡斯迪诺夫教授"
D.SharedStrings[16778]="瑟拉提克琥珀诱捕者"
D.SharedStrings[16779]="瑟留斯·黑翼"
D.SharedStrings[16780]="瑟维斯·明焰"
D.SharedStrings[16781]="瑟芬崔斯克向一个随机的敌人喷吐毒液。"
D.SharedStrings[16782]="瑟芬崔斯克的子嗣"
D.SharedStrings[16783]="瑟莱德丝公主"
D.SharedStrings[16784]="瑟里提克投弹手"
D.SharedStrings[16785]="瑟里耶克爵士"
D.SharedStrings[16786]="瑟银兄弟会"
D.SharedStrings[16787]="瓦兰奈尔，远古王者之锤"
D.SharedStrings[16788]="瓦古斯是塞纳里奥要塞的铁匠，他需要一些附魔材料来为我们的部队制作强力的武器。去找到这些材料，把它们直接交给瓦古斯，这样塞纳里奥议会的军队就有了作战装备的保障。"
D.SharedStrings[16789]="瓦妮莎·菲格雷丝"
D.SharedStrings[16790]="瓦尔加·高炉"
D.SharedStrings[16791]="瓦尔基拉候选者"
D.SharedStrings[16792]="瓦尔基拉女武神"
D.SharedStrings[16793]="瓦尔基拉女王"
D.SharedStrings[16794]="瓦尔洛斯·云击"
D.SharedStrings[16795]="瓦尔莎拉德鲁伊"
D.SharedStrings[16796]="瓦尔莎拉被月神祝福过的水让生活在其中的藓鳃鲈鱼能够无限生长。"
D.SharedStrings[16797]="瓦尔莎拉难民"
D.SharedStrings[16798]="瓦拉丁·银刃"
D.SharedStrings[16799]="瓦拉加尔候选者"
D.SharedStrings[16800]="瓦拉加尔储物箱"
D.SharedStrings[16801]="瓦拉加尔净化者"
D.SharedStrings[16802]="瓦拉加尔刻符者"
D.SharedStrings[16803]="瓦拉加尔勇士"
D.SharedStrings[16804]="瓦拉加尔唤雷者"
D.SharedStrings[16805]="瓦拉加尔女武神"
D.SharedStrings[16806]="瓦拉加尔徽章"
D.SharedStrings[16807]="瓦拉加尔战剑"
D.SharedStrings[16808]="瓦拉加尔秘法师"
D.SharedStrings[16809]="瓦拉加尔符文使者"
D.SharedStrings[16810]="瓦拉加尔雷铸者"
D.SharedStrings[16811]="瓦拉加尔风暴之翼幼龙"
D.SharedStrings[16812]="瓦拉纳王子"
D.SharedStrings[16813]="瓦拉纳的备用徽记之戒"
D.SharedStrings[16814]="瓦拉里尔的搜寻"
D.SharedStrings[16815]="瓦格里女武神"
D.SharedStrings[16816]="瓦罗伦的收缩图腾"
D.SharedStrings[16817]="瓦莉拉·萨古纳尔"
D.SharedStrings[16818]="瓦萨里奥·林克格雷斯"
D.SharedStrings[16819]="瓦萨雷克的日记：战争的前奏"
D.SharedStrings[16820]="瓦蕾莉·兰格鲁"
D.SharedStrings[16821]="瓦里安·乌瑞恩国王"
D.SharedStrings[16822]="瓦里安·乌瑞恩国王发出胜利的战吼，为你回复20%的最大生命值。"
D.SharedStrings[16823]="瓦里昂娜变成一束暮光，让她能够不受伤害地逃走！"
D.SharedStrings[16824]="瓦里昂娜深吸一口气，开始施放暮光烈焰，它会对目标造成{1}点暗影伤害，并将目标送入暮光领域！"
D.SharedStrings[16825]="瓦里玛萨斯"
D.SharedStrings[16826]="瓦里玛萨斯之影"
D.SharedStrings[16827]="瓦雷迪斯·邪魂"
D.SharedStrings[16828]="甜蜜之寒"
D.SharedStrings[16829]="甜蜜的（白色）糖果。"
D.SharedStrings[16830]="生命之根的子嗣"
D.SharedStrings[16831]="生命值上限提高{1}%。"
D.SharedStrings[16832]="生命值上限提高{1}点。"
D.SharedStrings[16833]="生命值上限降低{1}%。"
D.SharedStrings[16834]="生命值低于50%时释放出炽热蒸汽，治疗周围激活的血球，为其恢复{2}%的最大生命值。"
D.SharedStrings[16835]="生命值和伤害根据装备水平获得提升。"
D.SharedStrings[16836]="生命值在{1}%以上时，受到的伤害降低{2}%。"
D.SharedStrings[16837]="生命值提高300点。近战攻击速度提高15%。每5秒恢复10点法力值。"
D.SharedStrings[16838]="生命值提高{1}%。"
D.SharedStrings[16839]="生命值提高{1}%。\r\n治疗和伤害吸收效果提高{2}%。\r\n造成的伤害提高{3}%。"
D.SharedStrings[16840]="生命值提高{1}%。\r\n造成的伤害提高{2}%。"
D.SharedStrings[16841]="生命值提高{1}%，并激活势不可挡。\r\n\r\n非骑乘状态时可以使用强震。"
D.SharedStrings[16842]="生命值提高{1}点。"
D.SharedStrings[16843]="生命值无法被恢复到{1}%以上。"
D.SharedStrings[16844]="生命值达到33%和66%时，瑟芬崔斯克将会下潜，然后出现在远处的地点，召唤两只多头蛇子嗣！"
D.SharedStrings[16845]="生命值降低{1}%。"
D.SharedStrings[16846]="生命守卫高拉"
D.SharedStrings[16847]="生命缚誓者的仆从"
D.SharedStrings[16848]="生命缚誓者的凋零之赐"
D.SharedStrings[16849]="生命缚誓者的恩赐"
D.SharedStrings[16850]="生成大量的闪电箭攻击地面，对所有敌方目标造成{1}点自然伤害。"
D.SharedStrings[16851]="生病的小鬼"
D.SharedStrings[16852]="生长催化剂"
D.SharedStrings[16853]="用250份阴燃精华为诺达希尔符文法杖充能，并获得烈焰之心。"
D.SharedStrings[16854]="用一把腐化的利刃打击一名敌人，造成暗影伤害。"
D.SharedStrings[16855]="用一次强力碾压攻击地面，对施法者前方锥形范围内的所有敌人造成物理伤害和昏迷效果。"
D.SharedStrings[16856]="用一股奥术能量轰击目标，造成{1}点奥术伤害。"
D.SharedStrings[16857]="用一股邪恶能量将你的目标拉到你面前。"
D.SharedStrings[16858]="用不稳定的邪能能量对你的武器进行强化。"
D.SharedStrings[16859]="用他的尾巴攻击目标敌人，造成物理伤害，并将目标击退。"
D.SharedStrings[16860]="用他的尾巴鞭笞5码范围内的所有敌人，造成物理伤害。"
D.SharedStrings[16861]="用他的长矛猛刺目标敌人，造成{1}%的武器伤害。"
D.SharedStrings[16862]="用任意武器进行疯狂打击。"
D.SharedStrings[16863]="用伊森德雷之泪封闭梦境之树的传送门。"
D.SharedStrings[16864]="用你的火鸡枪轰杀那些鬼鬼祟祟的潜行者。"
D.SharedStrings[16865]="用你的癫狂飞行器击落另一个名玩家的癫狂飞行器。"
D.SharedStrings[16866]="用你的锻造技能将钢铁打造成一把强大的锤子。需要铁砧。"
D.SharedStrings[16867]="用你的鱼抽打目标，造成{1}%武器伤害。"
D.SharedStrings[16868]="用公山羊打击者或公山羊打击者DX型，于1分钟内打击12只公山羊。"
D.SharedStrings[16869]="用共鸣奥术能量攻击一个敌人，造成奥术伤害并使目标受到的奥术伤害额外提高{1}%。"
D.SharedStrings[16870]="用冲击波对敌人造成伤害。"
D.SharedStrings[16871]="用利爪攻击目标敌人，造成{1}%的武器伤害，并将目标击退。"
D.SharedStrings[16872]="用力抓握附近的一个敌人。每秒对其造成{1}点物理伤害。"
D.SharedStrings[16873]="用发光的火炬点燃黑石深渊住宅区的8本暮光教义。"
D.SharedStrings[16874]="用夜之子魔刃从夜之子信使身上取得3叠信件。"
D.SharedStrings[16875]="用大炮发射救生火箭背包。让它们飞向热砂港幸存者！"
D.SharedStrings[16876]="用头撞击敌方目标，造成物理伤害，并将其击退。"
D.SharedStrings[16877]="用奥术能量制造一个猛烈的漩涡，对被卷入其中的所有敌人每秒造成{1}点奥术伤害。"
D.SharedStrings[16878]="用岩浆之拳打击敌人，造成火焰伤害，并在其位置制造一个火焰之池，每秒造成一次火焰伤害。"
D.SharedStrings[16879]="用巨大的战锤重击地面，形成一片邪能池，周期性造成火焰伤害。"
D.SharedStrings[16880]="用强风冲击一个目标敌人，造成{1}点自然伤害。"
D.SharedStrings[16881]="用强风冲击目标敌人，造成{1}点自然伤害。"
D.SharedStrings[16882]="用恐怖的煞能量将敌人震倒在地。"
D.SharedStrings[16883]="用恐惧震慑你自己，使你因恐惧而逃跑。"
D.SharedStrings[16884]="用抓钩将你拉向一名敌方目标。只能在霜火岭使用。"
D.SharedStrings[16885]="用散发浓重腥味的内脏包裹你，饥饿的长尾鲨无法抵抗它们的诱惑。"
D.SharedStrings[16886]="用暗影能量强化施法者的武器，每次攻击都会造成额外的暗影伤害。"
D.SharedStrings[16887]="用暗影魔法冲击敌人，对其造成{1}点暗影伤害。"
D.SharedStrings[16888]="用来从鲜血魔像的残骸中抽取意志残渣。"
D.SharedStrings[16889]="用某种失落的语言撰写的古老文字，刻在石头上。"
D.SharedStrings[16890]="用武器击打目标，造成{1}点伤害并打断施法。"
D.SharedStrings[16891]="用武器发动的近战攻击有一定几率使目标昏迷。"
D.SharedStrings[16892]="用气枪子弹击中目标。"
D.SharedStrings[16893]="用灼热的根须缠住敌人。"
D.SharedStrings[16894]="用烈焰灼烧地面。"
D.SharedStrings[16895]="用燧石手枪射击，造成物理伤害。"
D.SharedStrings[16896]="用狐狸粪和树叶遮盖住使用者。使其隐形匿踪。"
D.SharedStrings[16897]="用电能之拳打击敌人，造成自然伤害，并在其位置制造一个闪电之池，每秒造成一次自然伤害。"
D.SharedStrings[16898]="用皇冠古龙水瓶向10个人喷洒古龙水。"
D.SharedStrings[16899]="用盾牌猛击一个敌人，造成物理伤害并将其击退。"
D.SharedStrings[16900]="用矿渣冲击敌人，造成{1}点火焰伤害。"
D.SharedStrings[16901]="用神圣的力量强化武器，攻击和施法时有几率重击敌人，造成额外的神圣伤害。"
D.SharedStrings[16902]="用神殿老鼠喂饱了4只贝瑟克猎豹之后，击败高阶祭司基尔娜拉（英雄难度）。"
D.SharedStrings[16903]="用粘液覆盖目标，使其在水中的移动速度提高，但每秒钟会造成自然伤害。"
D.SharedStrings[16904]="用绘图桌来选择建造兽栏还是坦克工厂。"
D.SharedStrings[16905]="用背包里的能源核心来激活一个损坏的鸦人构装体。随后构装体会跟随你，并协助你作战。\r\n\r\n消耗一块能源核心。"
D.SharedStrings[16906]="用能量冲击目标，对其造成奥术伤害。"
D.SharedStrings[16907]="用能量冲击目标，造成奥术伤害。"
D.SharedStrings[16908]="用自由图腾在黑石深渊解放6名火焰卫士、火焰驱逐者或炽热火焰卫士的精华。"
D.SharedStrings[16909]="用虚空灌注的利爪发动攻击，使所有近战攻击造成暗影伤害。"
D.SharedStrings[16910]="用赞吉尔的传送门进入祖尔格拉布。$b$b假如你迷路了或者需要回到祖尔格拉布，去跟探险者协会挖掘场的梅维克交谈。"
D.SharedStrings[16911]="用迎头痛击打断敌人施法可重置猛虎之怒的冷却时间。"
D.SharedStrings[16912]="用这把结构原始的机关枪造成中等伤害。"
D.SharedStrings[16913]="用这根重组过的斗棍，我将挣脱我的束缚并且返回毒蛇神殿向瓦许和她的爪牙报仇!"
D.SharedStrings[16914]="用迷惑性的魔法将你包裹，变成夜之子的样子。\r\n\r\n只能在苏拉玛城中使用。"
D.SharedStrings[16915]="用速效毒药污染黑石深渊西区军营或东区军营的6份谷物军粮。"
D.SharedStrings[16916]="用邪火包围目标，使其造成的伤害提高{1}%。"
D.SharedStrings[16917]="用邪能猛击地面，使一条直线上的地面喷发出邪能喷泉。"
D.SharedStrings[16918]="用邪能闪电攻击附近的位置。"
D.SharedStrings[16919]="用邪能魔法束缚目标。"
D.SharedStrings[16920]="用锁链囚禁附近所有目标，使其无法移动。"
D.SharedStrings[16921]="用锁链困住附近所有目标，使其无法移动。"
D.SharedStrings[16922]="用锁链猛笞敌人，造成{1}点物理伤害，并将其拉到施法者身边。"
D.SharedStrings[16923]="用锁链锁住附近所有的目标，使其无法移动。"
D.SharedStrings[16924]="用锋利的爪子撕掠目标，造成物理伤害。"
D.SharedStrings[16925]="用闪电攻击目标，对其造成自然伤害。"
D.SharedStrings[16926]="用闪电魔法冲击敌人，对其造成{1}点自然伤害。"
D.SharedStrings[16927]="用雕像隐藏的圣光之力驱散一个虚空具象。"
D.SharedStrings[16928]="用音速之刃挥砍一个敌人，造成{1}%的武器伤害并打断其施法。"
D.SharedStrings[16929]="用魔法轰击敌人，造成奥术伤害。"
D.SharedStrings[16930]="用鲜血仓促写在一块碎布片上的求救信。"
D.SharedStrings[16931]="用黑暗能量打击敌人，造成暗影伤害，并在其位置制造一个暗影之池，每秒造成一次暗影伤害。"
D.SharedStrings[16932]="用黑暗能量进行打击，造成相当于{1}%武器伤害的暗影伤害。"
D.SharedStrings[16933]="由一只充气的猪膀胱外裹坚韧的牛皮制成。"
D.SharedStrings[16934]="由一只充气的科多兽膀胱外裹坚韧的斑马条纹皮革制成。"
D.SharedStrings[16935]="由于“一羽难求”已经被捕猎到了濒临绝种的地步，这种卡利鸟进化出了敏锐的感知力。"
D.SharedStrings[16936]="由于卓格巴尔的贪婪捕杀，至高岭鲑鱼很少能活这么久。"
D.SharedStrings[16937]="由于将力量借给弗蕾亚，长老变得筋疲力尽了。"
D.SharedStrings[16938]="由于时间的关系，我必须将能够集中你的法术并且召唤风之灵的物品给你。拿走这个图腾，当你准备好的时候，跟着我一起多练习。"
D.SharedStrings[16939]="由于煞魔的出现，这位受害者被他们突然爆发的情绪给压垮了。"
D.SharedStrings[16940]="由于相信自己被太阳抛弃了，这些被诅咒的鸦人更喜欢白天时躲藏在森林里或者遮阳棚下。鸦爪祭司则更进一步，从不将自己的脸暴露在太阳之下。他们终日戴着仪式面具，以帮助他们集中精神与安苏沟通。"
D.SharedStrings[16941]="由于逐日岛这段时间以来所发生的混乱和变故，我几乎完全没有时间来收回我散落在岛上的东西。现在我必须守在这里观察太阳之井，所以我想只能拜托你替我收回这些东西了。$B$B我需要我的占卜宝珠，我的天灾魔法卷轴，还有我的日记本。来，拿着这个小背包，我的东西实在是太多了，你可以把它们都装在这里面带回来。请一定要把它们带回来给我，我会给你一点小礼物以表达谢意的——另外，这个小背包你也可以留下！"
D.SharedStrings[16942]="由于长年从事剥皮工作，你变得非常敏捷灵巧，急速提高{1}点。"
D.SharedStrings[16943]="由内省中的玩家所释放出来的混合物会与腐蚀相连接，并试图变得越来越强大。"
D.SharedStrings[16944]="由區域觸發器兔子施放，強制玩家召喚載具兔子。"
D.SharedStrings[16945]="由授权法师为您定制的美味原创冰淇淋。"
D.SharedStrings[16946]="由楚伦娜搭载。"
D.SharedStrings[16947]="由艾格文设计的水晶，专门用于克制艾露尼斯的魔法。"
D.SharedStrings[16948]="由艾格文设计的水晶，专门用于克制艾露尼斯的魔法。\r\n"
D.SharedStrings[16949]="由见习草药师采集。"
D.SharedStrings[16950]="由邪能魔法铸造的结构对大多数伤害来源免疫。\r\n用邪能岩弹发动的地狱火射击可以穿透这个效果。"
D.SharedStrings[16951]="由黑暗收割议会强化过的放逐锁链，可以永久放逐一个恶魔。"
D.SharedStrings[16952]="甲虫恢复生命值，并对昏迷和限制移动的效果免疫。同时移动速度提高{1}%。"
D.SharedStrings[16953]="甲虫的召唤活动今天开始了。去安其拉之门跟你的阵营领袖谈一谈吧。"
D.SharedStrings[16954]="电流穿过最近的目标。"
D.SharedStrings[16955]="电能风暴包围目标，伤害所有处于暴风眼之外的盟友。电能风暴伤害会随时间提高。"
D.SharedStrings[16956]="电荷充能"
D.SharedStrings[16957]="电镀机械熊仔"
D.SharedStrings[16958]="电闪雷鸣……"
D.SharedStrings[16959]="男性暗夜精灵"
D.SharedStrings[16960]="男性维库人幻象"
D.SharedStrings[16961]="男爵夫人的信函"
D.SharedStrings[16962]="留下一道火焰。"
D.SharedStrings[16963]="留下一道燃烧的余烬，每秒造成{1}点火焰伤害。"
D.SharedStrings[16964]="留在灵魂医者的复活法术范围内等待复活。"
D.SharedStrings[16965]="當你突然消失時，我們還以為你遭到了不測。\r\n\r\n我不知該對你的冒險歷程作何感想…我需要時間來整理心情。\r\n\r\n不論如何，很高興你安然無恙地回來了。"
D.SharedStrings[16966]="畸体被摧毁之后，下一步棋就是要对付阿拉基本人，并取得一块他的护命匣碎片。他出没于城镇中心的喷泉附近，说不定你已经见过他了。$b$b带上我的手榴弹，它们对付不了阿拉基，但是要是他打算召唤骷髅，你可以把它们再炸回去。"
D.SharedStrings[16967]="畸变瘟疫蔓延到普崔塞德教授身上，之前的目标身上每有一层畸变瘟疫，现在就会为普崔塞德教授恢复{1}点生命值。"
D.SharedStrings[16968]="畸变的憎恶产生的疾病正在对周围的玩家造成伤害！"
D.SharedStrings[16969]="畸变苦难胸甲"
D.SharedStrings[16970]="畸形树人护腿"
D.SharedStrings[16971]="疑之煞淡出现实世界，免疫所有伤害并强迫所有敌人面对他们各自的疑惑。"
D.SharedStrings[16972]="疑虑从每个小孔滋生出来。"
D.SharedStrings[16973]="疫病使者基兹法克斯"
D.SharedStrings[16974]="疯狂之缘里有四名充满仇恨的灵魂：可怕的巨魔格里雷克被神剥夺了再生能力；战士雷纳塔基以热衷施虐而臭名昭著；先知哈扎拉尔整日被恐怖的未来预言所折磨；强大的战将乌苏雷则拥有号令风暴的力量。"
D.SharedStrings[16975]="疯狂冲击位于你前方的所有目标，将其击退并造成物理伤害。"
D.SharedStrings[16976]="疯狂旋转，对附近所有敌人造成物理伤害。"
D.SharedStrings[16977]="疯狂法师提尔希的魔精就在这根灵魂之杖里了。"
D.SharedStrings[16978]="疯狂测算手甲"
D.SharedStrings[16979]="疯狂的心能魔像"
D.SharedStrings[16980]="疯狂的猫咪女王（25人）"
D.SharedStrings[16981]="疯酒师的早餐"
D.SharedStrings[16982]="疲惫的卡拉波俘虏"
D.SharedStrings[16983]="疲惫的悼念者"
D.SharedStrings[16984]="疲惫的旅者，感谢你来到此地!请允许我自我介绍―我是奎恩提斯，一名德鲁伊，同时也是玛法里奥和塞纳里奥议会的身份低微的仆人。我和我的同伴(珊蒂斯.羽月将军和护国者―或许你听说过我们)想与你谈谈你为达纳苏斯的范达尔.鹿盔所做的事情。$B$B在进一步交谈之前，我想声明我们的谈话仅限于你我之间。如果你对此无异议的话，我们就可以开始了。"
D.SharedStrings[16985]="疲惫的祖鲁希德"
D.SharedStrings[16986]="疲惫的霜狼俘虏"
D.SharedStrings[16987]="疾速挥舞武器，在施法者面前一个锥形区域内造成物理伤害。"
D.SharedStrings[16988]="病人的血流尽之后就会死亡。"
D.SharedStrings[16989]="病木林深处就是纳克萨玛斯的宫殿入口。那儿的符文传送门被魔法结界笼罩，一般人是根本进不去的，不过现在不一样了。$B$B我们已经想出了破除结界的方法——奥术遮罩。我对肯瑞托古老的咒语进行了一些修改，使它具备了破除纳克萨玛斯结界的能力。我说过，这种咒语价格不菲，但是你对银色黎明的贡献是不可估量的！我们不会向你收取任何费用。"
D.SharedStrings[16990]="痛楚……迷惑……猜忌，这是一切的基石。"
D.SharedStrings[16991]="痛苦斗兽场：伊戈达斯！"
D.SharedStrings[16992]="痛苦的上层精灵"
D.SharedStrings[16993]="痛苦的土元素"
D.SharedStrings[16994]="痛苦的灵魂"
D.SharedStrings[16995]="痛苦的雏龙"
D.SharedStrings[16996]="瘟疫之锅的控制板仍然被牢牢地锁着。要想打开它，你就得先找到钥匙。"
D.SharedStrings[16997]="瘟疫使者帕斯图鲁斯"
D.SharedStrings[16998]="瘫痪。"
D.SharedStrings[16999]="瘫痪。任何伤害都会打断这个效果。"
D.SharedStrings[17000]="瘫痪，不能攻击或施法。生命值恢复速度提高。"
D.SharedStrings[17001]="瘫痪，不能攻击或施法。生命恢复速度提高。"
D.SharedStrings[17002]="白化小奇美拉"
D.SharedStrings[17003]="白色作战塔布羊"
D.SharedStrings[17004]="白色北极熊坐骑"
D.SharedStrings[17005]="白色原始迅猛龙"
D.SharedStrings[17006]="白色小食虱鸟"
D.SharedStrings[17007]="白色机械陆行鸟B型"
D.SharedStrings[17008]="白色淡水兽幼崽"
D.SharedStrings[17009]="白色骑乘塔布羊"
D.SharedStrings[17010]="白色骑乘骆驼"
D.SharedStrings[17011]="白色骷髅战马"
D.SharedStrings[17012]="白虎宗师"
D.SharedStrings[17013]="白虎弟子"
D.SharedStrings[17014]="白虎高手"
D.SharedStrings[17015]="白金圆盘完美无缺地勘合进控制台中。它开始旋转而白色的光束扫过圆盘。"
D.SharedStrings[17016]="白银之手"
D.SharedStrings[17017]="白银之手保卫者"
D.SharedStrings[17018]="白银之手十字军"
D.SharedStrings[17019]="白银之手圣殿骑士"
D.SharedStrings[17020]="白银之手持盾兵"
D.SharedStrings[17021]="白银之手新兵"
D.SharedStrings[17022]="白银之手方阵兵"
D.SharedStrings[17023]="白银之手治愈者"
D.SharedStrings[17024]="白银之手骑士"
D.SharedStrings[17025]="白银之手骑士团"
D.SharedStrings[17026]="白银保险箱"
D.SharedStrings[17027]="白银高阶卫士"
D.SharedStrings[17028]="白骨之庭的米斯希尔萨·阿奈尔要你去寻找一块染血的石头，并目睹王子的命运。"
D.SharedStrings[17029]="白骨庭院中的魔古族正在施法复活亡者之魂来扩充兵力。$B$B我们决不能任由他们让亡者士兵起死回生。$B$B带上这个火把，去超度你所找到的干尸遗骸。$B$B我们要在这些敌人复活之前先干掉他们。"
D.SharedStrings[17030]="白骨庭院里挤满了魔古族大军。他们正在那里肆无忌惮地施展召唤雷电的仪式。$B$B如果我们想要成功占领这座岛屿，就不能放任他们占据如此重要的战略位置。$B$B必须消灭他们。"
D.SharedStrings[17031]="白鬼爬行者"
D.SharedStrings[17032]="皂皂，砮皂的幼犊"
D.SharedStrings[17033]="皇冠药剂公司"
D.SharedStrings[17034]="皇冠药剂公司似乎正在制造某种合剂，而这就是其中一部分配方。其他部分应该就在附近。"
D.SharedStrings[17035]="皇冠药剂公司守卫发现了你！"
D.SharedStrings[17036]="皇家咒法师"
D.SharedStrings[17037]="皇家宰相佐尔洛克"
D.SharedStrings[17038]="皇家宰相佐尔洛克（英雄难度）"
D.SharedStrings[17039]="皇家恐怖卫士"
D.SharedStrings[17040]="皇家药剂师"
D.SharedStrings[17041]="皇家药剂师协会"
D.SharedStrings[17042]="皇帝的意志（英雄难度）"
D.SharedStrings[17043]="皮甲商"
D.SharedStrings[17044]="皮肤化为坚石，使最大生命值和当前生命值提高{1}%，并使受到的伤害降低{2}%。"
D.SharedStrings[17045]="盐目潮汐萨满"
D.SharedStrings[17046]="盐目钩刃战士"
D.SharedStrings[17047]="监工长石的出现会烧灼敌人，造成火焰伤害。"
D.SharedStrings[17048]="监护者吞噬它的幼仔，治疗自己，并打断了孵化的进程。"
D.SharedStrings[17049]="监督者埃卓凯丝"
D.SharedStrings[17050]="监视者维兹艾德姆"
D.SharedStrings[17051]="监视者维兹艾德姆开启一座恶魔之门，撤回到军团指挥舰上！"
D.SharedStrings[17052]="盖亚安祖母既是霜狼酋长杜隆坦的母亲，也是一位技术高超的治疗者。"
D.SharedStrings[17053]="盖有巴罗夫家族的印章。"
D.SharedStrings[17054]="盛满的绿色美酒节酒杯"
D.SharedStrings[17055]="盛满的蓝色美酒节酒杯"
D.SharedStrings[17056]="盛满的黄色美酒节酒杯"
D.SharedStrings[17057]="盛满食物的木桶"
D.SharedStrings[17058]="盛装打扮。"
D.SharedStrings[17059]="目前塞纳里奥要塞涌入了大量的新兵，我们的首要问题就成了如何保证他们在沙漠中生存下来。缺水的环境和遍布希利苏斯的剧毒生物都威胁着这些缺乏经验的志愿者。去收集一些必需的物资，把他们交给要塞里的卡兰德拉斯吧。"
D.SharedStrings[17060]="目前塞纳里奥要塞的骑兵团缺乏足够的毛皮护甲片，去收集大量护甲片，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。"
D.SharedStrings[17061]="目前正持有咬合的蟹爪。"
D.SharedStrings[17062]="目标已被冰冻。冰冻时无法进行任何动作，且受到的伤害提高{1}%。"
D.SharedStrings[17063]="目标成为一个恶魔。在变形时，恶魔能量会治疗施法者，并提高其所有攻击的爆击几率。"
D.SharedStrings[17064]="目标死亡"
D.SharedStrings[17065]="目标玩家从虚空中吸引碎石，每隔一段时间受到平台周围的碎石冲击。"
D.SharedStrings[17066]="目标的灵魂被从肉体剥离。"
D.SharedStrings[17067]="目标立刻化成一支暗影箭，传送到另一个地点，并让附近的敌人迷惑。"
D.SharedStrings[17068]="目标脚下的大地开始崩裂，潺潺流动的火屑每秒会对临近的所有玩家造成{1}点火焰伤害。"
D.SharedStrings[17069]="目标被裹进了炽热的蛛网！"
D.SharedStrings[17070]="目标被鼓舞。所有的近战和法术攻击都会治疗被鼓舞的目标，治疗量相当于伤害的{1}%。"
D.SharedStrings[17071]="目标：戈尔隆德"
D.SharedStrings[17072]="目送斥候离开，然后与卢山大哥谈一谈。"
D.SharedStrings[17073]="盲目冲突腿甲"
D.SharedStrings[17074]="盲目怒火重盔"
D.SharedStrings[17075]="盲目怨恨护腕"
D.SharedStrings[17076]="盲眼守卫奥杜"
D.SharedStrings[17077]="盲眼巨龙开始调节声波，造成{1}点暗影伤害，对声音越大的目标造成越多的额外伤害。"
D.SharedStrings[17078]="盲眼巨龙施放音波吐息，追踪他的目标。"
D.SharedStrings[17079]="盲眼猎手格罗亚特"
D.SharedStrings[17080]="盲眼者莱欧瑟拉斯"
D.SharedStrings[17081]="相位变换。"
D.SharedStrings[17082]="相当令人震惊，$N。如果换作从别人口中道出，我想我会认为他们疯了。"
D.SharedStrings[17083]="相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。"
D.SharedStrings[17084]="相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献已被记录下来。$B$B防卫者的徽记之戒将会在你对抗邪恶力量时提供更多的保护。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。"
D.SharedStrings[17085]="相比环扣和枷锁，食人魔更喜欢用坚固的石环来锁住奴隶。数百年来操纵土元素的经验让他们可以轻松地将镣铐缩小，紧紧扣住奴隶的脚踝、手腕或脖子。"
D.SharedStrings[17086]="相连一方所受到伤害的{1}%会反射给你。"
D.SharedStrings[17087]="盾牌冲锋"
D.SharedStrings[17088]="看似精致复杂的锁其实并没有锁上。"
D.SharedStrings[17089]="看來你已經控制住局面。我並不想…打擾你。\r\n\r\n又少了一個追求權力的貴族需要擔心。做得很好，$n。"
D.SharedStrings[17090]="看來你有找到倖存者。很好，這讓我放心不少。"
D.SharedStrings[17091]="看來惡魔獵人的擔憂絕非空穴來風。那些惡魔居然敢在國喪期間悄悄潛入我們的城鎮！\r\n\r\n這對部落而言可不是什麼好兆頭。"
D.SharedStrings[17092]="看來血石滿足了。做得好！測試的時候到了…"
D.SharedStrings[17093]="看來這招有用，羅盤指著河流的方向。\r\n\r\n這表示…？"
D.SharedStrings[17094]="看到别人看不到的东西！"
D.SharedStrings[17095]="看到红外线成像。"
D.SharedStrings[17096]="看到这些无用的精灵魔法让我更加的愤怒而这些愤怒也能让我获得更多的力量。$B$B再去多拿一些秘药来给我，你就能获得另一个野蛮护卫。"
D.SharedStrings[17097]="看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想象一下大自然、松鼠或是所有你们会喜欢的东西。"
D.SharedStrings[17098]="看守者希尔希克"
D.SharedStrings[17099]="看守者斯蒂沃特"
D.SharedStrings[17100]="看守者贝瓦里尔"
D.SharedStrings[17101]="看护者斯密瑟斯"
D.SharedStrings[17102]="看来……看来我们是别想在这层层叠叠的群山中找到一个合适的定居点了。$B$B相信我，我不是那种轻言放弃的人……但是被冻住的引擎、讨厌的维库女人、飞来飞去的恶龙和乱七八糟的其它怪物，换了是你，你能怎么办？$B$B不过，不要慌张！我只是说我们找不到一个合适的定居点，但这并不意味着我们不能送你一程……单线旅行总是很简单的。$B$B<莉吉特指了指附近的火箭。>"
D.SharedStrings[17103]="看来你刚热身完毕，$N.在我们为了参赛而加紧练习时，别忘了天灾军团还在外头肆虐着。"
D.SharedStrings[17104]="看来你已经变得非常强大，足以应对下一次军团的威胁。请尽快与达拉然的大法师茉德拉谈一谈。六人议会欠你一份情。"
D.SharedStrings[17105]="看来元素的力量破坏了这样物品，上面的文字已无法辨识。"
D.SharedStrings[17106]="看来赞吉尔前往祖尔格拉布的传送门还开着。祖尔格拉布是个危险的地方，但梅维克觉得你能胜任。$b$b传送门就在前面正等着你呢。"
D.SharedStrings[17107]="看来这附近的维库人喜欢用龙鳞来装饰护甲。$B$B如果你能从这里的幼龙身上收集足够的材料，或许可以做出一些有用的东西。"
D.SharedStrings[17108]="看来那些新教徒的数量又增加了。你知道该怎么做吧……$B$B新来的教徒在荒凉之门的南端接受训练。他们之中的绝大部分人应该都持有一件特殊的物品——幻象宝珠。$B$B这种宝珠可以用来伪装诅咒教徒，使他们能够安全地自由行动，渗透或是完全伪装成敌人的模样。$B$B去干掉那些蠢货，从他们身上收集幻象宝珠，然后对黑暗压制者使用它。"
D.SharedStrings[17109]="看样子你有足够的智慧和力量完成我的任务。这本帐簿的内容表明他正待在影牙城堡。所以我现在要派你去那里。$b$b我们已经向那里派了一个人，但他还没有取得任何进展。赶快行动。我们的侦查员会在那里和你碰头。记得带上你的朋友一起过去。"
D.SharedStrings[17110]="看看吧，$N。巫毒的力量更加强大了，不是吗?让原始的力量流遍你吧。"
D.SharedStrings[17111]="看看指南针指向哪里！"
D.SharedStrings[17112]="看管者索恩格林"
D.SharedStrings[17113]="看见别人无法看见的东西！"
D.SharedStrings[17114]="看起来你的传送重组矩阵与上一个使用传送器的人搞混了。"
D.SharedStrings[17115]="看起来像是个战歌兽人，闻起来也像是战歌兽人。"
D.SharedStrings[17116]="看起来光彩照人！"
D.SharedStrings[17117]="看起来异种蝎的意图，不——它们存在的原因，就是毁灭它们遇到的所有其它生物。它们的目标非常明确，也正是由于这个原因，它们成了对艾泽拉斯所有生物的巨大威胁。$B$B我们现在见到的仅仅是个开始，我怀疑它们的力量来自卡利姆多的腹地：安戈洛环形山。到塔纳利斯沙漠里的加基森镇去，跟炼金师匹斯特苏格谈一谈。把我的想法告诉他，他肯定会帮我们对抗异种蝎的。"
D.SharedStrings[17118]="看起来比利亚姆喝掉了一些奥能电浆。"
D.SharedStrings[17119]="看起来，这张被水浸透的纸上应该是记录着一种烈性酒的酿造配方。也许达拉然“再来一杯”的店主会对这个感兴趣……"
D.SharedStrings[17120]="看门者克里克希尔"
D.SharedStrings[17121]="真是…不容易…但我很高興我們成功了。"
D.SharedStrings[17122]="真是一場精采的冒險。我們現在總算有足夠的法力提供給難民了。謝謝你，$n。"
D.SharedStrings[17123]="真是了不起的发现，$N。我不能让你将它卖给别人，所以我会开出很高的价钱。"
D.SharedStrings[17124]="真是令人嘆為觀止，$n。\r\n\r\n蘇艾許將是我們未來有力的盟友。我會暫時注意著它。"
D.SharedStrings[17125]="真是太奇妙了！這絕對不是出自燃燒軍團之手。讓我仔細瞧瞧。"
D.SharedStrings[17126]="真是讓人生氣。好吧，至少她與生俱來的能力和我預估的差不多…"
D.SharedStrings[17127]="真是除草利器，嗯？哈哈！$B$B我猜你一定想要更多炸药，以备今后派上用场，所以我已经抄好了结构图，你可以自己制作了。$B$B我觉得，如果花草树木发了狂，就应该统统除掉。"
D.SharedStrings[17128]="真正的主人"
D.SharedStrings[17129]="真理守卫者中的能量在不安地颤动着。附近一定潜藏着什么邪恶的东西！"
D.SharedStrings[17130]="真理守卫者中的能量在不安地颤动着。附近一定潜藏着恶魔！"
D.SharedStrings[17131]="真理守护者"
D.SharedStrings[17132]="真理追寻者伊格瑞姆"
D.SharedStrings[17133]="真聪明啊……$b$b就在我们自以为已经控制了局面的时候，他们悄悄地在我们脚下挖出隧道，占领了圣殿！$b$b现在我们被两支蛛魔部队夹在中间，而且情况还在迅速恶化。$b$b我们的第一步行动是阻止他们的增援，封闭他们的隧道。$b$b拿着这些手雷，把它们扔到西北方的蛛魔隧道里去。"
D.SharedStrings[17134]="真言术：盾"
D.SharedStrings[17135]="真迷人。\r\n\r\n真希望這法術不會消散。"
D.SharedStrings[17136]="真高兴能再次见到朋友和亲人，不过也许我做得有些太夸张了……我已经吃光了他们为我准备的一切！$B$B能不能帮我一个忙，再给我拿来一些那种美味的悼念糕饼？我会非常感激你的……$B$B我想，那边的查普曼正在出售食谱。"
D.SharedStrings[17137]="眩晕。"
D.SharedStrings[17138]="眩晕。\r\n流血。"
D.SharedStrings[17139]="眩目之尘使你的命中率降低{1}%。"
D.SharedStrings[17140]="眼下，我们有了一个干扰赞达拉战争机器的机会，还能顺便给自己找点乐子。$b$b在这片兽栏中，有一头魔暴龙和一头恐角龙，它们都是全副武装，并且心智被赞达拉符咒所奴役。$b$b我要你潜入营地并干扰那里的任意一个束缚仪式。没有特定目标。你只要解决掉那些想要束缚这些野兽的家伙就行了。这能够让这些武装到牙齿的野兽发狂并肆虐赞达拉的营地。然后，我们只要坐着看热闹就行了。"
D.SharedStrings[17141]="眼棱射线轰击附近的区域，造成自然伤害。"
D.SharedStrings[17142]="着火了！"
D.SharedStrings[17143]="着魔的高阶侍女"
D.SharedStrings[17144]="着魔的魔导师"
D.SharedStrings[17145]="督军佐尔玛兹的钥匙"
D.SharedStrings[17146]="督军克罗格"
D.SharedStrings[17147]="督军卡利瑟里斯"
D.SharedStrings[17148]="督军帕杰什"
D.SharedStrings[17149]="督军扎伊拉"
D.SharedStrings[17150]="督军扎伊拉和加尔鲁什在暮光高地的事件期间形成了非常亲密的关系，且她和她的龙喉兽人承诺为加尔鲁什的事业效忠。骇人的迦拉卡斯是所有龙族灾变祖先的直系后裔，扎伊拉骑在它的背上，监管着奥格瑞玛的海防力量。"
D.SharedStrings[17151]="督军扎伊拉派出手下最精锐的龙喉士兵参战。两名守卫监视并保护着高处塔楼上的防空火炮。击败这些守卫可以让玩家获得防空火炮的控制权。\r\n\r\n两次时机恰到好处的火炮射击就可以击落迦拉卡斯。"
D.SharedStrings[17152]="督军托尔罗克"
D.SharedStrings[17153]="督军拉姆塔斯"
D.SharedStrings[17154]="督军的死亡之轮"
D.SharedStrings[17155]="督军达尔，三重血刃"
D.SharedStrings[17156]="睿智的厄索克子嗣，他们的话语解释了当前我们所见的一切。"
D.SharedStrings[17157]="睿智织雾者之灵"
D.SharedStrings[17158]="睿盖尔的无尽指环"
D.SharedStrings[17159]="睿盖尔的裂音之匕"
D.SharedStrings[17160]="瞄准目标射击，使远程伤害提高{1}点。"
D.SharedStrings[17161]="瞄准目标射击，造成大量额外伤害。"
D.SharedStrings[17162]="瞄准目标射击，造成相当于{1}%武器伤害的物理伤害。"
D.SharedStrings[17163]="瞧瞧这儿，真是一团糟！所有的酒都浪费了！$b$b祝踏岚警告我们说不要跟你们这些陌生人讲话，但眼下我也顾不了那么多了。$b$b当时我们正把酒送到晨芳园，结果半路上遇袭了。现在所有的酒都丢了！$b$b你想跟我们和解吗？那就帮我们找回一些还未破损的蜜酒酒桶吧，这样就能减少些损失了。"
D.SharedStrings[17164]="瞧，我知道在这种时候提这样的要求很过分，但我要你暂时从失败的悲伤中振作起来。$B$B我会照顾这些士兵，你得找到之前你所说克瓦迪尔将军在西边的战场。在那里，你能窥视到女武士更多的经历。我有种强烈的预感，那名女武士是我们打败纳迦的关键。$B$B请你赶快——我会尽我所能为你争取时间。"
D.SharedStrings[17165]="瞬发攻击，对一个敌人造成物理伤害。"
D.SharedStrings[17166]="瞬发攻击，造成{1}点物理伤害。"
D.SharedStrings[17167]="知己知彼"
D.SharedStrings[17168]="知识古树"
D.SharedStrings[17169]="知识就是力量"
D.SharedStrings[17170]="矮人劳工都被吓坏了，无法正常工作！"
D.SharedStrings[17171]="矮人建筑营地"
D.SharedStrings[17172]="矮人火炮陷阱的受害者。"
D.SharedStrings[17173]="矮人迫击炮小队工程师"
D.SharedStrings[17174]="石化古树的拇指"
D.SharedStrings[17175]="石头守卫斯托克顿"
D.SharedStrings[17176]="石头守卫（英雄难度）"
D.SharedStrings[17177]="石头终于安静了下来，但你却隐约感觉到了一股不安。有什么不对劲。$B$B也许你应该把目前的发现告诉斯奎尔图。"
D.SharedStrings[17178]="石树长老的精华使弗蕾亚造成的物理伤害提高{1}%。"
D.SharedStrings[17179]="石爪山战争古树"
D.SharedStrings[17180]="石爪山脉任务"
D.SharedStrings[17181]="石语者埃鲁纳克"
D.SharedStrings[17182]="石趾的磨难便鞋"
D.SharedStrings[17183]="码头管理员"
D.SharedStrings[17184]="砂槌食人魔法师"
D.SharedStrings[17185]="研究散发着浓浓香水味的守卫附近的空气。"
D.SharedStrings[17186]="砮皂考验着敌人的韧性，每层效果使对手的生命值提高{1}%，并使砮皂造成的伤害提高{2}%。"
D.SharedStrings[17187]="砰！对炮击地点周围半径12码范围内的所有敌人造成{1}点伤害。"
D.SharedStrings[17188]="破坏一块天灾水晶，将它送回它原本所在的世界。"
D.SharedStrings[17189]="破坏者吉普提拉克"
D.SharedStrings[17190]="破坏者奥科索尔"
D.SharedStrings[17191]="破坏钢铁部落的活动，并收集情报。"
D.SharedStrings[17192]="破坏魔女巫会"
D.SharedStrings[17193]="破坏魔毁灭者"
D.SharedStrings[17194]="破坏魔破坏者"
D.SharedStrings[17195]="破坏魔队长"
D.SharedStrings[17196]="破城者护腕"
D.SharedStrings[17197]="破天号上的萨萨里安希望你从奥尔杜萨的苦痛新兵身上夺取幻象宝珠，然后对那里的3名黑暗压制者使用。"
D.SharedStrings[17198]="破天号上的萨萨里安希望你前往奥尔杜萨，杀死升腾者奥鲁麦斯。"
D.SharedStrings[17199]="破天号上的萨萨里安希望你去收集5份黑暗物质，然后在奥尔杜萨召唤出一名黑暗信使。"
D.SharedStrings[17200]="破天号上的萨萨里安要你使用憎恶复活工具包制造一名复活的憎恶，然后利用它杀死15只冰寒食尸鬼、15只残忍的恶鬼和15名复活的联盟士兵。"
D.SharedStrings[17201]="破天号上的首席技师波尔维克要你在破碎前线使用偷来的液体。$B$B你需要收集被丢弃的头盔、被丢弃的护甲和一堆白骨才能召唤假人，这些材料都可以在破碎前线找到。"
D.SharedStrings[17202]="破损的土灵雕像"
D.SharedStrings[17203]="破桶而出的炎诛"
D.SharedStrings[17204]="破甲攻击"
D.SharedStrings[17205]="破碎命运印记物资"
D.SharedStrings[17206]="破碎地板对站在其中的所有敌人造成{1}点物理伤害，并击穿黑石铸造厂的地板，使得所有玩家跌落至地板下层。"
D.SharedStrings[17207]="破碎大地符文"
D.SharedStrings[17208]="破碎残阳基地的守备官夏安希望你将调和过的水晶核心放入5台被打败的奥术守卫体内，将它们转换成友军。"
D.SharedStrings[17209]="破碎残阳射手"
D.SharedStrings[17210]="破碎残阳战士"
D.SharedStrings[17211]="破碎残阳新兵"
D.SharedStrings[17212]="破碎海滩之战"
D.SharedStrings[17213]="破碎的奎尔德拉终于完整如初了，但如果不经过适当的锻打，你还无法使用它作战。它参差不齐的萨隆邪铁边缘仍然脆弱易碎。$B$B你可以在冰冠堡垒深处的灵魂洪炉对它进行深度锻造。把奎尔德拉带到噬魂者的住所去，找到那里的坩埚。将这把剑放进坩埚里，对它进行锻造，然后再回来见我。我会在冰封大殿等你。"
D.SharedStrings[17214]="破碎群岛上遍布着各种各样的势力。如果我们想要有机会战胜燃烧军团，就必须将他们联合起来。向他们证明你的价值，然后向我汇报。"
D.SharedStrings[17215]="破胆怒吼"
D.SharedStrings[17216]="破裂的物质位面让一部分暮光渗透了进来！"
D.SharedStrings[17217]="破译的暮光文件"
D.SharedStrings[17218]="砸开碎片，开启一道通往埃索达的传送门。\r\n\r\n只能在日歌农场使用。"
D.SharedStrings[17219]="砸开碎片，开启一道通往奥格瑞玛的传送门。\r\n\r\n只能在日歌农场使用。"
