D.SharedStrings[17221]="砸开碎片，开启一道通往暴风城的传送门。\r\n\r\n只能在日歌农场使用。"
D.SharedStrings[17222]="砸开碎片，开启一道通往达纳苏斯的传送门。\r\n\r\n只能在日歌农场使用。"
D.SharedStrings[17223]="砸开碎片，开启一道通往铁炉堡的传送门。\r\n\r\n只能在日歌农场使用。"
