D.SharedStrings[17233]="碎手争斗者"
D.SharedStrings[17234]="碎手兽人会在战斗中通过自残来庆祝胜利。他们最勇猛的战士身上总是伤痕累累。随着年岁的增长，人们就更难分清这些疤痕到底是敌人留下的，还是获得胜利的兽人自己留下的。"
