D.SharedStrings[17236]="碎木岗哨守卫"
D.SharedStrings[17237]="碎潮者阿奎里斯"
D.SharedStrings[17238]="碎片跳动着，透露出不祥的征兆。难道其中蕴含着冰霜领主的精华？"
D.SharedStrings[17239]="碎裂的艾鲁恩防护水晶"
