D.SharedStrings[17244]="碎银矿脉荣誉击杀"
D.SharedStrings[17245]="碎颅者发出怒吼，致使先前被弧形冲击命中过的区域发生爆炸，对区域内的所有敌人造成{1}点物理伤害。"
