D.SharedStrings[17257]="磁力装置拉杆"
D.SharedStrings[17258]="磁铁的原理是什么呢？"
D.SharedStrings[17259]="磨利的海象人鱼叉"
D.SharedStrings[17260]="磨难碎片的效果持续不断，受到的法术伤害提高{1}%，造成的治疗效果降低{2}%。"
D.SharedStrings[17261]="磨魂者传送门"
D.SharedStrings[17262]="礼物，礼物，礼物……啊，呸！$B$B这些地精玷污了冬幕节的真正含义。这是个新旧更替的时节；大地在冬天爷爷降下的皑皑白雪下沉睡，冬天爷爷可不是那个身着红衣装模作样的傻子！$B$B如果你想亲自了解冬幕节，就去询问探险者协会的史学家卡尼克吧。有人关心历史胜过关心礼物，我想他一定会很惊讶的。"
D.SharedStrings[17263]="祈求者之路"
D.SharedStrings[17264]="祈求贝瑟克的祝福，使附近所有盟友造成的伤害提高{1}%。"
D.SharedStrings[17265]="祖嘎克·毒魔应该对这疯狂的局面负责。$b$b他玷污了这座神殿，是时候终结他的恐怖统治了。"
D.SharedStrings[17266]="祖尔格拉布只在英雄难度下开放。"
D.SharedStrings[17267]="祖尔法拉克"
D.SharedStrings[17268]="祖尔法拉克僵尸"
D.SharedStrings[17269]="祖穆拉恩结界"
