D.SharedStrings[17273]="祝你有个美好的一天，$N，很高兴和你做生意。"
D.SharedStrings[17274]="祝踏岚"
D.SharedStrings[17275]="祝踏岚会偶尔发动一次偷袭，使附近的敌人昏迷，并使其承受的伤害提高，持续12秒。"
D.SharedStrings[17276]="祝踏岚带领着影踪派努力保护潘达利亚不受煞的侵害，他是一名技艺非凡的勇士，也是一位无畏的领袖。"
D.SharedStrings[17277]="祝踏岚是速度、敏捷与力量的大师。"
D.SharedStrings[17278]="神准冲击造成的伤害提高{1}%。"
D.SharedStrings[17279]="神器 - 野兽控制猎人哈提显示资料"
D.SharedStrings[17280]="神圣法术强度提高{1}点。"
