D.SharedStrings[17300]="神话守卫"
D.SharedStrings[17301]="神谕之树、大德鲁伊和德鲁伊们一起密切关注着泰达希尔的成长。但是虽然我们有了一个新家，但我们还没有重新得到不朽的生命。"
