D.SharedStrings[17303]="神谕者莱萨斯"
D.SharedStrings[17304]="神鹤派宗师"
D.SharedStrings[17305]="神龙，迷雾之杖"
D.SharedStrings[17306]="祭坛的原貌已经无法辨认，但它现在的主人却无庸置疑…"
D.SharedStrings[17307]="祭坛：光明使者的荣耀"
D.SharedStrings[17308]="祭拜东部王国的火焰。"
D.SharedStrings[17309]="祭拜卡利姆多的火焰。"
