D.SharedStrings[17322]="科林·桑德玛尔"
D.SharedStrings[17323]="科沃克跳向目标所在位置，落地时消灭掉附近的敌人。"
D.SharedStrings[17324]="科沃斯向附近的敌人位置召唤一阵腐臭蜂群。"
