D.SharedStrings[17345]="科隆加恩用力挤压目标，造成{1}点物理伤害。"
D.SharedStrings[17346]="科雷萨又被称为恐惧之门，它是挡在我们与冰冠堡垒之间的最后一道屏障。它位于铁墙壁垒的南方，要越过冰川和战火平原才能抵达。当我们的部队开进那里以后，他们可能会遭到严重减员，甚至更糟。$B$B我们一定要削弱科雷萨的防御力量，不然我们的部队只会在它的城墙上撞得头破血流。$B$B科雷萨的城头上布署着巫妖王手下最凶狠、最狂热的仆从。你要尽量消灭这些守卫，希望这么做能有点用。"
