D.SharedStrings[17434]="穿上一件伪装大氅。它只会影响现有披风的外形，而不会影响属性和效果。"
D.SharedStrings[17435]="穿上一件附有魔法效果的夺日者战袍。这件伪装服只能在达拉然使用。"
