D.SharedStrings[17437]="穿上你最好的节日套装……直到它消失为止。"
D.SharedStrings[17438]="穿上兽人衣着。"
D.SharedStrings[17439]="穿上竞争者的服装，使你可以使用特殊技能攻击其它竞争者。\r\n\r\n一旦装备，受到的治疗效果会降低100%。"
D.SharedStrings[17440]="穿刺一个敌人，造成物理伤害，并将单元击退。"
D.SharedStrings[17441]="穿刺一条魔枢雏龙，使其沾染红龙之血，在25秒后被驯服。"
D.SharedStrings[17442]="穿刺投掷命中残骸堆后，会立即将其摧毁。"
D.SharedStrings[17443]="穿刺护甲"
D.SharedStrings[17444]="穿刺泰罗克前方一条直线上的敌人，造成大量伤害。"
D.SharedStrings[17445]="穿戴上卡拉波仪式长袍。"
D.SharedStrings[17446]="穿戴好你的超酷派对套装（亮闪闪的珠宝、潮人装束和清爽遮阳镜），然后前往在卡亚罗贸易公司总部泳池边举行的聚会，款待10位科赞聚会者。"
D.SharedStrings[17447]="穿戴萨格雷伪装。"
D.SharedStrings[17448]="穿林过险如履平地"
D.SharedStrings[17449]="穿着3件美酒节服装，喝个烂醉如泥，在达拉然跳舞。"
D.SharedStrings[17450]="穿着全套仲夏火焰节套装，在彩带杆旁跳舞60秒。"
D.SharedStrings[17451]="穿着感恩者的裙子、长袍或是外衣中的任意一件，在每个敌对主城的盛宴餐桌旁坐下。"
D.SharedStrings[17452]="穿着白色礼服衬衣和黑色礼服短裤，亲吻一个穿着端庄的裙子的人。"
D.SharedStrings[17453]="穿越敌人的传送门"
D.SharedStrings[17454]="穿越时空的束缚，突然出现在你的敌人身后。"
D.SharedStrings[17455]="穿越时空，帮助克罗米阻止对她的刺杀！前往诺森德的龙眠神殿开启你们的冒险之旅。"
D.SharedStrings[17456]="穿越某些邪能壁垒或结节时变得容易多了。"
D.SharedStrings[17457]="穿过一条直线上的敌人，造成{1}点冰霜伤害，并将其击退。"
D.SharedStrings[17458]="穿过位于海加尔山烈焰之痕中心的火焰之门。跟里面的法登·爪击谈一谈。"
D.SharedStrings[17459]="穿过暗影，在40码范围内的敌人之间来回穿梭，每0.5秒攻击一个敌人。"
D.SharedStrings[17460]="穿过海加尔山闪电崖上的火焰之门，跟里面的乔丹·奥拉夫森谈一谈。"
D.SharedStrings[17461]="穿过被召唤单位的链接将造成暗影伤害。"
D.SharedStrings[17462]="穿过赞吉尔的传送门。$b$b假如你迷路了或者需要回到祖尔格拉布，去跟探险者协会挖掘场的梅维克交谈。"
