D.SharedStrings[17663]="第一个试炼是要搜寻月神湖底的神殿灵珠。它会很快地腐烂，因此你要在找到它后立即把它拿到雷姆洛斯神殿去。在神殿里使用它，然后跟塔加里谈谈，她是月光林地里最值得信赖的守卫之一。$B$B你的时间非常紧迫，而且还要与其他寻找灵珠的德鲁伊竞争，灵敏和智慧是你取胜的关键。$B$B祝你好运，$n。"
D.SharedStrings[17664]="第一次尝试时即成功击败烈焰巨兽，并且没有队友修理坦克（10人）。"
D.SharedStrings[17665]="第一次尝试时即成功击败烈焰巨兽，并且没有队友修理坦克（25人）。"
D.SharedStrings[17666]="第一阶段：巨兽二型"
D.SharedStrings[17667]="第一阶段：把她打下来！"
D.SharedStrings[17668]="第一阶段：特攻部队"
D.SharedStrings[17669]="第一阶段：长者议会"
D.SharedStrings[17670]="第七军团"
D.SharedStrings[17671]="第七军团伞兵"
D.SharedStrings[17672]="第七军团勇士"
D.SharedStrings[17673]="第七军团斥候"
D.SharedStrings[17674]="第七军团潜水员"
D.SharedStrings[17675]="第七军团突击队"
D.SharedStrings[17676]="第七军团龙骑兵"
D.SharedStrings[17677]="第三章：焦木仪式"
D.SharedStrings[17678]="第三阶段：主人的力量"
D.SharedStrings[17679]="第三阶段：奥术大师"
D.SharedStrings[17680]="第三阶段：扭曲虚空"
D.SharedStrings[17681]="第三阶段：死亡的真正面貌"
D.SharedStrings[17682]="第三阶段：空中指挥单位"
D.SharedStrings[17683]="第三阶段：还有更多的人会像你一样倒下！"
D.SharedStrings[17684]="第二个守护者倒在地上之后，一口箱子出现在屋子后面。莫非这就是它们在保护的东西？"
D.SharedStrings[17685]="第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。$B$B与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。"
D.SharedStrings[17686]="第二次兽人战争的结局"
D.SharedStrings[17687]="第二章：拉希奥的战争"
D.SharedStrings[17688]="第二阶段：VX-001"
D.SharedStrings[17689]="第二阶段：燃烧的鬼群"
D.SharedStrings[17690]="第二阶段：萨弗拉斯将成为你的末日！"
D.SharedStrings[17691]="第二阶段：迦拉卡斯，末裔"
D.SharedStrings[17692]="第二阶段：领教贝瑟克的真正威力吧！"
D.SharedStrings[17693]="第四章：黑暗化身"
D.SharedStrings[17694]="笼中的双头飞龙"
D.SharedStrings[17695]="等到你的侍从休息充分再给他指派下一个任务。"
D.SharedStrings[17696]="等到我這裡的工作完成後，請你帶我去找薩莉瑟拉。"
D.SharedStrings[17697]="等待瑞亚从隐藏的龙巢中把蛋拿回来。"
D.SharedStrings[17698]="等有更多果實成熟時，我會再度請你幫忙。\r\n\r\n現在，我們需要討論令人不安的消息。"
D.SharedStrings[17699]="等级 1"
D.SharedStrings[17700]="等级 2"
D.SharedStrings[17701]="等级 3"
D.SharedStrings[17702]="等级 4"
D.SharedStrings[17703]="等级 6"
D.SharedStrings[17704]="简直太有型了，真不敢相信这是从桶里翻出来的！"
D.SharedStrings[17705]="管理者埃克索图斯"
D.SharedStrings[17706]="管理者鹿盔"
D.SharedStrings[17707]="箭矢从天花板射下，对触发地砖上的所有敌人造成{1}点物理伤害。"
D.SharedStrings[17708]="箱子几经偷盗、买卖和追寻。凡是打算解开其中封存的魔法之人，都遭到了其力量的反噬。$B$B饶是如此，箱子本身还是毫发未伤，充盈着魔法能量。偶尔，它还会震动一两下子，仿佛其中装着什么活物一般。$B$B貌似它已经同你绑定在了一起，如今是你的东西了。"
D.SharedStrings[17709]="箱子周围打有透气孔，搬运时会咯咯作响。"
D.SharedStrings[17710]="箱子里有各种小玩意，里面藏着一枚刻有独特纹章的玺戒。$B$B这枚戒指由一种坚不可摧的银质金属打造，但是由于主人常年佩戴，加上不经意的扭动和摩擦而留下了痕迹。"
D.SharedStrings[17711]="米克哈尔的日记"
D.SharedStrings[17712]="米妮瓦·悲鸦"
D.SharedStrings[17713]="米妮瓦·悲鸦有几率出现，对附近的所有敌人造成大量伤害。"
D.SharedStrings[17714]="米尔菲丝·法力风暴"
D.SharedStrings[17715]="米尔豪斯·法力风暴"
D.SharedStrings[17716]="米尔豪斯·法力风暴的影像"
D.SharedStrings[17717]="米尼格布·魔爆把你变成了绵羊！无法在绵羊状态下施法。右键点击此图标可以取消这个效果。"
D.SharedStrings[17718]="米希卡"
D.SharedStrings[17719]="米拉娜·星光"
D.SharedStrings[17720]="米斯希尔萨·阿奈尔"
D.SharedStrings[17721]="米斯希尔萨·阿奈尔要你收集3份无面者之血。"
D.SharedStrings[17722]="米米尔隆"
D.SharedStrings[17723]="米米尔隆之愚号"
D.SharedStrings[17724]="米米尔隆是个聪明的家伙，他给自己的地盘装上了一套自毁装置。$B$B很不幸，如果你想要拿到徽记，就必须争分夺秒。如果你需要了解什么详细的资料，可以去档案馆控制台那里查询。"
D.SharedStrings[17725]="米米尔隆的头部"
D.SharedStrings[17726]="米米尔隆的影像"
D.SharedStrings[17727]="米米尔隆的徽记"
D.SharedStrings[17728]="米莉安·唤法者"
D.SharedStrings[17729]="米莎的基础攻击会为其恢复{1}%的最大生命值。"
D.SharedStrings[17730]="米露恩有时出现，演奏林地之歌，召唤精灵龙协助你作战。"
D.SharedStrings[17731]="米露恩的召唤。"
D.SharedStrings[17732]="粉碎冷却的魔像，对附近的敌人造成{1}点伤害。"
D.SharedStrings[17733]="粉碎周围的天灾部队。"
D.SharedStrings[17734]="粉碎所有变成石头的敌人，并让它们旁边的敌人也受到伤害，伤害严重程度因为这些敌人距离石头的远近而有所不同。"
D.SharedStrings[17735]="粉碎皇冠药剂公司"
D.SharedStrings[17736]="粉碎者据点卫士"
D.SharedStrings[17737]="粗暴的开始"
D.SharedStrings[17738]="粗麻小径组织者"
D.SharedStrings[17739]="粘性毒素正在变硬，叠加3次后将会变得粘稠。\r\n移动将会破坏毒素使其无法完全变稠。"
D.SharedStrings[17740]="精制恐怖角斗士的活跃护腕"
D.SharedStrings[17741]="精制恶毒角斗士的冥想之靴"
D.SharedStrings[17742]="精制恶毒角斗士的活跃护足"
D.SharedStrings[17743]="精制恶毒角斗士的顽强勋章"
D.SharedStrings[17744]="精密切割手套"
D.SharedStrings[17745]="精心包裹的礼物"
D.SharedStrings[17746]="精心打造，适用于各种杯型，覆着冰冷的涂饰。"
D.SharedStrings[17747]="精心提炼，供战争中使用。"
D.SharedStrings[17748]="精灵龙灵魂精华"
D.SharedStrings[17749]="精美的战斗号角"
D.SharedStrings[17750]="精英亡灵卫兵"
D.SharedStrings[17751]="精通提高{1}。"
D.SharedStrings[17752]="精通提高{1}点。"
D.SharedStrings[17753]="精通等级提高{1}。"
D.SharedStrings[17754]="精锐征服军需官"
D.SharedStrings[17755]="精锐护甲军需官"
D.SharedStrings[17756]="精锐竞技场商人"
D.SharedStrings[17757]="糟糕的万圣节"
D.SharedStrings[17758]="索克的尾巴尖"
D.SharedStrings[17759]="索克的酸蚀之牙"
D.SharedStrings[17760]="索兰尼亚的物品"
D.SharedStrings[17761]="索利达尔，群星之怒"
D.SharedStrings[17762]="索基佐格将军"
D.SharedStrings[17763]="索基佐格将军跟其他食人魔一起待在火腹熔炉，他就在巨槌石西部边缘的洞穴里。我要你将这件货物交到他和食人魔手中。$b$b包裹里是你找来的新鲜狼肉，浸泡在我们从风暴祭坛取回的魔能泻药中。$b$b如果我是你的话，就绝不会碰这玩意儿。$b$b将它交给索基佐格将军。他一定会让食人魔饱餐一顿的；幸运的话，他自己也会来上一口。"
D.SharedStrings[17764]="索姆瓦尔猎手"
D.SharedStrings[17765]="索拉斯·托尔贝恩"
D.SharedStrings[17766]="索拉斯·托尔贝恩国王"
D.SharedStrings[17767]="索拉查盆地"
D.SharedStrings[17768]="索拉纳·血怒"
D.SharedStrings[17769]="索朗格斯的指节"
D.SharedStrings[17770]="索林·法师之手"
D.SharedStrings[17771]="索瓦尔勋爵"
D.SharedStrings[17772]="索罗夫的宝藏"
D.SharedStrings[17773]="索迪尔的火葬柴堆"
D.SharedStrings[17774]="紧急无坡道离船装置"
D.SharedStrings[17775]="紧急灭火机器人"
D.SharedStrings[17776]="紧急警告"
D.SharedStrings[17777]="紧盯一个目标，只对其进行攻击，直至将其杀死或失去目标。"
D.SharedStrings[17778]="紫罗兰之眼的荣耀"
D.SharedStrings[17779]="紫罗兰徽记"
D.SharedStrings[17780]="紫罗兰监狱"
D.SharedStrings[17781]="紫罗兰监狱中关押着巫妖王手下的数名大将，而燃烧军团的爪牙很可能已经大量潜入。我们必须到那里去阻止恶魔放出任何囚犯。"
D.SharedStrings[17782]="紫罗兰监狱卫兵"
D.SharedStrings[17783]="紫罗兰监狱的防御系统对非法入侵的生命体造成{1}点奥术伤害。"
D.SharedStrings[17784]="紫罗兰监狱：进入紫罗兰监狱"
D.SharedStrings[17785]="紫罗兰高地农夫"
D.SharedStrings[17786]="紫色机械陆行鸟"
D.SharedStrings[17787]="紫色骑乘虚空鳐"
D.SharedStrings[17788]="紫色骷髅战马"
D.SharedStrings[17789]="終於被人從這個可怕的牢籠中放出來了，太好了。作為回報，我會遵守對你和你古怪的多毛朋友所做的的承諾。"
D.SharedStrings[17790]="終於，我們失落已久的同胞總算能重回這個世界了。精靈的歸屬，是燦爛的星空，而非虛假的幻象。\r\n\r\n感謝你，$n。"
D.SharedStrings[17791]="總算可稍稍鬆一口氣。你做得很好，可以稍微休息一下。"
D.SharedStrings[17792]="纠缠根须"
D.SharedStrings[17793]="红宝石之种的魔力使幼龙重归大地，并用它的精华使大地得到滋养……"
D.SharedStrings[17794]="红猎犬反冲火箭运载器"
D.SharedStrings[17795]="红玉守护者"
D.SharedStrings[17796]="红色其拉作战坦克"
D.SharedStrings[17797]="红色原始迅猛龙"
D.SharedStrings[17798]="红色幼龙喷出一道火墙，造成火焰伤害。"
D.SharedStrings[17799]="红色幼龙喷射出烈焰之墙，造成火焰伤害。"
D.SharedStrings[17800]="红色影踪派骑乘虎"
D.SharedStrings[17801]="红色机械陆行鸟"
D.SharedStrings[17802]="红色装甲龙鹰"
D.SharedStrings[17803]="红色骑乘虚空鳐"
D.SharedStrings[17804]="红色骷髅战马"
D.SharedStrings[17805]="红色骸骨军马"
D.SharedStrings[17806]="红色龙鹰幼崽"
D.SharedStrings[17807]="红蓝两色机械陆行鸟"
D.SharedStrings[17808]="约书亚·阿维利"
D.SharedStrings[17809]="约尔兰·图布雷"
D.SharedStrings[17810]="约格莫夫·冰锤中尉"
D.SharedStrings[17811]="约翰·J·基沙恩"
D.SharedStrings[17812]="纪元之石磨成的沙粒永无止尽地从一头流向另一头，即不满溢，也不会枯竭。"
D.SharedStrings[17813]="纪念在对抗伊利丹·怒风的战争中取得的胜利。"
D.SharedStrings[17814]="纯净之光发现了你内心的勇气，形成了一堵墙来保护你和你的盟友。"
D.SharedStrings[17815]="纯净暗影水晶"
D.SharedStrings[17816]="纯净曙光猫眼石"
D.SharedStrings[17817]="纯心蟋蟀罐"
D.SharedStrings[17818]="纯洁的凯瑟琳"
D.SharedStrings[17819]="纯洁者耶德瑞克"
D.SharedStrings[17820]="纳克拉尔·掠爪"
D.SharedStrings[17821]="纳兹亚的三叉戟"
D.SharedStrings[17822]="纳兹夏尔入侵者"
D.SharedStrings[17823]="纳兹夏尔女士"
D.SharedStrings[17824]="纳兹夏尔女武士"
D.SharedStrings[17825]="纳兹夏尔愈灵者"
D.SharedStrings[17826]="纳兹夏尔毒蛇守卫"
D.SharedStrings[17827]="纳兹夏尔荣誉守卫"
D.SharedStrings[17828]="纳兹夏尔风暴女巫"
D.SharedStrings[17829]="纳兹戈林"
D.SharedStrings[17830]="纳兹戈林将军"
D.SharedStrings[17831]="纳兹戈林将军苏醒了"
D.SharedStrings[17832]="纳兹戈林的信号枪"
D.SharedStrings[17833]="纳兹戈林的切腹之匕"
D.SharedStrings[17834]="纳兹戈林的抛光勋章"
D.SharedStrings[17835]="纳兹格雷尔"
D.SharedStrings[17836]="纳多克斯长老"
D.SharedStrings[17837]="纳拉雷克斯"
D.SharedStrings[17838]="纳拉雷克斯的信徒"
D.SharedStrings[17839]="纳撒尼尔·比斯贝克"
D.SharedStrings[17840]="纳斯拉克森末日使徒"
D.SharedStrings[17841]="纳斯拉克森末日射手"
D.SharedStrings[17842]="纳斯拉克森裂肉者"
D.SharedStrings[17843]="纳斯拉克森裂隙"
D.SharedStrings[17844]="纳格兰大满贯"
D.SharedStrings[17845]="纳格兰的战歌氏族可跻身德拉诺最优秀的猎人的行列，他们的狩猎者可以帮我们为这批坐骑提供试炼。$B$B你能在纳格兰找到一位名叫狩猎大师卡拉克的兽人，死在他手上的凶残动物的数量是他们整个氏族里最多的。骑上你的坐骑去干掉他，为那些被杀害的动物报仇。"
D.SharedStrings[17846]="纳格兰的战火"
D.SharedStrings[17847]="纳格兰的风鹏是一种非常聪明的捕食者，它们经常成群结队地突袭猎物。要是你的坐骑不时刻注意着天空的话，就可得跟它这双眼睛说再见了。$B$B去纳格兰干掉那里最凶猛的风鹏——暗翼大鹏。这对你们俩来说都是个试炼。"
D.SharedStrings[17848]="纳格兰的风鹏是一种非常聪明的捕食者，它们经常成群结队地突袭猎物。要是你的坐骑不时刻注意着天空的话，就可得跟它这双眼睛说再见了。$B$B去纳格兰干掉那里最凶猛的风鹏——暗翼大鹏。这对你的坐骑来说是个不错的试炼。"
