D.SharedStrings[17872]="终于!$B$B挣脱了这些束缚，斗棍也重回我的身边，我就可以把那个深海女巫送回冰冷的深渊去…"
D.SharedStrings[17873]="终于有重大突破了！我们的僵尸样本在天灾的影响下产生了新的特性，并结出了丰硕的果实……$B$B把这只盒子带到奥格瑞玛去。里面是一枚带有僵尸疫病的徽记，上面还有我们添加的其它东西——一种反药剂。这两种将在徽记上相互作用，而我敢肯定，这枚徽记就是治愈疫病的关键。$B$B把这只盒子交给我的助手，药剂师卡尔洛夫。他就在奥格瑞玛的萨尔酋长身边。"
