D.SharedStrings[17990]="美酒节除了赛羊会外，还有一项传统，那就是饮酒狂欢！如果你有时间的话，就将这张礼品券交给贝尔比吧。她就在美酒节营地的后面。要是你看不见她，没关系，她一定会看见你的。$B$B无论如何，将礼品券交给她，你就能免费领到一只美酒节酒杯。她还出售各种美酒哦。"
