D.SharedStrings[18019]="考古学训练师"
D.SharedStrings[18020]="考尔曼大胆地穿越黑暗之门寻找正义与荣耀。但不幸的是，他被敌人俘虏并失去了信念，被关押在血槌炉渣矿井里。救出考尔曼后，他内心对救赎的渴望被重新点燃。"
D.SharedStrings[18021]="考瓦斯·血棘"
D.SharedStrings[18022]="考虑到你如此忠心地为我服务，我在此赦免你的罪孽。带上它，从我的眼前消失吧。告诉你的人民，过去的事情既往不咎。$B$B$n，别让我再看见你，否则我会杀了你。"
D.SharedStrings[18023]="考达拉魔枢上层的科拉丝塔萨要你骑着她的幼龙杀死5名鳞誓精英。"
D.SharedStrings[18024]="考里格·斯托克顿"
D.SharedStrings[18025]="耐力提高{1}%。"
D.SharedStrings[18026]="耐力提高{1}点。"
D.SharedStrings[18027]="耐力提高{1}点。该效果等同于守护药剂。"
D.SharedStrings[18028]="耐力降低{1}%。"
D.SharedStrings[18029]="耐力降低{1}点。"
D.SharedStrings[18030]="耐奥祖麾下的一名副官就在前方。经过他之后再走几步就是洞穴的出口。$b$b我要回去告诉卡德加，洞穴已经清理干净了。等你解决掉克里丹后，我们再会合！"
