D.SharedStrings[18048]="联盟布匹军需官"
D.SharedStrings[18049]="联盟徽记"
D.SharedStrings[18050]="联盟战地指挥官"
D.SharedStrings[18051]="联盟拒绝从阿什兰撤退。告诉他们，部落绝不会袖手旁观，眼看他们掠夺古代食人魔帝国的力量为他们所用的。"
D.SharedStrings[18052]="联盟控制。"
D.SharedStrings[18053]="联盟控制着滩头。你在暮光海岸战斗的时候，攻击和法术强度都会增强。"
D.SharedStrings[18054]="联盟新兵"
D.SharedStrings[18055]="联盟旗帜"
D.SharedStrings[18056]="联盟步兵"
D.SharedStrings[18057]="联盟真是个阴险的敌人，$n。他们张口闭口说在保护灰谷的森林，以此证明他们对我们贫瘠之地领土的进攻行动是正当的。$B$B今天，我们有机会把敌人彻底赶出部落的领土。去战歌峡谷，夺回一切本属于我们的东西！"
D.SharedStrings[18058]="联盟队长"
D.SharedStrings[18059]="联盟需要你的帮助！"
D.SharedStrings[18060]="聚众闹事（第2赛季）"
D.SharedStrings[18061]="聚焦之虹的钥匙"
D.SharedStrings[18062]="聚焦水晶"
D.SharedStrings[18063]="聚焦水晶已经制作完成了，$n。等你做好准备，我就会用它粉碎凯尔娜拉的护盾。$b$b但是，在矿场里和她交手太不安全了。只要她的护盾一失效，我就会把我们传送到尤鲁恩矿场外面的安全地点。当她远离水晶时就好对付得多了。$b$b等你准备好开始时就来与我交谈吧。"
D.SharedStrings[18064]="聚焦魔法能量，并用来冲击空中的敌人。"
D.SharedStrings[18065]="聚集真气能量，然后将其投向一个生命值较高的敌方目标。"
D.SharedStrings[18066]="聪明的阿西约"
D.SharedStrings[18067]="肉弹被饥饿驱使，狂暴地攻击撕咬目标。目标会变成一堆乱七八糟的骨头。"
D.SharedStrings[18068]="肮脏的希尔盖"
