D.SharedStrings[18081]="胆汁喷洒机因为系统崩溃而离线了。现在它正尝试通过替代系统重新进行能量连接。"
D.SharedStrings[18082]="背包商人"
D.SharedStrings[18083]="背叛……憎恨……混乱，这是一切的支柱。"
D.SharedStrings[18084]="背叛的小鬼"
D.SharedStrings[18085]="背叛者的黑暗之弓"
D.SharedStrings[18086]="背弃者瓦加斯"
D.SharedStrings[18087]="背水一战"
D.SharedStrings[18088]="胜利点数增加2点。"
D.SharedStrings[18089]="胜利点数增加6点。"
D.SharedStrings[18090]="胜利的诚意"
D.SharedStrings[18091]="胜利者岗哨士兵"
D.SharedStrings[18092]="胡恩·高岭"
D.SharedStrings[18093]="胡萝卜吐息造成{1}点物理伤害，并将施法者面前锥形区域内的目标击退。"
D.SharedStrings[18094]="能为老朋友做最后一点事吗？我的老伙伴，瓦雷索斯堕入了梦魇的魔掌。我们曾经并肩为保护这片土地而奋斗。正是他与这片土地的密切联系，才令他在这黑暗的时刻堕落。$b$b正如所有遭受这悲惨命运的人一样，他已无可拯救。$b$b拜托了，$n，送他回归平静吧。"
D.SharedStrings[18095]="能再次看看朋友和家人的感覺真好，雖然我或許有點太超過了...我已經把他們今天給我準備的東西全吃光了!$B$B我能麻煩你幫我找些美味的亡者麵包嗎?我會非常感激...$B$B我想，那邊的小販有在賣食譜。"
D.SharedStrings[18096]="能同你结识真是不胜荣幸，$r。$b$b你的名声响彻艾泽拉斯，妇孺皆知。$b$b我将在卡雷苟斯到达时，向他献上拉格纳罗斯的心脏。它的力量将被用来进一步地强化你的武器。$b$b典礼马上就要开始了。我被指派来当你的护卫，等你准备好了，咱们就出发。"
D.SharedStrings[18097]="能在水下呼吸。\r\n但是视野不够清晰。"
D.SharedStrings[18098]="能够从邪魂堡垒内的恶魔身上收集净化的血液。"
D.SharedStrings[18099]="能够在水上行走。"
D.SharedStrings[18100]="能够承受大量伤害的姿态。\r\n\r\n受到的伤害降低{1}%。"
D.SharedStrings[18101]="能够用于制造传说布甲。"
D.SharedStrings[18102]="能将这个消息带给我们一定需要莫大的勇气。我正开始怀疑为何蓝龙军团敢如此大胆地对神庙本身发动攻击。如今我晓得，他们大量使用那些原本蓝龙军团视为对造成艾泽拉斯巨大威胁的魔法。<龙后无可奈何地摇了摇头。>$B$B很伪善，但任由他们去吧。如果玛里苟斯不能恢复理智，我们除了对他的进犯进行反击之外，别无他法。"
D.SharedStrings[18103]="能让你进出燃烧王座的恶魔符文之一。"
D.SharedStrings[18104]="能读到这行字就说明你遇到了一个bug，赶紧的报bug。"
D.SharedStrings[18105]="能量回复速度提高{1}%。"
D.SharedStrings[18106]="能量恢复速度提高{1}%。\r\n攻击速度提高{2}%。"
D.SharedStrings[18107]="能量的符文在施法者的武器上闪烁，对目标造成暗影伤害。"
D.SharedStrings[18108]="脉动之血护腿"
D.SharedStrings[18109]="脉动的卵囊"
