D.SharedStrings[18111]="脉动防护护肩"
D.SharedStrings[18112]="脓疮蜘蛛正从疯狂的麦德加背上跳下来！"
D.SharedStrings[18113]="脚踢目标敌人，造成物理伤害。"
D.SharedStrings[18114]="脚踢连击，对附近所有敌人造成物理伤害。"
D.SharedStrings[18115]="脚踢附近的敌人。\r\n免疫定身效果和诱捕效果。"
D.SharedStrings[18116]="脱离战斗后，巨石之盾会生成一层护盾。"
D.SharedStrings[18117]="脱离战斗后，生命值恢复速度加快{1}%。"
D.SharedStrings[18118]="脱离战斗并保持静止一小段时间后，玩家将遁入暗影。"
D.SharedStrings[18119]="脱离战斗时获得暗遁效果。"
