D.SharedStrings[18136]="腐烂的食物每秒造成自然伤害。"
D.SharedStrings[18137]="腐臭的疫病之云包围施法者，对所有邻近敌人造成暗影伤害。"
D.SharedStrings[18138]="腐臭的疾病之云包围施法者，对附近的敌人造成自然伤害。"
D.SharedStrings[18139]="腐蚀你所有的术士火焰法术，为其灌注邪恶的魔法。"
D.SharedStrings[18140]="腐蚀寄生虫"
