D.SharedStrings[18147]="腐蚀者马尔戴斯"
D.SharedStrings[18148]="腐蚀钉刺护腕"
D.SharedStrings[18149]="腐蚀领主乌鲁格"
D.SharedStrings[18150]="腾跃至空中并猛踢目标。"
D.SharedStrings[18151]="臣服憎恶臂甲"
D.SharedStrings[18152]="自从你揪出诅咒教派的间谍之后，银色北伐军已经把赛场中的卫兵数量增加了一倍。只要这里还没有被夷为平地，只要锦标赛还没有被完全破坏，诅咒教徒就不会善罢甘休。$B$B银色北伐军的斥候发现了一支诅咒教派的部队，他们在一条名叫冰喉的冰霜巨龙的带领下向我们奔袭。$B$B你必须在他们发动攻击之前阻止他们。根据斥候的报告，冰喉就盘旋在我们的西南方向，铁墙大坝和奥尔杜萨交界的地方。"
D.SharedStrings[18153]="自从我们夺回这座凄凉的岛屿后，僵尸和食尸鬼就一直在遗忘山丘肆虐。好几次我们都想彻底清理这些家伙，但他们还是三番五次地卷土重来。$b$b有一位中尉指出，杀死食尸鬼后应该取走大腿骨，这样他们就不能在夜里复生了。你能帮我们处理一下这件事吗？"
D.SharedStrings[18154]="自从我们踏上托尔巴拉德的土地，就一直在努力清理咒怨地牢的牢房。似乎每次我们即将大功告成时，那个大法师就会冒出来，把我们打回去。$B$B现在既然我们已经占领岛屿了，就该再试一次。你去跑一趟，把他的法杖给我带回来，作为你完成任务的证据。"
D.SharedStrings[18155]="自你上一次接受考验来已经有一段时间了。预言者努波顿想让你去见他。$B$B你的智慧在过去的这段时间里是否有长足的提高？因为你被召唤的原因，是要去了解水元素的秘密。$B$B你一定记得先知在埃索达水晶大厅的什么位置，对吧？"
D.SharedStrings[18156]="自动净化装置"
D.SharedStrings[18157]="自动幽影助步机5000型"
D.SharedStrings[18158]="自律动机便鞋"
D.SharedStrings[18159]="自我激怒，体积变大，提高攻击速度，降低造成的伤害。"
D.SharedStrings[18160]="自我激怒，体积变大，造成的伤害提高。"
