D.SharedStrings[18177]="致衰一击造成相当于{1}%武器伤害的暗影伤害，将目标击退，并使目标的身体变得衰弱。"
D.SharedStrings[18178]="致：达拉然下水道，郭雅夫人\n\n重要！\n\n特急件！\n\n立即投递！"
D.SharedStrings[18179]="舊文字存檔:釋放所有符能，對一名敵人造成可隨攻擊強度而提高的{1}點暗影傷害，或者恢復一名友方不死生物最多{1}點生命力。"
D.SharedStrings[18180]="舒玛之血"
D.SharedStrings[18181]="舞兰，双后的利刃之扇"
D.SharedStrings[18182]="舰船：驱逐舰"
D.SharedStrings[18183]="舰队上将特塞斯"
D.SharedStrings[18184]="船长“闷水壶”苏道"
D.SharedStrings[18185]="船长克星弗洛格"
D.SharedStrings[18186]="船隻即將從刃拳海岸的碼頭出航，\r\n\r\n在你出發前，先做好準備吧。我有預感這會是艱難的一仗。"
D.SharedStrings[18187]="艰巨的任务总在最后，$n。你已经击败了一位上古之神和一位巫妖王的大将，现在是面对萨格拉斯的时候了。$B$B带上这根杖子前往斯坦索姆。你会在那儿发现一处神圣之地：洛丹伦最伟大的骑士们的埋骨之处。将这柄被玷污的传说之杖放在神圣之地中，准备好挑战被驱赶出法杖的可怕生物……击败控制着法杖的恶魔，然后再回来找我。"
D.SharedStrings[18188]="艰难的挑战：啸天者托瓦拉"
D.SharedStrings[18189]="艰难的挑战：塔隆戈尔"
D.SharedStrings[18190]="艰难的挑战：斯古洛克，格鲁尔之子"
D.SharedStrings[18191]="艰难的挑战：武器大师席恩"
D.SharedStrings[18192]="艰难的挑战：督军扎伊拉"
D.SharedStrings[18193]="艰难的挑战：破桶而出的炎诛"
D.SharedStrings[18194]="艰难的挑战：织焰者孔格勒"
D.SharedStrings[18195]="艰难的挑战：翼虫首领尼诺洛克"
D.SharedStrings[18196]="艰难的挑战：高阶贤者维里克斯"
D.SharedStrings[18197]="艰难的挑战：黑暗院长加丁"
D.SharedStrings[18198]="色彩艳丽，触手生温。"
D.SharedStrings[18199]="艺术家奥利盖为大魔导师制作的彩蛋。这批彩蛋在送往王宫的途中失踪了。"
D.SharedStrings[18200]="艾乐瑞瑟·雷弗拉尔"
D.SharedStrings[18201]="艾克诺·钢铁使者"
D.SharedStrings[18202]="艾利桑德"
D.SharedStrings[18203]="艾利桑德曾因为对抗燃烧军团而享有盛名。她和手下的上层精灵追随者们背弃了走上黑暗之路的艾萨拉女王，之后利用阿曼苏尔之眼的力量创造出了暗夜井，保护了苏拉玛免遭大分裂的破坏。但一万多年后，军团再临了，她被逼上了绝路。于是她与恶魔结盟了，希望能再一次利用暗夜井的力量“拯救”她的人民。"
D.SharedStrings[18204]="艾利桑德的回响"
D.SharedStrings[18205]="艾卓-尼鲁布"
D.SharedStrings[18206]="艾尔·阿拉哈"
D.SharedStrings[18207]="艾尔女祭司"
D.SharedStrings[18208]="艾尔文小羊羔"
D.SharedStrings[18209]="艾尔杰恩，锯齿新月斧"
D.SharedStrings[18210]="艾尔的祝福让你可以从此处直接跃往艾尔的宝库。"
D.SharedStrings[18211]="艾尔的祝福让你可以从此处直接跃往英灵殿，但要付出巨大的代价。"
D.SharedStrings[18212]="艾尔的选民"
D.SharedStrings[18213]="艾尔米拉修女"
D.SharedStrings[18214]="艾尔罗·埃伯洛克公爵"
D.SharedStrings[18215]="艾希迪尔"
D.SharedStrings[18216]="艾希迪尔的卫士"
D.SharedStrings[18217]="艾德温·范克里夫"
D.SharedStrings[18218]="艾德里斯·索恩领主"
D.SharedStrings[18219]="艾恩·戈德布鲁姆博士"
D.SharedStrings[18220]="艾拉岡從自身形態中吸收能量，製造六個能量核心，每個能量核心都具有重新啟動至高天核的能力。在此過程中艾拉岡會變得虛弱，使其受到的傷害提高{1}%。"
D.SharedStrings[18221]="艾斯的捷烬斗篷"
D.SharedStrings[18222]="艾格文击败萨格拉斯的化身后，将他封印在了陵墓深处，但那具恐怖的躯壳现在又开始活动了……"
D.SharedStrings[18223]="艾格文的影像"
D.SharedStrings[18224]="艾欧娜尔的斗志高昂，你可以借助她的力量飞上天空一小段时间。"
D.SharedStrings[18225]="艾欧娜尔的礼物"
D.SharedStrings[18226]="艾欧娜尔的礼物为弗蕾亚和她的所有仆从恢复{1}%的生命值。"
D.SharedStrings[18227]="艾欧娜尔的精华"
D.SharedStrings[18228]="艾欧纳尔的火花"
D.SharedStrings[18229]="艾沃尔祖传护腕"
D.SharedStrings[18230]="艾泽拉斯二十大劲歌金曲"
D.SharedStrings[18231]="艾泽拉斯保卫者：军团入侵"
D.SharedStrings[18232]="艾泽拉斯入侵计划"
D.SharedStrings[18233]="艾泽拉斯地狱火"
D.SharedStrings[18234]="艾泽拉斯快递公司应该送一批碧玉来给我的，但我刚刚听说他们的船撞上了一座名叫欧格佐尼亚的小岛。我挺担心那些船员的，据说岛上的女食人魔会对不幸登岛的男性举行可怕的仪式。不过，我的工作还得继续，我们需要那些宝石。我听说你是个非常出色的珠宝匠——今晚之前能交给我三颗裂纹碧玉吗？"
D.SharedStrings[18235]="艾泽拉斯最后的守护者"
D.SharedStrings[18236]="艾泽拉斯的吟游诗人们眼中的宝贝。"
