D.SharedStrings[18403]="莉娜的宠物龅牙又闯进我的作坊了！$b$b当时我正在制作一只手镯，是今天就要交货的。工作就要完成了，只差镶宝石的环节。我花了一整晚切割宝石，但是就在我出去吃早餐的那一小会，该死的小怪物冲进我的作坊，把它看到的所有宝石都给吞了！那东西可以消化一切，而且说正经的，光是收拾它留下的一堆烂摊子就足以让你累断腰了。$b$b我必须尽快弄到备用的宝石，信使今晚就要来了。帮帮忙啊！"
