D.SharedStrings[18499]="获得在银色锦标赛中代表所有部落种族阵营出战的资格。"
D.SharedStrings[18500]="获得在银色锦标赛中代表暴风城出战的资格。"
D.SharedStrings[18501]="获得在银色锦标赛中代表森金出战的资格。"
D.SharedStrings[18502]="获得在银色锦标赛中代表诺莫瑞根流亡者出战的资格。"
D.SharedStrings[18503]="获得在银色锦标赛中代表达纳苏斯出战的资格。"
D.SharedStrings[18504]="获得在银色锦标赛中代表铁炉堡出战的资格。"
D.SharedStrings[18505]="获得在银色锦标赛中代表银月城出战的资格。"
D.SharedStrings[18506]="获得在银色锦标赛中代表雷霆崖出战的资格。"
D.SharedStrings[18507]="获得地之祝福。\r\n伤害提高{1}%。\r\n攻击间隔时间缩短{2}%。"
D.SharedStrings[18508]="获得技能：法力虚空。"
D.SharedStrings[18509]="获得技能：法力虚空。\r\n法力虚空持续地吸取法力值，直到该目标死亡。法力虚空在被摧毁后会归还所有被吸取的法力值。"
D.SharedStrings[18510]="获得技能：消化酸液。\r\n消化酸液对随机目标造成自然伤害。"
D.SharedStrings[18511]="获得技能：深度腐蚀。\r\n在深度腐蚀的效果影响下，受到5次治疗将导致爆炸，对周围所有盟友造成{2}点暗影伤害。"
D.SharedStrings[18512]="获得技能：灵魂切割。\r\n灵魂切割会对当前目标造成{1}点暗影伤害。"
D.SharedStrings[18513]="获得技能：灼热之血。\r\n灼热之血随机对远距离的敌人造成{1}点火焰伤害。"
D.SharedStrings[18514]="获得招架，数值相当于由装备提供的爆击的{1}%。"
D.SharedStrings[18515]="获得月夜猛虎巨灵的祝福。攻击速度和施法速度提高{1}%。获得了黑海岸月夜猛虎的友好认同。"
D.SharedStrings[18516]="获得极快的游泳速度和生命值回复速度。"
D.SharedStrings[18517]="获得死亡之翼背脊之战的胜利（巨龙之魂）"
D.SharedStrings[18518]="获得死亡之翼背脊之战的胜利（英雄：巨龙之魂）"
D.SharedStrings[18519]="获得水下呼吸能力，并且在海底的移动速度提高{1}%。"
D.SharedStrings[18520]="获得火、水及空气结界，然后杀死哈辛·考尔。"
D.SharedStrings[18521]="获得熔火效果的铁铸像，在接触到水时会变得脆弱。"
D.SharedStrings[18522]="获得的经验值提高{1}%。"
D.SharedStrings[18523]="获得的荣誉值提高{1}%。\r\n下士军衔以上的参战者获得的最终荣誉奖励提高{1}%。"
D.SharedStrings[18524]="获得的金币总量"
D.SharedStrings[18525]="获得神圣毁灭技能。"
D.SharedStrings[18526]="获得神龙之赐技能，为一名盟友恢复大量生命。"
D.SharedStrings[18527]="获得索利达尔，群星之怒。"
D.SharedStrings[18528]="获得紧急回避技能，向后跳离，避开附近的雷神兽人。"
D.SharedStrings[18529]="获得萨弗拉斯，炎魔拉格纳罗斯之手。"
D.SharedStrings[18530]="获得蓟熊巨灵的祝福。受到的物理及魔法伤害降低{1}%。获得了黑海岸蓟皮熊的友好认同。"
D.SharedStrings[18531]="获得血帆舰长之帽……然后出门去呼吸一点新鲜空气。"
D.SharedStrings[18532]="获得赤喉之咬技能，对目标造成大量伤害并降低其移动速度。"
D.SharedStrings[18533]="获得达拉然烹饪奖牌"
D.SharedStrings[18534]="获得达拉然珠宝匠硬币"
D.SharedStrings[18535]="获得连续10场排位赛的胜利，且保持个人等级在1800以上。"
D.SharedStrings[18536]="获得阿拉希盆地战斗的胜利，获取一只阿拉希资源箱，然后向避难谷地的玛克里尔中士复命。"
D.SharedStrings[18537]="获得雄鹿巨灵的祝福。移动速度提高{1}%。获得了黑海岸雄鹿的友好认同。"
D.SharedStrings[18538]="获得雷霆之怒，逐风者的祝福之剑。"
D.SharedStrings[18539]="获得食人魔进攻命令书"
D.SharedStrings[18540]="获释的卡拉波俘虏"
D.SharedStrings[18541]="获释的联盟奴隶"
D.SharedStrings[18542]="获释的部落奴隶"
D.SharedStrings[18543]="获释的霜狼俘虏"
D.SharedStrings[18544]="菜公施放践踏，造成{1}点物理伤害，变得更加愤怒。"
D.SharedStrings[18545]="菲亚斯科·尖笑"
D.SharedStrings[18546]="菲兹兰克弹射号"
D.SharedStrings[18547]="菲兹兰克飞行员"
D.SharedStrings[18548]="菲兹普罗克主管"
D.SharedStrings[18549]="菲利普·斯多姆威尔"
D.SharedStrings[18550]="菲奥娜·斯多姆威尔"
D.SharedStrings[18551]="菲奥拉是一个忠实的伙伴，她从来没迷失过方向。"
D.SharedStrings[18552]="菲奥拉的马车"
D.SharedStrings[18553]="菲奥拉马车的挽具"
D.SharedStrings[18554]="菲娜·伯恩多提尔"
D.SharedStrings[18555]="菲拉·白羽"
D.SharedStrings[18556]="菲拉斯哨兵"
D.SharedStrings[18557]="萌芽的永生孢子"
D.SharedStrings[18558]="营地中的首席炼金师可能知道它有什么用。"
D.SharedStrings[18559]="营地里的物资储备越来越少了，$n。我们最近发现西南边的监狱中储备着多年来没有用掉的干粮。我们要派你去尽可能收集那些干粮，把它们带回营地来。$B$B还有一件事，那座监狱里到处都是逃脱的囚犯，所以你要多加小心。"
D.SharedStrings[18560]="营救4名受伤的暴风城士兵。"
D.SharedStrings[18561]="营救并保护治疗者，直至神真子的伤口愈合。"
D.SharedStrings[18562]="营救金·热桶、崖·火树、方老太和钟思亚。"
D.SharedStrings[18563]="萨什比特沿着图书馆外缘挥舞战槌，对经过的所有玩家造成{1}点物理伤害。"
D.SharedStrings[18564]="萨伊娜·风驰队长"
D.SharedStrings[18565]="萨吉塔暗礁行者"
D.SharedStrings[18566]="萨塔耶的攻击在目标身上施加不断叠加的减速效果，最终将目标定身。"
D.SharedStrings[18567]="萨奇尔"
D.SharedStrings[18568]="萨尔克·暴怒图腾"
D.SharedStrings[18569]="萨尔制造出一个水体防护层，保护盟友免受善德之潮的影响。"
D.SharedStrings[18570]="萨尔加斯·安威玛尔"
D.SharedStrings[18571]="萨尔因作战斥候"
D.SharedStrings[18572]="萨尔的精英团"
D.SharedStrings[18573]="萨尔诺斯开始制造灌魔幽灵。幽灵试图占据最近的一具堕落十字军的尸体，使其变成一个灌魔僵尸。"
D.SharedStrings[18574]="萨布拉的凯旋头环"
D.SharedStrings[18575]="萨弗拉斯召唤烈焰之子。如果它吸收了烈焰之子，造成的伤害就会提高。"
D.SharedStrings[18576]="萨弗拉斯烈焰摧毁侵入炎魔之王领地的所有敌人，造成{1}点火焰伤害。"
D.SharedStrings[18577]="萨弗拉斯重击"
D.SharedStrings[18578]="萨弗拉斯，炎魔拉格纳罗斯之手"
D.SharedStrings[18579]="萨弗拉斯，炎魔拉格纳罗斯之手（公会版）"
D.SharedStrings[18580]="萨弗隆先驱者"
D.SharedStrings[18581]="萨弗隆熔岩投掷者"
D.SharedStrings[18582]="萨拉哈·天剑"
D.SharedStrings[18583]="萨拉塔斯"
D.SharedStrings[18584]="萨拉塔斯，黑暗帝国之刃"
D.SharedStrings[18585]="萨拉托，血吼的亵渎之影"
D.SharedStrings[18586]="萨斯多拉，风行者的遗产"
D.SharedStrings[18587]="萨格拉斯之墓：古墓主母"
D.SharedStrings[18588]="萨格拉斯之墓：堕落的化身"
D.SharedStrings[18589]="萨格拉斯之墓：欺诈者"
D.SharedStrings[18590]="萨格拉斯之墓：艾格文之路"
D.SharedStrings[18591]="萨格拉斯之墓：解放灵魂"
D.SharedStrings[18592]="萨格拉斯在我们的世界上留下了一道伤疤，$n。这道伤疤绝不会马上愈合……\n\n联盟和部落之间的伤疤也一样。\n\n为了拯救艾泽拉斯免遭毁灭，已经有太多生命在战斗中牺牲。我绝不能坐看这个世界再次陷落。\n\n我走之前有个请求。请把这封信交给麦格尼·铜须。他在希利苏斯寻找治疗伤口的方法。\n\n这封信里的信息对他或许会很有用。"
D.SharedStrings[18593]="萨格拉斯权杖"
D.SharedStrings[18594]="萨格雷作战计划"
D.SharedStrings[18595]="萨格雷战争议会"
D.SharedStrings[18596]="萨格雷束缚者"
D.SharedStrings[18597]="萨洛拉丝女王"
D.SharedStrings[18598]="萨洛瑞安·寻晨者"
D.SharedStrings[18599]="萨洛瑞安·寻晨者的遗体"
D.SharedStrings[18600]="萨满之镜胸甲"
D.SharedStrings[18601]="萨满祭司的下一个熔岩爆裂变为瞬发。"
D.SharedStrings[18602]="萨满祭司训练师"
D.SharedStrings[18603]="萨满训练师"
D.SharedStrings[18604]="萨穆·野火"
D.SharedStrings[18605]="萨维斯之影"
D.SharedStrings[18606]="萨维斯将潜藏的腐蚀散布到了翡翠梦境之中。与其他玩家一起对抗他的力量！（普通难度）"
D.SharedStrings[18607]="萨缪尔修士"
D.SharedStrings[18608]="萨莉斯·黑暗猎手"
D.SharedStrings[18609]="萨萨里安"
D.SharedStrings[18610]="萨诺克的碎裂之盔"
D.SharedStrings[18611]="萨赫特的狮子"
D.SharedStrings[18612]="萨隆邪铁蒸汽"
D.SharedStrings[18613]="萨鲁法尔从技能和召唤生物造成的伤害中汲取鲜血能量。"
D.SharedStrings[18614]="萨鲁法尔召唤出两只血兽协同作战。"
D.SharedStrings[18615]="萨鲁法尔大王"
D.SharedStrings[18616]="萨鲁法尔每获得一点鲜血能量，身体就会变大{1}%。"
D.SharedStrings[18617]="萨鲁法尔每获得一点鲜血能量，身体就会变大{1}%，所造成的伤害也会提高{2}%。"
D.SharedStrings[18618]="落入神圣陵墓奥金顿核心的塔隆戈尔吞噬了上百个德莱尼的灵魂，变成了一头臃肿的畸形怪物。\n\n这个面目全非的兽人因此抛弃了旧名，给自己起了一个新名字：血魔。"
D.SharedStrings[18619]="落石之雨对攻击范围内的所有敌人造成{1}点物理伤害。"
D.SharedStrings[18620]="落网的受害者"
D.SharedStrings[18621]="葛林克尔已经栽在你手上了?很好。少了他的妨碍，我们夺下壁垒的机会大大的提升了。"
D.SharedStrings[18622]="葬火之星歼灭者"
D.SharedStrings[18623]="蒂亚和米亚以及拉里"
D.SharedStrings[18624]="蒂凡妮·卡蒂亚"
D.SharedStrings[18625]="蒂梵妮·尼尔森"
D.SharedStrings[18626]="蒂玛，幽影之母"
D.SharedStrings[18627]="蒂萨·热炉"
D.SharedStrings[18628]="蒙塔克的灼热之息手套"
D.SharedStrings[18629]="蒙面的十字军战士"
D.SharedStrings[18630]="蒸汽动力拍卖师"
D.SharedStrings[18631]="蒸汽已经凝结起来，随时都有可能扩散开，对敌人造成严重伤害，并将敌人击退。"
D.SharedStrings[18632]="蓝烛捕鼠者"
D.SharedStrings[18633]="蓝烛捕鼠者的宠物"
D.SharedStrings[18634]="蓝紫熊猫人凤凰"
D.SharedStrings[18635]="蓝翼守护者"
