D.SharedStrings[18638]="蓝色发条战士"
D.SharedStrings[18639]="蓝色小矛骑兵"
D.SharedStrings[18640]="蓝色影踪派骑乘虎"
D.SharedStrings[18641]="蓝色机械陆行鸟"
D.SharedStrings[18642]="蓝色美酒节酒杯"
D.SharedStrings[18643]="蓝色装甲龙鹰"
D.SharedStrings[18644]="蓝色骑乘塔布羊"
D.SharedStrings[18645]="蓝色骑乘虚空鳐"
D.SharedStrings[18646]="蓝色骷髅战马"
D.SharedStrings[18647]="蓝色骸骨军马"
D.SharedStrings[18648]="蓝龙军团的精华保护着你。\r\n造成的伤害和治疗量提高。"
D.SharedStrings[18649]="蓟叶威吓者"
D.SharedStrings[18650]="蓟鬃偷猎者"
D.SharedStrings[18651]="蔑潮女武神"
D.SharedStrings[18652]="蔚蓝甲壳护腕"
D.SharedStrings[18653]="蕨墙村的萨尔格要你去杀掉10个火鬃斥候，10个火鬃灰尾龙人和5个火鬃守卫。"
D.SharedStrings[18654]="蕾瑟塔蒂丝的网"
D.SharedStrings[18655]="薇兰达斯·拉文凯斯夫人"
D.SharedStrings[18656]="薇薇安在战斗中被击败了。你可以在她痊愈后在兵营里重新招募她。"
D.SharedStrings[18657]="薇薇安曾经在洛丹伦废墟居住过很长一段时间，并在那里为黑暗女王本人提供私人服务。"
D.SharedStrings[18658]="薩斯葛爾任務獎勵標記者，燒光薩斯葛爾，丘陵哨塔"
D.SharedStrings[18659]="薩斯葛爾任務獎勵標記者，燒光薩斯葛爾，北方哨塔"
D.SharedStrings[18660]="薩斯葛爾任務獎勵標記者，燒光薩斯葛爾，南方哨塔"
D.SharedStrings[18661]="薩斯葛爾任務獎勵標記者，燒光薩斯葛爾，熔爐哨塔"
D.SharedStrings[18662]="藏卷人"
D.SharedStrings[18663]="藏宝海湾的利益"
D.SharedStrings[18664]="藏宝海湾的大财主里维加兹派我到这里的目的，就是确保这次巨魔的威胁可以有效地被遏止，至少成功把他们挡在藏宝海湾的大门外。$b$b我需要大家马上行动，取得成效。$b$b所以你应该到那里去，奋勇杀敌。$b$b然后你要找到一样可以把巨魔从藏宝海湾驱逐走的物件。$b$b你要是能做到的话，我们会给予你报酬的。"
D.SharedStrings[18665]="藏宝海湾的某些家伙可能会感兴趣。"
D.SharedStrings[18666]="虔诚的战斗祭司"
D.SharedStrings[18667]="虚空之光圣贤"
D.SharedStrings[18668]="虚空之光熔炉 - 至少解锁1个神器能力"
D.SharedStrings[18669]="虚空之光熔炉"
D.SharedStrings[18670]="虚空之剑泽达特"
D.SharedStrings[18671]="虚空之子"
D.SharedStrings[18672]="虚空之誓教徒意识到了你的存在。小心应付。"
D.SharedStrings[18673]="虚空之门"
D.SharedStrings[18674]="虚空仓库"
D.SharedStrings[18675]="虚空传送门"
D.SharedStrings[18676]="虚空冲击"
D.SharedStrings[18677]="虚空召唤者的卷轴"
D.SharedStrings[18678]="虚空守望者瓦苏拉"
D.SharedStrings[18679]="虚空恐魔"
D.SharedStrings[18680]="虚空猎手幼崽"
D.SharedStrings[18681]="虚空盘踞在你体内。急速和移动速度提高25%，但受到的魔法伤害提高50%。"
D.SharedStrings[18682]="虚空矿洞剥石者的外皮"
D.SharedStrings[18683]="虚空碎片"
D.SharedStrings[18684]="虚空能量的束缚将一个定相小鬼与主人绑定。"
D.SharedStrings[18685]="虚空行者"
D.SharedStrings[18686]="虚空行者爪牙"
D.SharedStrings[18687]="虚空裂缝"
D.SharedStrings[18688]="虚空裂隙"
D.SharedStrings[18689]="虚空触须"
D.SharedStrings[18690]="虛無再生者 - 任務 - 虛無山脈 - 加倫希斯"
D.SharedStrings[18691]="虫群卫士希赛克"
D.SharedStrings[18692]="虫语清道夫"
D.SharedStrings[18693]="虽然书面文字主要是食人魔的大贵族阶层的专属，但偶尔也会有一些灵感大发的普通食人魔会尝试用双手将一个故事永久记载下来。这幅象形图画似乎记载了作者某次特别痛苦的烹饪体验。"
D.SharedStrings[18694]="虽然以龙类的标准只是一只雏龙，但泽洛斯仍然是古老技艺的强大践行者。"
D.SharedStrings[18695]="虽然你已向我证明自己的来意，你还需要继续努力向我部族怀疑的兄弟们证明你自己。只有这样，我才能继续帮助你。$B$B有些死木熊怪戴着特殊的头饰，可以作为削减他们势力的证据。带给我你从任何头饰上取得的羽毛;你每给我一套5个，就会赢得木喉的信赖。"
D.SharedStrings[18696]="虽然只是惊鸿一瞥，但你更加深入地了解了麦迪文的思想和过往。"
D.SharedStrings[18697]="虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。"
D.SharedStrings[18698]="虽然大多数卓格巴尔都喜欢原始状态下宝石粗糙的棱角，但有些卓格巴尔更青睐光滑浑圆的珠宝。他们不会使用标准的宝石切割工具，而是把它们放到带手柄的石头容器里，翻滚上几个星期时间。操作这些工具的往往是仆人、奴隶或是不服管教的年轻人。"
D.SharedStrings[18699]="虽然对英勇的冒险者们没什么用，但贸易订单可以卖给商人换取少量货币。"
D.SharedStrings[18700]="虽然我们已经把力量都给你了，我们还是想送给你一次……神器外观方面的……强化。\n\n我们代表六人议会、达拉然和艾泽拉斯，再次感谢你，$n。"
D.SharedStrings[18701]="虽然看似简单，但这碗汤面的绝妙之处在于能让人神清气爽，重新振作起来。"
D.SharedStrings[18702]="虽然看起来凶猛，但血眼隼龙的喙更适合啄食水果。"
D.SharedStrings[18703]="虽然这个铜质罗盘已饱经风霜，但它的制造工艺确是一流的。"
D.SharedStrings[18704]="虽然这张图纸看上去已经被严重烧毁，并且失去了其中蕴含的魔法，但商人也许并不知道这有什么区别……"
D.SharedStrings[18705]="虽然这张雕文看上去已经被严重烧毁，并且失去了其中蕴含的魔法，但商人也许并不知道这有什么区别……"
D.SharedStrings[18706]="虽然这把法杖没有什么明显的特征，但是你觉得它已经非常古老了。"
D.SharedStrings[18707]="虽然这种附魔曾经风靡一时，可它现在似乎已经完全失效了。"
D.SharedStrings[18708]="蛇蜥的石化之眼"
D.SharedStrings[18709]="蛇鳞鲜血斗篷"
D.SharedStrings[18710]="蛊心魔古厄夏"
D.SharedStrings[18711]="蛛后泰兰娜消失在暗影之中，并召唤蜘蛛群攻击她的敌人！\r\n"
D.SharedStrings[18712]="蛛形地雷"
D.SharedStrings[18713]="蛮锤狮鹫幼崽"
D.SharedStrings[18714]="蛮锤部族代表"
D.SharedStrings[18715]="蜘蛛发出尖啸，召唤更多的蜘蛛从蛛网上落下。"
D.SharedStrings[18716]="蜥蜴人追猎者外套"
D.SharedStrings[18717]="蜥蜴人追猎者头盔"
D.SharedStrings[18718]="蜥蜴人追猎者手套"
D.SharedStrings[18719]="蜥蜴人追猎者护肩"
D.SharedStrings[18720]="蜥蜴人追猎者护腿"
D.SharedStrings[18721]="蜷曲的暮光之爪"
D.SharedStrings[18722]="蝙蝠管理员"
D.SharedStrings[18723]="融入了冰之精华。收集20个这样的东西，同时没有被冰霜灼烧击中，就能赢得这次挑战！"
D.SharedStrings[18724]="螳螂妖宰相的长袍"
D.SharedStrings[18725]="螳螂妖甲质护腕"
D.SharedStrings[18726]="螳螂妖！这些家伙突然就冒了出来，击溃了我们的护卫队，把我们的人都驱散了。$b$b现在它们正准备攻打石犁村。$b$b请帮帮我们，$c，在它们召集大军包围我们的村庄之前，消灭掉一些有生力量。$b$b如果我的表哥林大使还活着，并仍在护卫队的话，他应该会酬谢你的帮助的。"
D.SharedStrings[18727]="蟠龙脊上的影踪派神射手时时刻刻都在监视着恐惧废土。他们一定会欢迎像你一样训练有素的$c的协助。$B$B坐上风筝，去向女射手李琪薇报到吧。"
D.SharedStrings[18728]="蟠龙脊防御者"
D.SharedStrings[18729]="蠕动的碎心魔"
D.SharedStrings[18730]="蠕虫的鳞片受到了邪能的强化，每层效果使受到的伤害降低{1}%。"
D.SharedStrings[18731]="蠕行的亡灵花"
