D.SharedStrings[18860]="血卫士伯鲁恩"
D.SharedStrings[18861]="血卫士扎尔什"
D.SharedStrings[18862]="血卫士陶德雷克"
D.SharedStrings[18863]="血帆桨手"
D.SharedStrings[18864]="血帆海盗"
D.SharedStrings[18865]="血帆海马掠夺者"
D.SharedStrings[18866]="血怒者科尔拉克"
D.SharedStrings[18867]="血槌或是刀塔，都不重要。所有的食人魔氏族互相征战，争取拥有弑龙者格鲁尔支持的统治权。$B$B每一个都是我们的敌人，不管最后花落谁家。"
D.SharedStrings[18868]="血槌炉渣矿井"
D.SharedStrings[18869]="血槌炉渣矿井（英雄难度）"
D.SharedStrings[18870]="血槌食人魔都是凶残的奴隶主，指挥官。他们将德拉诺各地的无辜平民虏到位于霜火岭的炉渣矿井里，逼迫他们不眠不休地挖掘矿物和宝石，所有人都是有去无回。$B$B我们怀疑那些家伙正在全力为他们的巫王寻找一件拥有无穷力量的古老遗物。$B$B食人魔戈洛克用铁腕手段统治着炉渣矿井。只要干掉他，矿井就会随之崩溃。"
D.SharedStrings[18871]="血清使生物开始急速老化，并最终化为尘土。"
D.SharedStrings[18872]="血环之血"
D.SharedStrings[18873]="血环克星"
D.SharedStrings[18874]="血环氏族对塔纳安的钢铁部落提供了极大的援助。他们在泽斯高不断追捕我们的斥候、破坏我们的行动，同时还在帮助古尔丹聚集更多的力量。\n\n我们可以考虑对泽斯高进行一次直接突击，迫使他们撤兵回防。这应该能为我们赢得一定的喘息时间。"
D.SharedStrings[18875]="血琥珀将被用来研究一种可以对付费伍德森林中的堕落力量的方法，你已经证明了自己愿意为塞纳里奥议会做任何事情。\r\n\r\n也许通过杀掉那些元素生物来证明这一点显得有些奇怪，但我们最终的目标是拯救所有的生灵，到那时一切都会证明我们现在所走的道路是正确的。现在我们可以开始专注于如何救更多的生命了。\r\n\r\n$N.，是时候开始净化费伍德森林了。"
D.SharedStrings[18876]="血精灵大祭司"
D.SharedStrings[18877]="血红仪式匕首"
D.SharedStrings[18878]="血缚混血战士"
D.SharedStrings[18879]="血肉塑造者阿尔瑙德"
D.SharedStrings[18880]="血肉撕裂者诺格加尔"
D.SharedStrings[18881]="血肉灰烬效果结束会对附近所有敌人造成火焰伤害。"
D.SharedStrings[18882]="血腥之神印戒"
D.SharedStrings[18883]="血色修道院"
D.SharedStrings[18884]="血色修道院（英雄难度）"
D.SharedStrings[18885]="血色十字军"
D.SharedStrings[18886]="血色十字军指挥官莫格莱尼"
D.SharedStrings[18887]="血色十字军的问题是，即使死后，他们会不断死灰复燃。$B$B大检察官怀特迈恩在幕后控制着这些死尸的复活。如果她死了，十字军也将随之覆灭。$B$B让她彻底死亡，我们需要传说中的两把剑，每一把都有着残缺但传奇的历史。$B$B我很幸运……呃，这两把圣化长剑就在修道院内放着。$B$B去寻找这两把剑。一旦你击败了怀特迈恩，就使用圣化长剑的力量净化她，使她安息。"
D.SharedStrings[18888]="血色十字军领袖之剑"
D.SharedStrings[18889]="血色大厅（奖励目标）奖励任务"
D.SharedStrings[18890]="血色大厅（英雄难度）"
D.SharedStrings[18891]="血色指挥官玛尔兰"
D.SharedStrings[18892]="血色防御者"
D.SharedStrings[18893]="血色阿古尼特水晶"
D.SharedStrings[18894]="血警卫修理工"
D.SharedStrings[18895]="血警卫修理工使用神圣魔法治疗一名盟友。"
D.SharedStrings[18896]="血警卫修理工冲击一名玩家，对其造成暗影伤害。"
D.SharedStrings[18897]="血领主曼多基尔"
D.SharedStrings[18898]="血领主曼多基尔向他的目标冲锋并使用斩首技能，造成{1}点物理伤害。"
D.SharedStrings[18899]="血领主曼多基尔跃入空中，准备发起毁灭猛击，对其前方的敌人造成大量伤害。"
D.SharedStrings[18900]="血领主的浸血腿甲"
D.SharedStrings[18901]="血骑士"
