D.SharedStrings[18903]="血鬃短齿战士"
D.SharedStrings[18904]="血魔?你为什么这么问，我已经很多年没有听到这个名字了!$B$B在第二次大战之后，血魔回到了这里，旁边跟着他的死亡骑士们。无法适应他的新形态所带来极坏的天性又失去他最尊敬的领导者古尔丹的支持，血魔自杀了。$B$B假如他现在以灵魂的形态游走在这片大地的话，对我来说倒是个新消息。但是，也许有了你的协助我可以研究推敲相关的消息。"
