D.SharedStrings[18963]="被困在珍珠采掘场的短暂日子，使我对纳迦的真正目的感到好奇。对，现在我知道纳迦想要把奈瑟匹拉当成无坚不摧的战争机器，不过如果只有这么简单的话，为什么还要把我们绑去采珍珠？$b$b假如我们能逃出去的话，我倒是很想研究一下这些珍珠。我们在采掘场里找到的珍珠都太大了，搬都没法搬，不过我见过那些督军和先知随身带着小珍珠。"
