D.SharedStrings[19156]="装备在鱼竿上之后，可以使你的钓鱼技能提高200点，持续10分钟。"
D.SharedStrings[19157]="装备在鱼竿上之后，可以使你的钓鱼技能提高25点，持续10分钟。"
D.SharedStrings[19158]="装备在鱼竿上之后，可以使你的钓鱼技能提高50点，持续10分钟。"
D.SharedStrings[19159]="装备在鱼竿上之后，可以使你的钓鱼技能提高75点，持续10分钟。"
D.SharedStrings[19160]="装备有一枚高爆手雷。"
D.SharedStrings[19161]="装备武器套装。\r\n冬幕节期间，冷却时间会缩短。"
D.SharedStrings[19162]="装备爆炎弹。"
D.SharedStrings[19163]="装备被偷走了！\r\n受到的伤害提高{1}%。"
D.SharedStrings[19164]="装备鱼竿之后可以寻找一片水域钓鱼。当水中的鱼漂溅起水花的时候，立刻右键点击鱼漂以捕捉上钩的鱼。钓鱼技能的等级越高，你越有可能在高等级的水域中钓到鱼。"
D.SharedStrings[19165]="装备鱼竿，寻找一片水域钓鱼。当水中的鱼漂溅起水花的时候，立刻右键点击鱼漂以捕捉上钩的鱼。钓鱼技能的等级越高，你越有可能在高等级的水域中钓到鱼。"
D.SharedStrings[19166]="装扮你的溜溜。"
D.SharedStrings[19167]="装有20枚暗月游戏代币。"
D.SharedStrings[19168]="装有5枚暗月木马门票。"
D.SharedStrings[19169]="装有5枚暗月游戏代币。"
D.SharedStrings[19170]="装有大量真铁炸弹。"
D.SharedStrings[19171]="装甲拉扎什迅猛龙"
D.SharedStrings[19172]="装甲断牙护腰"
D.SharedStrings[19173]="装甲板连接束"
D.SharedStrings[19174]="装甲蓝色驭风者"
D.SharedStrings[19175]="装甲雪色狮鹫"
D.SharedStrings[19176]="装配有爆炸性的火焰炸弹。"
D.SharedStrings[19177]="裘碧卡·碎影"
D.SharedStrings[19178]="裘诺向一个敌人所在位置冲锋，如果成功则造成物理伤害，并将其击飞！"
D.SharedStrings[19179]="裝飾用的可調整閃電鏈法術"
D.SharedStrings[19180]="複製一名敵人的副手武器，並裝備起來。"
D.SharedStrings[19181]="褐石大师和他的弟子们逐渐……清醒了过来。"
D.SharedStrings[19182]="褐色作战塔布羊"
D.SharedStrings[19183]="褐色环尾浣熊"
D.SharedStrings[19184]="褐色骑乘塔布羊"
D.SharedStrings[19185]="褪尽生命的气息，他看起来老弱了许多。"
D.SharedStrings[19186]="西北部有些矮人正在准备修建一座挖掘场。他们认为地下埋藏着某些秘密，事实也的确如此，不过挖掘和污染大地并不是获得这些秘密的正确途径。$B$B收集矮人的挖掘工具，把它们全都毁掉，然后把这些被损坏的工具带给我。$B$B要毁掉这些工具的话，你必须得找到一块铁砧才行。在雷霆崖就有一处铁匠铺，不过任何铁砧——包括矮人营地里的——都可以用来毁掉工具。"
D.SharedStrings[19187]="西南面的眠月花园以前曾经是一群高贵的上层精灵的最终安息地，那里同样是一个强大的魔网能量线枢纽。$B$B蓝龙军团利用一种被他们自己称为“湍流之针”的魔法设备摧毁了那个枢纽，释放了能量，将能量指引去他们想要的地方。$B$B我希望你能帮我寻找我想要的信息。$B$B在这片土地被摧毁之后，上层精灵的鬼魂开始复活并击败了一部分法师猎手成员。去他们的尸体上看看有什么有用的信息。"
D.SharedStrings[19188]="西宝的圣徒之触"
D.SharedStrings[19189]="西部卫戍军士要你前往斯克恩，利用军士的弯刀确保20个蔑冬部族的维库人无法复活。"
D.SharedStrings[19190]="西部荒野人民军"
D.SharedStrings[19191]="西部荒野杂味炖肉"
D.SharedStrings[19192]="西部荒野流浪者"
D.SharedStrings[19193]="西风，泰坦守护者的长剑"
D.SharedStrings[19194]="要不是扯破了，这块布很适合用来过滤炼金液体。"
D.SharedStrings[19195]="要取得战争的胜利，我们要做的并不仅仅是简单地打败敌人，胜利的关键往往取决于双方的战争资源。$B$B阿拉希盆地蕴藏着大量物资，部落和联盟都想抢先夺取这些资源。$B$B如果联盟获胜，我们的军队将获得大量的剑和矛。如果部落获胜，这些武器也一样会被造出来，只不过是由部落的士兵拿在手里，指着我们！去帮助阿拉希盆地的联盟吧，$n。"
D.SharedStrings[19196]="要塞建筑师"
D.SharedStrings[19197]="要塞战役：沙塔斯的陷落"
D.SharedStrings[19198]="要塞战役：血环氏族的克星"
D.SharedStrings[19199]="要塞战役：进击奥金顿"
D.SharedStrings[19200]="要塞战役：鲜血竞技场"
D.SharedStrings[19201]="要塞魔导师"
D.SharedStrings[19202]="要对付火和水和空气的话……"
D.SharedStrings[19203]="要想延长你的会员期的话，你就得花些钱来为你的会员卡续费。"
D.SharedStrings[19204]="要拿到霍迪尔的徽记可不容易。你不但要击败霍迪尔，而且必须抢在他打碎装着徽记的箱子之前击败他！$B$B如果你想了解更多信息的话，可以去查查档案馆的控制台。那里面的知识比世界上所有的图书馆加在一起还要多！"
D.SharedStrings[19205]="要是他们就把它们那么搁着的话……"
D.SharedStrings[19206]="要看一下书吗？"
D.SharedStrings[19207]="要钓就钓到最好：奥格瑞玛"
D.SharedStrings[19208]="要钓就钓到最好：幽暗城"
D.SharedStrings[19209]="要钓就钓到最好：暴风城"
D.SharedStrings[19210]="要钓就钓到最好：达纳苏斯"
D.SharedStrings[19211]="要钓就钓到最好：铁炉堡"
D.SharedStrings[19212]="要钓就钓到最好：雷霆崖"
D.SharedStrings[19213]="覆盖着肉块。能让任何一条饿狗都看得垂涎三尺。"
D.SharedStrings[19214]="见习护甲军需官"
D.SharedStrings[19215]="见习竞技场商人"
D.SharedStrings[19216]="见习萨满金矿"
D.SharedStrings[19217]="见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!"
