D.SharedStrings[19352]="誓日荣誉卫士"
D.SharedStrings[19353]="誓约者力量戒指"
D.SharedStrings[19354]="誓约者力量指环"
D.SharedStrings[19355]="誓约者坚忍戒指"
D.SharedStrings[19356]="誓约者坚忍指环"
D.SharedStrings[19357]="誓约者坚忍斗篷"
D.SharedStrings[19358]="誓约者战争之石"
D.SharedStrings[19359]="誓约者战争斗篷"
D.SharedStrings[19360]="誓约者战争雕像"
D.SharedStrings[19361]="誓约者的防御者之石"
D.SharedStrings[19362]="誓约者的防御者雕像"
D.SharedStrings[19363]="謝謝你。在你來之前，我們完全沒有獲救的希望。"
D.SharedStrings[19364]="謝謝你。既然我拿回戰刃了，我要夷平魔魂堡。\r\n\r\n我的怒火無人能擋，復仇之前不會停息。"
D.SharedStrings[19365]="謝謝你。此處將永遠無法回復生氣，但至少不會再有人因為林精陷入瘋狂而受傷。"
D.SharedStrings[19366]="謝謝你救回歐庫雷斯。他對於我們的計劃是無可取代的戰力。"
D.SharedStrings[19367]="謝謝你，$n。你使我看清我的目標，給了我繼續活下去的理由。我們並肩作戰，就能夠拯救蘇拉瑪爾，並彌補我族人所犯下的罪。"
D.SharedStrings[19368]="謝謝你，$n。希望我們的部隊看到你完成這件事以後會恢復理智，並停止這種騷擾行為。"
D.SharedStrings[19369]="謝謝你，$n。我們每一天都朝解救蘇拉瑪爾更近一步。"
D.SharedStrings[19370]="謝謝你，$r。我會照料夜眼的傷勢。告訴我發生了什麼事！"
D.SharedStrings[19371]="謝謝你，現在我們就能開始我們的工作了。"
D.SharedStrings[19372]="警告荆棘谷的人们，并找到另一名暗矛大使。"
D.SharedStrings[19373]="警告，你的载具已经离开了规定区域。\r\n\r\n自爆系统启动。"
D.SharedStrings[19374]="警告：魔石锭在加热后必须立刻锻打成型，否则将会冷却并报废。"
D.SharedStrings[19375]="警惕的暮色卫队卫兵"
D.SharedStrings[19376]="警戒者凯萨尔"
D.SharedStrings[19377]="计时结束后，如果没有人被标记出来，躲藏者就会获胜！"
D.SharedStrings[19378]="计算你杀死敌方坦克的数量。"
D.SharedStrings[19379]="计算者帕萨雷恩"
D.SharedStrings[19380]="让一位强大的死亡骑士从墓穴中复活。"
D.SharedStrings[19381]="让一名敌人飞上天，使其对附近的敌人造成自然伤害。"
D.SharedStrings[19382]="让一名黑石兽人昏厥。只能从目标身后使用。"
D.SharedStrings[19383]="让你的战刃在接下来的3秒内在你周围急速旋转。"
D.SharedStrings[19384]="让你看上去像另外某人。"
D.SharedStrings[19385]="让你能够向你的宠物下达各种命令。"
D.SharedStrings[19386]="让使用者可以更好地理解止松熊怪的文字。"
D.SharedStrings[19387]="让充电火花跟随目标，每隔一段时间冲击地面，造成自然伤害。"
D.SharedStrings[19388]="让卡瑞纳库把你送回灵翼平原的莫德奈身边。"
D.SharedStrings[19389]="让它被空气充满，充上10次气大概就可以了。"
D.SharedStrings[19390]="让我们共进午餐：奥格瑞玛"
D.SharedStrings[19391]="让我们共进午餐：幽暗城"
D.SharedStrings[19392]="让我们共进午餐：暴风城"
D.SharedStrings[19393]="让我们共进午餐：达纳苏斯"
D.SharedStrings[19394]="让我们共进午餐：雷霆崖"
D.SharedStrings[19395]="让我们的敌人被一一击倒吧!为了雷矛部族的荣誉而战!"
D.SharedStrings[19396]="让我送你回到莫德奈那里吧。他一定想要再见你一面。"
D.SharedStrings[19397]="让战争领主加尔顿带你去看部队的战利品。"
D.SharedStrings[19398]="让施法者从目标的视野中消失，出现在目标背后。同时还会召唤出数个施法者的幻影。"
D.SharedStrings[19399]="让施法者周围的区域燃起大火，每秒钟对身边所有的敌人造成{1}点火焰伤害。"
D.SharedStrings[19400]="让施法者的生命值回复所承受伤害的一半。"
D.SharedStrings[19401]="让森提纳克斯号向这个区域派遣一名强大的恶魔军官。"
D.SharedStrings[19402]="让森提纳克斯号在这个区域召唤恶魔传送门。"
D.SharedStrings[19403]="让森提纳克斯号强化这个区域的恶魔传送门。"
D.SharedStrings[19404]="让欧鲁诺克和你的盟友摧毁屏障，然后阻止古尔丹。"
D.SharedStrings[19405]="让灵魂返回躯体，使死亡目标回复{1}%的生命值和{2}%的法力值。"
D.SharedStrings[19406]="让烈焰……净化一切？"
D.SharedStrings[19407]="让目标体内充满迪菲亚的力量。使其造成物理伤害提高{1}%，范围伤害法术和技能对其造成的伤害减少{2}%。生命值提高{3}%。"
D.SharedStrings[19408]="让目标感染痛痒，最终变成中毒效果。"
D.SharedStrings[19409]="训练假人"
D.SharedStrings[19410]="训练有素的丛林鹦鹉"
D.SharedStrings[19411]="训练有素的剥皮匠可以用塞纳里奥信标从费伍德森林里的生物身上找到受污染的毛皮，我可以把这些皮制作成塞纳里奥植物药膏。$B$B当你在这里采集兽皮的时候，记得带上信标。给我弄些受污染的毛皮来，我就可以给你几份药膏。"
D.SharedStrings[19412]="训练有素的草药师可以用塞纳里奥信标探测到那些被污染的魔藤―这是费伍德森林被污染后所诞生的产物。我在这里进行了一些研究工作，现在我可以把魔藤转化为一种净化原料……然后就可以用它来制作我们所说的塞纳里奥植物药膏了。$B$B当你在费伍德森林里收集草药的时候，别忘了带着这个信标来寻找魔藤。给我弄些魔藤来，我就给你几份药膏作为交换。"
D.SharedStrings[19413]="训练有素的萨满祭司可以与四种元素交流——大地，火焰，空气和水。这是众所周知的。$b$b但是，不那么众所周知的一件事是，其实还有第五种元素。这种元素的表述不像其它四种那么清晰，它与所有生物都具备的某种共性相关。$b$b我的想法是，既然这只螃蟹是海洋生物，那么它与奈瑟匹拉就有很相似的地方。借助元素的影响，我们可以说服它给奈瑟匹拉当传声筒。"
D.SharedStrings[19414]="训练过的岩石猎鹰"
D.SharedStrings[19415]="许多人都没有活到摆脱平庸的那一天。你已经证明了自己是一个勇士的楷模，$C。现在是提升你的军阶的时候了。$B$B这是你的新徽记。"
D.SharedStrings[19416]="许多坐骑在见到凶残的捕食者时都会吓得腿软。而在戈尔隆德荒凉的峭壁间，生存着世上最凶残的捕食者。你将在那里迎接下一场挑战。$B$B带上你的坐骑去大迅猛龙裂鞭的巢穴，看看你能否得胜归来。"
D.SharedStrings[19417]="许多士兵在这座岛上不幸丧命，$n。我们必须尽可能地对亡者表达敬意，才不枉他们的牺牲。$b$b我要你前往正西方的遗忘山丘，令兄弟们被折磨的灵魂得以解脱。要当心，据说那片区域有亡灵出没。"
D.SharedStrings[19418]="许多悲伤蜡烛装饰着这座南瓜祭坛，摇曳的火光似乎是在窃笑与嘲讽着你……"
D.SharedStrings[19419]="许多迷信的上层精灵会随身携带一些魔石碎片，当作幸运护身符。佩带这种咒符的一般是乡下的农夫，为功课烦恼的学生，或是那些夹在平民与贵族之间左右为难的官吏。"
D.SharedStrings[19420]="论古代魔法及如何防止法师毁灭世界"
D.SharedStrings[19421]="设法召唤并击杀灰烬公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。"
D.SharedStrings[19422]="设法释放风暴烈酒酿造厂中的猢狲缠人精（任意难度）。"
D.SharedStrings[19423]="访问萨洛瑞安·寻晨者的遗体，获得他的祝福，以使用奎尔德拉。"
D.SharedStrings[19424]="证明你的力量。"
D.SharedStrings[19425]="证明自己：无限伤害（10波）（90级）"
D.SharedStrings[19426]="证明自己：无限伤害（20波）（90级）"
D.SharedStrings[19427]="证明自己：无限伤害（30波）（90级）"
D.SharedStrings[19428]="证明自己：无限坦克（10波）（90级）"
D.SharedStrings[19429]="证明自己：无限坦克（20波）（90级）"
D.SharedStrings[19430]="证明自己：无限坦克（30波）（90级）"
D.SharedStrings[19431]="证明自己：无限治疗（10波）（90级）"
D.SharedStrings[19432]="证明自己：无限治疗（20波）（90级）"
D.SharedStrings[19433]="证明自己：无限治疗（30波）（90级）"
D.SharedStrings[19434]="评级双子峰的战斗"
D.SharedStrings[19435]="评级双子峰的胜利"
D.SharedStrings[19436]="评级吉尔尼斯之战的战斗"
D.SharedStrings[19437]="评级吉尔尼斯之战的胜利"
D.SharedStrings[19438]="评级寇魔古寺的战斗"
D.SharedStrings[19439]="评级寇魔古寺的胜利"
D.SharedStrings[19440]="评级战歌峡谷的战斗"
D.SharedStrings[19441]="评级战歌峡谷的胜利"
D.SharedStrings[19442]="评级最低物品等级奖励"
D.SharedStrings[19443]="评级深风峡谷的战斗"
D.SharedStrings[19444]="评级深风峡谷的胜利"
D.SharedStrings[19445]="评级碎银矿脉的战斗"
D.SharedStrings[19446]="评级远古海滩的战斗"
D.SharedStrings[19447]="评级远古海滩的胜利"
D.SharedStrings[19448]="评级阿拉希盆地的战斗"
D.SharedStrings[19449]="评级阿拉希盆地的胜利"
D.SharedStrings[19450]="评级风暴之眼的战斗"
D.SharedStrings[19451]="诅咒一个生物。"
D.SharedStrings[19452]="诅咒之喉"
D.SharedStrings[19453]="诅咒之喉吸取了非精英人型或恶魔生物的灵魂，获得了{1}%的伤害加成。"
D.SharedStrings[19454]="诅咒之地：世界的另一端"
D.SharedStrings[19455]="诅咒教派"
D.SharedStrings[19456]="诅咒教派一直都是以喜欢制订庞大的计划但最终鲜有成功而声明狼藉，但我这次感觉有些不一样……$B$B也许是由于接近巫妖王，提高了他们的热情。不管怎样，它们似乎比以往任何时候都更有信心了。我们必须了解是什么让他们感到自信，并想办法夺走他们的自信！$B$B我相信关键就在他们的研究员身上。去搞清楚他们正在干些什么，然后向我报告具体的细节。"
D.SharedStrings[19457]="诅咒教派律法文件中的一页，该文件共有三页。"
D.SharedStrings[19458]="诅咒教派控制着荒凉之门，是吗？一点都不出我的意料。$B$B我们来跟他们玩一个小游戏吧。你之前已经注意到了，新来的教徒在荒凉之门的南端接受训练。他们之中的绝大部分人应该都持有一件特殊的物品——幻象宝珠。$B$B这种宝珠可以用来伪装诅咒教徒，使他们能够安全地自由行动，渗透或是完全伪装成敌人的模样。$B$B去干掉那些蠢货，从他们身上收集幻象宝珠，然后对黑暗压制者使用它。"
D.SharedStrings[19459]="诅咒神教"
D.SharedStrings[19460]="试图传播亚煞极之触。"
D.SharedStrings[19461]="试图采集星光玫瑰时失败的几率降低。"
D.SharedStrings[19462]="试炼竞技场获胜"
D.SharedStrings[19463]="试着把地精热土豆扔给友方玩家。如果他们的背包中有剩余的空间，就可以接住……前提是你要扔得准！"
D.SharedStrings[19464]="试穿一套新的服装。"
D.SharedStrings[19465]="该传送门可将玩家从卡桑琅丛林的一头快速传送到另一头。"
D.SharedStrings[19466]="该传送门可将玩家快速传送到锦绣谷。"
D.SharedStrings[19467]="该元素显得虚弱且极不稳定！\r\n造成的伤害降低{1}%。\r\n最大生命值降低{2}%。\r\n生命值迅速降低。"
D.SharedStrings[19468]="该元素被束缚，受到血槌食人魔的奴役。"
D.SharedStrings[19469]="该单位在战斗中不断积累经验，随着时间的推移变得越发强大。"
D.SharedStrings[19470]="该单位已经无法控制其行动。"
D.SharedStrings[19471]="该单位被一个网兜缠住了！"
D.SharedStrings[19472]="该单位钻地入地下，释放一次潜地弹幕攻击。"
D.SharedStrings[19473]="该单位钻地，释放一次潜地弹幕攻击。"
D.SharedStrings[19474]="该地区正在遭受燃烧军团的攻击。"
D.SharedStrings[19475]="该生物会由生命卫士保其免于一死，或当生命卫士死亡时回满生命值。与其他非生命卫士的盟友共享生命值。"
D.SharedStrings[19476]="该生物死亡时会发生爆炸，并伴有强光。"
D.SharedStrings[19477]="该生物死亡时会解除附近所有盟友的群体控制效果。"
D.SharedStrings[19478]="该生物濒死时会为主人恢复满生命值，或牺牲自己来保主人免于一死。"
D.SharedStrings[19479]="该生物濒死时会为盟友回满生命值，或牺牲自己来保盟友免于一死。"
D.SharedStrings[19480]="该生物濒死时会为盟友回满生命值，或牺牲自己来保盟友免于一死。\r\n除了生命卫士之外的其他盟友会共享生命值。"
D.SharedStrings[19481]="该生物由纯粹的魔法组成，可以被驱散。"
D.SharedStrings[19482]="该生物造成的伤害将用鲜血灌注死亡使者萨鲁法尔。"
D.SharedStrings[19483]="该通用光环会在携带者承受不同派系的法术时自动触发不同的法术效果：\r\n\r\n火焰：34192\r\n冰霜：34193\r\n奥术：34194\r\n自然：34195\r\n暗影：34196\r\n神圣：34197\r\n物理：34198\r\n\r\n对生物使用法术ID#产生对应效果。"
D.SharedStrings[19484]="详尽的研究"
D.SharedStrings[19485]="语云的热气球"
D.SharedStrings[19486]="诱捕目标，每3秒对其造成一次自然伤害。"
D.SharedStrings[19487]="诱捕者德佐克斯"
D.SharedStrings[19488]="诱捕附近所有的敌人，将其石化。"
D.SharedStrings[19489]="说实话，我都不知道我们是如何撑这么久的。纳迦拿走了我的护甲和武器，只给我留了几件破衣服和一把采矿锄……而且那把锄早就断了。$B$B如果我们还想扳回局面的话，我就需要一些武器装备……我的伙伴们也一样，不过可能他们不太愿意承认这一点。$b$b我在附近的纳迦库房见过武器架。虽然我对三叉戟不是很熟，但用它总比用我自己的拳头好。"
D.SharedStrings[19490]="说服安娜丝黛夫人把宝石切割大师的图鉴集交给你。"
D.SharedStrings[19491]="说真的，$N，我没空发呆聊天。$B$B等你收集到那些根茎再告诉我。"
D.SharedStrings[19492]="请原谅我的慌乱——我以前从没杀死过任何人。$b$b我叫伊瑞尔，是卡拉波的学徒。$b$b你说你带了一支军队来？看来圣光今天真的眷顾我了。$b$b那我愿意跟你走。带路吧，$n。"
D.SharedStrings[19493]="请接受我的感谢。$B$B我承认这是个残忍的作战，但话说回来我们也别无选择－他们比起我们这一连串的突袭其实也丝毫不逊色，我们必须驱逐这些维库族才能进压冰冠冰川。$B$B我们应该还会需要更多的援助。请再借助你的力量并且在战场上证明你的价值。"
D.SharedStrings[19494]="请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布尔的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布尔主城幽坑城的属地;但是在科赞被玷污之前，它曾是一片伟大的土地。即使在今天，我们仍将科赞看作神圣的地方。"
D.SharedStrings[19495]="请确保有20码的空地以供赛车奔跑！"
D.SharedStrings[19496]="诸天之拳"
D.SharedStrings[19497]="诺兹多姆"
D.SharedStrings[19498]="诺兹多姆在目标区域张开一个时光领域，使得源质流星消亡于时间之中，当其进入时光领域之后，速度大幅度降低。另外，任何身处时光领域的敌人的攻击速度降低{1}%。"
D.SharedStrings[19499]="诺兹多姆开始将所有精力专注于对抗死亡之翼，使他无法使用自己的气息或时光领域来帮助他的勇士们。"
D.SharedStrings[19500]="诺兹多姆开始将所有精力专注于死亡之翼，使他无法使用自己的气息或时光领域来帮助他的勇士们。"
D.SharedStrings[19501]="诺兹多姆的子嗣"
D.SharedStrings[19502]="诺兹多姆，时光之王"
D.SharedStrings[19503]="诺德·杰码"
D.SharedStrings[19504]="诺拉，烈焰之母"
D.SharedStrings[19505]="诺斯的特殊药剂"
D.SharedStrings[19506]="诺格弗格药剂"
