D.SharedStrings[19530]="调查荒芜之地观察者的陵墓里的守护者宝藏。"
D.SharedStrings[19531]="调查黑骑士的身世是否属实，然后回到银色比武场，向北伐军战士莱达拉汇报你的发现。"
