D.SharedStrings[19535]="调酒师童福"
D.SharedStrings[19536]="谜之种因能够随机长出任意熊猫人草药而得名。"
D.SharedStrings[19537]="谢谢。知道它们不会再为我们而牺牲，我感觉好些了。"
D.SharedStrings[19538]="谢谢你帮维斯雷修好了那架飞行器。$B$B你愿意再帮我们一个忙吗？西北方有一股不寻常的气流袭来。我已经指派了飞行员维克去侦察情况，不过他恐怕还需要一名副驾驶员。$B$B如果你觉得自己能胜任的话，就飞往湖边着陆场去找他吧。哦，记得告诉他，是我派你去的。"
D.SharedStrings[19539]="谢谢你，$N。你在战歌峡谷中的威名已经传遍了灰谷森林。"
D.SharedStrings[19540]="谷地大德鲁伊"
