D.SharedStrings[19542]="豪侠骑士"
D.SharedStrings[19543]="贝丝缇拉克"
D.SharedStrings[19544]="贝什塔尔被迫为你效力，但不会太久！"
D.SharedStrings[19545]="贝尔多斯"
D.SharedStrings[19546]="贝尔比保证可以让每个人看起来都很迷人！"
D.SharedStrings[19547]="贝恩·血蹄"
D.SharedStrings[19548]="贝恩·血蹄腾空跃起，从天而降，以千钧之力对目标区域造成{1}点物理伤害。这一击可将巨石粉碎！"
D.SharedStrings[19549]="贝恩向目标投掷图腾，对其造成{1}点物理伤害，并将其击退。贝恩的图腾在原地存在数秒。"
