D.SharedStrings[19553]="贝蒂尔德·深砧"
D.SharedStrings[19554]="贝蒂斯周期性从装满炸弹的篮子里拿出炸弹，短时间后对附近的敌人造成火焰伤害。"
D.SharedStrings[19555]="负伤的暴风城步兵"
D.SharedStrings[19556]="贡多拉船娘"
D.SharedStrings[19557]="财宝都是假的，不过那些洞穴践踏者才看不出来呢。愚蠢的食人魔！$B$B计划是这样的……你走进舰队司令的洞去，把“财宝”到处乱洒，贿赂食人魔。然后再去单挑托尼·双牙。$B$B钥匙就很容易到手了！"
D.SharedStrings[19558]="财富在等着你……"
