D.SharedStrings[19588]="赛拉·月卫"
D.SharedStrings[19589]="赛拉对我们的进展还满意吗？我并不关心她本人，只是我们的确需要她的帮助。"
D.SharedStrings[19590]="赛特提克御风者"
