D.SharedStrings[19592]="赛莱托斯大使"
D.SharedStrings[19593]="赛莱拉·钢咏"
D.SharedStrings[19594]="赞吉尔的剧毒折磨坩埚"
D.SharedStrings[19595]="赞扎可以使用适当的材料对你的装备进行古老的魔法增强处理！你听说过野性戒卫吗？啊，你当然没有听说过。你满脑子都是那些低级的暗夜精灵的魔法。$B$B给我拿来一份暗夜精灵的秘药，我也许能重新为你附魔。去吧，我会把野性戒卫作为奖励送给你的。"
D.SharedStrings[19596]="赞达拉之火"
D.SharedStrings[19597]="赞达拉入侵者"
D.SharedStrings[19598]="赞达拉啮趾者"
D.SharedStrings[19599]="赞达拉啸天龙"
D.SharedStrings[19600]="赞达拉巨神像"
D.SharedStrings[19601]="赞达拉巨神像用力猛击地面，对直线上的敌人造成{1}点自然伤害。"
D.SharedStrings[19602]="赞达拉巨魔发现了一种将神灵束缚在野兽体内的方法，这可以让它们获得惊人而致命的力量。$b$b我们必须阻止他们。$b$b去兽栏寻找一个神谕者并击败他。你可以通过那些发光的野兽来辨认找到他们。$b$b我们不能让这样的暴行继续下去。"
D.SharedStrings[19603]="赞达拉恐龙统领"
D.SharedStrings[19604]="赞达拉战争使者"
D.SharedStrings[19605]="赞达拉战船在这座岛屿四周的海域上大肆掠夺。他们不断地从赞达拉运送士兵和作战野兽，来壮大雷神的军队。$B$B要是我们能夺取宫殿的船坞，雷电之王的补给线就会被截断，而你在这里的据点也会变得越发稳固。$B$B我有个计划可以实现这一目标，而且用不着劳烦整支大军出动。"
D.SharedStrings[19606]="赞达拉撕踝者"
D.SharedStrings[19607]="赞达拉暗影坠饰"
D.SharedStrings[19608]="赞达拉的迅猛龙和掠食龙是对我们部队的重大威胁。它们是出色的狩猎者，能够长途追踪猎物，对毫无准备的目标尤为致命。$b$b我需要你前往兽栏减少那里的恐龙数量。我们要在训练完成前先干掉它们。"
D.SharedStrings[19609]="赞达拉石盾卫士"
D.SharedStrings[19610]="赞达拉碎颅者向他选定的目标冲锋，击退其路径上的所有敌人，并对他们造成{1}点物理伤害。"
D.SharedStrings[19611]="赞达拉终极仪式长袍"
D.SharedStrings[19612]="赞达拉血肉撕裂者"
D.SharedStrings[19613]="赞达拉袭胫者"
