D.SharedStrings[19615]="赞达拉预言书"
D.SharedStrings[19616]="赞达拉飞翼龙"
D.SharedStrings[19617]="赞达拉驭兽师"
D.SharedStrings[19618]="赢得12次暗月死斗大赛并获得格斗大师徽记。"
D.SharedStrings[19619]="赢得一场宠物战斗。"
D.SharedStrings[19620]="赢得一场扔火炬游戏，然后与吞火大师谈一谈。"
