D.SharedStrings[19635]="赫利克斯·破甲"
D.SharedStrings[19636]="赫利克斯的雇员"
D.SharedStrings[19637]="赫尔努拉斯"
D.SharedStrings[19638]="赫尔达·影刃"
D.SharedStrings[19639]="赫尔默大使"
D.SharedStrings[19640]="赫尼·马雷布镇长"
