D.SharedStrings[19647]="赭色骷髅战马"
D.SharedStrings[19648]="走过魔古符文的玩家，其伤害、急速、移动速度和生命回复速度都得到了提高。"
D.SharedStrings[19649]="赶快把这条雏龙带回去交给莱洛拉斯！"
D.SharedStrings[19650]="赶快行动，穿过这道传送门！我会在传送门的另一边与你汇合。"
D.SharedStrings[19651]="起义：艾利桑德的反击"
D.SharedStrings[19652]="起搏器有时可以让一个已死的盟友复活。无法在战斗中使用。"
D.SharedStrings[19653]="趁机攻击一块不平衡的结构，造成{1}点物理伤害。"
D.SharedStrings[19654]="超声波之环"
D.SharedStrings[19655]="超声波螺丝刀"
D.SharedStrings[19656]="超级新星"
D.SharedStrings[19657]="超级测蛋器是克格尔.曲藤的最新成果，看起来真是令人印象深刻。$B$B你刚刚接触到超级测蛋器的控制面板，它就劈啪作响了起来。"
D.SharedStrings[19658]="超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，复盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的“叮”的声音过后，机器的盖子猛地打开了，里面摆着一只精心包装过的，扎着蝴蝶结的小盒子。"
D.SharedStrings[19659]="超级清洁器5200型突然停止了运行，“叮”的一声响，机器的盖子打开了，里面放着一只扎着蝴蝶结的小盒子。似乎这机器在清除物体表面的污垢以后会把物体包装起来。即使机器没有清理过什么，至少这东西被装在了一个漂亮的盒子里。$B$B好吧，让我们来看看它有没有清洁你放进去的东西……"
D.SharedStrings[19660]="超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动!"
D.SharedStrings[19661]="超级清洁器5200型！"
