D.SharedStrings[19665]="超载的蛛形地雷"
D.SharedStrings[19666]="跃向一个敌人，对其造成{1}点火焰伤害，并将附近所有敌人击退。"
D.SharedStrings[19667]="跃向一个敌人，对附近所有敌人造成物理伤害。"
D.SharedStrings[19668]="跃向一个敌人，造成{1}点物理伤害，将附近的所有敌人击退并生成一团窒息的烟云。"
D.SharedStrings[19669]="跃向一个敌人，造成{1}点物理伤害，并使附近的所有敌人昏迷。"
