D.SharedStrings[19676]="跃向附近的一名敌人并扫击数次，对施法者前方的所有敌人造成物理伤害。"
D.SharedStrings[19677]="跑过拱门，击中红色标记和紫色标记，然后返回钢铁精灵游戏营地。"
D.SharedStrings[19678]="跑过拱门，击中蓝色标记和绿色标记，然后返回钢铁精灵游戏营地。"
