D.SharedStrings[19686]="跟冬天爷爷谈一谈，他就在奥格瑞玛的烟林牧场零售店附近。"
D.SharedStrings[19687]="跟冬天爷爷谈一谈，他就在铁炉堡的烟林牧场零售店附近。"
