D.SharedStrings[19751]="路納斯特家族交遊廣闊，當時機來臨時，他們會是一大助益。"
D.SharedStrings[19752]="跳上佐尔奇克的幼龙，与他展开近身战斗。"
D.SharedStrings[19753]="跳上对手的幼龙，与他展开近身战斗。"
D.SharedStrings[19754]="跳上载具，只能在户外使用，须遵守通用的载具规则。"
D.SharedStrings[19755]="跳到周围的一个位置，潜入阴影，准备攻击！"
D.SharedStrings[19756]="跳到目标身上，将其打翻在地，每0.5秒造成一次物理伤害，并使其昏迷2秒。"
D.SharedStrings[19757]="跳向一个敌人所在的位置，对冲击区域的所有目标造成奥术伤害。"
D.SharedStrings[19758]="跳向一个敌人所在的位置，造成{1}点物理伤害，并将其击退。"
D.SharedStrings[19759]="跳向一个敌人，造成小范围的物理伤害。"
D.SharedStrings[19760]="跳向一个敌人，造成小范围的自然伤害。"
D.SharedStrings[19761]="跳向一个目标位置，对附近的敌人造成物理伤害。"
D.SharedStrings[19762]="跳向一个目标并造成武器伤害。"
D.SharedStrings[19763]="跳向一名敌人。"
D.SharedStrings[19764]="跳向一名敌人，对一小片区域内包括施法者在内的所有人造成{1}点火焰伤害并使其昏迷。"
D.SharedStrings[19765]="跳向敌人，猛击数次。"
D.SharedStrings[19766]="跳向目标地雷，将其踩入地下，以减弱爆炸威力。"
D.SharedStrings[19767]="跳向目标，对敌人和距离他最近的两个盟友造成{1}%的武器伤害。"
D.SharedStrings[19768]="跳向目标，落地时对附近的所有敌人造成物理伤害。"
D.SharedStrings[19769]="跳向目标，造成{1}%的武器伤害。"
D.SharedStrings[19770]="跳向目标，造成{1}%的武器伤害，并将目标击倒。"
D.SharedStrings[19771]="跳向远处的敌人，对其附近的所有目标造成伤害并令其昏迷。"
D.SharedStrings[19772]="跳在空中时能再跳一次。"
D.SharedStrings[19773]="跳在空中时能再跳一次，每5秒触发一次。"
D.SharedStrings[19774]="跳进一口井中，以传送到达拉然下水道4个随机位置的其中一个。使用附带泼水效果。"
D.SharedStrings[19775]="践踏地面，对10码范围内的所有敌人造成物理伤害。"
D.SharedStrings[19776]="践踏地面，对12码范围内的所有敌人造成物理伤害，并将他们击飞。"
D.SharedStrings[19777]="践踏地面，对一个大型范围内的所有敌人造成物理伤害，并将其击飞到空中。"
D.SharedStrings[19778]="践踏地面，对周围的所有敌人造成{1}点物理伤害，并将其击退。"
D.SharedStrings[19779]="践踏地面，对施法者面前锥形区域内的所有敌人造成物理伤害。"
D.SharedStrings[19780]="践踏地面，对施法者面前锥形区域内的所有盟友和敌人造成物理伤害。"
D.SharedStrings[19781]="践踏地面，对附近的所有敌人造成{1}点物理伤害，并将其击退。"
D.SharedStrings[19782]="践踏地面，对附近的敌人造成普通伤害，并将他们击退。"
D.SharedStrings[19783]="践踏地面，对附近的敌人造成普通伤害，并将其击退。"
D.SharedStrings[19784]="践踏地面，对附近的敌人造成普通伤害，并将它们击退。"
D.SharedStrings[19785]="践踏地面，造成{1}点物理伤害，并将敌人击退至施法者远处。"
